INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('verb-to-be','Verb ''to be'' (am/is/are) — Động từ to be','Thì động từ','Pre-A1','Dùng am/is/are để nói ai đó/cái gì đó LÀ gì, THẾ NÀO hoặc Ở ĐÂU.','[{"label":"Khẳng định","formula":"S + am/is/are + ...","example":"I am happy. She is a teacher. They are here."},{"label":"Phủ định","formula":"S + am/is/are + not + ...","example":"I am not sad. He is not tall."},{"label":"Nghi vấn","formula":"Am/Is/Are + S + ...?","example":"Are you ok? Is she your mum?"},{"label":"Rút gọn","formula":"I''m / you''re / he''s / she''s / it''s / we''re / they''re; isn''t / aren''t","example":"I''m five. It isn''t cold."}]',NULL,'["Nói tên, tuổi, nghề nghiệp: I am Tom. She is a doctor.","Miêu tả tính chất/cảm xúc: The dog is big. We are happy.","Nói vị trí (ở đâu): The cat is on the bed. They are at school."]',NULL,'[{"en":"I am seven years old.","vi":"Tôi bảy tuổi.","kind":"aff"},{"en":"She is my friend.","vi":"Cô ấy là bạn của tôi.","kind":"aff"},{"en":"The books are on the table.","vi":"Những cuốn sách ở trên bàn.","kind":"aff"},{"en":"He is not at home.","vi":"Anh ấy không có ở nhà.","kind":"neg"},{"en":"Are you happy?","vi":"Bạn có vui không?","kind":"ques"}]','["✗ I am student. → ✓ I am a student. (đếm được số ít cần a/an)","✗ She are nice. → ✓ She is nice. (she đi với is)","✗ I no happy. → ✓ I am not happy. (phủ định cần am/is/are + not)"]','["Nhớ cặp: I → am; he/she/it → is; you/we/they → are.","Nói nhanh dùng rút gọn: I''m, you''re, it''s."]',NULL,'["articles-a-an", "there-is-are"]','["to be","am is are","động từ to be","là","am","is","are"]',NULL,'["multiple_choice","fill_blank","ordering","matching"]',1,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('articles-a-an','Articles a/an — Mạo từ a/an','Danh từ & Mạo từ','Pre-A1','Dùng a/an trước danh từ đếm được số ít khi nói tới MỘT cái nào đó chung chung.','[{"label":"Dùng a","formula":"a + phụ âm... + N","example":"a dog, a book, a car"},{"label":"Dùng an","formula":"an + nguyên âm (a,e,i,o,u)... + N","example":"an apple, an egg, an orange"}]',NULL,'["Nói tới MỘT vật/người chung, không cụ thể: I have a pen.","a đứng trước từ bắt đầu bằng âm phụ âm: a cat, a boy.","an đứng trước từ bắt đầu bằng âm nguyên âm: an apple, an umbrella."]',NULL,'[{"en":"I have a dog.","vi":"Tôi có một con chó.","kind":"aff"},{"en":"She eats an apple.","vi":"Cô ấy ăn một quả táo.","kind":"aff"},{"en":"It is an egg.","vi":"Đó là một quả trứng.","kind":"aff"},{"en":"He is a good boy.","vi":"Cậu ấy là một cậu bé ngoan.","kind":"aff"}]','["✗ a apple → ✓ an apple (âm nguyên âm dùng an)","✗ an dog → ✓ a dog (âm phụ âm dùng a)","✗ I have book. → ✓ I have a book. (đếm được số ít cần a/an)"]','["Chữ cái đầu là a, e, i, o, u → thường dùng an.","a/an chỉ dùng cho MỘT vật đếm được (số ít)."]','[{"with":"plural-nouns","note":"Số nhiều KHÔNG dùng a/an: a book → books (không phải a books)."}]','["verb-to-be", "plural-nouns"]','["a an","articles","mạo từ","một","a apple an apple"]',NULL,'["multiple_choice","fill_blank","ordering","matching"]',4,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('plural-nouns','Plural nouns — Danh từ số nhiều','Danh từ & Mạo từ','Pre-A1','Thêm -s (hoặc -es) vào danh từ đếm được để nói có NHIỀU hơn một.','[{"label":"Thường: thêm -s","formula":"N + s","example":"cat → cats, book → books"},{"label":"Kết thúc -s,-x,-ch,-sh: thêm -es","formula":"N + es","example":"box → boxes, bus → buses"},{"label":"Bất quy tắc","formula":"đổi cả từ","example":"man → men, child → children, foot → feet"}]','["two","three","many","some","these","those"]','["Nói có nhiều hơn một vật: one book → two books.","Sau these/those và số đếm ≥ 2 luôn dùng số nhiều.","Một số danh từ đặc biệt đổi khác: man → men, woman → women."]','["box → boxes; bus → buses (kết thúc -s,-x,-ch,-sh thêm -es)","baby → babies; city → cities (phụ âm + y → đổi y thành i, thêm -es)","man → men; child → children; foot → feet (bất quy tắc)"]','[{"en":"I have two dogs.","vi":"Tôi có hai con chó.","kind":"aff"},{"en":"There are three boxes.","vi":"Có ba cái hộp.","kind":"aff"},{"en":"These children are happy.","vi":"Những đứa trẻ này rất vui.","kind":"aff"},{"en":"My feet are cold.","vi":"Chân tôi lạnh.","kind":"aff"}]','["✗ two book → ✓ two books (số nhiều thêm -s)","✗ boxs → ✓ boxes (kết thúc -x thêm -es)","✗ childs → ✓ children (bất quy tắc)"]','["Nhiều hơn một → thường thêm ''s''.","Học thuộc vài từ đặc biệt: man/men, child/children, foot/feet."]','[{"with":"articles-a-an","note":"Số nhiều bỏ a/an: a cat → cats."}]','["articles-a-an", "there-is-are"]','["plural","số nhiều","thêm s es","boxes babies","danh từ"]','[{"term":"child → children","meaning":"đứa trẻ → những đứa trẻ","example":"The children are playing outside.","group":"Bất quy tắc"},{"term":"man → men","meaning":"người đàn ông → những người đàn ông","example":"Two men are waiting at the door.","group":"Bất quy tắc"},{"term":"woman → women","meaning":"người phụ nữ → những người phụ nữ","example":"The women work in that office.","group":"Bất quy tắc"},{"term":"foot → feet","meaning":"bàn chân → những bàn chân","example":"My feet hurt after the long walk.","group":"Bất quy tắc"},{"term":"tooth → teeth","meaning":"cái răng → những cái răng","example":"Brush your teeth twice a day.","group":"Bất quy tắc"},{"term":"mouse → mice","meaning":"con chuột → những con chuột","example":"There are mice in the kitchen.","group":"Bất quy tắc"},{"term":"person → people","meaning":"người → nhiều người","example":"Many people came to the party.","group":"Bất quy tắc"},{"term":"goose → geese","meaning":"con ngỗng → những con ngỗng","example":"The geese are near the lake.","group":"Bất quy tắc"},{"term":"fish → fish","meaning":"con cá → những con cá (không đổi)","example":"I caught three fish today.","group":"Không đổi"},{"term":"sheep → sheep","meaning":"con cừu → những con cừu (không đổi)","example":"The farmer has ten sheep.","group":"Không đổi"},{"term":"deer → deer","meaning":"con hươu → những con hươu (không đổi)","example":"We saw two deer in the forest.","group":"Không đổi"},{"term":"aircraft → aircraft","meaning":"máy bay → những máy bay (không đổi)","example":"Five aircraft landed safely.","group":"Không đổi"},{"term":"series → series","meaning":"loạt, chuỗi → nhiều loạt (không đổi)","example":"She watched two TV series last month.","group":"Không đổi"},{"term":"leaf → leaves","meaning":"chiếc lá → những chiếc lá","example":"The leaves fall in autumn.","group":"-f/-fe → -ves"},{"term":"knife → knives","meaning":"con dao → những con dao","example":"The knives are in the drawer.","group":"-f/-fe → -ves"},{"term":"wife → wives","meaning":"người vợ → những người vợ","example":"Their wives are good friends.","group":"-f/-fe → -ves"},{"term":"wolf → wolves","meaning":"con sói → những con sói","example":"The wolves hunt at night.","group":"-f/-fe → -ves"},{"term":"shelf → shelves","meaning":"cái kệ → những cái kệ","example":"The books are on the shelves.","group":"-f/-fe → -ves"},{"term":"baby → babies","meaning":"em bé → những em bé","example":"The babies are sleeping now.","group":"-y → -ies"},{"term":"city → cities","meaning":"thành phố → những thành phố","example":"We visited three cities in Japan.","group":"-y → -ies"},{"term":"country → countries","meaning":"quốc gia → những quốc gia","example":"Many countries joined the meeting.","group":"-y → -ies"},{"term":"potato → potatoes","meaning":"củ khoai tây → những củ khoai tây","example":"I bought five potatoes.","group":"-o → -oes"},{"term":"tomato → tomatoes","meaning":"quả cà chua → những quả cà chua","example":"The tomatoes are red and ripe.","group":"-o → -oes"},{"term":"hero → heroes","meaning":"anh hùng → những anh hùng","example":"The soldiers are our heroes.","group":"-o → -oes"}]','["fill_blank","multiple_choice","matching","ordering"]',5,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('there-is-are','There is / There are — There is/are','Câu & Cấu trúc','Pre-A1','Dùng There is/There are để nói CÓ cái gì đó tồn tại ở một nơi.','[{"label":"Số ít","formula":"There is + a/an + N (số ít)","example":"There is a cat on the bed."},{"label":"Số nhiều","formula":"There are + số/some + Ns","example":"There are three books."},{"label":"Phủ định","formula":"There isn''t / There aren''t + ...","example":"There isn''t a dog. There aren''t any pens."},{"label":"Nghi vấn","formula":"Is/Are there + ...?","example":"Is there a park? Are there any apples?"}]','["there is","there are","on","in","under","some","any"]','["Nói có một vật ở đâu đó: There is a book on the table.","Nói có nhiều vật: There are five students in the class.","Hỏi/nói không có: Is there a shop here? There isn''t any milk."]',NULL,'[{"en":"There is a dog in the garden.","vi":"Có một con chó trong vườn.","kind":"aff"},{"en":"There are two chairs here.","vi":"Có hai cái ghế ở đây.","kind":"aff"},{"en":"There isn''t a cat under the bed.","vi":"Không có con mèo nào dưới gầm giường.","kind":"neg"},{"en":"Are there any books?","vi":"Có cuốn sách nào không?","kind":"ques"}]','["✗ There are a cat. → ✓ There is a cat. (số ít dùng is)","✗ There is two dogs. → ✓ There are two dogs. (số nhiều dùng are)","✗ Have a book on the table. → ✓ There is a book on the table."]','["Một vật → There is; nhiều vật → There are.","There is/are = ''có'' (tồn tại), khác have got là ''ai sở hữu''."]','[{"with":"have-got","note":"there is/are nói cái gì tồn tại; have got nói ai sở hữu cái gì."}]','["verb-to-be", "plural-nouns", "prepositions-place"]','["there is","there are","có","tồn tại","there isn''t there aren''t"]',NULL,'["multiple_choice","fill_blank","ordering","matching"]',8,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('can-ability','can / can''t (ability) — can/can''t chỉ khả năng','Động từ khuyết thiếu','Pre-A1','Dùng can/can''t để nói ai đó CÓ THỂ hay KHÔNG THỂ làm việc gì.','[{"label":"Khẳng định","formula":"S + can + V (nguyên thể)","example":"I can swim. She can run fast."},{"label":"Phủ định","formula":"S + can''t (cannot) + V","example":"I can''t fly. He can''t cook."},{"label":"Nghi vấn","formula":"Can + S + V ...?","example":"Can you swim? Can she sing?"},{"label":"Trả lời ngắn","formula":"Yes, S + can. / No, S + can''t.","example":"Yes, I can. No, I can''t."}]',NULL,'["Nói khả năng làm được: I can ride a bike.","Nói không làm được: He can''t swim.","Hỏi về khả năng: Can you dance?"]',NULL,'[{"en":"I can play football.","vi":"Tôi có thể chơi bóng đá.","kind":"aff"},{"en":"She can sing very well.","vi":"Cô ấy có thể hát rất hay.","kind":"aff"},{"en":"My baby brother can''t walk.","vi":"Em bé của tôi chưa biết đi.","kind":"neg"},{"en":"Can you help me?","vi":"Bạn có thể giúp tôi không?","kind":"ques"}]','["✗ She cans swim. → ✓ She can swim. (can không thêm -s)","✗ I can to swim. → ✓ I can swim. (sau can dùng động từ nguyên thể, không to)","✗ He can swims. → ✓ He can swim."]','["Sau can luôn là động từ nguyên mẫu, KHÔNG thêm -s, KHÔNG có to.","can''t = cannot (không thể)."]',NULL,'[]','["can","can''t","cannot","khả năng","có thể","ability"]',NULL,'["multiple_choice","fill_blank","matching","ordering"]',9,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('present-simple','Present Simple — Hiện tại đơn','Thì động từ','A1','Thì hiện tại đơn diễn tả thói quen, sự thật hiển nhiên và điều lặp đi lặp lại. Với chủ ngữ số ít ngôi thứ ba (he/she/it), động từ phải thêm -s hoặc -es.','[{"label":"Khẳng định","formula":"S + V(s/es) + O","example":"She plays tennis every day."},{"label":"Phủ định","formula":"S + don''t/doesn''t + V(nguyên thể)","example":"He doesn''t like coffee."},{"label":"Nghi vấn","formula":"Do/Does + S + V(nguyên thể)?","example":"Do you speak English?"}]','["every day","every week","usually","always","often","sometimes","never","on Mondays"]','["Diễn tả thói quen, việc làm hằng ngày.","Nói về sự thật hiển nhiên, chân lý (mặt trời mọc ở hướng đông).","Nói về lịch trình cố định, sở thích chung."]','["Thêm -s cho hầu hết động từ: play → plays.","Thêm -es cho động từ tận cùng -s, -ss, -sh, -ch, -x, -o: go → goes, watch → watches.","Động từ tận cùng phụ âm + y: đổi y thành -ies: study → studies (nhưng play → plays vì trước y là nguyên âm)."]','[{"en":"I go to school by bike.","vi":"Tôi đi học bằng xe đạp.","kind":"aff"},{"en":"My mother works in a hospital.","vi":"Mẹ tôi làm việc trong bệnh viện.","kind":"aff","note":"Ngôi thứ ba số ít: work → works."},{"en":"We don''t watch TV in the morning.","vi":"Chúng tôi không xem TV vào buổi sáng.","kind":"neg"},{"en":"Does she like chocolate?","vi":"Cô ấy có thích sô cô la không?","kind":"ques"}]','["Quên thêm -s/-es ở ngôi thứ ba số ít: viết ''He like'' thay vì ''He likes''.","Dùng ''doesn''t'' nhưng vẫn để động từ có -s: sai ''He doesn''t likes''; đúng là ''He doesn''t like''.","Thêm -s vào động từ sau ''do/does'': sai ''Does she plays?''; đúng ''Does she play?''."]','["Sau don''t/doesn''t và do/does, động từ luôn ở dạng nguyên thể (không -s).","Nhớ quy tắc: he, she, it → thêm -s vào động từ."]','[{"with":"present-continuous","note":"Hiện tại đơn cho thói quen; hiện tại tiếp diễn cho việc đang xảy ra ngay lúc nói."}]','["adverbs-of-frequency", "present-continuous"]','["hiện tại đơn","present simple","thói quen","does","don''t"]',NULL,'["multiple_choice","fill_blank","ordering","matching"]',1,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('present-continuous','Present Continuous — Hiện tại tiếp diễn','Thì động từ','A1','Thì hiện tại tiếp diễn diễn tả hành động đang xảy ra ngay tại thời điểm nói. Công thức dùng động từ to be (am/is/are) kết hợp với động từ thêm đuôi -ing.','[{"label":"Khẳng định","formula":"S + am/is/are + V-ing","example":"She is reading a book."},{"label":"Phủ định","formula":"S + am/is/are + not + V-ing","example":"They aren''t sleeping."},{"label":"Nghi vấn","formula":"Am/Is/Are + S + V-ing?","example":"Are you listening to me?"}]','["now","right now","at the moment","Look!","Listen!","today"]','["Diễn tả hành động đang diễn ra ngay lúc nói.","Mô tả điều đang xảy ra trong bức tranh, ảnh.","Nói về việc đang diễn ra trong giai đoạn hiện tại (không nhất thiết ngay lúc này)."]','["Thêm -ing cho hầu hết động từ: play → playing.","Động từ tận cùng -e câm: bỏ e rồi thêm -ing: make → making, write → writing.","Động từ một âm tiết tận cùng nguyên âm + phụ âm: gấp đôi phụ âm: run → running, sit → sitting."]','[{"en":"I am doing my homework now.","vi":"Tôi đang làm bài tập bây giờ.","kind":"aff"},{"en":"Look! The baby is crying.","vi":"Nhìn kìa! Em bé đang khóc.","kind":"aff","note":"Từ ''Look!'' báo hiệu hành động đang xảy ra."},{"en":"We aren''t playing football.","vi":"Chúng tôi không đang chơi bóng đá.","kind":"neg"},{"en":"Is your dad cooking dinner?","vi":"Bố bạn có đang nấu bữa tối không?","kind":"ques"}]','["Quên động từ to be: sai ''She reading''; đúng ''She is reading''.","Quên đuôi -ing: sai ''I am read''; đúng ''I am reading''.","Không gấp đôi phụ âm khi cần: sai ''runing''; đúng ''running''."]','["Luôn có đủ hai phần: to be (am/is/are) + động từ-ing.","Khi thấy ''now'', ''Look!'', ''Listen!'' thì dùng thì tiếp diễn."]','[{"with":"present-simple","note":"Tiếp diễn cho việc đang xảy ra bây giờ; hiện tại đơn cho thói quen thường ngày."}]','["present-simple", "verb-to-be"]','["hiện tại tiếp diễn","present continuous","-ing","am is are","đang"]',NULL,'["multiple_choice","fill_blank","ordering","matching"]',2,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('past-simple-be','Past Simple of ''to be'' (was/were) — Quá khứ đơn của to be','Thì động từ','A1','Dạng quá khứ của động từ to be là was và were. Dùng was với I, he, she, it; dùng were với you, we, they để nói về trạng thái, đặc điểm trong quá khứ.','[{"label":"Khẳng định","formula":"I/He/She/It + was ; You/We/They + were","example":"I was at home yesterday."},{"label":"Phủ định","formula":"S + wasn''t/weren''t","example":"They weren''t happy."},{"label":"Nghi vấn","formula":"Was/Were + S ?","example":"Were you tired?"}]','["yesterday","last night","last week","last year","ago","in 2020"]','["Nói về trạng thái, cảm xúc trong quá khứ.","Miêu tả vị trí, tuổi, đặc điểm của người/vật trong quá khứ.","Nói về thời tiết, thời gian đã qua."]',NULL,'[{"en":"She was a good student.","vi":"Cô ấy đã là một học sinh giỏi.","kind":"aff"},{"en":"We were at the park last Sunday.","vi":"Chúng tôi đã ở công viên Chủ nhật tuần trước.","kind":"aff","note":"we → were."},{"en":"He wasn''t at school yesterday.","vi":"Hôm qua cậu ấy không có ở trường.","kind":"neg"},{"en":"Was it cold last night?","vi":"Đêm qua trời có lạnh không?","kind":"ques"}]','["Dùng nhầm was/were: sai ''They was''; đúng ''They were''.","Dùng ''was'' với you: sai ''You was''; đúng ''You were''.","Thêm động từ thường sau was/were khi không cần: ''was'' đã đủ nghĩa ''thì/là/ở''."]','["Ghi nhớ: I/he/she/it → WAS; you/we/they → WERE.","Viết tắt: was not = wasn''t, were not = weren''t."]','[{"with":"verb-to-be","note":"verb-to-be là hiện tại (am/is/are); was/were là dạng quá khứ của chính nó."}]','["verb-to-be", "prepositions-time"]','["quá khứ đơn to be","was were","wasn''t","weren''t","yesterday"]',NULL,'["multiple_choice","fill_blank","matching","ordering"]',3,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('prepositions-time','Prepositions of time (in/on/at) — Giới từ chỉ thời gian','Giới từ','A1','Ba giới từ in, on, at dùng để chỉ thời gian theo quy tắc: at cho giờ/thời điểm cụ thể, on cho ngày/thứ, in cho tháng/năm/mùa/buổi trong ngày.','[{"label":"at — giờ, thời điểm","formula":"at + giờ / at night / at noon","example":"The class starts at 8 o''clock."},{"label":"on — ngày, thứ","formula":"on + thứ / ngày / ngày lễ / on the weekend","example":"We have English on Monday."},{"label":"in — tháng, năm, mùa, buổi","formula":"in + tháng / năm / mùa / buổi trong ngày","example":"My birthday is in July."}]','["o''clock","Monday","morning","July","summer","night","weekend"]','["Dùng at với giờ cụ thể và một số cụm cố định (at night, at noon, at the moment).","Dùng on với thứ trong tuần, ngày cụ thể, ngày lễ và cuối tuần (on the weekend — cách nói Mỹ).","Dùng in với tháng, năm, mùa và buổi trong ngày (in the morning/afternoon/evening)."]',NULL,'[{"en":"I get up at 6 o''clock.","vi":"Tôi thức dậy lúc 6 giờ.","kind":"aff","note":"at + giờ."},{"en":"She was born in 2015.","vi":"Cô bé sinh năm 2015.","kind":"aff","note":"in + năm."},{"en":"We play football on Saturday.","vi":"Chúng tôi chơi bóng đá vào thứ Bảy.","kind":"aff","note":"on + thứ."},{"en":"Do you study in the evening?","vi":"Bạn có học vào buổi tối không?","kind":"ques","note":"in the evening."}]','["Dùng nhầm ''in'' cho giờ: sai ''in 7 o''clock''; đúng ''at 7 o''clock''.","Dùng ''on'' cho tháng: sai ''on July''; đúng ''in July''.","Đặc biệt: ''at night'' nhưng ''in the morning/afternoon/evening''."]','["Ghi nhớ theo độ ''lớn'': at (nhỏ nhất - giờ) → on (ngày) → in (lớn nhất - tháng/năm).","Học thuộc cụm cố định: at night, on the weekend, in the morning."]','[{"with":"prepositions-place","note":"Cùng ba từ in/on/at nhưng dùng cho nơi chốn có quy tắc khác."}]','["prepositions-place"]','["giới từ thời gian","in on at","at 8 o''clock","on Monday","in July"]','[{"term":"at 6 o''clock","meaning":"lúc 6 giờ — at + giờ cụ thể","example":"I wake up at 6 o''clock.","group":"at (giờ/thời điểm)"},{"term":"at night","meaning":"vào ban đêm","example":"Owls hunt at night.","group":"at (giờ/thời điểm)"},{"term":"at noon","meaning":"vào buổi trưa (12 giờ)","example":"We have lunch at noon.","group":"at (giờ/thời điểm)"},{"term":"on the weekend","meaning":"vào cuối tuần (Anh-Mỹ; Anh-Anh nói at the weekend)","example":"I relax on the weekend.","group":"on (ngày/thứ)"},{"term":"at Christmas","meaning":"vào dịp Giáng sinh","example":"We meet at Christmas.","group":"at (giờ/thời điểm)"},{"term":"on Monday","meaning":"vào thứ Hai — on + thứ trong tuần","example":"We have a test on Monday.","group":"on (ngày/thứ)"},{"term":"on July 5th","meaning":"vào ngày 5 tháng 7 — on + ngày cụ thể","example":"The trip is on July 5th.","group":"on (ngày/thứ)"},{"term":"on my birthday","meaning":"vào ngày sinh nhật của tôi","example":"I get gifts on my birthday.","group":"on (ngày/thứ)"},{"term":"on weekdays","meaning":"vào các ngày trong tuần (thứ Hai–thứ Sáu)","example":"I go to school on weekdays.","group":"on (ngày/thứ)"},{"term":"in July","meaning":"vào tháng Bảy — in + tháng","example":"My holiday is in July.","group":"in (tháng/năm/mùa/buổi)"},{"term":"in 2020","meaning":"vào năm 2020 — in + năm","example":"She was born in 2020.","group":"in (tháng/năm/mùa/buổi)"},{"term":"in summer","meaning":"vào mùa hè — in + mùa","example":"It is hot in summer.","group":"in (tháng/năm/mùa/buổi)"},{"term":"in the morning","meaning":"vào buổi sáng — in + buổi trong ngày","example":"I run in the morning.","group":"in (tháng/năm/mùa/buổi)"},{"term":"in the 21st century","meaning":"vào thế kỷ 21 — in + thế kỷ","example":"We live in the 21st century.","group":"in (tháng/năm/mùa/buổi)"},{"term":"at the moment","meaning":"ngay lúc này, hiện tại","example":"She is busy at the moment.","group":"at (giờ/thời điểm)"},{"term":"in the evening","meaning":"vào buổi tối","example":"We watch TV in the evening.","group":"in (tháng/năm/mùa/buổi)"}]','["multiple_choice","fill_blank","matching","ordering"]',4,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('prepositions-place','Prepositions of place — Giới từ chỉ nơi chốn','Giới từ','A1','Giới từ chỉ nơi chốn cho biết một vật ở ĐÂU. Ba từ nền tảng là in (bên trong), on (trên bề mặt), at (tại một điểm); ngoài ra còn cả một nhóm chỉ vị trí tương quan: under/over, above/below, behind (đằng sau), in front of (đằng trước), next to/beside (bên cạnh), between (giữa hai), near (gần), opposite (đối diện).','[{"label":"in — bên trong","formula":"in + không gian có ranh giới (in the box, in the room)","example":"The cat is in the box."},{"label":"on — trên bề mặt","formula":"on + bề mặt tiếp xúc (on the table, on the wall)","example":"The book is on the table."},{"label":"at — tại một điểm","formula":"at + địa điểm/điểm cụ thể (at home, at the door)","example":"She is at the bus stop."},{"label":"under / over — dưới / trên (không chạm)","formula":"under + vật ở dưới · over + vật ở trên che phủ","example":"The ball is under the chair."},{"label":"above / below — cao hơn / thấp hơn","formula":"above + cao hơn · below + thấp hơn (không cần thẳng hàng)","example":"The clock is above the door."},{"label":"behind / in front of — đằng sau / đằng trước","formula":"behind + phía sau · in front of + phía trước","example":"The car is behind the house."},{"label":"next to / beside — bên cạnh","formula":"next to = beside + ngay kế bên","example":"The bank is next to the shop."},{"label":"between / among — giữa hai / giữa nhiều","formula":"between + HAI vật/người · among + NHIỀU (từ 3 trở lên)","example":"She sits between Tom and Ann."},{"label":"near / opposite — gần / đối diện","formula":"near + ở gần · opposite + ở phía đối diện","example":"The café is opposite the bank."}]','["in the room","on the table","at the door","under the chair","behind the house","in front of the gate","next to the shop","between the two trees","opposite the bank"]','["in — vật nằm bên trong một không gian có ranh giới (phòng, hộp, túi, thành phố): in the bag, in London.","on — vật nằm trên/tiếp xúc một bề mặt (bàn, tường, sàn): on the floor, on the wall.","at — một điểm hoặc địa điểm cụ thể: at home, at school, at the bus stop, at the door.","under/over — thẳng dưới/thẳng trên và thường không chạm: under the table, a lamp over the desk.","above/below — cao hơn/thấp hơn nói chung: the shelf above the sink, her name below mine.","behind/in front of — đằng sau/đằng trước một vật: behind the door, in front of the school.","next to = beside — ngay bên cạnh; between — ở giữa HAI vật; among — ở giữa NHIỀU vật.","near — ở gần (không sát); opposite — ở phía đối diện, mặt đối mặt qua một khoảng."]',NULL,'[{"en":"My pens are in the bag.","vi":"Bút của tôi ở trong túi.","kind":"aff","note":"in + không gian kín."},{"en":"There is a picture on the wall.","vi":"Có một bức tranh trên tường.","kind":"aff","note":"on + bề mặt."},{"en":"The dog is under the table.","vi":"Con chó ở dưới gầm bàn.","kind":"aff","note":"under + phía dưới."},{"en":"A tree is in front of the gate.","vi":"Một cái cây ở đằng trước cổng.","kind":"aff","note":"in front of + đằng trước."},{"en":"The bank is next to the shop.","vi":"Ngân hàng ở ngay cạnh cửa hàng.","kind":"aff","note":"next to = beside."},{"en":"She sits between Tom and Ann.","vi":"Cô ấy ngồi giữa Tom và Ann.","kind":"aff","note":"between + hai người."},{"en":"Is the car behind the house?","vi":"Chiếc xe có ở đằng sau nhà không?","kind":"ques","note":"behind + đằng sau."}]','["Dùng ''in'' thay ''on'' cho bề mặt: sai ''in the table''; đúng ''on the table''.","Dùng ''between'' cho nhiều vật: sai ''between the students''; đúng ''among the students'' (from 3 trở lên).","Quên ''of'' sau ''in front'': sai ''in front the school''; đúng ''in front of the school''.","Nhầm ''behind'' (đằng sau) với ''back of''; và ''opposite'' (đối diện) với ''in front of'' (đằng trước, cùng hướng).","Dùng ''in'' với home/school khi chỉ vị trí chung: thường dùng ''at home'', ''at school''."]','["Ba từ nền: in = bên trong · on = chạm bề mặt · at = tại một điểm.","Cặp đối nhau dễ nhớ: behind ↔ in front of, above ↔ below, under ↔ over.","between = giữa HAI (đếm được hai đầu), among = giữa NHIỀU.","Cụm cố định: at home, at school, at work, in bed, in the corner."]','[{"with":"prepositions-time","note":"Cùng ba từ in/on/at nhưng đây là quy tắc cho NƠI CHỐN, không phải thời gian."},{"with":"prepositions-movement","note":"Nơi chốn nói VỊ TRÍ đứng yên (in/behind/next to); chuyển động nói HƯỚNG đi (to/into/across)."}]','["prepositions-time", "there-is-are"]','["giới từ nơi chốn","giới từ chỉ vị trí","in on at","behind in front of","đằng sau đằng trước","next to between","under over above below","opposite near"]','[{"term":"in","meaning":"ở trong (không gian bao quanh)","example":"The keys are in the box.","group":"in/on/at"},{"term":"on","meaning":"ở trên (bề mặt tiếp xúc)","example":"The book is on the desk.","group":"in/on/at"},{"term":"at","meaning":"ở tại (một điểm, địa điểm)","example":"She is at the door.","group":"in/on/at"},{"term":"under","meaning":"ở dưới (bên dưới, thấp hơn)","example":"The cat is under the table.","group":"Vị trí trên–dưới"},{"term":"over","meaning":"ở phía trên (che phủ, cao hơn)","example":"A lamp hangs over the table.","group":"Vị trí trên–dưới"},{"term":"above","meaning":"ở bên trên (cao hơn, không tiếp xúc)","example":"The clock is above the door.","group":"Vị trí trên–dưới"},{"term":"below","meaning":"ở bên dưới (thấp hơn)","example":"Her name is below mine.","group":"Vị trí trên–dưới"},{"term":"behind","meaning":"ở phía sau","example":"The car is behind the house.","group":"Vị trí xung quanh"},{"term":"in front of","meaning":"ở phía trước","example":"A tree is in front of the gate.","group":"Vị trí xung quanh"},{"term":"next to","meaning":"ngay bên cạnh","example":"The bank is next to the shop.","group":"Vị trí xung quanh"},{"term":"between","meaning":"ở giữa (hai vật/người)","example":"She sits between Tom and Ann.","group":"Vị trí xung quanh"},{"term":"among","meaning":"ở giữa (nhiều vật/người)","example":"He stood among the students.","group":"Vị trí xung quanh"},{"term":"near","meaning":"ở gần","example":"The park is near my school.","group":"Vị trí xung quanh"},{"term":"opposite","meaning":"ở đối diện","example":"The café is opposite the bank.","group":"Vị trí xung quanh"},{"term":"beside","meaning":"ở bên cạnh (kế bên)","example":"He sat beside me.","group":"Vị trí xung quanh"},{"term":"inside","meaning":"ở bên trong","example":"The dog is inside the house.","group":"in/on/at"},{"term":"outside","meaning":"ở bên ngoài","example":"The children play outside the house.","group":"in/on/at"},{"term":"around","meaning":"ở xung quanh, quanh","example":"There is a fence around the garden.","group":"Vị trí xung quanh"}]','["multiple_choice","fill_blank","matching","ordering"]',5,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('adverbs-of-frequency','Adverbs of frequency — Trạng từ tần suất','Tính từ & Trạng từ','A1','Trạng từ tần suất (always, usually, often, sometimes, never...) cho biết mức độ thường xuyên của hành động. Chúng đứng trước động từ thường nhưng đứng sau động từ to be.','[{"label":"Với động từ thường","formula":"S + trạng từ tần suất + V","example":"I always brush my teeth."},{"label":"Với động từ to be","formula":"S + am/is/are + trạng từ tần suất","example":"She is never late."}]','["always (100%)","usually","often","sometimes","rarely","never (0%)"]','["Cho biết một hành động xảy ra thường xuyên đến mức nào.","Thường đi cùng thì hiện tại đơn khi nói về thói quen.","Đứng trước động từ thường, đứng sau động từ to be và trợ động từ."]',NULL,'[{"en":"He always does his homework.","vi":"Cậu ấy luôn luôn làm bài tập.","kind":"aff","note":"always đứng trước động từ thường."},{"en":"We sometimes go to the cinema.","vi":"Thỉnh thoảng chúng tôi đi xem phim.","kind":"aff"},{"en":"I am usually happy.","vi":"Tôi thường vui vẻ.","kind":"aff","note":"usually đứng sau ''am''."},{"en":"They never eat fast food.","vi":"Họ không bao giờ ăn đồ ăn nhanh.","kind":"neg"}]','["Đặt trạng từ sai vị trí: sai ''I brush always my teeth''; đúng ''I always brush my teeth''.","Đặt trạng từ trước to be: sai ''She never is late''; đúng ''She is never late''.","Dùng ''never'' với động từ phủ định: ''never'' đã mang nghĩa phủ định rồi, không cần don''t."]','["Quy tắc vị trí: trước động từ thường, sau động từ to be.","Thứ tự mức độ: always → usually → often → sometimes → rarely → never."]','[{"with":"present-simple","note":"Trạng từ tần suất thường đi cùng hiện tại đơn để diễn tả thói quen."}]','["present-simple", "verb-to-be"]','["trạng từ tần suất","always","usually","sometimes","never","adverbs of frequency"]','[{"term":"always","meaning":"luôn luôn (≈100%)","example":"I always get up early.","group":"Thang tần suất"},{"term":"usually","meaning":"thường xuyên (≈90%)","example":"She usually walks to school.","group":"Thang tần suất"},{"term":"normally","meaning":"thường thì (≈80%)","example":"We normally eat at home.","group":"Thang tần suất"},{"term":"often","meaning":"thường, hay (≈70%)","example":"He often plays football.","group":"Thang tần suất"},{"term":"frequently","meaning":"thường xuyên (≈65%)","example":"They frequently visit us.","group":"Thang tần suất"},{"term":"sometimes","meaning":"thỉnh thoảng (≈50%)","example":"I sometimes eat out.","group":"Thang tần suất"},{"term":"occasionally","meaning":"đôi khi (≈30%)","example":"We occasionally go fishing.","group":"Thang tần suất"},{"term":"rarely","meaning":"hiếm khi (≈10%)","example":"She rarely drinks coffee.","group":"Thang tần suất"},{"term":"seldom","meaning":"ít khi (≈10%)","example":"He seldom talks in class.","group":"Thang tần suất"},{"term":"hardly ever","meaning":"hầu như không bao giờ (≈5%)","example":"I hardly ever watch TV.","group":"Thang tần suất"},{"term":"never","meaning":"không bao giờ (0%)","example":"They never eat meat.","group":"Thang tần suất"}]','["multiple_choice","fill_blank","ordering","matching"]',6,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('some-any','some / any — some/any','Danh từ & Mạo từ','A1','Some và any dùng với danh từ số nhiều và danh từ không đếm được để chỉ một lượng không xác định. Some dùng trong câu khẳng định; any dùng trong câu phủ định và câu hỏi.','[{"label":"some — câu khẳng định","formula":"S + V + some + danh từ","example":"I have some apples."},{"label":"any — câu phủ định","formula":"S + don''t/doesn''t + V + any + danh từ","example":"We don''t have any milk."},{"label":"any — câu hỏi","formula":"Do/Does/Is/Are + S + ... any + danh từ?","example":"Is there any water?"}]',NULL,'["Dùng some trong câu khẳng định để chỉ ''một số/một ít''.","Dùng any trong câu phủ định và câu hỏi.","Dùng some trong lời mời/đề nghị dù là câu hỏi (Would you like some tea?)."]',NULL,'[{"en":"There are some books on the desk.","vi":"Có một vài quyển sách trên bàn.","kind":"aff","note":"some + danh từ số nhiều."},{"en":"I don''t have any money.","vi":"Tôi không có đồng nào cả.","kind":"neg","note":"any trong câu phủ định."},{"en":"Are there any eggs in the fridge?","vi":"Trong tủ lạnh có quả trứng nào không?","kind":"ques","note":"any trong câu hỏi."},{"en":"Would you like some juice?","vi":"Bạn có muốn uống chút nước ép không?","kind":"ques","note":"some trong lời mời."}]','["Dùng ''any'' trong câu khẳng định thường: sai ''I have any pens''; đúng ''I have some pens''.","Dùng ''some'' trong câu phủ định: sai ''I don''t have some money''; đúng ''any money''.","Dùng some/any với danh từ số ít đếm được: nên dùng a/an (a book, không phải some book)."]','["Nhớ nhanh: some → câu khẳng định; any → câu phủ định & câu hỏi.","Ngoại lệ: lời mời/đề nghị dùng some (Would you like some...?)."]','[{"with":"articles-a-an","note":"a/an dùng cho danh từ số ít đếm được; some/any dùng cho số nhiều và không đếm được."}]','["articles-a-an", "plural-nouns", "there-is-are"]','["some any","một vài","câu phủ định","câu hỏi","lượng không xác định"]',NULL,'["multiple_choice","fill_blank","ordering","matching"]',9,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('comparative-adjectives','Comparative adjectives — So sánh hơn (tính từ)','Tính từ & Trạng từ','A1','So sánh hơn dùng để so sánh hai người/vật. Tính từ ngắn thêm -er, tính từ dài dùng more, và thường theo sau là ''than'' (hơn).','[{"label":"Tính từ ngắn (1 âm tiết)","formula":"tính từ + -er + than","example":"Tom is taller than Ben."},{"label":"Tính từ dài (≥2 âm tiết)","formula":"more + tính từ + than","example":"This book is more interesting than that one."},{"label":"Bất quy tắc","formula":"good→better · bad→worse · far→farther","example":"My English is better than before."}]','["than","-er","more"]','["So sánh hai đối tượng để chỉ ra cái nào hơn về một đặc điểm.","Tính từ ngắn (1 âm tiết) thêm -er; tính từ dài (2 âm tiết trở lên) dùng more.","Sau tính từ so sánh hơn thường có ''than'' (hơn)."]','["Hầu hết tính từ ngắn thêm -er: small → smaller.","Tính từ tận cùng -e: chỉ thêm -r: nice → nicer.","Tận cùng phụ âm + y: đổi y thành -ier: happy → happier.","Một âm tiết nguyên âm + phụ âm: gấp đôi phụ âm: big → bigger."]','[{"en":"An elephant is bigger than a cat.","vi":"Con voi to hơn con mèo.","kind":"aff","note":"big → bigger (gấp đôi g)."},{"en":"She is happier than her brother.","vi":"Cô ấy vui vẻ hơn anh trai mình.","kind":"aff","note":"happy → happier."},{"en":"This film is more exciting than that one.","vi":"Bộ phim này hấp dẫn hơn bộ phim kia.","kind":"aff","note":"tính từ dài dùng more."},{"en":"Is a train faster than a car?","vi":"Tàu hỏa có nhanh hơn ô tô không?","kind":"ques"}]','["Dùng cả -er và more: sai ''more bigger''; đúng ''bigger''.","Dùng ''more'' với tính từ ngắn: sai ''more tall''; đúng ''taller''.","Quên ''than'' khi so sánh hai vật: ''taller than'', không phải ''taller from/that''."]','["Tính từ ngắn → -er; tính từ dài → more. Không dùng cả hai cùng lúc.","Học thuộc bất quy tắc: good→better, bad→worse."]',NULL,'["comparatives-superlatives"]','["so sánh hơn","comparative","than","-er","more","bigger taller"]',NULL,'["multiple_choice","fill_blank","matching","ordering"]',10,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('question-words','Question words (Wh-) — Từ để hỏi Wh-','Câu & Cấu trúc','A1','Từ để hỏi Wh- (what, where, when, who, why, how...) đứng đầu câu để hỏi thông tin cụ thể. Sau từ để hỏi thường có trợ động từ hoặc động từ to be.','[{"label":"Với động từ thường","formula":"Wh- + do/does + S + V?","example":"Where do you live?"},{"label":"Với động từ to be","formula":"Wh- + am/is/are + S?","example":"Who is that boy?"}]','["what","where","when","who","why","how","which","whose"]','["Dùng what để hỏi vật/sự việc, where hỏi nơi chốn, when hỏi thời gian.","Dùng who hỏi người, why hỏi lý do, how hỏi cách thức/tình trạng.","Từ để hỏi luôn đứng đầu câu hỏi."]',NULL,'[{"en":"What is your name?","vi":"Tên bạn là gì?","kind":"ques","note":"what + is."},{"en":"Where do you go to school?","vi":"Bạn đi học ở đâu?","kind":"ques","note":"where + do."},{"en":"Why are you sad?","vi":"Sao bạn buồn vậy?","kind":"ques","note":"why hỏi lý do."},{"en":"How old are you?","vi":"Bạn bao nhiêu tuổi?","kind":"ques","note":"how old hỏi tuổi."}]','["Quên trợ động từ do/does: sai ''Where you live?''; đúng ''Where do you live?''.","Dùng cả do và is: sai ''What is do you name?''; đúng ''What is your name?''.","Trả lời sai loại thông tin: ''Where'' hỏi nơi chốn, đừng trả lời thời gian."]','["Ghi nhớ: What (cái gì), Where (ở đâu), When (khi nào), Who (ai), Why (tại sao), How (như thế nào).","Sau Wh- dùng động từ to be HOẶC trợ động từ do/does, không dùng cả hai."]','[{"with":"present-simple","note":"Câu hỏi Wh- với động từ thường dùng do/does giống câu hỏi Yes/No của hiện tại đơn."}]','["present-simple", "verb-to-be"]','["từ để hỏi","wh questions","what where when who why how","câu hỏi"]','[{"term":"what","meaning":"cái gì — hỏi về vật, sự việc, thông tin","example":"What is your name?","group":"Wh- cơ bản"},{"term":"who","meaning":"ai — hỏi về người (làm chủ ngữ)","example":"Who is that girl?","group":"Wh- cơ bản"},{"term":"whom","meaning":"ai (làm tân ngữ) — trang trọng","example":"Whom did you meet?","group":"Wh- cơ bản"},{"term":"whose","meaning":"của ai — hỏi sở hữu","example":"Whose bag is this?","group":"Wh- cơ bản"},{"term":"which","meaning":"cái nào — hỏi khi có lựa chọn giới hạn","example":"Which color do you like?","group":"Wh- cơ bản"},{"term":"where","meaning":"ở đâu — hỏi nơi chốn","example":"Where do you live?","group":"Wh- cơ bản"},{"term":"when","meaning":"khi nào — hỏi thời gian","example":"When is the party?","group":"Wh- cơ bản"},{"term":"why","meaning":"tại sao — hỏi lý do","example":"Why are you late?","group":"Wh- cơ bản"},{"term":"how","meaning":"như thế nào — hỏi cách thức, tình trạng","example":"How are you today?","group":"How + ..."},{"term":"how many","meaning":"bao nhiêu — hỏi số lượng (danh từ đếm được)","example":"How many books do you have?","group":"How + ..."},{"term":"how much","meaning":"bao nhiêu — hỏi lượng (không đếm được) hoặc giá tiền","example":"How much is this shirt?","group":"How + ..."},{"term":"how old","meaning":"bao nhiêu tuổi — hỏi tuổi","example":"How old are you?","group":"How + ..."},{"term":"how long","meaning":"bao lâu / dài bao nhiêu — hỏi thời lượng, độ dài","example":"How long is the movie?","group":"How + ..."},{"term":"how often","meaning":"bao lâu một lần — hỏi tần suất","example":"How often do you exercise?","group":"How + ..."}]','["multiple_choice","fill_blank","matching","ordering"]',11,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('much-many','much / many / how much / how many — Lượng từ cơ bản','Danh từ & Mạo từ','A1','Dùng ''many'' với danh từ đếm được số nhiều (many books) và ''much'' với danh từ không đếm được (much water). Cả hai hay xuất hiện ở câu phủ định và câu hỏi; ở câu khẳng định thường thay bằng ''a lot of / lots of''. Hỏi số lượng: ''How many + đếm được…?'' và ''How much + không đếm được…?'' (cũng hỏi giá: How much is it?).','[{"label":"many + đếm được số nhiều","formula":"many + N(số nhiều)","example":"I don''t have many books."},{"label":"much + không đếm được","formula":"much + N(không đếm được)","example":"There isn''t much water."},{"label":"a lot of / lots of + cả hai","formula":"a lot of / lots of + N","example":"She has a lot of friends. / We drink lots of milk."},{"label":"How many / How much + …?","formula":"How many + N(đếm được)…? / How much + N(không đếm được)…?","example":"How many apples do you want? / How much sugar do you need?"}]','["many","much","a lot of","lots of","how many","how much"]','["''many'' đi với danh từ ĐẾM ĐƯỢC số nhiều: many books, many people, many cars.","''much'' đi với danh từ KHÔNG ĐẾM ĐƯỢC: much water, much money, much time.","''much'' và ''many'' hay dùng ở câu PHỦ ĐỊNH và câu HỎI; ở câu khẳng định thường dùng ''a lot of / lots of''.","''a lot of / lots of'' dùng được cho CẢ HAI loại danh từ, rất hợp câu khẳng định: a lot of books, a lot of water.","''How many + danh từ đếm được…?'' hỏi số lượng đồ đếm được: How many students…?","''How much + danh từ không đếm được…?'' hỏi lượng đồ không đếm được; cũng dùng để hỏi GIÁ TIỀN: How much is it? = Cái này bao nhiêu tiền?"]',NULL,'[{"en":"How many books do you have?","vi":"Bạn có bao nhiêu quyển sách?","kind":"ques","note":"how many + danh từ đếm được."},{"en":"How much water do you drink every day?","vi":"Mỗi ngày bạn uống bao nhiêu nước?","kind":"ques","note":"how much + danh từ không đếm được."},{"en":"There isn''t much milk in the fridge.","vi":"Trong tủ lạnh không có nhiều sữa.","kind":"neg","note":"much ở câu phủ định."},{"en":"I have a lot of friends at school.","vi":"Tôi có rất nhiều bạn ở trường.","kind":"aff","note":"a lot of hợp câu khẳng định."},{"en":"How much is this bag?","vi":"Cái túi này bao nhiêu tiền?","kind":"ques","note":"How much…? hỏi giá tiền."}]','["Sai ''much books''; đúng ''many books'' (books đếm được).","Sai ''many money''; đúng ''much money'' (money không đếm được).","Sai ''How much apples do you want?''; đúng ''How many apples do you want?'' (apples đếm được).","Sai ''I have much friends''; đúng ''I have a lot of friends'' (câu khẳng định nên dùng a lot of)."]','["Nhớ mẹo: MANY đi với cái ĐẾM được (many = number), MUCH đi với cái KHÔNG đếm được (much = amount).","Bí quá thì dùng ''a lot of / lots of'' cho cả hai loại — luôn đúng ở câu khẳng định.","Hỏi giá tiền luôn là ''How much…?'', không bao giờ ''How many…?''."]','[{"with":"quantifiers","note":"quantifiers (A2) là lượng từ rộng hơn: a few/a little/plenty of/enough… phân biệt kỹ hơn much/many cơ bản ở đây."},{"with":"some-any","note":"some/any (A1) chỉ ''một ít/không xác định'' cho cả hai loại; much/many nhấn vào SỐ LƯỢNG NHIỀU và loại danh từ (đếm được/không đếm được)."},{"with":"countable-uncountable","note":"countable/uncountable (A2) là nền tảng phân loại danh từ, quyết định chọn many hay much."}]','["some-any", "countable-uncountable"]','["much","many","how much","how many","a lot of","lots of","lượng từ","đếm được","không đếm được","bao nhiêu","giá tiền"]','[{"term":"many + books","meaning":"many đi với danh từ đếm được số nhiều.","example":"I don''t have many books.","group":"many (+ đếm được số nhiều)"},{"term":"many + people","meaning":"many + danh từ đếm được số nhiều chỉ người.","example":"Were there many people at the party?","group":"many (+ đếm được số nhiều)"},{"term":"many + cars","meaning":"many + danh từ đếm được số nhiều.","example":"There aren''t many cars here.","group":"many (+ đếm được số nhiều)"},{"term":"much + water","meaning":"much đi với danh từ không đếm được.","example":"There isn''t much water left.","group":"much (+ không đếm được)"},{"term":"much + money","meaning":"much + danh từ không đếm được (money).","example":"I don''t have much money.","group":"much (+ không đếm được)"},{"term":"much + time","meaning":"much + danh từ không đếm được (time).","example":"We don''t have much time.","group":"much (+ không đếm được)"},{"term":"a lot of / lots of + đếm được","meaning":"a lot of / lots of dùng cho danh từ đếm được, hợp câu khẳng định.","example":"She has a lot of friends.","group":"a lot of / lots of (+ cả hai)"},{"term":"a lot of / lots of + không đếm được","meaning":"a lot of / lots of dùng cho danh từ không đếm được, hợp câu khẳng định.","example":"We drink lots of milk.","group":"a lot of / lots of (+ cả hai)"},{"term":"How many…?","meaning":"Hỏi số lượng với danh từ đếm được.","example":"How many students are there?","group":"how many / how much (hỏi số lượng)"},{"term":"How much…?","meaning":"Hỏi lượng với danh từ không đếm được.","example":"How much sugar do you need?","group":"how many / how much (hỏi số lượng)"},{"term":"How much is it?","meaning":"Dùng How much…? để hỏi giá tiền.","example":"How much is this T-shirt?","group":"how many / how much (hỏi số lượng)"}]','["multiple_choice","fill_blank","matching","ordering"]',17,'2026-07-22T15:14:06.817Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('past-simple','Past Simple — Quá khứ đơn','Thì động từ','A2','Diễn tả hành động đã xảy ra và kết thúc trong quá khứ, thường có mốc thời gian rõ ràng (yesterday, last week, in 2010).','[{"label":"Khẳng định (động từ thường)","formula":"S + V-ed / V2","example":"I watched TV last night."},{"label":"Phủ định","formula":"S + didn''t + V (nguyên thể)","example":"She didn''t call me."},{"label":"Nghi vấn","formula":"Did + S + V (nguyên thể)?","example":"Did you go to school?"},{"label":"To be (quá khứ)","formula":"S + was/were (not)","example":"They were happy."}]','["yesterday","last night/week/year","ago","in 2010","when I was young"]','["Kể một hành động đã hoàn tất trong quá khứ.","Kể chuỗi sự việc xảy ra lần lượt trong quá khứ.","Nói về thói quen hoặc trạng thái trong quá khứ (nay không còn)."]','["Đa số thêm -ed: work → worked.","Kết thúc -e chỉ thêm -d: like → liked.","Phụ âm + y → -ied: study → studied.","Nhiều động từ bất quy tắc: go → went, see → saw, buy → bought."]','[{"en":"We visited our grandparents last Sunday.","vi":"Chúng tôi đã thăm ông bà vào Chủ nhật tuần trước.","kind":"aff"},{"en":"He didn''t do his homework yesterday.","vi":"Hôm qua cậu ấy đã không làm bài tập.","kind":"neg"},{"en":"Did they enjoy the party?","vi":"Họ có thích bữa tiệc không?","kind":"ques"},{"en":"I was at home two hours ago.","vi":"Hai tiếng trước tôi ở nhà.","kind":"aff","note":"Dùng was/were với to be."}]','["Sai: She didn''t went. → Đúng: She didn''t go (sau didn''t dùng nguyên thể).","Sai: Did you saw it? → Đúng: Did you see it?","Quên đổi động từ bất quy tắc: buyed → bought."]','["Trong câu phủ định/nghi vấn, ''did'' đã mang dấu quá khứ nên động từ chính trở về nguyên thể.","Học thuộc bảng động từ bất quy tắc là chìa khóa của thì này."]','[{"with":"present-perfect","note":"Past Simple có mốc thời gian quá khứ rõ ràng; Present Perfect không nói rõ thời điểm."}]','["past-simple-be"]','["quá khứ đơn","V-ed","did","ago"]','[{"term":"cut → cut → cut","meaning":"cắt","example":"I cut the bread.","group":"Không đổi (V=V2=V3)"},{"term":"put → put → put","meaning":"đặt, để","example":"I put it on the table.","group":"Không đổi (V=V2=V3)"},{"term":"hit → hit → hit","meaning":"đánh, đập","example":"He hit the ball hard.","group":"Không đổi (V=V2=V3)"},{"term":"let → let → let","meaning":"cho phép, để cho","example":"She let me go.","group":"Không đổi (V=V2=V3)"},{"term":"shut → shut → shut","meaning":"đóng lại","example":"I shut the door.","group":"Không đổi (V=V2=V3)"},{"term":"cost → cost → cost","meaning":"có giá, tốn (tiền)","example":"The book cost ten dollars.","group":"Không đổi (V=V2=V3)"},{"term":"hurt → hurt → hurt","meaning":"làm đau, đau","example":"I hurt my leg yesterday.","group":"Không đổi (V=V2=V3)"},{"term":"read → read → read","meaning":"đọc (V2/V3 đọc là /red/)","example":"I read a book last night.","group":"Không đổi (V=V2=V3)"},{"term":"buy → bought → bought","meaning":"mua","example":"I bought a new phone.","group":"V2 = V3"},{"term":"bring → brought → brought","meaning":"mang, đem lại","example":"She brought some food.","group":"V2 = V3"},{"term":"teach → taught → taught","meaning":"dạy","example":"He taught us English.","group":"V2 = V3"},{"term":"catch → caught → caught","meaning":"bắt, chụp lấy","example":"I caught the ball.","group":"V2 = V3"},{"term":"think → thought → thought","meaning":"nghĩ, suy nghĩ","example":"I thought about you.","group":"V2 = V3"},{"term":"feel → felt → felt","meaning":"cảm thấy","example":"I felt tired last night.","group":"V2 = V3"},{"term":"keep → kept → kept","meaning":"giữ","example":"She kept the letter.","group":"V2 = V3"},{"term":"sleep → slept → slept","meaning":"ngủ","example":"I slept well last night.","group":"V2 = V3"},{"term":"find → found → found","meaning":"tìm thấy","example":"I found my keys.","group":"V2 = V3"},{"term":"make → made → made","meaning":"làm, chế tạo","example":"She made a cake.","group":"V2 = V3"},{"term":"say → said → said","meaning":"nói","example":"He said hello.","group":"V2 = V3"},{"term":"pay → paid → paid","meaning":"trả (tiền)","example":"I paid for lunch.","group":"V2 = V3"},{"term":"sell → sold → sold","meaning":"bán","example":"They sold their car.","group":"V2 = V3"},{"term":"tell → told → told","meaning":"kể, bảo","example":"She told me a story.","group":"V2 = V3"},{"term":"sit → sat → sat","meaning":"ngồi","example":"I sat on the chair.","group":"V2 = V3"},{"term":"stand → stood → stood","meaning":"đứng","example":"We stood at the door.","group":"V2 = V3"},{"term":"win → won → won","meaning":"thắng, giành được","example":"Our team won the game.","group":"V2 = V3"},{"term":"meet → met → met","meaning":"gặp","example":"I met her yesterday.","group":"V2 = V3"},{"term":"go → went → gone","meaning":"đi","example":"I went home.","group":"Ba dạng khác nhau"},{"term":"do → did → done","meaning":"làm","example":"I did my homework.","group":"Ba dạng khác nhau"},{"term":"see → saw → seen","meaning":"nhìn, thấy","example":"I saw a bird.","group":"Ba dạng khác nhau"},{"term":"eat → ate → eaten","meaning":"ăn","example":"I ate breakfast.","group":"Ba dạng khác nhau"},{"term":"give → gave → given","meaning":"cho, tặng","example":"She gave me a gift.","group":"Ba dạng khác nhau"},{"term":"take → took → taken","meaning":"lấy, cầm","example":"I took the bus.","group":"Ba dạng khác nhau"},{"term":"write → wrote → written","meaning":"viết","example":"I wrote a letter.","group":"Ba dạng khác nhau"},{"term":"speak → spoke → spoken","meaning":"nói (chuyện)","example":"He spoke slowly.","group":"Ba dạng khác nhau"},{"term":"drive → drove → driven","meaning":"lái xe","example":"She drove to work.","group":"Ba dạng khác nhau"},{"term":"break → broke → broken","meaning":"làm vỡ, làm gãy","example":"I broke the cup.","group":"Ba dạng khác nhau"},{"term":"choose → chose → chosen","meaning":"chọn","example":"I chose the red one.","group":"Ba dạng khác nhau"},{"term":"know → knew → known","meaning":"biết","example":"I knew the answer.","group":"Ba dạng khác nhau"},{"term":"grow → grew → grown","meaning":"lớn lên, trồng","example":"The plant grew fast.","group":"Ba dạng khác nhau"},{"term":"begin → began → begun","meaning":"bắt đầu","example":"The film began late.","group":"Ba dạng khác nhau"},{"term":"drink → drank → drunk","meaning":"uống","example":"I drank some water.","group":"Ba dạng khác nhau"},{"term":"swim → swam → swum","meaning":"bơi","example":"We swam in the sea.","group":"Ba dạng khác nhau"},{"term":"ride → rode → ridden","meaning":"cưỡi, đạp (xe)","example":"I rode my bike.","group":"Ba dạng khác nhau"},{"term":"wear → wore → worn","meaning":"mặc, đeo","example":"She wore a blue dress.","group":"Ba dạng khác nhau"}]','["multiple_choice","fill_blank","matching","ordering"]',1,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('future-will','Future ''will'' — Tương lai đơn (will)','Thì động từ','A2','Dùng ''will'' để nói về tương lai: quyết định tức thời, lời hứa, dự đoán, hoặc đề nghị giúp đỡ.','[{"label":"Khẳng định","formula":"S + will + V (nguyên thể)","example":"I will help you."},{"label":"Phủ định","formula":"S + won''t + V","example":"She won''t come."},{"label":"Nghi vấn","formula":"Will + S + V?","example":"Will you join us?"}]','["tomorrow","next week/month","soon","in the future","I think","probably"]','["Quyết định ngay lúc nói (không định trước).","Lời hứa, đề nghị giúp đỡ.","Dự đoán về tương lai (thường có I think, probably, maybe)."]','["will not viết tắt là won''t.","''ll dùng cho mọi ngôi: I''ll, you''ll, she''ll..."]','[{"en":"It''s cold. I''ll close the window.","vi":"Trời lạnh. Tôi sẽ đóng cửa sổ.","kind":"aff","note":"Quyết định tức thời."},{"en":"I think it will rain tomorrow.","vi":"Tôi nghĩ ngày mai trời sẽ mưa.","kind":"aff","note":"Dự đoán."},{"en":"She won''t be late again.","vi":"Cô ấy sẽ không trễ nữa.","kind":"neg"},{"en":"Will you help me with this?","vi":"Bạn giúp mình việc này nhé?","kind":"ques"}]','["Sai: I will to go. → Đúng: I will go (không có ''to'' sau will).","Sai: She wills come. → Đúng: She will come (will không chia theo ngôi).","Dùng will cho kế hoạch đã định trước; nên dùng ''be going to''."]','["will + động từ nguyên thể, không thêm -s và không có ''to''.","Quyết định ngay lúc nói → will; kế hoạch đã tính trước → be going to."]','[{"with":"future-going-to","note":"will cho quyết định tức thời/dự đoán; be going to cho dự định đã lên kế hoạch hoặc dấu hiệu hiện tại."}]','["future-going-to"]','["tương lai đơn","will","won''t","dự đoán"]',NULL,'["multiple_choice","fill_blank","matching","ordering"]',3,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('future-going-to','''be going to'' — Dự định (be going to)','Thì động từ','A2','Dùng ''be going to'' cho dự định, kế hoạch đã quyết định từ trước, hoặc dự đoán dựa vào dấu hiệu hiện tại.','[{"label":"Khẳng định","formula":"S + am/is/are + going to + V","example":"I am going to travel."},{"label":"Phủ định","formula":"S + am/is/are + not + going to + V","example":"He isn''t going to come."},{"label":"Nghi vấn","formula":"Am/Is/Are + S + going to + V?","example":"Are you going to study?"}]','["tonight","tomorrow","next week","this weekend","look!","look at those clouds"]','["Dự định, kế hoạch đã quyết định trước lúc nói.","Dự đoán dựa trên bằng chứng/dấu hiệu đang thấy ngay bây giờ."]',NULL,'[{"en":"We are going to visit Da Nang next month.","vi":"Tháng sau chúng tôi sẽ đi thăm Đà Nẵng.","kind":"aff","note":"Kế hoạch đã định."},{"en":"Look at those clouds! It''s going to rain.","vi":"Nhìn mây kìa! Trời sắp mưa.","kind":"aff","note":"Dự đoán theo dấu hiệu."},{"en":"She isn''t going to buy a new phone.","vi":"Cô ấy sẽ không mua điện thoại mới.","kind":"neg"},{"en":"Are you going to watch the match tonight?","vi":"Tối nay bạn sẽ xem trận đấu chứ?","kind":"ques"}]','["Sai: I am going to shopping. → Đúng: I am going to go shopping (sau ''going to'' là động từ nguyên thể).","Quên chia ''be'' theo chủ ngữ: He are going to → He is going to.","Sai: I going to play. → Đúng: I am going to play (thiếu ''am'')."]','["Nhớ chia đúng be: I am / he-she-it is / you-we-they are.","Kế hoạch đã tính trước → be going to; quyết định ngay lúc nói → will."]','[{"with":"future-will","note":"be going to cho dự định đã lên kế hoạch; will cho quyết định tức thời."}]','["future-will"]','["be going to","dự định","kế hoạch","tương lai"]',NULL,'["multiple_choice","fill_blank","matching","ordering"]',4,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('present-perfect','Present Perfect — Hiện tại hoàn thành','Thì động từ','A2','Nối quá khứ với hiện tại: hành động vừa xảy ra, trải nghiệm, hoặc việc bắt đầu trong quá khứ và còn kéo dài đến hiện tại. Không nói rõ thời điểm.','[{"label":"Khẳng định","formula":"S + have/has + V3 (past participle)","example":"I have finished my homework."},{"label":"Phủ định","formula":"S + haven''t/hasn''t + V3","example":"She hasn''t eaten yet."},{"label":"Nghi vấn","formula":"Have/Has + S + V3?","example":"Have you seen this film?"}]','["already","yet","just","ever","never","since","for","recently"]','["Hành động vừa mới xảy ra (just).","Trải nghiệm cho đến hiện tại (ever/never).","Hành động bắt đầu trong quá khứ và còn tiếp tục (for/since).","Hành động đã/chưa hoàn thành tính đến bây giờ (already/yet)."]','["has dùng với he/she/it; have dùng với I/you/we/they.","V3: worked, gone, seen, done, been... (nhiều từ bất quy tắc).","for + khoảng thời gian (for two years); since + mốc thời gian (since 2020)."]','[{"en":"I have just finished my lunch.","vi":"Tôi vừa ăn trưa xong.","kind":"aff","note":"just = vừa mới."},{"en":"She has never been to Japan.","vi":"Cô ấy chưa bao giờ đến Nhật.","kind":"aff","note":"never = chưa từng."},{"en":"We haven''t finished the project yet.","vi":"Chúng tôi vẫn chưa xong dự án.","kind":"neg"},{"en":"Have you ever eaten sushi?","vi":"Bạn đã bao giờ ăn sushi chưa?","kind":"ques"}]','["Sai: I have finished it yesterday. → Đúng: I finished it yesterday (có ''yesterday'' phải dùng Past Simple).","Sai: She have gone. → Đúng: She has gone (he/she/it dùng has).","Nhầm V2 với V3: I have saw → I have seen."]','["Không dùng Present Perfect với mốc thời gian quá khứ cụ thể (yesterday, last week).","yet dùng trong câu phủ định/nghi vấn; already dùng trong câu khẳng định."]','[{"with":"past-simple","note":"Present Perfect không nói rõ thời điểm và liên quan hiện tại; Past Simple có mốc quá khứ xác định."}]','["past-simple"]','["hiện tại hoàn thành","have/has V3","already","yet","since","for"]',NULL,'["multiple_choice","fill_blank","matching","ordering"]',5,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('comparatives-superlatives','Comparatives & Superlatives — So sánh hơn/nhất','Tính từ & Trạng từ','A2','So sánh hơn (comparative) dùng khi so 2 đối tượng; so sánh nhất (superlative) dùng khi so 3 đối tượng trở lên.','[{"label":"So sánh hơn (tính từ ngắn)","formula":"adj + -er + than","example":"Tom is taller than Ben."},{"label":"So sánh hơn (tính từ dài)","formula":"more + adj + than","example":"This book is more interesting than that one."},{"label":"So sánh nhất (tính từ ngắn)","formula":"the + adj + -est","example":"She is the tallest in class."},{"label":"So sánh nhất (tính từ dài)","formula":"the most + adj","example":"It is the most beautiful city."}]','["than","the ... -est","the most","in/of + nhóm"]','["So sánh hơn: so sánh giữa 2 người/vật, luôn dùng ''than''.","So sánh nhất: nêu đối tượng vượt trội nhất trong một nhóm (từ 3 trở lên), luôn có ''the''."]','["Tính từ 1 âm tiết: thêm -er/-est (small → smaller → smallest).","Kết thúc phụ âm + y: đổi y → i (happy → happier → happiest).","Nguyên âm + phụ âm cuối: gấp đôi phụ âm (big → bigger → biggest).","Bất quy tắc: good → better → best; bad → worse → worst; far → farther/further."]','[{"en":"My bag is heavier than yours.","vi":"Cặp của tôi nặng hơn cặp của bạn.","kind":"aff"},{"en":"This is the most expensive watch in the shop.","vi":"Đây là chiếc đồng hồ đắt nhất trong cửa hàng.","kind":"aff"},{"en":"English isn''t more difficult than Maths for me.","vi":"Với tôi, tiếng Anh không khó hơn Toán.","kind":"neg"},{"en":"Who is the best student in your class?","vi":"Ai là học sinh giỏi nhất lớp bạn?","kind":"ques"}]','["Sai: more taller / most tallest → Đúng: taller / tallest (không dùng cả hai cách cùng lúc).","Quên ''the'' trước so sánh nhất: She is tallest → She is the tallest.","Sai: gooder / more good → Đúng: better (bất quy tắc)."]','["Tính từ 1 âm tiết thường dùng -er/-est; tính từ 2 âm tiết trở lên thường dùng more/most.","So sánh nhất luôn đi với ''the''."]',NULL,NULL,'["so sánh hơn","so sánh nhất","-er","more","the -est","the most"]','[{"term":"good → better → best","meaning":"tốt / tốt hơn / tốt nhất","example":"This is the best day.","group":"Bất quy tắc"},{"term":"bad → worse → worst","meaning":"tệ / tệ hơn / tệ nhất","example":"Today is worse than yesterday.","group":"Bất quy tắc"},{"term":"far → farther/further → farthest/furthest","meaning":"xa / xa hơn / xa nhất","example":"My house is farther than yours.","group":"Bất quy tắc"},{"term":"little → less → least","meaning":"ít / ít hơn / ít nhất","example":"I have less time than you.","group":"Bất quy tắc"},{"term":"many/much → more → most","meaning":"nhiều / nhiều hơn / nhiều nhất","example":"She has more books than me.","group":"Bất quy tắc"},{"term":"tall → taller → tallest","meaning":"cao / cao hơn / cao nhất","example":"He is the tallest boy.","group":"Tính từ ngắn + -er/-est"},{"term":"big → bigger → biggest","meaning":"to / to hơn / to nhất (gấp đôi phụ âm)","example":"This is the biggest room.","group":"Tính từ ngắn + -er/-est"},{"term":"nice → nicer → nicest","meaning":"đẹp, dễ chịu / hơn / nhất (bỏ e thêm -r)","example":"She is nicer than him.","group":"Tính từ ngắn + -er/-est"},{"term":"old → older → oldest","meaning":"già, cũ / hơn / nhất","example":"He is older than me.","group":"Tính từ ngắn + -er/-est"},{"term":"cheap → cheaper → cheapest","meaning":"rẻ / rẻ hơn / rẻ nhất","example":"This bag is cheaper.","group":"Tính từ ngắn + -er/-est"},{"term":"happy → happier → happiest","meaning":"vui / vui hơn / vui nhất","example":"I am happier today.","group":"-y → -ier/-iest"},{"term":"easy → easier → easiest","meaning":"dễ / dễ hơn / dễ nhất","example":"This test is easier.","group":"-y → -ier/-iest"},{"term":"early → earlier → earliest","meaning":"sớm / sớm hơn / sớm nhất","example":"I came earlier than you.","group":"-y → -ier/-iest"},{"term":"expensive → more expensive → most expensive","meaning":"đắt / đắt hơn / đắt nhất","example":"This car is more expensive.","group":"Tính từ dài dùng more/most"},{"term":"beautiful → more beautiful → most beautiful","meaning":"đẹp / đẹp hơn / đẹp nhất","example":"She is the most beautiful.","group":"Tính từ dài dùng more/most"},{"term":"important → more important → most important","meaning":"quan trọng / hơn / nhất","example":"Health is more important.","group":"Tính từ dài dùng more/most"},{"term":"difficult → more difficult → most difficult","meaning":"khó / khó hơn / khó nhất","example":"This is the most difficult part.","group":"Tính từ dài dùng more/most"},{"term":"interesting → more interesting → most interesting","meaning":"thú vị / hơn / nhất","example":"This book is more interesting.","group":"Tính từ dài dùng more/most"}]','["multiple_choice","fill_blank","matching","ordering"]',6,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('countable-uncountable','Countable / Uncountable nouns — Danh từ đếm được/không đếm được','Danh từ & Mạo từ','A2','Danh từ đếm được có số ít/số nhiều (a book, two books); danh từ không đếm được không có số nhiều và không dùng a/an (water, rice, money).','[{"label":"Đếm được số ít","formula":"a/an + N (số ít)","example":"an apple, a chair"},{"label":"Đếm được số nhiều","formula":"N + -s/-es","example":"two apples, three boxes"},{"label":"Không đếm được","formula":"N (không -s, không a/an)","example":"water, information, rice"}]','["a/an","some","any","much","many","a piece of","a glass of"]','["Danh từ đếm được: có thể đếm 1, 2, 3... và có dạng số nhiều.","Danh từ không đếm được: chất lỏng, hạt nhỏ, khái niệm trừu tượng — không dùng a/an, luôn ở số ít.","Muốn đếm danh từ không đếm được, dùng đơn vị: a glass of water, a piece of paper."]',NULL,'[{"en":"I need some water and two eggs.","vi":"Tôi cần một ít nước và hai quả trứng.","kind":"aff","note":"water không đếm được; eggs đếm được."},{"en":"There isn''t much sugar in my coffee.","vi":"Cà phê của tôi không có nhiều đường.","kind":"neg"},{"en":"Can I have a piece of cake?","vi":"Cho tôi một miếng bánh được không?","kind":"ques","note":"Dùng đơn vị đếm cho cake."},{"en":"She gave me some useful information.","vi":"Cô ấy cho tôi vài thông tin hữu ích.","kind":"aff","note":"information luôn không đếm được."}]','["Sai: a water, two informations → Đúng: some water, some information.","Sai: many money → Đúng: much money (money không đếm được).","Sai: These furnitures → Đúng: This furniture (furniture không đếm được)."]','["Một số danh từ hay bị nhầm là đếm được nhưng không đếm được: information, advice, news, furniture, money, homework.","Không đếm được luôn đi với động từ số ít: The news is good."]','[{"with":"quantifiers","note":"much dùng với không đếm được; many dùng với đếm được số nhiều."}]','[]','["đếm được","không đếm được","countable","uncountable","a piece of"]','[{"term":"water","meaning":"nước; đếm bằng ''a glass of water''","example":"I drink a lot of water.","group":"Chất lỏng/thực phẩm"},{"term":"milk","meaning":"sữa; ''a glass/carton of milk''","example":"There is some milk in the fridge.","group":"Chất lỏng/thực phẩm"},{"term":"coffee","meaning":"cà phê; ''a cup of coffee''","example":"I need some coffee.","group":"Chất lỏng/thực phẩm"},{"term":"tea","meaning":"trà; ''a cup of tea''","example":"She drinks tea every day.","group":"Chất lỏng/thực phẩm"},{"term":"bread","meaning":"bánh mì; ''a loaf/slice of bread''","example":"I eat bread for breakfast.","group":"Chất lỏng/thực phẩm"},{"term":"rice","meaning":"cơm, gạo; ''a bowl of rice''","example":"We eat rice every day.","group":"Chất lỏng/thực phẩm"},{"term":"sugar","meaning":"đường; ''a spoon of sugar''","example":"I don''t take sugar.","group":"Chất lỏng/thực phẩm"},{"term":"food","meaning":"thức ăn; dùng much/little","example":"There isn''t much food left.","group":"Chất lỏng/thực phẩm"},{"term":"information","meaning":"thông tin; ''a piece of information''","example":"I need some information.","group":"Trừu tượng/thông tin"},{"term":"advice","meaning":"lời khuyên; ''a piece of advice''","example":"She gave me good advice.","group":"Trừu tượng/thông tin"},{"term":"news","meaning":"tin tức; luôn số ít","example":"The news is very good.","group":"Trừu tượng/thông tin"},{"term":"knowledge","meaning":"kiến thức; dùng much/little","example":"He has a lot of knowledge.","group":"Trừu tượng/thông tin"},{"term":"homework","meaning":"bài tập về nhà; ''a piece of homework''","example":"I have a lot of homework.","group":"Trừu tượng/thông tin"},{"term":"work","meaning":"công việc; ''a piece of work''","example":"I have too much work.","group":"Trừu tượng/thông tin"},{"term":"time","meaning":"thời gian; dùng much/little","example":"We don''t have much time.","group":"Trừu tượng/thông tin"},{"term":"music","meaning":"âm nhạc; dùng much/some","example":"I like listening to music.","group":"Trừu tượng/thông tin"},{"term":"weather","meaning":"thời tiết; luôn không đếm","example":"The weather is nice today.","group":"Trừu tượng/thông tin"},{"term":"traffic","meaning":"giao thông; dùng much/heavy","example":"There is a lot of traffic.","group":"Trừu tượng/thông tin"},{"term":"money","meaning":"tiền; đếm bằng đơn vị tiền tệ","example":"I don''t have much money.","group":"Không đếm được (khối/chất)"},{"term":"furniture","meaning":"đồ đạc; ''a piece of furniture''","example":"We bought new furniture.","group":"Không đếm được (khối/chất)"},{"term":"luggage","meaning":"hành lý; ''a piece of luggage''","example":"My luggage is heavy.","group":"Không đếm được (khối/chất)"},{"term":"paper","meaning":"giấy; ''a sheet/piece of paper''","example":"I need some paper.","group":"Không đếm được (khối/chất)"}]','["multiple_choice","fill_blank","matching","ordering"]',7,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('first-conditional','First Conditional — Câu điều kiện loại 1','Mệnh đề','A2','Nói về điều kiện có thật, có khả năng xảy ra ở hiện tại/tương lai và kết quả của nó. Mệnh đề If dùng hiện tại đơn, mệnh đề chính dùng will.','[{"label":"Cấu trúc cơ bản","formula":"If + S + V (hiện tại đơn), S + will + V","example":"If it rains, I will stay home."},{"label":"Đảo vế","formula":"S + will + V + if + S + V (hiện tại đơn)","example":"I will stay home if it rains."},{"label":"Phủ định kết quả","formula":"If + S + V, S + won''t + V","example":"If you don''t hurry, you won''t catch the bus."}]','["if","unless","when","as soon as"]','["Diễn tả điều kiện có thật, có khả năng xảy ra trong tương lai và hệ quả của nó.","Dùng cho lời hứa, cảnh báo, kế hoạch phụ thuộc điều kiện."]','["Mệnh đề If: KHÔNG dùng will, dùng hiện tại đơn.","Khi mệnh đề If đứng trước, có dấu phẩy ngăn cách; khi đứng sau thì không cần phẩy."]','[{"en":"If you study hard, you will pass the exam.","vi":"Nếu bạn học chăm, bạn sẽ đậu kỳ thi.","kind":"aff"},{"en":"If she doesn''t call, I won''t wait.","vi":"Nếu cô ấy không gọi, tôi sẽ không đợi.","kind":"neg"},{"en":"What will you do if it rains tomorrow?","vi":"Bạn sẽ làm gì nếu mai trời mưa?","kind":"ques"},{"en":"We will be late if we don''t leave now.","vi":"Chúng ta sẽ trễ nếu không đi ngay bây giờ.","kind":"aff"}]','["Sai: If it will rain, I will stay. → Đúng: If it rains, I will stay (mệnh đề If không dùng will).","Quên chia -s ở hiện tại đơn: If he study → If he studies.","Nhầm với điều kiện loại 2 (dùng cho tình huống không có thật)."]','["Nhớ quy tắc: If + hiện tại đơn, ... will + nguyên thể.","''unless'' = ''if... not'' (nếu... không)."]','[{"with":"future-will","note":"First Conditional dùng will ở mệnh đề chính; mệnh đề If phải dùng hiện tại đơn."}]','["future-will"]','["điều kiện loại 1","if","will","first conditional"]',NULL,'["multiple_choice","fill_blank","matching","ordering"]',9,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('have-to','have to / don''t have to — have to (bắt buộc)','Động từ khuyết thiếu','A2','''have to'' diễn tả sự bắt buộc, nghĩa vụ (thường do quy định bên ngoài). ''don''t have to'' nghĩa là không cần thiết (không bắt buộc).','[{"label":"Khẳng định","formula":"S + have/has to + V","example":"I have to go to school."},{"label":"Phủ định","formula":"S + don''t/doesn''t have to + V","example":"She doesn''t have to work today."},{"label":"Nghi vấn","formula":"Do/Does + S + have to + V?","example":"Do you have to wear a uniform?"}]','["must","rules","necessary","obligation"]','["have to: diễn tả sự bắt buộc, nghĩa vụ (thường do quy định, hoàn cảnh bên ngoài).","don''t have to: không cần thiết, không bắt buộc (được tự do lựa chọn)."]','["he/she/it dùng ''has to''; các ngôi còn lại dùng ''have to''.","Câu phủ định/nghi vấn dùng trợ động từ do/does."]','[{"en":"Students have to wear a uniform at this school.","vi":"Học sinh phải mặc đồng phục ở trường này.","kind":"aff","note":"Bắt buộc theo quy định."},{"en":"You don''t have to pay; it''s free.","vi":"Bạn không cần trả tiền; nó miễn phí.","kind":"neg","note":"Không cần thiết."},{"en":"Does he have to get up early?","vi":"Cậu ấy có phải dậy sớm không?","kind":"ques"},{"en":"She has to finish her report today.","vi":"Hôm nay cô ấy phải hoàn thành báo cáo.","kind":"aff"}]','["Sai: She have to go. → Đúng: She has to go.","Nhầm ''don''t have to'' (không cần) với ''mustn''t'' (bị cấm) — hai nghĩa khác hẳn nhau.","Sai: Do you have to going? → Đúng: Do you have to go?"]','["don''t have to = không bắt buộc (được phép không làm); mustn''t = cấm (không được làm).","have to giống must về nghĩa ''phải'', nhưng have to chia được ở nhiều thì và ngôi."]','[{"with":"should","note":"have to là bắt buộc/nghĩa vụ mạnh; should chỉ là lời khuyên nhẹ nhàng."}]','["should"]','["have to","bắt buộc","nghĩa vụ","don''t have to"]',NULL,'["multiple_choice","fill_blank","ordering","matching"]',10,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('should','should / shouldn''t — should (lời khuyên)','Động từ khuyết thiếu','A2','''should'' dùng để đưa ra lời khuyên hoặc gợi ý điều nên làm; ''shouldn''t'' khuyên điều không nên làm.','[{"label":"Khẳng định","formula":"S + should + V (nguyên thể)","example":"You should drink more water."},{"label":"Phủ định","formula":"S + shouldn''t + V","example":"You shouldn''t eat too much candy."},{"label":"Nghi vấn","formula":"Should + S + V?","example":"Should I call the doctor?"}]','["advice","I think you should","maybe you should"]','["Đưa ra lời khuyên hoặc gợi ý điều nên/không nên làm.","Hỏi ý kiến, xin lời khuyên (Should I...?)."]','["should + động từ nguyên thể (không ''to'', không -s).","shouldn''t = should not."]','[{"en":"You should see a doctor if you feel sick.","vi":"Bạn nên đi khám bác sĩ nếu thấy mệt.","kind":"aff"},{"en":"He shouldn''t stay up so late.","vi":"Cậu ấy không nên thức khuya như vậy.","kind":"neg"},{"en":"Should we take an umbrella?","vi":"Chúng ta có nên mang ô không?","kind":"ques"},{"en":"I think you should study for the test.","vi":"Tôi nghĩ bạn nên ôn bài cho bài kiểm tra.","kind":"aff"}]','["Sai: You should to go. → Đúng: You should go (không có ''to'').","Sai: She shoulds come. → Đúng: She should come (should không chia theo ngôi).","Sai: You should going. → Đúng: You should go (dùng nguyên thể)."]','["should là lời khuyên nhẹ; must/have to mới là bắt buộc.","Câu hỏi xin lời khuyên rất hay dùng: What should I do?"]','[{"with":"have-to","note":"should là lời khuyên (nên); have to là bắt buộc (phải)."}]','["have-to"]','["should","lời khuyên","nên","shouldn''t"]',NULL,'["multiple_choice","fill_blank","matching","ordering"]',11,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('may-might-possibility','may / might (possibility) — may/might chỉ khả năng','Động từ khuyết thiếu','A2','''may'' và ''might'' + động từ nguyên thể diễn tả một khả năng ở hiện tại hoặc tương lai (có thể xảy ra, nhưng không chắc). ''might'' thường nghe hơi kém chắc chắn hơn ''may'' một chút.','[{"label":"Khẳng định","formula":"S + may/might + V (nguyên thể)","example":"It may rain later."},{"label":"Phủ định","formula":"S + may not / might not + V","example":"She might not come to the party."},{"label":"Khả năng đang diễn ra","formula":"S + may/might + be + V-ing","example":"He might be sleeping now."}]','["may","might","maybe","perhaps","possibly","it''s possible"]','["Diễn tả khả năng ở hiện tại hoặc tương lai mà người nói không chắc chắn.","may và might gần như thay thế được cho nhau ở nghĩa khả năng; might nghe kém chắc hơn chút.","Phủ định: may not / might not = có lẽ không (KHÔNG viết tắt ''mayn''t'').","Sau may/might luôn là động từ nguyên thể không ''to''."]','["may/might không chia theo ngôi (he may, she might).","may not / might not thường KHÔNG viết tắt trong nghĩa khả năng."]','[{"en":"Take an umbrella — it may rain this afternoon.","vi":"Mang theo ô đi — chiều nay trời có thể mưa.","kind":"aff","note":"Khả năng tương lai."},{"en":"She might come to the party, but she isn''t sure.","vi":"Cô ấy có lẽ sẽ đến bữa tiệc, nhưng chưa chắc.","kind":"aff"},{"en":"I may not have time tomorrow.","vi":"Ngày mai có lẽ tôi không có thời gian.","kind":"neg","note":"may not = có lẽ không."},{"en":"He isn''t answering; he might be busy.","vi":"Anh ấy không trả lời; có lẽ đang bận.","kind":"aff","note":"might be + V-ing: khả năng đang xảy ra."}]','["Sai: It may to rain. → Đúng: It may rain (không có ''to'' sau may/might).","Sai: She mights come. → Đúng: She might come (might không chia theo ngôi).","Nhầm ''maybe'' (trạng từ, 1 từ, đầu câu: Maybe she is tired) với ''may be'' (may + be: She may be tired)."]','["Muốn nói ''có lẽ'' một cách đơn giản, có thể thay bằng ''Maybe...'' + hiện tại đơn: ''Maybe it will rain''.","may/might ở đây chỉ KHẢ NĂNG; lên band B1 sẽ học thêm cách dùng để SUY ĐOÁN có bằng chứng (modals-deduction)."]','[{"with":"modals-deduction","note":"Ở A2, may/might chỉ nêu khả năng chung chung. Ở B1 (modals-deduction), might/may/could/must/can''t dùng để suy đoán dựa trên bằng chứng cụ thể."}]','[]','["may","might","khả năng","possibility","maybe","perhaps"]',NULL,'["multiple_choice","fill_blank","matching","ordering"]',18,'2026-07-17T09:37:03.819Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('present-perfect-vs-past-simple','Present Perfect vs Past Simple — Phân biệt HTHT & QKĐ','Thì động từ','B1','Hiện tại hoàn thành (have/has + V3) nối quá khứ với hiện tại — thời điểm không rõ hoặc còn ảnh hưởng bây giờ. Quá khứ đơn (V2/V-ed) nói về việc đã kết thúc, gắn mốc thời gian cụ thể trong quá khứ.','[{"label":"Hiện tại hoàn thành","formula":"S + have/has + V3","example":"I have visited London twice."},{"label":"Quá khứ đơn","formula":"S + V2/V-ed","example":"I visited London in 2019."}]','["HTHT: already","yet","just","ever","never","so far","recently","since","for","QKĐ: yesterday","ago","last week/year","in 2019","when I was young"]','["Dùng HTHT khi thời điểm KHÔNG quan trọng/không nói rõ, hoặc việc còn liên quan hiện tại.","Dùng QKĐ khi có mốc thời gian đã qua và kết thúc rõ ràng.","Có ''ago'', ''yesterday'', ''last...'' hay câu hỏi ''When...?'' → luôn QKĐ, không dùng HTHT.","Trải nghiệm sống trong đời (chưa nói lúc nào) → HTHT; kể chi tiết một lần cụ thể → QKĐ."]',NULL,'[{"en":"I have lost my keys, so I can''t get in.","vi":"Tôi làm mất chìa khóa rồi nên không vào được.","note":"HTHT — hậu quả còn ở hiện tại."},{"en":"I lost my keys yesterday.","vi":"Hôm qua tôi làm mất chìa khóa.","kind":"aff","note":"QKĐ — có mốc ''yesterday''."},{"en":"Have you ever eaten sushi?","vi":"Bạn đã bao giờ ăn sushi chưa?","kind":"ques","note":"HTHT — trải nghiệm."},{"en":"She has just finished her homework.","vi":"Cô ấy vừa làm xong bài tập.","note":"HTHT với ''just''."},{"en":"We didn''t watch the film last night.","vi":"Tối qua chúng tôi không xem phim đó.","kind":"neg","note":"QKĐ — ''last night''."}]','["SAI: ''I have seen him yesterday.'' → ĐÚNG: ''I saw him yesterday.'' (có ''yesterday'' phải dùng QKĐ).","Quên chia have/has đúng ngôi: he/she/it dùng ''has''.","Dùng QKĐ khi việc còn tiếp tục/còn ảnh hưởng: ''I live here for 5 years'' → ''I have lived here for 5 years.''"]','["Mẹo: hỏi ''có nói RÕ lúc nào không?'' — có mốc quá khứ → QKĐ; không rõ/còn liên quan → HTHT.","''since + mốc'' (since 2020) và ''for + khoảng'' (for 3 years) hầu như luôn đi với HTHT."]','[{"with":"present-perfect-continuous","note":"HTHT nhấn kết quả/số lần; HTHT tiếp diễn nhấn tính liên tục của hành động."}]','["past-simple", "present-perfect"]','["present perfect","past simple","already","yet","since","for","ago"]',NULL,'["multiple_choice","fill_blank","matching","ordering"]',1,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('past-perfect','Past Perfect — Quá khứ hoàn thành','Thì động từ','B1','had + V3: diễn tả hành động xảy ra và HOÀN TẤT trước một mốc/hành động khác trong quá khứ. Là ''quá khứ của quá khứ'' — dùng để làm rõ việc nào xảy ra trước.','[{"label":"Khẳng định","formula":"S + had + V3","example":"The train had left when we arrived."},{"label":"Phủ định","formula":"S + had + not + V3","example":"I hadn''t met her before that day."},{"label":"Nghi vấn","formula":"Had + S + V3?","example":"Had you finished before he came?"}]','["before","after","when","by the time","already","just","never...before","until then"]','["Việc xảy ra TRƯỚC một mốc quá khứ khác dùng past perfect; việc sau dùng quá khứ đơn.","Thường đi với ''before/after/by the time'' để nối hai việc trong quá khứ.","Kể trải nghiệm ''lần đầu'' tính đến một thời điểm quá khứ: ''It was the best film I had ever seen.''","Trong câu tường thuật, quá khứ đơn/HTHT của lời nói gốc lùi về past perfect."]',NULL,'[{"en":"When I got to the station, the train had already left.","vi":"Khi tôi đến ga, tàu đã rời đi rồi.","note":"Tàu đi TRƯỚC lúc tôi đến."},{"en":"She had never flown before she was 20.","vi":"Cô ấy chưa từng đi máy bay trước năm 20 tuổi.","kind":"aff"},{"en":"They hadn''t finished dinner when the guests arrived.","vi":"Họ chưa ăn xong bữa tối khi khách đến.","kind":"neg"},{"en":"Had you ever visited Paris before that trip?","vi":"Bạn đã bao giờ tới Paris trước chuyến đó chưa?","kind":"ques"}]','["Dùng past perfect cho MỌI việc quá khứ: chỉ dùng khi cần chỉ rõ việc xảy ra trước việc khác.","SAI thứ tự: ''After I had eaten, I went out'' đúng; đừng để cả hai đều past perfect khi không cần.","Quên V3 (past participle): ''had went'' sai, phải là ''had gone''."]','["Nếu ''before/after'' đã cho biết thứ tự rõ ràng thì có thể dùng quá khứ đơn cho cả hai, nhưng past perfect làm nghĩa chắc chắn hơn.","Mẹo: việc nào xong TRƯỚC thì ''had + V3''."]','[{"with":"past-simple","note":"Quá khứ đơn kể chuỗi việc theo trình tự; past perfect lùi thêm một bước để chỉ việc xảy ra trước đó."}]','["past-simple", "reported-speech"]','["past perfect","had","before","after","by the time"]',NULL,'["multiple_choice","fill_blank","ordering","matching"]',3,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('second-conditional','Second Conditional — Câu điều kiện loại 2','Mệnh đề','B1','If + quá khứ đơn, ... would + V(nguyên thể): nói về tình huống KHÔNG có thật hoặc khó xảy ra ở hiện tại/tương lai, và kết quả tưởng tượng của nó.','[{"label":"Cấu trúc chuẩn","formula":"If + S + V2/V-ed, S + would + V","example":"If I had more time, I would travel more."},{"label":"Đảo vế (mệnh đề chính trước)","formula":"S + would + V + if + S + V2/V-ed","example":"I would help you if I could."},{"label":"Với ''were'' (mọi ngôi)","formula":"If I/he/she were..., ...","example":"If I were you, I would apologise."}]','["if","would","could","might","If I were you","unless"]','["Giả định trái với thực tế hiện tại: ''If I were rich...'' (thực tế không giàu).","Nói việc khó/không thể xảy ra và kết quả tưởng tượng.","Đưa lời khuyên với ''If I were you, I would...''.","Trong văn trang trọng/chuẩn mực dùng ''were'' cho mọi ngôi (I/he/she were)."]',NULL,'[{"en":"If I won the lottery, I would buy a house.","vi":"Nếu tôi trúng số, tôi sẽ mua một căn nhà.","note":"Khó xảy ra."},{"en":"If I were you, I wouldn''t worry about it.","vi":"Nếu tôi là bạn, tôi sẽ không lo về chuyện đó.","kind":"aff","note":"Lời khuyên."},{"en":"She would travel the world if she had enough money.","vi":"Cô ấy sẽ đi khắp thế giới nếu có đủ tiền.","kind":"aff"},{"en":"What would you do if you lost your job?","vi":"Bạn sẽ làm gì nếu mất việc?","kind":"ques"}]','["SAI: ''If I would win...'' — vế ''if'' KHÔNG dùng would; dùng quá khứ đơn.","SAI: ''If I will have time...'' — điều kiện loại 2 dùng quá khứ đơn, không dùng will.","Nhầm với loại 1: loại 1 nói việc có thể xảy ra (If + hiện tại, will); loại 2 nói việc không/khó xảy ra."]','["Mẹo nhớ: ''if + quá khứ, would + nguyên thể''. Không bao giờ ''would'' ở cả hai vế.","''would'' có thể thay bằng ''could'' (có thể) hoặc ''might'' (có lẽ) để đổi sắc thái."]','[{"with":"first-conditional","note":"Loại 1 (If + hiện tại, will) nói khả năng có thật; loại 2 (If + quá khứ, would) nói giả định không/khó có thật."}]','["first-conditional", "past-simple"]','["second conditional","if I were you","would","unreal"]',NULL,'["multiple_choice","fill_blank","matching","ordering"]',4,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('passive-voice','Passive Voice (present & past) — Câu bị động (hiện tại & quá khứ)','Câu bị động','B1','be + V3 (past participle): dùng khi muốn nhấn vào ĐỐI TƯỢNG chịu tác động thay vì người thực hiện, hoặc khi không biết/không cần nói ai làm. Chia ''be'' theo thì và ngôi của chủ ngữ mới.','[{"label":"Hiện tại đơn bị động","formula":"S + am/is/are + V3","example":"English is spoken here."},{"label":"Quá khứ đơn bị động","formula":"S + was/were + V3","example":"The window was broken yesterday."},{"label":"Nêu tác nhân","formula":"... + by + tác nhân","example":"The letter was written by Tom."}]','["by","be + V3","is/are + V3","was/were + V3"]','["Nhấn vào vật/việc bị tác động; người thực hiện không quan trọng hoặc không rõ.","Dùng ''by + tác nhân'' khi cần nêu rõ ai/cái gì gây ra hành động.","Chủ ngữ của câu chủ động thành ''by...'' ; tân ngữ thành chủ ngữ mới của câu bị động.","Phổ biến trong văn viết trang trọng, tin tức, quy trình, khoa học."]',NULL,'[{"en":"Millions of cars are made in Japan every year.","vi":"Hàng triệu chiếc xe được sản xuất ở Nhật mỗi năm.","note":"Hiện tại đơn bị động."},{"en":"The bridge was built in 1990.","vi":"Cây cầu được xây vào năm 1990.","kind":"aff","note":"Quá khứ đơn bị động."},{"en":"This song isn''t sung in English.","vi":"Bài hát này không được hát bằng tiếng Anh.","kind":"neg"},{"en":"Was the report finished on time?","vi":"Bản báo cáo có được hoàn thành đúng hạn không?","kind":"ques"}]','["Quên đổi ''be'' theo thì: hiện tại ''is/are'', quá khứ ''was/were''.","Dùng động từ thường thay vì V3: ''is make'' sai, phải là ''is made''.","Lạm dụng ''by...'' khi không cần: nếu tác nhân hiển nhiên/không rõ thì bỏ đi."]','["Công thức lõi: đổi tân ngữ lên đầu → thêm ''be'' đúng thì → động từ về V3.","Chỉ động từ có tân ngữ (ngoại động từ) mới chuyển sang bị động được."]','[{"with":"present-simple","note":"Chủ động nhấn người làm (People speak English); bị động nhấn đối tượng (English is spoken)."}]','["present-simple", "past-simple"]','["passive voice","be + past participle","by","is made","was built"]',NULL,'["multiple_choice","fill_blank","ordering","matching"]',5,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('reported-speech','Reported Speech (statements) — Câu tường thuật (câu trần thuật)','Mệnh đề','B1','Thuật lại lời người khác không dùng dấu ngoặc kép. Thường lùi thì một bậc, đổi đại từ/sở hữu và trạng từ chỉ thời gian–nơi chốn cho hợp ngữ cảnh mới. Dùng ''say'' hoặc ''tell + người''.','[{"label":"Cấu trúc chung","formula":"S + said (that) + mệnh đề lùi thì","example":"He said (that) he was tired."},{"label":"Với ''tell''","formula":"S + told + O + (that) + mệnh đề","example":"She told me she would come."}]','["say","tell","that","the day before","the next day","there","then"]','["Lùi thì một bậc: hiện tại đơn→quá khứ đơn; hiện tại tiếp diễn→quá khứ tiếp diễn; HTHT/quá khứ đơn→quá khứ hoàn thành; will→would; can→could.","Đổi đại từ và tính từ sở hữu theo người nói/nghe mới (I→he/she, my→his/her).","Đổi trạng từ: now→then, today→that day, tomorrow→the next day, yesterday→the day before, here→there.","''say'' không có tân ngữ người ngay sau; ''tell'' bắt buộc có tân ngữ người (tell me/him)."]',NULL,'[{"en":"\"I am busy,\" she said. → She said (that) she was busy.","vi":"\"Tôi bận,\" cô ấy nói. → Cô ấy nói rằng cô ấy bận.","note":"Hiện tại → quá khứ."},{"en":"\"We will help you,\" they said. → They said they would help me.","vi":"\"Chúng tôi sẽ giúp bạn,\" họ nói. → Họ nói họ sẽ giúp tôi.","kind":"aff","note":"will → would."},{"en":"He told me he had finished the work.","vi":"Anh ấy bảo tôi rằng anh ấy đã làm xong việc.","kind":"aff","note":"Quá khứ đơn/HTHT → quá khứ hoàn thành."},{"en":"She said she didn''t like coffee.","vi":"Cô ấy nói cô ấy không thích cà phê.","kind":"neg"}]','["Dùng ''say me'' — sai; phải ''tell me'' hoặc ''say to me''.","Quên lùi thì khi động từ tường thuật ở quá khứ (said/told).","Quên đổi đại từ: ''He said I was tired'' khi ý là chính anh ấy mệt → ''He said he was tired.''"]','["Nếu điều được nói vẫn ĐÚNG ở hiện tại (sự thật chung) thì có thể không lùi thì.","Mẹo: ''tell'' luôn có người nghe, ''say'' thì không cần."]','[{"with":"past-perfect","note":"Trong tường thuật, quá khứ đơn/HTHT của lời gốc lùi về quá khứ hoàn thành (had + V3)."}]','["past-perfect", "past-simple", "future-will"]','["reported speech","say","tell","backshift","that clause"]','[{"term":"am/is → was","meaning":"Lùi thì: động từ ''to be'' số ít hiện tại (am/is) đổi thành was.","example":"\"I am tired\" → She said she was tired.","group":"Lùi thì (động từ)"},{"term":"are → were","meaning":"Lùi thì: động từ ''to be'' số nhiều hiện tại (are) đổi thành were.","example":"\"They are here\" → He said they were here.","group":"Lùi thì (động từ)"},{"term":"do/does → did","meaning":"Lùi thì: trợ động từ hiện tại đơn (do/does) đổi thành did.","example":"\"Do you agree?\" → She asked if I agreed.","group":"Lùi thì (động từ)"},{"term":"present simple → past simple","meaning":"Lùi thì: hiện tại đơn chuyển thành quá khứ đơn.","example":"\"I like tea\" → He said he liked tea.","group":"Lùi thì (động từ)"},{"term":"present continuous → past continuous","meaning":"Lùi thì: hiện tại tiếp diễn chuyển thành quá khứ tiếp diễn.","example":"\"I am working\" → She said she was working.","group":"Lùi thì (động từ)"},{"term":"will → would","meaning":"Lùi thì: will chuyển thành would.","example":"\"I will go\" → He said he would go.","group":"Lùi thì (động từ)"},{"term":"can → could","meaning":"Lùi thì: can chuyển thành could.","example":"\"I can swim\" → She said she could swim.","group":"Lùi thì (động từ)"},{"term":"may → might","meaning":"Lùi thì: may chuyển thành might.","example":"\"It may rain\" → He said it might rain.","group":"Lùi thì (động từ)"},{"term":"must → had to","meaning":"Lùi thì: must (bắt buộc) chuyển thành had to.","example":"\"I must leave\" → She said she had to leave.","group":"Lùi thì (động từ)"},{"term":"present perfect → past perfect","meaning":"Lùi thì: hiện tại hoàn thành chuyển thành quá khứ hoàn thành.","example":"\"I have finished\" → He said he had finished.","group":"Lùi thì (động từ)"},{"term":"past simple → past perfect","meaning":"Lùi thì: quá khứ đơn chuyển thành quá khứ hoàn thành.","example":"\"I saw him\" → She said she had seen him.","group":"Lùi thì (động từ)"},{"term":"now → then","meaning":"Đổi trạng từ chỉ thời gian khi tường thuật: now thành then.","example":"\"I''m busy now\" → He said he was busy then.","group":"Đổi từ chỉ thời gian/nơi chốn"},{"term":"today → that day","meaning":"Đổi trạng từ thời gian: today thành that day.","example":"\"I''ll call today\" → She said she would call that day.","group":"Đổi từ chỉ thời gian/nơi chốn"},{"term":"tomorrow → the next day","meaning":"Đổi trạng từ thời gian: tomorrow thành the next day.","example":"\"I''ll come tomorrow\" → He said he would come the next day.","group":"Đổi từ chỉ thời gian/nơi chốn"},{"term":"yesterday → the day before","meaning":"Đổi trạng từ thời gian: yesterday thành the day before.","example":"\"I saw her yesterday\" → He said he had seen her the day before.","group":"Đổi từ chỉ thời gian/nơi chốn"},{"term":"tonight → that night","meaning":"Đổi trạng từ thời gian: tonight thành that night.","example":"\"I''ll study tonight\" → She said she would study that night.","group":"Đổi từ chỉ thời gian/nơi chốn"},{"term":"here → there","meaning":"Đổi trạng từ chỉ nơi chốn: here thành there.","example":"\"I live here\" → He said he lived there.","group":"Đổi từ chỉ thời gian/nơi chốn"},{"term":"this → that","meaning":"Đổi từ chỉ định số ít: this thành that.","example":"\"I like this\" → She said she liked that.","group":"Đổi từ chỉ thời gian/nơi chốn"},{"term":"these → those","meaning":"Đổi từ chỉ định số nhiều: these thành those.","example":"\"These are mine\" → He said those were his.","group":"Đổi từ chỉ thời gian/nơi chốn"},{"term":"ago → before","meaning":"Đổi trạng từ thời gian: ago thành before.","example":"\"He left an hour ago\" → She said he had left an hour before.","group":"Đổi từ chỉ thời gian/nơi chốn"},{"term":"next week → the following week","meaning":"Đổi trạng từ thời gian: next week thành the following week.","example":"\"I''ll travel next week\" → He said he would travel the following week.","group":"Đổi từ chỉ thời gian/nơi chốn"},{"term":"I → he / she","meaning":"Đổi đại từ chủ ngữ ngôi thứ nhất theo người nói được tường thuật.","example":"\"I am ready\" → She said she was ready.","group":"Đổi đại từ"},{"term":"we → they","meaning":"Đổi đại từ chủ ngữ số nhiều ngôi thứ nhất thành they.","example":"\"We won\" → They said they had won.","group":"Đổi đại từ"},{"term":"my → his / her","meaning":"Đổi tính từ sở hữu ngôi thứ nhất theo người được tường thuật.","example":"\"This is my book\" → He said that was his book.","group":"Đổi đại từ"}]','["multiple_choice","fill_blank","matching","ordering"]',6,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('relative-clauses-defining','Defining Relative Clauses — Mệnh đề quan hệ xác định','Mệnh đề','B1','Mệnh đề bắt đầu bằng who/which/that/where/whose... bổ nghĩa, xác định RÕ danh từ đứng trước (thông tin cần thiết, không có thì câu thiếu nghĩa). KHÔNG dùng dấu phẩy tách.','[{"label":"Người (chủ/tân ngữ)","formula":"N (người) + who/that + mệnh đề","example":"The man who lives next door is a doctor."},{"label":"Vật/việc","formula":"N (vật) + which/that + mệnh đề","example":"The book which I bought is great."},{"label":"Nơi chốn / sở hữu","formula":"where / whose","example":"That''s the house where I grew up."}]','["who","which","that","whose","where","when"]','["who cho người, which cho vật; that dùng được cho cả hai (thường trong mệnh đề xác định).","whose chỉ sở hữu (của người/vật); where chỉ nơi chốn; when chỉ thời gian.","Khi đại từ quan hệ là TÂN NGỮ của mệnh đề, có thể lược bỏ: ''the book (that) I bought''.","Mệnh đề xác định KHÔNG dùng dấu phẩy vì thông tin là bắt buộc để hiểu."]',NULL,'[{"en":"The woman who called you is my teacher.","vi":"Người phụ nữ đã gọi cho bạn là cô giáo của tôi.","note":"who = chủ ngữ, không lược được."},{"en":"This is the phone that I want to buy.","vi":"Đây là chiếc điện thoại tôi muốn mua.","kind":"aff","note":"that = tân ngữ, có thể bỏ."},{"en":"I know a girl whose father is a pilot.","vi":"Tôi quen một cô gái có bố là phi công.","kind":"aff","note":"whose = sở hữu."},{"en":"Do you remember the day when we met?","vi":"Bạn có nhớ ngày chúng ta gặp nhau không?","kind":"ques","note":"when = thời gian."}]','["Lặp lại tân ngữ: ''The book that I bought it'' — thừa ''it'', bỏ đi.","Dùng ''which'' cho người: sai; người dùng ''who/that''.","Thêm dấu phẩy vào mệnh đề xác định (biến nó thành không xác định, đổi nghĩa)."]','["Khi đại từ quan hệ đứng ngay trước một danh từ/đại từ (chủ ngữ khác) → nó là tân ngữ → lược được.","Không lược được khi đại từ quan hệ làm CHỦ NGỮ của mệnh đề."]','[{"with":"relative-clauses-non-defining","note":"Xác định: thông tin cần thiết, không phẩy, dùng that được; không xác định: thông tin thêm, có phẩy, không dùng that."}]','[]','["relative clause","who","which","that","whose","where"]',NULL,'["multiple_choice","fill_blank","matching","ordering"]',7,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('gerund-infinitive','Gerund vs Infinitive — Danh động từ & động từ nguyên mẫu','Câu & Cấu trúc','B1','Sau một số động từ dùng V-ing (gerund), sau số khác dùng to + V (infinitive). Có động từ dùng được cả hai (đôi khi đổi nghĩa). Gerund cũng dùng sau giới từ và làm chủ ngữ.','[{"label":"Động từ + V-ing","formula":"enjoy/finish/avoid/mind/suggest + V-ing","example":"I enjoy reading books."},{"label":"Động từ + to V","formula":"want/decide/hope/need/promise + to V","example":"She decided to leave early."},{"label":"Sau giới từ","formula":"giới từ + V-ing","example":"He''s good at cooking."}]','["enjoy","finish","avoid","mind","want","decide","hope","need","at/of/about + V-ing"]','["Dùng V-ing sau: enjoy, finish, avoid, mind, suggest, keep, practice, can''t stand.","Dùng to + V sau: want, decide, hope, need, promise, agree, learn, would like.","Luôn dùng V-ing sau giới từ (in, at, of, about, before, after...).","Một số động từ (like, love, hate, start, begin) dùng cả hai với nghĩa gần như nhau."]',NULL,'[{"en":"I enjoy swimming in the sea.","vi":"Tôi thích bơi ngoài biển.","note":"enjoy + V-ing."},{"en":"They want to buy a new car.","vi":"Họ muốn mua một chiếc xe mới.","kind":"aff","note":"want + to V."},{"en":"She''s interested in learning Spanish.","vi":"Cô ấy hứng thú với việc học tiếng Tây Ban Nha.","kind":"aff","note":"giới từ ''in'' + V-ing."},{"en":"I stopped smoking two years ago.","vi":"Tôi bỏ hút thuốc hai năm trước.","note":"stop + V-ing = ngừng làm việc đó."}]','["SAI: ''I enjoy to read.'' → ĐÚNG: ''I enjoy reading.''","SAI: ''I want reading.'' → ĐÚNG: ''I want to read.''","Sau giới từ dùng nguyên thể: ''good at cook'' sai, phải ''good at cooking''."]','["Nhớ nghĩa đổi: ''stop to do'' (dừng lại để làm) vs ''stop doing'' (ngừng làm); ''remember to do'' (nhớ để làm) vs ''remember doing'' (nhớ đã làm).","Học động từ theo nhóm ''ưa V-ing'' và ''ưa to V'' để đỡ nhầm."]',NULL,'["present-continuous"]','["gerund","infinitive","V-ing","to + verb","enjoy","want","stop"]','[{"term":"enjoy","meaning":"enjoy + V-ing: thích, tận hưởng việc gì","example":"I enjoy reading.","group":"Chỉ theo V-ing"},{"term":"finish","meaning":"finish + V-ing: làm xong việc gì","example":"She finished cooking.","group":"Chỉ theo V-ing"},{"term":"avoid","meaning":"avoid + V-ing: tránh làm gì","example":"He avoids eating late.","group":"Chỉ theo V-ing"},{"term":"mind","meaning":"mind + V-ing: phiền/ngại làm gì","example":"Do you mind waiting?","group":"Chỉ theo V-ing"},{"term":"suggest","meaning":"suggest + V-ing: đề nghị làm gì","example":"She suggested going out.","group":"Chỉ theo V-ing"},{"term":"practice","meaning":"practice + V-ing: luyện tập làm gì (Anh-Mỹ viết ''practice'' cho cả danh từ và động từ; Anh-Anh viết động từ là ''practise'')","example":"I practice speaking English.","group":"Chỉ theo V-ing"},{"term":"keep","meaning":"keep + V-ing: cứ tiếp tục làm gì","example":"He keeps talking.","group":"Chỉ theo V-ing"},{"term":"consider","meaning":"consider + V-ing: cân nhắc làm gì","example":"We''re considering moving.","group":"Chỉ theo V-ing"},{"term":"admit","meaning":"admit + V-ing: thừa nhận đã làm gì","example":"He admitted lying.","group":"Chỉ theo V-ing"},{"term":"deny","meaning":"deny + V-ing: phủ nhận đã làm gì","example":"She denied taking it.","group":"Chỉ theo V-ing"},{"term":"imagine","meaning":"imagine + V-ing: tưởng tượng việc gì","example":"Imagine living abroad.","group":"Chỉ theo V-ing"},{"term":"miss","meaning":"miss + V-ing: nhớ/tiếc việc gì","example":"I miss seeing you.","group":"Chỉ theo V-ing"},{"term":"risk","meaning":"risk + V-ing: liều/mạo hiểm làm gì","example":"Don''t risk losing it.","group":"Chỉ theo V-ing"},{"term":"can''t help","meaning":"can''t help + V-ing: không thể không làm gì","example":"I can''t help laughing.","group":"Chỉ theo V-ing"},{"term":"want","meaning":"want + to-V: muốn làm gì","example":"I want to go home.","group":"Chỉ theo to-V"},{"term":"decide","meaning":"decide + to-V: quyết định làm gì","example":"She decided to stay.","group":"Chỉ theo to-V"},{"term":"hope","meaning":"hope + to-V: hy vọng làm gì","example":"We hope to win.","group":"Chỉ theo to-V"},{"term":"plan","meaning":"plan + to-V: dự định làm gì","example":"They plan to travel.","group":"Chỉ theo to-V"},{"term":"promise","meaning":"promise + to-V: hứa làm gì","example":"He promised to call.","group":"Chỉ theo to-V"},{"term":"agree","meaning":"agree + to-V: đồng ý làm gì","example":"She agreed to help.","group":"Chỉ theo to-V"},{"term":"offer","meaning":"offer + to-V: ngỏ ý/đề nghị làm gì","example":"He offered to pay.","group":"Chỉ theo to-V"},{"term":"refuse","meaning":"refuse + to-V: từ chối làm gì","example":"They refused to leave.","group":"Chỉ theo to-V"},{"term":"learn","meaning":"learn + to-V: học làm gì","example":"I''m learning to drive.","group":"Chỉ theo to-V"},{"term":"manage","meaning":"manage + to-V: xoay xở làm được gì","example":"She managed to finish.","group":"Chỉ theo to-V"},{"term":"expect","meaning":"expect + to-V: mong/dự kiến làm gì","example":"We expect to arrive soon.","group":"Chỉ theo to-V"},{"term":"afford","meaning":"afford + to-V: đủ khả năng (chi trả) làm gì","example":"I can''t afford to buy it.","group":"Chỉ theo to-V"},{"term":"pretend","meaning":"pretend + to-V: giả vờ làm gì","example":"He pretended to sleep.","group":"Chỉ theo to-V"},{"term":"seem","meaning":"seem + to-V: có vẻ như","example":"She seems to know.","group":"Chỉ theo to-V"},{"term":"stop","meaning":"stop + V-ing: ngừng hẳn việc đó; stop + to-V: dừng lại ĐỂ làm việc khác","example":"He stopped smoking. vs He stopped to smoke.","group":"Cả hai — ĐỔI nghĩa"},{"term":"remember","meaning":"remember + V-ing: nhớ (chuyện đã làm); remember + to-V: nhớ (phải làm chuyện sắp tới)","example":"I remember locking the door. vs Remember to lock the door.","group":"Cả hai — ĐỔI nghĩa"},{"term":"forget","meaning":"forget + V-ing: quên (chuyện đã làm); forget + to-V: quên (phải làm chuyện sắp tới)","example":"I''ll never forget meeting her. vs I forgot to call him.","group":"Cả hai — ĐỔI nghĩa"},{"term":"try","meaning":"try + V-ing: thử làm (để xem sao); try + to-V: cố gắng làm gì","example":"Try adding more salt. vs I tried to open it.","group":"Cả hai — ĐỔI nghĩa"},{"term":"regret","meaning":"regret + V-ing: hối tiếc (chuyện đã làm); regret + to-V: lấy làm tiếc phải (báo tin)","example":"I regret saying that. vs We regret to inform you.","group":"Cả hai — ĐỔI nghĩa"},{"term":"go on","meaning":"go on + V-ing: tiếp tục việc đang làm; go on + to-V: chuyển sang làm việc khác","example":"He went on talking. vs He went on to become a doctor.","group":"Cả hai — ĐỔI nghĩa"},{"term":"mean","meaning":"mean + V-ing: kéo theo/đồng nghĩa với; mean + to-V: có ý định làm gì","example":"This means working late. vs I meant to help.","group":"Cả hai — ĐỔI nghĩa"},{"term":"like","meaning":"like + V-ing / to-V: thích làm gì (nghĩa gần như nhau)","example":"I like swimming. / I like to swim.","group":"Cả hai — nghĩa gần như nhau"},{"term":"love","meaning":"love + V-ing / to-V: rất thích làm gì","example":"She loves dancing. / She loves to dance.","group":"Cả hai — nghĩa gần như nhau"},{"term":"hate","meaning":"hate + V-ing / to-V: ghét làm gì","example":"I hate waiting. / I hate to wait.","group":"Cả hai — nghĩa gần như nhau"},{"term":"prefer","meaning":"prefer + V-ing / to-V: thích hơn (làm gì)","example":"I prefer walking. / I prefer to walk.","group":"Cả hai — nghĩa gần như nhau"},{"term":"begin","meaning":"begin + V-ing / to-V: bắt đầu làm gì","example":"It began raining. / It began to rain.","group":"Cả hai — nghĩa gần như nhau"},{"term":"start","meaning":"start + V-ing / to-V: bắt đầu làm gì","example":"She started crying. / She started to cry.","group":"Cả hai — nghĩa gần như nhau"},{"term":"continue","meaning":"continue + V-ing / to-V: tiếp tục làm gì","example":"They continued playing. / They continued to play.","group":"Cả hai — nghĩa gần như nhau"}]','["multiple_choice","fill_blank","matching","ordering"]',9,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('used-to','used to — used to (thói quen trong quá khứ)','Thì động từ','B1','''used to + V(nguyên thể)'' diễn tả thói quen hoặc trạng thái ĐÃ có trong quá khứ nhưng nay không còn. Ở phủ định/nghi vấn dùng ''didn''t use to'' / ''Did ... use to'' (bỏ ''d'').','[{"label":"Khẳng định","formula":"S + used to + V","example":"I used to play football every weekend."},{"label":"Phủ định","formula":"S + didn''t use to + V","example":"She didn''t use to like vegetables."},{"label":"Nghi vấn","formula":"Did + S + use to + V?","example":"Did you use to live here?"}]','["used to","didn''t use to","in the past","when I was young","no longer"]','["Nói thói quen quá khứ đã dừng: ''I used to smoke'' (giờ không hút nữa).","Nói trạng thái quá khứ đã đổi: ''There used to be a cinema here.''","Phủ định/nghi vấn bỏ ''d'': ''didn''t use to'', ''Did ... use to?''.","Chỉ dùng cho quá khứ — KHÔNG có dạng ''use to'' cho hiện tại (hiện tại dùng ''usually + hiện tại đơn'')."]',NULL,'[{"en":"We used to live in a small village.","vi":"Chúng tôi từng sống ở một ngôi làng nhỏ.","note":"Trạng thái quá khứ, nay khác."},{"en":"He didn''t use to exercise, but now he runs daily.","vi":"Trước đây anh ấy không tập thể dục, nhưng giờ chạy bộ mỗi ngày.","kind":"neg"},{"en":"Did you use to have long hair?","vi":"Trước đây bạn từng để tóc dài à?","kind":"ques"},{"en":"There used to be a big tree in front of our house.","vi":"Trước đây có một cái cây to trước nhà chúng tôi.","kind":"aff"}]','["SAI: ''didn''t used to'' — sau ''did'' phải là ''use to'' (bỏ d): ''didn''t use to''.","Dùng cho hiện tại: ''I use to go'' (ý hiện tại) sai; hiện tại dùng ''I usually go''.","Nhầm với ''be used to + V-ing'' (quen với việc gì) — nghĩa hoàn toàn khác."]','["Phân biệt: ''used to + V'' (thói quen quá khứ) ≠ ''be/get used to + V-ing'' (quen/dần quen với việc gì).","Có thể thay ''used to'' bằng ''would + V'' cho hành động lặp lại quá khứ, nhưng KHÔNG dùng ''would'' cho trạng thái (would be a cinema → sai)."]','[{"with":"past-simple","note":"Quá khứ đơn kể một việc/nhiều việc đã xảy ra; ''used to'' nhấn thói quen/trạng thái kéo dài trong quá khứ nay không còn."}]','["past-simple", "adverbs-of-frequency"]','["used to","past habit","didn''t use to","would"]',NULL,'["multiple_choice","fill_blank","ordering","matching"]',11,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('third-conditional','Third Conditional — Câu điều kiện loại 3','Mệnh đề','B2','Diễn tả điều kiện KHÔNG có thật trong quá khứ và kết quả trái ngược với thực tế đã xảy ra; dùng để nuối tiếc, trách móc hoặc suy đoán về những gì đã có thể khác đi.','[{"label":"Cấu trúc chuẩn","formula":"If + S + had + V3/-ed, S + would have + V3/-ed","example":"If I had studied harder, I would have passed the exam."},{"label":"Modal thay would","formula":"If + S + had + V3, S + could/might have + V3","example":"If we had left earlier, we might have caught the train."},{"label":"Đảo ngữ (trang trọng)","formula":"Had + S + V3, S + would have + V3","example":"Had she known the truth, she would have acted differently."}]','["if","had","would have","could have","might have","otherwise"]','["Giả định trái với thực tế trong QUÁ KHỨ: cả hai vế đều không xảy ra thật.","Bày tỏ nuối tiếc hoặc phê phán về một lựa chọn đã qua.","Có thể đảo ngữ ''Had + S...'' để bỏ ''if'', mang sắc thái trang trọng/văn viết."]',NULL,'[{"en":"If they had booked earlier, they would have got cheaper tickets.","vi":"Nếu họ đặt sớm hơn, họ đã mua được vé rẻ hơn.","kind":"aff"},{"en":"She wouldn''t have missed the flight if she had checked the time.","vi":"Cô ấy đã không lỡ chuyến bay nếu để ý giờ giấc.","kind":"neg","note":"Vế chính có thể đứng trước, không cần dấu phẩy."},{"en":"If I hadn''t helped him, would he have finished on time?","vi":"Nếu tôi không giúp anh ấy, liệu anh ấy có xong đúng hạn không?","kind":"ques"},{"en":"Had we known about the traffic, we would have taken another route.","vi":"Giá mà chúng tôi biết trước có kẹt xe thì đã đi đường khác.","kind":"aff","note":"Đảo ngữ bỏ ''if''."}]','["Dùng ''would have'' ở vế if: sai ''If I would have known'', đúng ''If I had known''.","Chia sai trợ động từ: ''would have went'' → đúng ''would have gone''.","Nhầm sang loại 2 (hiện tại) khi ngữ cảnh nói về quá khứ."]','["Nhớ ''quá khứ trong quá khứ'': vế if dùng Past Perfect (had + V3).","Đổi would → could/might để nói khả năng thay vì chắc chắn."]','[{"with":"second-conditional","note":"Loại 2 nói về hiện tại/tương lai không thật (If I had money...); loại 3 nói về QUÁ KHỨ không thật (If I had had money...)."},{"with":"mixed-conditionals","note":"Điều kiện hỗn hợp trộn thời gian: ví dụ nguyên nhân quá khứ (loại 3) → kết quả hiện tại (loại 2)."}]','["second-conditional", "wish-if-only", "past-perfect"]','["third conditional","điều kiện loại 3","if had would have"]',NULL,'["multiple_choice","fill_blank","ordering","matching"]',4,'2026-07-14T08:15:26.184Z');
INSERT OR IGNORE INTO grammar (id,title,category,cefr,summary,forms,signals,usage,spelling,examples,mistakes,tips,compare,related,keywords,bank,drill_types,position,created_at) VALUES ('wish-if-only','wish / if only — wish / if only','Mệnh đề','B2','Diễn tả điều tiếc nuối hoặc mong muốn trái với thực tế; lùi thì để chỉ mức độ không thật: quá khứ đơn cho hiện tại, quá khứ hoàn thành cho quá khứ, và ''would'' để phàn nàn/mong người khác đổi hành vi. ''If only'' mạnh hơn ''wish''.','[{"label":"Tiếc ở hiện tại","formula":"wish / if only + S + V2/-ed (were)","example":"I wish I knew the answer. / I wish I were taller."},{"label":"Tiếc ở quá khứ","formula":"wish / if only + S + had + V3","example":"I wish I had studied medicine."},{"label":"Phàn nàn/mong đổi hành vi","formula":"wish / if only + S + would + V","example":"I wish you would stop interrupting me."}]','["wish","if only","were","had","would"]','["Mong ước trái thực tế ở HIỆN TẠI → lùi về quá khứ đơn (dùng ''were'' cho mọi ngôi ở văn trang trọng).","Tiếc nuối về QUÁ KHỨ đã rồi → dùng quá khứ hoàn thành (had + V3).","''wish + would'' dùng để phàn nàn về hành vi khó chịu của người/vật khác, mong nó thay đổi (không dùng cho chính mình).","''If only'' cùng cấu trúc nhưng nhấn cảm xúc mạnh hơn ''wish''."]',NULL,'[{"en":"I wish I lived closer to the sea.","vi":"Ước gì tôi sống gần biển hơn.","kind":"aff","note":"Tiếc ở hiện tại → quá khứ đơn."},{"en":"If only we had booked the tickets earlier!","vi":"Giá mà chúng tôi đã đặt vé sớm hơn!","kind":"aff","note":"Tiếc quá khứ → had + V3."},{"en":"I wish it would stop raining.","vi":"Ước gì trời tạnh mưa đi.","kind":"aff","note":"wish + would: mong sự việc thay đổi."},{"en":"Don''t you wish you had taken that opportunity?","vi":"Cậu có ước gì mình đã nắm lấy cơ hội đó không?","kind":"ques"}]','["Dùng hiện tại sau wish cho điều không thật: sai ''I wish I have more time'', đúng ''I wish I had more time''.","Dùng ''wish + would'' cho chính mình: sai ''I wish I would be taller'', đúng ''I wish I were taller''.","Nhầm thì khi tiếc quá khứ: phải là ''wish + had + V3'', không phải ''wish + V2''."]','["Quy tắc lùi thì giống câu điều kiện: hiện tại→quá khứ, quá khứ→quá khứ hoàn thành.","''were'' (thay ''was'') sau wish/if only nghe chuẩn mực hơn: I wish he were here."]','[{"with":"second-conditional","note":"Cùng lùi thì cho hiện tại không thật; wish nhấn MONG ƯỚC, second conditional nhấn ĐIỀU KIỆN-KẾT QUẢ."},{"with":"third-conditional","note":"''wish + had V3'' và loại 3 đều nói về quá khứ trái thực tế, thường diễn đạt cùng một sự nuối tiếc."}]','["second-conditional", "third-conditional"]','["wish","if only","regret","ước gì","giá mà"]',NULL,'["multiple_choice","fill_blank","ordering","matching"]',10,'2026-07-14T08:15:26.184Z');
