INSERT OR IGNORE INTO grammar_items (id,grammar_id,cefr,tier,type,payload,status,source,question_id) VALUES ('fffe9388-9b73-4ee8-b876-9df349478cfa','present-simple','A1',1,'multiple_choice','{"position": 14, "type": "multiple_choice", "question": "First I have breakfast. ___, I go to school.", "image": null, "word_bank": null, "hint": null, "explanation": "''Then'' nối 2 hành động liên tiếp trong ngày.", "options": ["Then", "Finish", "Usually", "Work"], "answer": "Then", "accept": null, "pairs": null, "tokens": null, "categories": null, "items": null, "grammar_id": "present-simple"}','live','teacher','a11091d2-8a0f-4cf5-9419-3d2121a23017');
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('49aec5af-da0e-4a5b-be23-ff7a9e11e4d8','a1-s1-03-read-aloud-daily-routine','My Daily Routine',1,'reading','A1 Movers',NULL,'Every day, I wake up at half past six. First, I have breakfast with my family. Then, I get dressed for school. My school starts at eight o''clock. I usually study hard in class. After that, I have lunch with my friends. I finish school at four o''clock and walk home. In the evening, I work on my homework. Then, I watch TV for a little while. Finally, I go to bed at nine o''clock. I sleep well every night.','[{"text":"Every day, I wake up at half past six.","ipa":"/ˈɛvri deɪ, aɪ weɪk ʌp æt hæf pæst sɪks./","vi":"Mỗi ngày, tôi thức dậy lúc sáu giờ rưỡi."},{"text":"First, I have breakfast with my family.","ipa":"/fɜrst, aɪ hæv ˈbrɛkfəst wɪð maɪ ˈfæməli./","vi":"Đầu tiên, tôi ăn sáng cùng gia đình."},{"text":"Then, I get dressed for school.","ipa":"/ðɛn, aɪ gɛt drɛst fɔr skul./","vi":"Sau đó, tôi mặc quần áo để đi học."},{"text":"My school starts at eight o''clock.","ipa":"/maɪ skul stɑrts æt eɪt əˈklɑk./","vi":"Trường tôi bắt đầu lúc tám giờ."},{"text":"I usually study hard in class.","ipa":"/aɪ ˈjuʒuəli ˈstʌdi hɑrd ɪn klæs./","vi":"Tôi thường học tập chăm chỉ trên lớp."},{"text":"After that, I have lunch with my friends.","ipa":"/ˈæftər ðæt, aɪ hæv lʌntʃ wɪð maɪ frɛndz./","vi":"Sau đó, tôi ăn trưa cùng bạn bè."},{"text":"I finish school at four o''clock and walk home.","ipa":"/aɪ ˈfɪnɪʃ skul æt fɔr əˈklɑk ænd wɔk hoʊm./","vi":"Tôi tan học lúc bốn giờ và đi bộ về nhà."},{"text":"In the evening, I work on my homework.","ipa":"/ɪn ði ˈivnɪŋ, aɪ wɜrk ɑn maɪ ˈhoʊmwɜrk./","vi":"Vào buổi tối, tôi làm bài tập về nhà."},{"text":"Then, I watch TV for a little while.","ipa":"/ðɛn, aɪ wɑtʃ tiˈvi fɔr ə ˈlɪtəl waɪl./","vi":"Sau đó, tôi xem tivi một lát."},{"text":"Finally, I go to bed at nine o''clock.","ipa":"/ˈfaɪnəli, aɪ goʊ tu bɛd æt naɪn əˈklɑk./","vi":"Cuối cùng, tôi đi ngủ lúc chín giờ."},{"text":"I sleep well every night.","ipa":"/aɪ slip wɛl ˈɛvri naɪt./","vi":"Tôi ngủ ngon mỗi đêm."}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,30,'a1-s1','98253879c87a47b0b55fbf5205991da4',NULL,NULL,'2026-07-25T12:43:22.645Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('a9ea759e-8f50-46f8-8995-f406f8ec0544','a1-s1-04-listen-daily-routine','What Time Do You Wake Up?',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Oliver: Hi Grace! What time do you usually wake up?
Grace: Hi Oliver! I wake up at six thirty every morning.
Oliver [surprised]: Wow, that''s early! I wake up at seven fifteen.
Grace: What do you do after that?
Oliver: I have breakfast, then I get ready for school.
Grace: I have breakfast too. Then I study for twenty minutes before school.
Oliver [surprised]: Really? What time does your school start?
Grace: My school starts at eight o''clock. What about yours?
Oliver: My school starts at eight fifteen.
Grace: What time do you finish school?
Oliver: I finish at three thirty. Then I do my homework.
Grace: I finish at four o''clock. After that, I usually play outside.
Oliver: What time do you go to bed?
Grace: I go to bed at nine o''clock. And you?
Oliver [happy]: I go to bed at nine thirty. Good night, Grace!
Grace [happy]: Good night, Oliver!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,40,'a1-s1','98253879c87a47b0b55fbf5205991da4',NULL,NULL,'2026-07-25T12:43:22.645Z',NULL);
