INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('7e557439-e772-4ed1-88ec-e5c8b89110e3','a1-s1-08-read-aloud-family-activities','Family Time',1,'reading','A1 Movers',NULL,'My family always spends time together. On weekdays, we usually have dinner together at seven o''clock. We sometimes play board games after dinner. My father often reads books with me before bed. We never miss family time on weekends. Once a week, we visit my grandparents. Twice a month, we go to the cinema together. How often do you spend time with your family? I think family time is very important.','[{"text":"My family always spends time together.","ipa":"/maɪ ˈfæməli ˈɔlweɪz spɛndz taɪm təˈɡɛðər./","vi":"Gia đình tôi luôn dành thời gian cho nhau."},{"text":"On weekdays, we usually have dinner together at seven o''clock.","ipa":"/ɑn ˈwikˌdeɪz, wi ˈjuʒəwəli hæv ˈdɪnər təˈɡɛðər æt ˈsɛvən əˈklɑk./","vi":"Vào các ngày trong tuần, chúng tôi thường ăn tối cùng nhau lúc bảy giờ."},{"text":"We sometimes play board games after dinner.","ipa":"/wi ˈsʌmˌtaɪmz pleɪ bɔrd ɡeɪmz ˈæftər ˈdɪnər./","vi":"Thỉnh thoảng chúng tôi chơi trò chơi trên bàn sau bữa tối."},{"text":"My father often reads books with me before bed.","ipa":"/maɪ ˈfɑðər ˈɔfən ridz bʊks wɪð mi bɪˈfɔr bɛd./","vi":"Bố thường đọc sách cùng tôi trước khi đi ngủ."},{"text":"We never miss family time on weekends.","ipa":"/wi ˈnɛvər mɪs ˈfæməli taɪm ɑn ˈwiˌkɛndz./","vi":"Chúng tôi không bao giờ bỏ lỡ thời gian dành cho gia đình vào cuối tuần."},{"text":"Once a week, we visit my grandparents.","ipa":"/wʌns ə wik, wi ˈvɪzɪt maɪ ˈɡrænˌpɛrənts./","vi":"Mỗi tuần một lần, chúng tôi đến thăm ông bà."},{"text":"Twice a month, we go to the cinema together.","ipa":"/twaɪs ə mʌnθ, wi ɡoʊ tu ðə ˈsɪnəmə təˈɡɛðər./","vi":"Mỗi tháng hai lần, chúng tôi cùng nhau đi xem phim."},{"text":"How often do you spend time with your family?","ipa":"/haʊ ˈɔfən du ju spɛnd taɪm wɪð jʊər ˈfæməli?/","vi":"Bạn có thường dành thời gian cho gia đình mình không?"},{"text":"I think family time is very important.","ipa":"/aɪ θɪŋk ˈfæməli taɪm ɪz ˈvɛri ɪmˈpɔrtənt./","vi":"Tôi nghĩ thời gian dành cho gia đình rất quan trọng."}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,80,'a1-s1','263cc2bede3c45d79bbcad8792af76b3',NULL,NULL,'2026-07-25T12:43:22.645Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('c26e3759-2a3c-406e-9794-12885df4ef0d','a1-s1-09-listen-family-activities','Family Time Together',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Sophie: Hi Daniel! What do you usually do with your family?
Daniel: Hi Sophie! We always have dinner together every evening.
Sophie [happy]: That''s nice! We sometimes cook together on weekends.
Daniel: How often do you see your grandparents?
Sophie: I see them once a week, on Sundays.
Daniel: We visit our grandparents twice a month.
Sophie: Do you play games together?
Daniel: Yes, we often play board games after dinner.
Sophie: We never watch TV during dinner.
Daniel: We never do that either. We always talk together.
Sophie: What do you do at weekends?
Daniel: At weekends, we usually go to the park together.
Sophie [happy]: That sounds fun! We sometimes go to the park too.
Daniel [excited]: Let''s go together next weekend!
Sophie [happy]: Great idea!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,90,'a1-s1','263cc2bede3c45d79bbcad8792af76b3',NULL,NULL,'2026-07-25T12:43:22.645Z',NULL);
