INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('3263f3e4-ea7f-4d68-b31e-f5d58f16aa4c','bcfe85db-750a-4fef-aa15-8f84fd005882',6,'ordering','Put the words in the correct order.',NULL,'She has got long hair',NULL,NULL,NULL,'Trật tự: She + has got + long + hair.',NULL,NULL,'["has", "hair", "She", "got", "long"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('4b22da08-1c06-49af-b54b-a780c5a2c0e4','bcfe85db-750a-4fef-aa15-8f84fd005882',7,'ordering','Put the words in the correct order.',NULL,'I have got blue eyes',NULL,NULL,NULL,'Trật tự: I + have got + blue + eyes.',NULL,NULL,'["got", "blue", "have", "eyes", "I"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('c14cd262-ae97-4235-a75c-9c6bdcc0f426','bcfe85db-750a-4fef-aa15-8f84fd005882',8,'multiple_choice','My grandfather is quiet, but he is very ___.','["funny", "funnily", "fun", "funniness"]','funny',NULL,NULL,NULL,'Tính từ mô tả tính cách: funny.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
