INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('57aacc9d-ca24-440b-83a8-2136e30cef1c','bcfe85db-750a-4fef-aa15-8f84fd005882',10,'multiple_choice','He is not tall, he is ___.','["short", "shorter", "shortly", "shortness"]','short',NULL,NULL,NULL,'''Short'' là tính từ đối lập với ''tall''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('de0a508d-0d66-47bf-803b-a06a10a72439','bcfe85db-750a-4fef-aa15-8f84fd005882',11,'categorize','Sort each word by category.',NULL,NULL,NULL,NULL,NULL,'Phân loại từ tả ngoại hình và từ tả tính cách.',NULL,NULL,NULL,'["Appearance", "Personality"]','[{"text": "tall", "category": "Appearance"}, {"text": "hair", "category": "Appearance"}, {"text": "eyes", "category": "Appearance"}, {"text": "friendly", "category": "Personality"}, {"text": "quiet", "category": "Personality"}, {"text": "funny", "category": "Personality"}]',NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('3e33d8dd-2193-4a91-b322-fecb782471c0','bcfe85db-750a-4fef-aa15-8f84fd005882',12,'matching','Match each word to its meaning.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng tính từ với nghĩa.',NULL,'[{"left": "tall", "right": "opposite of short"}, {"left": "friendly", "right": "kind and nice to others"}, {"left": "quiet", "right": "doesn''t talk much"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('d1520901-54da-47c3-84f3-e532503de98e','bcfe85db-750a-4fef-aa15-8f84fd005882',13,'multiple_choice','She looks like her mother. She ___ got the same eyes.','["has", "have", "is", "does"]','has',NULL,NULL,NULL,'''She'' ngôi thứ 3 số ít dùng ''has got''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('cfdd020b-dd0c-48c8-9e17-ea29b63d8ef9','a1-s1-13-read-aloud-describing-people','My Grandmother',1,'reading','A1 Movers',NULL,'Let me tell you about my grandmother. She is not very tall; she is quite short. She has got short grey hair and kind brown eyes. She is friendly and quiet, but she is also very funny. She always smiles when she talks to me. People say I look like her because we have got the same eyes. My grandmother has got a warm heart. I love spending time with her every weekend.','[{"text":"Let me tell you about my grandmother.","ipa":"/lɛt mi tɛl ju əˈbaʊt maɪ ˈɡrændˌmʌðər./","vi":"Để mình kể cho bạn nghe về bà của mình nhé."},{"text":"She is not very tall; she is quite short.","ipa":"/ʃi ɪz nɑt ˈvɛri tɔl; ʃi ɪz kwaɪt ʃɔrt./","vi":"Bà không cao lắm; bà khá thấp."},{"text":"She has got short grey hair and kind brown eyes.","ipa":"/ʃi həz ɡɑt ʃɔrt ɡreɪ hɛr ænd kaɪnd braʊn aɪz./","vi":"Bà có mái tóc ngắn màu xám và đôi mắt nâu hiền từ."},{"text":"She is friendly and quiet, but she is also very funny.","ipa":"/ʃi ɪz ˈfrɛndli ænd ˈkwaɪət, bʌt ʃi ɪz ˈɔlsoʊ ˈvɛri ˈfʌni./","vi":"Bà rất thân thiện và ít nói, nhưng bà cũng rất hài hước."},{"text":"She always smiles when she talks to me.","ipa":"/ʃi ˈɔlweɪz smaɪlz wɛn ʃi tɔks tu mi./","vi":"Bà luôn mỉm cười khi trò chuyện với mình."},{"text":"People say I look like her because we have got the same eyes.","ipa":"/ˈpipəl seɪ aɪ lʊk laɪk hər bɪˈkəz wi həv ɡɑt ðə seɪm aɪz./","vi":"Mọi người bảo mình trông giống bà vì hai bà cháu có đôi mắt giống hệt nhau."},{"text":"My grandmother has got a warm heart.","ipa":"/maɪ ˈɡrændˌmʌðər həz ɡɑt ə wɔrm hɑrt./","vi":"Bà mình là người có trái tim ấm áp."},{"text":"I love spending time with her every weekend.","ipa":"/aɪ lʌv ˈspɛndɪŋ taɪm wɪð hər ˈɛvəri ˈwikˌɛnd./","vi":"Mình rất thích dành thời gian ở bên bà vào mỗi cuối tuần."}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,130,'a1-s1','264127e4120e4d2bb62236b78f0189b9',NULL,NULL,'2026-07-25T12:43:22.645Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('8ea7d800-13e5-4190-94f8-a1d3ed3e3431','a1-s1-14-listen-describing-people','What Does Your Family Look Like?',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Emma: Hi Jack! Do you have a photo of your family?
Jack: Yes! This is my sister. She is tall and she has got long black hair.
Emma [happy]: She looks friendly. What about your brother?
Jack: My brother is short. He has got short brown hair and green eyes.
Emma: Is he funny?
Jack [happy]: Yes, he is very funny! He makes everyone laugh.
Emma: What does your grandmother look like?
Jack: She is quiet, but kind. She has got grey hair and blue eyes.
Emma: I think I look like my mother. We have both got brown eyes.
Jack [happy]: That''s nice! Is your mother tall or short?
Emma: She is tall, like me.
Jack: My mother is young. She has got curly hair.
Emma: What color are her eyes?
Jack: Her eyes are brown, just like mine.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,140,'a1-s1','264127e4120e4d2bb62236b78f0189b9',NULL,NULL,'2026-07-25T12:43:22.645Z',NULL);
