INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('940ac4be-1649-43ff-92a3-058f29e907ed','8ea7d800-13e5-4190-94f8-a1d3ed3e3431',10,'matching','Match each person to their description.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng người với đặc điểm ngoại hình.',NULL,'[{"left": "Jack''s sister", "right": "tall, long black hair"}, {"left": "Jack''s brother", "right": "short, green eyes"}, {"left": "Jack''s grandmother", "right": "grey hair, blue eyes"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('d4473135-a450-4970-9b1c-11750eaacc4c','8ea7d800-13e5-4190-94f8-a1d3ed3e3431',11,'categorize','Sort each person by height.',NULL,NULL,NULL,NULL,NULL,'Phân loại nhân vật theo chiều cao được nhắc tới trong hội thoại.',NULL,NULL,NULL,'["Tall", "Short"]','[{"text": "Jack''s sister", "category": "Tall"}, {"text": "Jack''s brother", "category": "Short"}, {"text": "Emma", "category": "Tall"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('1e6046d8-0f62-445d-bf72-d5cb6453ac99','a1-s1-15-reading-family-gathering','A Big Family Gathering',1,'reading','A1 Movers',NULL,'Every summer, my family has a big gathering. My grandparents, aunts, uncles, and cousins all come together. My grandmother is short with grey hair, and she always cooks delicious food. My uncle is tall and very funny - he always tells jokes. We usually eat lunch together at one o''clock. After that, the children play games in the garden. My cousins and I sometimes play football together. In the evening, everyone sits together and talks about the year. My family gathering happens once a year, but it is my favorite day. I always feel happy when I am with my family.','[{"text":"Every summer, my family has a big gathering.","ipa":"/ˈɛvri ˈsʌmər, maɪ ˈfæməli hæz ə bɪɡ ˈɡæðərɪŋ./","vi":"Mỗi mùa hè, gia đình tôi đều có một buổi họp mặt lớn."},{"text":"My grandparents, aunts, uncles, and cousins all come together.","ipa":"/maɪ ˈɡrændˌpɛrənts, ænts, ˈʌŋkəlz, ænd ˈkʌzənz ɔl kʌm təˈɡɛðər./","vi":"Ông bà, cô dì, chú bác và anh chị em họ của tôi đều tụ họp lại."},{"text":"My grandmother is short with grey hair, and she always cooks delicious food.","ipa":"/maɪ ˈɡrændˌmʌðər ɪz ʃɔrt wɪð ɡreɪ hɛr, ænd ʃi ˈɔlweɪz kʊks dɪˈlɪʃəs fud./","vi":"Bà tôi thấp, tóc bạc, và bà luôn nấu những món ăn rất ngon."},{"text":"My uncle is tall and very funny - he always tells jokes.","ipa":"/maɪ ˈʌŋkəl ɪz tɔl ænd ˈvɛri ˈfʌni - hi ˈɔlweɪz tɛlz dʒoʊks./","vi":"Chú tôi cao và rất hài hước - chú ấy luôn kể chuyện cười."},{"text":"We usually eat lunch together at one o''clock.","ipa":"/wi ˈjuʒuəli it lʌntʃ təˈɡɛðər æt wʌn əˈklɑk./","vi":"Chúng tôi thường ăn trưa cùng nhau vào lúc một giờ."},{"text":"After that, the children play games in the garden.","ipa":"/ˈæftər ðæt, ðə ˈtʃɪldrən pleɪ ɡeɪmz ɪn ðə ˈɡɑrdən./","vi":"Sau đó, bọn trẻ chơi đùa trong vườn."},{"text":"My cousins and I sometimes play football together.","ipa":"/maɪ ˈkʌzənz ænd aɪ ˈsʌmˌtaɪmz pleɪ ˈfʊtˌbɔl təˈɡɛðər./","vi":"Tôi và các anh chị em họ thỉnh thoảng chơi đá bóng cùng nhau."},{"text":"In the evening, everyone sits together and talks about the year.","ipa":"/ɪn ði ˈivnɪŋ, ˈɛvriˌwʌn sɪts təˈɡɛðər ænd tɔks əˈbaʊt ðə jɪr./","vi":"Vào buổi tối, mọi người ngồi lại với nhau và trò chuyện về một năm đã qua."},{"text":"My family gathering happens once a year, but it is my favorite day.","ipa":"/maɪ ˈfæməli ˈɡæðərɪŋ ˈhæpənz wʌns ə jɪr, bʌt ɪt ɪz maɪ ˈfeɪvərɪt deɪ./","vi":"Buổi họp mặt gia đình tôi diễn ra mỗi năm một lần, nhưng đó là ngày tôi yêu thích nhất."},{"text":"I always feel happy when I am with my family.","ipa":"/aɪ ˈɔlweɪz fil ˈhæpi wɛn aɪ æm wɪð maɪ ˈfæməli./","vi":"Tôi luôn cảm thấy hạnh phúc khi được ở bên gia đình mình."}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'reading_comprehension',NULL,150,'a1-s1','63fcb6083c8ab61c175811c3f3ff2625',NULL,NULL,'2026-07-25T12:43:22.645Z',NULL);
