INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('c2d0f34b-9528-4e0e-82d7-9729a999626f','1e6046d8-0f62-445d-bf72-d5cb6453ac99',6,'ordering','Put the words in the correct order.',NULL,'We usually eat lunch together',NULL,NULL,NULL,'Trật tự: We + usually + eat + lunch + together.',NULL,NULL,'["together", "lunch", "eat", "We", "usually"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('32222d48-e792-4e7d-9547-e884310e9a9b','1e6046d8-0f62-445d-bf72-d5cb6453ac99',7,'matching','Match each person to what they do.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng người với hành động trong bài đọc.',NULL,'[{"left": "Grandmother", "right": "cooks delicious food"}, {"left": "Uncle", "right": "tells jokes"}, {"left": "Children", "right": "play games in the garden"}]',NULL,NULL,NULL,NULL,NULL);
