INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('d62531b5-55d1-4170-a545-617502e55b57','a1-s1-16-mixed-checkpoint','The Person I Live With',1,'mixed','A1 Movers',NULL,'I live with my older sister, Lily. She is nineteen years old, and she has got long brown hair and green eyes. She is tall and friendly, and she is also very funny. Every morning, Lily wakes up at seven o''clock. She usually has breakfast, then she starts work at nine o''clock. She works at a hospital as a nurse. Lily always helps me with my homework after school. We sometimes cook dinner together, and we often watch movies at weekends. She never gets angry with me. Once a week, we visit our grandparents together. I think I am very lucky to live with my sister.','[{"text":"I live with my older sister, Lily.","ipa":"/aɪ lɪv wɪð maɪ ˈoʊldər ˈsɪstər, ˈlɪli./","vi":"Tôi sống cùng chị gái của tôi, Lily."},{"text":"She is nineteen years old, and she has got long brown hair and green eyes.","ipa":"/ʃi ɪz naɪnˈtin jɪrz oʊld, ænd ʃi hæz gɑt lɔŋ braʊn hɛr ænd grin aɪz./","vi":"Chị ấy mười chín tuổi, có mái tóc dài màu nâu và đôi mắt màu xanh lá."},{"text":"She is tall and friendly, and she is also very funny.","ipa":"/ʃi ɪz tɔl ænd ˈfrɛndli, ænd ʃi ɪz ˈɔlsoʊ ˈvɛri ˈfʌni./","vi":"Chị ấy cao, thân thiện và cũng rất vui tính."},{"text":"Every morning, Lily wakes up at seven o''clock.","ipa":"/ˈɛvri ˈmɔrnɪŋ, ˈlɪli weɪks ʌp æt ˈsɛvən əˈklɑk./","vi":"Mỗi sáng, Lily thức dậy lúc bảy giờ."},{"text":"She usually has breakfast, then she starts work at nine o''clock.","ipa":"/ʃi ˈjuʒuəli hæz ˈbrɛkfəst, ðɛn ʃi stɑrts wɜrk æt naɪn əˈklɑk./","vi":"Chị ấy thường ăn sáng, sau đó bắt đầu làm việc lúc chín giờ."},{"text":"She works at a hospital as a nurse.","ipa":"/ʃi wɜrks æt ə ˈhɑˌspɪtəl æz ə nɜrs./","vi":"Chị ấy làm y tá tại một bệnh viện."},{"text":"Lily always helps me with my homework after school.","ipa":"/ˈlɪli ˈɔlweɪz hɛlps mi wɪð maɪ ˈhoʊmˌwɜrk ˈæftər skul./","vi":"Lily luôn giúp tôi làm bài tập về nhà sau giờ học."},{"text":"We sometimes cook dinner together, and we often watch movies at weekends.","ipa":"/wi ˈsʌmˌtaɪmz kʊk ˈdɪnər təˈgɛðər, ænd wi ˈɔfən wɑtʃ ˈmuviz æt ˈwiˌkɛndz./","vi":"Chúng tôi thỉnh thoảng nấu bữa tối cùng nhau và thường xem phim vào cuối tuần."},{"text":"She never gets angry with me.","ipa":"/ʃi ˈnɛvər gɛts ˈæŋgri wɪð mi./","vi":"Chị ấy không bao giờ giận tôi."},{"text":"Once a week, we visit our grandparents together.","ipa":"/wʌns ə wik, wi ˈvɪzɪt ˈaʊər ˈgrændˌpɛrənts təˈgɛðər./","vi":"Mỗi tuần một lần, chúng tôi cùng nhau đi thăm ông bà."},{"text":"I think I am very lucky to live with my sister.","ipa":"/aɪ θɪŋk aɪ æm ˈvɛri ˈlʌki tu lɪv wɪð maɪ ˈsɪstər./","vi":"Tôi nghĩ mình rất may mắn khi được sống cùng chị gái."}]',NULL,'I live with my older sister, Lily. She is nineteen years old, and she has got long brown hair and green eyes. She is tall and friendly, and she is also very funny. Every morning, Lily wakes up at seven o''clock. She usually has breakfast, then she starts work at nine o''clock. She works at a hospital as a nurse. Lily always helps me with my homework after school. We sometimes cook dinner together, and we often watch movies at weekends. She never gets angry with me. Once a week, we visit our grandparents together. I think I am very lucky to live with my sister.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mixed_all',NULL,160,'a1-s1','686966f831a6465b92b3356bad5730e9',NULL,NULL,'2026-07-25T12:43:22.645Z',NULL);
