INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('ce8f2f0f-5a2d-4600-8b27-53244cb72f0f','bc8cefa3-bfc5-45b7-b4f6-e95b9550f7f7',14,'categorize','Sort each phrase by the correct preposition (in / on / at).',NULL,NULL,NULL,NULL,NULL,'Chia theo loại thời gian: buổi trong ngày → ''in'', ngày → ''on'', giờ cụ thể → ''at''.',NULL,NULL,NULL,'["in","on","at"]','[{"text":"the morning","category":"in"},{"text":"Monday","category":"on"},{"text":"9 o''clock","category":"at"},{"text":"the afternoon","category":"in"},{"text":"Friday","category":"on"},{"text":"break time","category":"at"}]',NULL,'prepositions-time');
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('b7a11921-3f38-4b0a-b350-e0670472edfe','bc8cefa3-bfc5-45b7-b4f6-e95b9550f7f7',15,'categorize','Sort each phrase by the correct preposition (in / on / at).',NULL,NULL,NULL,NULL,NULL,'''at night'' và ''at the weekend'' là cụm cố định; ngày trong tuần dùng ''on''; buổi trong ngày dùng ''in''.',NULL,NULL,NULL,'["in","on","at"]','[{"text":"night","category":"at"},{"text":"the weekend","category":"at"},{"text":"Sunday","category":"on"},{"text":"the evening","category":"in"},{"text":"break time","category":"at"},{"text":"Monday","category":"on"}]',NULL,'prepositions-time');
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('a2be90ff-6ff1-450c-ace3-d2bb50467df1','a1-s2-03-read-aloud-timetable','My School Timetable',1,'reading','A1 Movers',NULL,'Look at my school timetable! On Monday, I have four lessons. My first subject is Maths, from nine to ten o''clock. Next, I have English. I like English very much. After that, we have a short break. Then I have Science, from eleven to twelve. In the afternoon, I have History. History is interesting, but it is a little hard for me. Our lessons finish at three o''clock. I always check my timetable before school. It helps me remember every lesson!','[{"text":"Look at my school timetable!","ipa":"/lʊk æt maɪ skul ˈtaɪmˌteɪbəl/","vi":"Hãy nhìn vào thời khóa biểu ở trường của mình này!"},{"text":"On Monday, I have four lessons.","ipa":"/ɑn ˈmʌndeɪ, aɪ hæv fɔr ˈlɛsənz./","vi":"Vào thứ Hai, mình có bốn tiết học."},{"text":"My first subject is Maths, from nine to ten o''clock.","ipa":"/maɪ fɜrst ˈsʌbdʒɪkt ɪz mæθs, frʌm naɪn tu tɛn əˈklɑk./","vi":"Môn học đầu tiên của mình là Toán, từ chín giờ đến mười giờ."},{"text":"Next, I have English.","ipa":"/nɛkst, aɪ hæv ˈɪŋɡlɪʃ./","vi":"Tiếp theo, mình có môn Tiếng Anh."},{"text":"I like English very much.","ipa":"/aɪ laɪk ˈɪŋɡlɪʃ ˈvɛri mʌtʃ./","vi":"Mình rất thích môn Tiếng Anh."},{"text":"After that, we have a short break.","ipa":"/ˈæftər ðæt, wi hæv ə ʃɔrt breɪk./","vi":"Sau đó, chúng mình có một giờ giải lao ngắn."},{"text":"Then I have Science, from eleven to twelve.","ipa":"/ðɛn aɪ hæv ˈsaɪəns, frʌm ɪˈlɛvən tu twɛlv./","vi":"Sau đó mình có môn Khoa học, từ mười một giờ đến mười hai giờ."},{"text":"In the afternoon, I have History.","ipa":"/ɪn ði ˌæftərˈnun, aɪ hæv ˈhɪstəri./","vi":"Vào buổi chiều, mình có môn Lịch sử."},{"text":"History is interesting, but it is a little hard for me.","ipa":"/ˈhɪstəri ɪz ˈɪntrəstɪŋ, bʌt ɪt ɪz ə ˈlɪtəl hɑrd fɔr mi./","vi":"Lịch sử rất thú vị, nhưng nó hơi khó đối với mình."},{"text":"Our lessons finish at three o''clock.","ipa":"/ˈaʊər ˈlɛsənz ˈfɪnɪʃ æt θri əˈklɑk./","vi":"Các tiết học của chúng mình kết thúc lúc ba giờ."},{"text":"I always check my timetable before school.","ipa":"/aɪ ˈɔlˌweɪz tʃɛk maɪ ˈtaɪmˌteɪbəl bɪˈfɔr skul./","vi":"Mình luôn kiểm tra thời khóa biểu trước khi đến trường."},{"text":"It helps me remember every lesson!","ipa":"/ɪt hɛlps mi rɪˈmɛmbər ˈɛvəri ˈlɛsən!/","vi":"Nó giúp mình nhớ được mọi tiết học!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,230,'a1-s2','499aee0ac29b416fbb9d69796f59f2ed',NULL,NULL,'2026-07-25T12:44:28.068Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('3091c08f-deb0-4bc3-87be-cd34777b2fdd','a1-s2-04-listen-timetable','What''s Your Timetable?',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Emma: Hi Jack! What subjects do you have on Monday?
Jack: Hi Emma! I have Maths and English on Monday.
Emma: Do you have History too?
Jack: No, I have History on Tuesday.
Emma: What time is your first lesson?
Jack: It starts at nine o''clock and finishes at ten.
Emma: When is your break?
Jack: Our break is at half past ten, in the morning.
Emma: Do you like Science?
Jack [excited]: Yes, I love Science! It''s very interesting.
Emma: What about English?
Jack: English is good, but Maths is a little hard for me.
Emma: What time do your lessons finish?
Jack: They finish at three o''clock every day.
Emma [happy]: Thanks, Jack! See you at school.
Jack [happy]: See you, Emma!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,240,'a1-s2','499aee0ac29b416fbb9d69796f59f2ed',NULL,NULL,'2026-07-25T12:44:28.068Z',NULL);
