INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('ff9809cb-c8a7-4dae-a813-6f127d51f3a5','a1-s2-08-read-aloud-my-job','My Job',1,'reading','A1 Movers',NULL,'Hello! My name is Sam. I work in a big company in the city. I work in an office with my colleagues. Every day, I talk to different customers. Sometimes I have a meeting with my manager. My job is hard, but it is also very interesting. I get a good salary at the end of the month. I like my colleagues. They are friendly and helpful. We work together every day. I am happy with my job!','[{"text":"Hello!","ipa":"/həˈloʊ/","vi":"Xin chào!"},{"text":"My name is Sam.","ipa":"/maɪ neɪm ɪz sæm/","vi":"Tên tôi là Sam."},{"text":"I work in a big company in the city.","ipa":"/aɪ wɜrk ɪn ə bɪg ˈkʌmpəni ɪn ðə ˈsɪti/","vi":"Tôi làm việc tại một công ty lớn trong thành phố."},{"text":"I work in an office with my colleagues.","ipa":"/aɪ wɜrk ɪn ən ˈɔfɪs wɪð maɪ ˈkɑligz/","vi":"Tôi làm việc trong văn phòng cùng với các đồng nghiệp của mình."},{"text":"Every day, I talk to different customers.","ipa":"/ˈɛvri deɪ, aɪ tɔk tu ˈdɪfrənt ˈkʌstəmərz/","vi":"Mỗi ngày, tôi nói chuyện với nhiều khách hàng khác nhau."},{"text":"Sometimes I have a meeting with my manager.","ipa":"/ˈsʌmtaɪmz aɪ hæv ə ˈmitɪŋ wɪð maɪ ˈmænɪdʒər/","vi":"Thỉnh thoảng tôi có cuộc họp với quản lý của mình."},{"text":"My job is hard, but it is also very interesting.","ipa":"/maɪ dʒɑb ɪz hɑrd, bʌt ɪt ɪz ˈɔlsoʊ ˈvɛri ˈɪntrəstɪŋ/","vi":"Công việc của tôi rất vất vả, nhưng cũng rất thú vị."},{"text":"I get a good salary at the end of the month.","ipa":"/aɪ gɛt ə gʊd ˈsæləri æt ðə ɛnd ʌv ðə mʌnθ/","vi":"Tôi nhận được mức lương tốt vào cuối tháng."},{"text":"I like my colleagues.","ipa":"/aɪ laɪk maɪ ˈkɑligz/","vi":"Tôi quý mến các đồng nghiệp của mình."},{"text":"They are friendly and helpful.","ipa":"/ðeɪ ɑr ˈfrɛndli ænd ˈhɛlpfʊl/","vi":"Họ rất thân thiện và hay giúp đỡ."},{"text":"We work together every day.","ipa":"/wi wɜrk təˈgɛðər ˈɛvri deɪ/","vi":"Chúng tôi làm việc cùng nhau mỗi ngày."},{"text":"I am happy with my job!","ipa":"/aɪ æm ˈhæpi wɪð maɪ dʒɑb/","vi":"Tôi rất vui với công việc của mình!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,280,'a1-s2','8646d5fe42d94ece9c4973e8cad89e84',NULL,NULL,'2026-07-25T12:44:28.068Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('3aca09f3-60a5-48df-b29d-c3c657849d21','a1-s2-09-listen-what-do-you-do','What Do You Do?',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Sophie: Hi Daniel! What do you do?
Daniel: Hi Sophie! I work in an office. I work as an accountant.
Sophie: Do you like your job?
Daniel: Yes, it''s interesting, but sometimes it''s hard.
Sophie: Do you have a lot of meetings?
Daniel: Yes, I have a meeting every Monday morning.
Sophie: Who do you work with?
Daniel: I work with my colleagues. They are very friendly.
Sophie: Do you talk to customers?
Daniel: No, I don''t talk to customers. I work with numbers.
Sophie: Is the salary good?
Daniel [happy]: Yes, the salary is good. I''m happy with my job.
Sophie: What company do you work for?
Daniel: I work for a big company called Blue Star.
Sophie [happy]: That sounds great, Daniel!
Daniel [happy]: Thanks, Sophie! What do you do?',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,290,'a1-s2','8646d5fe42d94ece9c4973e8cad89e84',NULL,NULL,'2026-07-25T12:44:28.068Z',NULL);
