INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('c295b9d6-9cc2-43d9-a258-dee6a0b2e015','d4352678-949f-40a9-b9b6-1cbf4b89fed3',13,'ordering','Put the words in the correct order.',NULL,'Sorry you can''t use this',NULL,NULL,NULL,'Trật tự: Sorry + you + can''t + động từ + tân ngữ.',NULL,NULL,'["can''t","this","you","use","Sorry"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('a1c8b030-0e13-4ae6-8a18-33ca5607fae4','d4352678-949f-40a9-b9b6-1cbf4b89fed3',14,'categorize','Sort each sentence: asking permission or giving/refusing permission?',NULL,NULL,NULL,NULL,NULL,'Câu hỏi xin phép bắt đầu bằng Can/Could I; câu trả lời là cho/từ chối phép.',NULL,NULL,NULL,'["Asking permission","Giving/refusing permission"]','[{"text":"Can I use this?","category":"Asking permission"},{"text":"Of course you can.","category":"Giving/refusing permission"},{"text":"Could I borrow it?","category":"Asking permission"},{"text":"Sorry, you can''t.","category":"Giving/refusing permission"},{"text":"Can I turn it off?","category":"Asking permission"},{"text":"Yes, you can.","category":"Giving/refusing permission"}]',NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('08c67fff-b3ee-43da-9668-0381d1bcdbd9','d4352678-949f-40a9-b9b6-1cbf4b89fed3',15,'categorize','Sort each sentence: asking permission or giving/refusing permission?',NULL,NULL,NULL,NULL,NULL,'Câu hỏi xin phép bắt đầu bằng Can/Could I; câu trả lời là cho/từ chối phép.',NULL,NULL,NULL,'["Asking permission","Giving/refusing permission"]','[{"text":"Can I use your ruler?","category":"Asking permission"},{"text":"Sorry, it''s not allowed.","category":"Giving/refusing permission"},{"text":"Could I use the computer?","category":"Asking permission"},{"text":"Of course, go ahead.","category":"Giving/refusing permission"},{"text":"Can I be late today?","category":"Asking permission"},{"text":"No, you can''t be late.","category":"Giving/refusing permission"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('3388d3f7-dfc9-46da-9e43-a2891a2edd48','a1-s2-13-read-aloud-classroom-rules','Classroom Rules',1,'reading','A1 Movers',NULL,'In our classroom, we have some rules. First, we are not allowed to use our phones in class. Second, we can borrow a pencil if we ask nicely. ''Can I borrow your pencil?'' ''Of course!'' Third, we always turn off the lights before we go home. Fourth, we must not be late for class. If you are late, please say sorry to the teacher. These rules help our classroom stay safe and happy. I always follow the rules at school!','[{"text":"In our classroom, we have some rules.","ipa":"/ɪn ˈaʊər ˈklæsˌruːm, wi hæv sʌm ruːlz./","vi":"Trong lớp học của chúng ta có một vài quy định."},{"text":"First, we are not allowed to use our phones in class.","ipa":"/fɜːrst, wi ɑːr nɑːt əˈlaʊd tuː juːz ˈaʊər foʊnz ɪn klæs./","vi":"Thứ nhất, chúng ta không được phép sử dụng điện thoại trong lớp."},{"text":"Second, we can borrow a pencil if we ask nicely.","ipa":"/ˈsɛkənd, wi kæn ˈbɑːroʊ ə ˈpɛnsəl ɪf wi æsk ˈnaɪsli./","vi":"Thứ hai, chúng ta có thể mượn bút chì nếu hỏi một cách lịch sự."},{"text":"''Can I borrow your pencil?''","ipa":"/kæn aɪ ˈbɑːroʊ jʊər ˈpɛnsəl?/","vi":"Tớ mượn bút chì của cậu được không?"},{"text":"''Of course!''","ipa":"/əv ˈkɔːrs!/","vi":"Được chứ!"},{"text":"Third, we always turn off the lights before we go home.","ipa":"/θɜːrd, wi ˈɔːlˌweɪz tɜːrn ɔːf ðə laɪts bɪˈfɔːr wi ɡoʊ hoʊm./","vi":"Thứ ba, chúng ta luôn tắt đèn trước khi ra về."},{"text":"Fourth, we must not be late for class.","ipa":"/fɔːrθ, wi mʌst nɑːt bi leɪt fɔːr klæs./","vi":"Thứ tư, chúng ta không được đi học muộn."},{"text":"If you are late, please say sorry to the teacher.","ipa":"/ɪf juː ɑːr leɪt, pliːz seɪ ˈsɑːri tuː ðə ˈtiːtʃər./","vi":"Nếu bạn đi muộn, hãy xin lỗi giáo viên nhé."},{"text":"These rules help our classroom stay safe and happy.","ipa":"/ðiːz ruːlz hɛlp ˈaʊər ˈklæsˌruːm steɪ seɪf ænd ˈhæpi./","vi":"Những quy định này giúp lớp học của chúng ta an toàn và vui vẻ."},{"text":"I always follow the rules at school!","ipa":"/aɪ ˈɔːlˌweɪz ˈfɑːloʊ ðə ruːlz æt skuːl!/","vi":"Tớ luôn tuân thủ các quy định ở trường!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,330,'a1-s2','d0e340b026be48a9813f9de0ef9db059',NULL,NULL,'2026-07-25T12:44:28.068Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('1265ad74-8a85-4d46-8d08-116f6752e0fd','a1-s2-14-listen-can-i-use-this','Can I Use This?',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Oliver: Hi Grace! Can I borrow your ruler, please?
Grace: Of course! Here you are.
Oliver: Thanks! Could I also use your eraser?
Grace [gentle]: Sorry, you can''t. I need it right now.
Oliver: That''s okay. Can I turn off the light? It''s too bright.
Grace: Yes, you can. Go ahead.
Oliver: Is it allowed to use tools in the workshop alone?
Grace [serious]: No, it isn''t. You must ask the teacher first.
Oliver: I see. What are the rules for the workshop?
Grace [serious]: We must wear a helmet, and we can''t be late for the safety talk.
Oliver: Okay, thank you for telling me the rules.
Grace: No problem, Oliver. Let''s go to class now.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,340,'a1-s2','d0e340b026be48a9813f9de0ef9db059',NULL,NULL,'2026-07-25T12:44:28.068Z',NULL);
