INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('f78ba72f-34cf-4b42-8ded-5e30b04b8f2c','1265ad74-8a85-4d46-8d08-116f6752e0fd',13,'matching','Match each item to what happens with it.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng đồ vật với sự việc trong hội thoại.',NULL,'[{"left":"Ruler","right":"Oliver borrows it"},{"left":"Eraser","right":"Grace needs it"},{"left":"Light","right":"Oliver turns it off"},{"left":"Helmet","right":"students must wear it"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('c1c343fe-b4e3-42dd-bc51-d8e5d71b95fe','1265ad74-8a85-4d46-8d08-116f6752e0fd',14,'matching','Match each sentence to its function.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng chức năng giao tiếp của từng câu.',NULL,'[{"left":"Of course!","right":"giving permission"},{"left":"Sorry, you can''t.","right":"refusing permission"},{"left":"Can I ...?","right":"asking permission"},{"left":"You must ...","right":"a rule"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('34fea0a9-66ae-496f-b0b0-c1acf1c1c017','a1-s2-15-reading-people-at-school','The People Who Work at School',1,'reading','A1 Movers',NULL,'Ms. Parker works at Greenfield School. She is the school secretary. Every morning, she opens the office and answers the phone. Mr. Lopez is the caretaker. He arrives early and checks that everything is clean and safe. Mrs. Adams is a teacher. She teaches English to Class 4. She works hard every day and helps her students learn new words. The headteacher, Mr. Wilson, walks around the school and talks to teachers and students. He checks that everyone is having a good day. At lunchtime, the school cook, Sam, makes food for all the students. In the afternoon, Mrs. Adams has a meeting with other teachers. They talk about their students'' work. All these people work together to make school a great place. Everyone has an important job!','[{"text":"Ms. Parker works at Greenfield School.","ipa":"/ˈmɪz ˈpɑrkər wɜrks æt ˈgrinˌfild skul./","vi":"Cô Parker làm việc tại trường Greenfield."},{"text":"She is the school secretary.","ipa":"/ʃi ɪz ðə skul ˈsɛkrəˌtɛri./","vi":"Cô ấy là thư ký của trường."},{"text":"Every morning, she opens the office and answers the phone.","ipa":"/ˈɛvri ˈmɔrnɪŋ, ʃi ˈoʊpənz ði ˈɔfɪs ænd ˈænsərz ðə foʊn./","vi":"Mỗi sáng, cô ấy mở văn phòng và trả lời điện thoại."},{"text":"Mr. Lopez is the caretaker.","ipa":"/ˈmɪstər ˈloʊpɛz ɪz ðə ˈkɛrˌteɪkər./","vi":"Ông Lopez là người quản lý trường học."},{"text":"He arrives early and checks that everything is clean and safe.","ipa":"/hi əˈraɪvz ˈɜrli ænd tʃɛks ðæt ˈɛvriˌθɪŋ ɪz klin ænd seɪf./","vi":"Ông ấy đến sớm và kiểm tra xem mọi thứ có sạch sẽ và an toàn không."},{"text":"Mrs. Adams is a teacher.","ipa":"/ˈmɪsɪz ˈædəmz ɪz ə ˈtitʃər./","vi":"Bà Adams là một giáo viên."},{"text":"She teaches English to Class 4.","ipa":"/ʃi ˈtitʃəz ˈɪŋɡlɪʃ tu klæs fɔr./","vi":"Bà ấy dạy tiếng Anh cho Lớp 4."},{"text":"She works hard every day and helps her students learn new words.","ipa":"/ʃi wɜrks hɑrd ˈɛvri deɪ ænd hɛlps hɜr ˈstudənts lɜrn nu wɜrdz./","vi":"Bà ấy làm việc chăm chỉ mỗi ngày và giúp học sinh học từ mới."},{"text":"The headteacher, Mr. Wilson, walks around the school and talks to teachers and students.","ipa":"/ðə ˈhɛdˌtitʃər, ˈmɪstər ˈwɪlsən, wɔks əˈraʊnd ðə skul ænd tɔks tu ˈtitʃərz ænd ˈstudənts./","vi":"Hiệu trưởng, ông Wilson, đi quanh trường và trò chuyện với giáo viên và học sinh."},{"text":"He checks that everyone is having a good day.","ipa":"/hi tʃɛks ðæt ˈɛvriˌwʌn ɪz ˈhævɪŋ ə ɡʊd deɪ./","vi":"Ông ấy kiểm tra xem mọi người có một ngày tốt lành không."},{"text":"At lunchtime, the school cook, Sam, makes food for all the students.","ipa":"/æt ˈlʌntʃˌtaɪm, ðə skul kʊk, sæm, meɪks fud fɔr ɔl ðə ˈstudənts./","vi":"Vào giờ ăn trưa, đầu bếp của trường, Sam, chuẩn bị thức ăn cho tất cả học sinh."},{"text":"In the afternoon, Mrs. Adams has a meeting with other teachers.","ipa":"/ɪn ði ˈæftərˌnun, ˈmɪsɪz ˈædəmz hæz ə ˈmitɪŋ wɪð ˈʌðər ˈtitʃərz./","vi":"Vào buổi chiều, bà Adams có một cuộc họp với các giáo viên khác."},{"text":"They talk about their students'' work.","ipa":"/ðeɪ tɔk əˈbaʊt ðɛr ˈstudənts wɜrk./","vi":"Họ thảo luận về kết quả học tập của học sinh."},{"text":"All these people work together to make school a great place.","ipa":"/ɔl ðiz ˈpipəl wɜrk təˈɡɛðər tu meɪk skul ə ɡreɪt pleɪs./","vi":"Tất cả những người này làm việc cùng nhau để biến trường học thành một nơi tuyệt vời."},{"text":"Everyone has an important job!","ipa":"/ˈɛvriˌwʌn hæz ən ɪmˈpɔrtənt dʒɑb!/","vi":"Mọi người đều có một công việc quan trọng!"}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'reading_comprehension',NULL,350,'a1-s2','346b017295074994b5f978bb78510d70',NULL,NULL,'2026-07-25T12:44:28.068Z',NULL);
