INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('98a344de-0ded-4bdf-b1b9-dbb1054ed242','34fea0a9-66ae-496f-b0b0-c1acf1c1c017',14,'categorize','Sort each person by their role.',NULL,NULL,NULL,NULL,NULL,'Mrs. Adams trực tiếp dạy học sinh; những người còn lại giữ cho trường vận hành tốt.',NULL,NULL,NULL,'["Teaches students","Keeps school running"]','[{"text":"Mrs. Adams","category":"Teaches students"},{"text":"Ms. Parker","category":"Keeps school running"},{"text":"Mr. Lopez","category":"Keeps school running"},{"text":"Sam","category":"Keeps school running"},{"text":"Mr. Wilson","category":"Keeps school running"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('d62eeb35-d800-4314-8503-b45293ba7d5a','a1-s2-16-mixed-checkpoint','A Day at School or Work',1,'mixed','A1 Movers',NULL,'Every school day starts at eight o''clock. On Monday, I have Maths first, then English. We have a short break at half past ten. ''Can I have a biscuit?'' I ask my friend. ''Of course!'' she says. In the afternoon, I have Science and History. History is interesting, but Maths is a little hard for me. After school, my mother picks me up. She works in a big company in the city. She works hard every day and has a meeting every Friday. At home, we do our homework together. Before I go to bed, I turn off the light. It''s the end of a busy, happy day!','[{"text":"Every school day starts at eight o''clock.","ipa":"/ˈɛvri skul deɪ stɑrts æt eɪt əˈklɑk./","vi":"Mỗi ngày đi học đều bắt đầu lúc tám giờ."},{"text":"On Monday, I have Maths first, then English.","ipa":"/ɑn ˈmʌndeɪ, aɪ hæv mæθs fɜrst, ðɛn ˈɪŋɡlɪʃ./","vi":"Vào thứ Hai, mình học Toán trước, sau đó là tiếng Anh."},{"text":"We have a short break at half past ten.","ipa":"/wi hæv ə ʃɔrt breɪk æt hæf pæst tɛn./","vi":"Chúng mình có một giờ nghỉ ngắn lúc mười rưỡi."},{"text":"''Can I have a biscuit?'' I ask my friend.","ipa":"/kæn aɪ hæv ə ˈbɪskɪt? aɪ æsk maɪ frɛnd./","vi":"\"Mình ăn bánh quy được không?\" mình hỏi bạn."},{"text":"''Of course!'' she says.","ipa":"/əv kɔrs! ʃi sɛz./","vi":"\"Được chứ!\" bạn ấy nói."},{"text":"In the afternoon, I have Science and History.","ipa":"/ɪn ði ˌæftərˈnun, aɪ hæv ˈsaɪəns ænd ˈhɪstəri./","vi":"Vào buổi chiều, mình học môn Khoa học và Lịch sử."},{"text":"History is interesting, but Maths is a little hard for me.","ipa":"/ˈhɪstəri ɪz ˈɪntrəstɪŋ, bʌt mæθs ɪz ə ˈlɪtəl hɑrd fɔr mi./","vi":"Lịch sử thì thú vị, nhưng Toán hơi khó với mình một chút."},{"text":"After school, my mother picks me up.","ipa":"/ˈæftər skul, maɪ ˈmʌðər pɪks mi ʌp./","vi":"Sau giờ học, mẹ đón mình về."},{"text":"She works in a big company in the city.","ipa":"/ʃi wɜrks ɪn ə bɪɡ ˈkʌmpəni ɪn ðə ˈsɪti./","vi":"Mẹ làm việc tại một công ty lớn trong thành phố."},{"text":"She works hard every day and has a meeting every Friday.","ipa":"/ʃi wɜrks hɑrd ˈɛvri deɪ ænd hæz ə ˈmitɪŋ ˈɛvri ˈfraɪdeɪ./","vi":"Mẹ làm việc chăm chỉ mỗi ngày và có một cuộc họp vào mỗi thứ Sáu."},{"text":"At home, we do our homework together.","ipa":"/æt hoʊm, wi du ˈaʊər ˈhoʊmwɜrk təˈɡɛðər./","vi":"Ở nhà, chúng mình cùng nhau làm bài tập về nhà."},{"text":"Before I go to bed, I turn off the light.","ipa":"/bɪˈfɔr aɪ ɡoʊ tu bɛd, aɪ tɜrn ɔf ðə laɪt./","vi":"Trước khi đi ngủ, mình tắt đèn."},{"text":"It''s the end of a busy, happy day!","ipa":"/ɪts ði ɛnd ʌv ə ˈbɪzi, ˈhæpi deɪ!/","vi":"Vậy là kết thúc một ngày bận rộn và vui vẻ!"}]',NULL,'Every school day starts at eight o''clock. On Monday, I have Maths first, then English. We have a short break at half past ten. ''Can I have a biscuit?'' I ask my friend. ''Of course!'' she says. In the afternoon, I have Science and History. History is interesting, but Maths is a little hard for me. After school, my mother picks me up. She works in a big company in the city. She works hard every day and has a meeting every Friday. At home, we do our homework together. Before I go to bed, I turn off the light. It''s the end of a busy, happy day!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mixed_all',NULL,360,'a1-s2','b0620f9782ef410693417faa11918a0e',NULL,NULL,'2026-07-25T12:44:28.068Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('8197ce66-fb6d-44d7-add3-0c02815f9c24','d62eeb35-d800-4314-8503-b45293ba7d5a',0,'multiple_choice','What time does the school day start?','["Seven o''clock","Eight o''clock","Nine o''clock","Ten o''clock"]','Eight o''clock',NULL,NULL,NULL,'Đoạn ghi ''Every school day starts at eight o''clock''.',NULL,NULL,NULL,NULL,NULL,NULL,'prepositions-time');
