INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('4eb77741-9cde-4666-bbd5-fb0c71543826','d62eeb35-d800-4314-8503-b45293ba7d5a',2,'multiple_choice','When is the break?','["At half past nine","At half past ten","At eleven o''clock","At twelve o''clock"]','At half past ten',NULL,NULL,NULL,'Đoạn ghi ''a short break at half past ten''.',NULL,NULL,NULL,NULL,NULL,NULL,'prepositions-time');
