INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('5ee02a39-01be-4ad2-83f6-36e4c7af1d7c','a1-s3-03-read-aloud-family-meals','My Family''s Food Habits',1,'reading','A1 Movers',NULL,'My family usually eats breakfast at seven o''clock. We have some toast and a little jam. My mom likes fresh fruit every morning. At lunch, we eat a lot of vegetables and some rice. My dad doesn''t eat much meat, but he eats a few eggs every week. In the evening, we have dinner together. Sometimes we eat spicy noodles, but my little sister doesn''t like spicy food. She prefers salty snacks instead. We don''t have any sugar in our tea. I think fresh food tastes the best!','[{"text":"My family usually eats breakfast at seven o''clock.","ipa":"/maɪ ˈfæməli ˈjuʒuəli its ˈbrɛkfəst æt ˈsɛvən əˈklɑk./","vi":"Gia đình tôi thường ăn sáng lúc bảy giờ."},{"text":"We have some toast and a little jam.","ipa":"/wi hæv sʌm toʊst ænd ə ˈlɪtəl dʒæm./","vi":"Chúng tôi ăn bánh mì nướng và một ít mứt."},{"text":"My mom likes fresh fruit every morning.","ipa":"/maɪ mɑm laɪks frɛʃ frut ˈɛvəri ˈmɔrnɪŋ./","vi":"Mẹ tôi thích trái cây tươi vào mỗi buổi sáng."},{"text":"At lunch, we eat a lot of vegetables and some rice.","ipa":"/æt lʌntʃ, wi it ə lɑt ʌv ˈvɛdʒtəbəlz ænd sʌm raɪs./","vi":"Vào bữa trưa, chúng tôi ăn nhiều rau và một ít cơm."},{"text":"My dad doesn''t eat much meat, but he eats a few eggs every week.","ipa":"/maɪ dæd ˈdʌzənt it mʌtʃ mit, bʌt hi its ə fju ɛgz ˈɛvəri wik./","vi":"Bố tôi không ăn nhiều thịt, nhưng ông ấy ăn vài quả trứng mỗi tuần."},{"text":"In the evening, we have dinner together.","ipa":"/ɪn ði ˈivnɪŋ, wi hæv ˈdɪnər təˈgɛðər./","vi":"Vào buổi tối, chúng tôi ăn tối cùng nhau."},{"text":"Sometimes we eat spicy noodles, but my little sister doesn''t like spicy food.","ipa":"/ˈsʌmˌtaɪmz wi it ˈspaɪsi ˈnudəlz, bʌt maɪ ˈlɪtəl ˈsɪstər ˈdʌzənt laɪk ˈspaɪsi fud./","vi":"Đôi khi chúng tôi ăn mì cay, nhưng em gái tôi không thích đồ ăn cay."},{"text":"She prefers salty snacks instead.","ipa":"/ʃi priˈfɜrz ˈsɔlti snæks ɪnˈstɛd./","vi":"Con bé thích ăn đồ ăn vặt mặn hơn."},{"text":"We don''t have any sugar in our tea.","ipa":"/wi doʊnt hæv ˈɛni ˈʃʊgər ɪn ˈaʊər ti./","vi":"Chúng tôi không cho đường vào trà."},{"text":"I think fresh food tastes the best!","ipa":"/aɪ θɪŋk frɛʃ fud teɪsts ðə bɛst!/","vi":"Tôi nghĩ đồ ăn tươi là ngon nhất!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,430,'a1-s3','22943413d6f34b88b0b92888d79df2b1',NULL,NULL,'2026-07-25T12:45:24.335Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('a5bca6c6-c1bc-4a7b-9c3d-89512dff8ff2','a1-s3-04-listen-lunch-choices','What''s for Lunch?',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Oliver: Hi Emma! What''s for lunch today?
Emma: Hi Oliver! I have some rice and a little chicken.
Oliver: Nice! I have a lot of vegetables and some fresh fruit.
Emma: Do you have any spicy food?
Oliver: No, I don''t have any spicy food. I don''t like spicy food.
Emma: I have a few noodles too. They taste salty.
Oliver [happy]: Yum! I usually eat fruit after lunch.
Emma: Me too! Fresh apples are my favorite.
Oliver: Do you want some water?
Emma: Yes, please! I don''t have any juice today.
Oliver: Here you are. Let''s eat!
Emma: Thank you, Oliver!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,440,'a1-s3','22943413d6f34b88b0b92888d79df2b1',NULL,NULL,'2026-07-25T12:45:24.335Z',NULL);
