INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('1b4ebef5-f57e-4f7a-ab2a-dc20ad55cba6','a1-s3-08-read-aloud-shopping-list','Shopping at the Supermarket',1,'reading','A1 Movers',NULL,'Every Saturday, my mom and I go to the supermarket. We push a big trolley around the shop. First, we buy a kilo of rice and two bottles of water. Then we get a packet of noodles and some fresh vegetables. My mom asks, ''How many apples do we need?'' I say, ''We need six apples.'' At the checkout, my mom pays with her card. Sometimes she pays with cash instead. The cashier gives us a receipt and some change. We put everything in our bags and go home. Shopping at the supermarket is fun!','[{"text":"Every Saturday, my mom and I go to the supermarket.","ipa":"/ˈɛvri ˈsætərdeɪ, maɪ mɑm ænd aɪ ɡoʊ tu ðə ˈsupərmɑrkɪt./","vi":"Mỗi thứ Bảy, mẹ và tôi đều đi siêu thị."},{"text":"We push a big trolley around the shop.","ipa":"/wi pʊʃ ə bɪɡ ˈtrɑli əˈraʊnd ðə ʃɑp./","vi":"Chúng tôi đẩy một chiếc xe hàng lớn đi quanh cửa hàng."},{"text":"First, we buy a kilo of rice and two bottles of water.","ipa":"/fɜrst, wi baɪ ə ˈkiloʊ əv raɪs ænd tu ˈbɑtəlz əv ˈwɔtər./","vi":"Đầu tiên, chúng tôi mua một cân gạo và hai chai nước."},{"text":"Then we get a packet of noodles and some fresh vegetables.","ipa":"/ðɛn wi ɡɛt ə ˈpækɪt əv ˈnudəlz ænd sʌm frɛʃ ˈvɛdʒtəbəlz./","vi":"Sau đó, chúng tôi lấy một gói mì và một ít rau tươi."},{"text":"My mom asks, ''How many apples do we need?''","ipa":"/maɪ mɑm æsks, ''haʊ ˈmɛni ˈæpəlz du wi nid?''/","vi":"Mẹ tôi hỏi: ''Chúng ta cần bao nhiêu quả táo?''"},{"text":"I say, ''We need six apples.''","ipa":"/aɪ seɪ, ''wi nid sɪks ˈæpəlz.''/","vi":"Tôi trả lời: ''Chúng ta cần sáu quả táo.''"},{"text":"At the checkout, my mom pays with her card.","ipa":"/æt ðə ˈtʃɛkaʊt, maɪ mɑm peɪz wɪð hɜr kɑrd./","vi":"Tại quầy thanh toán, mẹ tôi trả tiền bằng thẻ."},{"text":"Sometimes she pays with cash instead.","ipa":"/ˈsʌmtaɪmz ʃi peɪz wɪð kæʃ ɪnˈstɛd./","vi":"Đôi khi mẹ trả bằng tiền mặt thay vì dùng thẻ."},{"text":"The cashier gives us a receipt and some change.","ipa":"/ðə kæˈʃɪr ɡɪvz ʌs ə rɪˈsit ænd sʌm tʃeɪndʒ./","vi":"Nhân viên thu ngân đưa cho chúng tôi hóa đơn và tiền thừa."},{"text":"We put everything in our bags and go home.","ipa":"/wi pʊt ˈɛvriθɪŋ ɪn ˈaʊər bæɡz ænd ɡoʊ hoʊm./","vi":"Chúng tôi cho mọi thứ vào túi và đi về nhà."},{"text":"Shopping at the supermarket is fun!","ipa":"/ˈʃɑpɪŋ æt ðə ˈsupərmɑrkɪt ɪz fʌn!/","vi":"Đi mua sắm ở siêu thị thật là vui!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,480,'a1-s3','72fd7560716c421db78fcf4a7a685656',NULL,NULL,'2026-07-25T12:45:24.335Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('6a3db1c5-964b-4d2e-9a30-9586b692b76c','a1-s3-09-listen-at-the-checkout','At the Checkout',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Sophie: Hello! Do you have a loyalty card?
James: No, I don''t. How much is the total?
Sophie: It''s twelve dollars and fifty cents.
James: How many bottles of water did I buy?
Sophie: You bought three bottles and one packet of biscuits.
James: Okay. Can I pay by card?
Sophie: Yes, of course. Or you can pay with cash.
James: I''ll pay by card, please.
Sophie: Here is your receipt and your change.
James: Thank you! Where can I get a trolley?
Sophie: There are trolleys next to the door.
James [happy]: Great, thank you very much!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,490,'a1-s3','72fd7560716c421db78fcf4a7a685656',NULL,NULL,'2026-07-25T12:45:24.335Z',NULL);
