INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('46552dca-b858-463e-8ea3-d0551a291587','0ef6bf05-2651-4647-a8e7-1027d292cc8e',14,'categorize','Sort each sentence: would like (now) or like (general).',NULL,NULL,NULL,NULL,NULL,'''would like'' diễn tả mong muốn ngay lúc nói; ''like'' diễn tả sở thích chung.',NULL,NULL,NULL,'["would like (want now)", "like (general preference)"]','[{"text": "I ___ a burger.", "category": "would like (want now)"}, {"text": "She ___ chocolate.", "category": "like (general preference)"}, {"text": "We ___ a table for two.", "category": "would like (want now)"}, {"text": "They ___ pizza.", "category": "like (general preference)"}, {"text": "He ___ dessert now.", "category": "would like (want now)"}, {"text": "I ___ spicy food.", "category": "like (general preference)"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('af09b423-250e-4d3e-ae15-f77e78317c5c','a1-s3-13-read-aloud-restaurant-visit','A Family Dinner Out',1,'reading','A1 Movers',NULL,'Last night, my family went to a restaurant for dinner. We booked a table for four people. The waiter asked, ''Would you like a starter?'' My dad said, ''Yes, please. I''d like some soup.'' For the main course, I had chicken and rice, and my sister had spicy noodles. My mom asked, ''Is there anything else on the menu?'' The waiter showed us the dessert menu. I would like chocolate cake, please! At the end, my dad asked for the bill. He paid by card and left a small tip. ''That''s all, thank you!'' he said. It was a wonderful dinner!','[{"text":"Last night, my family went to a restaurant for dinner.","ipa":"/læst naɪt, maɪ ˈfæməli wɛnt tu ə ˈrɛstərənt fɔr ˈdɪnər./","vi":"Tối qua, gia đình tôi đã đi ăn tối tại một nhà hàng."},{"text":"We booked a table for four people.","ipa":"/wi bʊkt ə ˈteɪbəl fɔr fɔr ˈpipəl./","vi":"Chúng tôi đã đặt một bàn cho bốn người."},{"text":"The waiter asked, ''Would you like a starter?''","ipa":"/ðə ˈweɪtər æskt, ''wʊd ju laɪk ə ˈstɑrtər?''/","vi":"Người phục vụ hỏi: ''Quý khách có muốn dùng món khai vị không?''"},{"text":"My dad said, ''Yes, please. I''d like some soup.''","ipa":"/maɪ dæd sɛd, ''jɛs, pliz. aɪd laɪk sʌm sup.''/","vi":"Bố tôi nói: ''Vâng, làm ơn. Cho tôi một ít súp.''"},{"text":"For the main course, I had chicken and rice, and my sister had spicy noodles.","ipa":"/fɔr ðə meɪn kɔrs, aɪ hæd ˈtʃɪkən ænd raɪs, ænd maɪ ˈsɪstər hæd ˈspaɪsi ˈnudəlz./","vi":"Đối với món chính, tôi ăn cơm gà, còn em gái tôi ăn mì cay."},{"text":"My mom asked, ''Is there anything else on the menu?''","ipa":"/maɪ mɑm æskt, ''ɪz ðɛr ˈɛniθɪŋ ɛls ɑn ðə ˈmɛnju?''/","vi":"Mẹ tôi hỏi: ''Thực đơn còn món nào khác không?''"},{"text":"The waiter showed us the dessert menu.","ipa":"/ðə ˈweɪtər ʃoʊd ʌs ðə dɪˈzɜrt ˈmɛnju./","vi":"Người phục vụ đưa cho chúng tôi xem thực đơn tráng miệng."},{"text":"I would like chocolate cake, please!","ipa":"/aɪ wʊd laɪk ˈtʃɑklət keɪk, pliz!/","vi":"Cho tôi một phần bánh sô-cô-la nhé!"},{"text":"At the end, my dad asked for the bill.","ipa":"/æt ði ɛnd, maɪ dæd æskt fɔr ðə bɪl./","vi":"Cuối bữa, bố tôi yêu cầu thanh toán hóa đơn."},{"text":"He paid by card and left a small tip.","ipa":"/hi peɪd baɪ kɑrd ænd lɛft ə smɔl tɪp./","vi":"Bố trả tiền bằng thẻ và để lại một khoản tiền boa nhỏ."},{"text":"''That''s all, thank you!'' he said.","ipa":"/''ðæts ɔl, θæŋk ju!'' hi sɛd./","vi":"''Chỉ vậy thôi, cảm ơn!'' bố nói."},{"text":"It was a wonderful dinner!","ipa":"/ɪt wʌz ə ˈwʌndərfəl ˈdɪnər!/","vi":"Đó là một bữa tối tuyệt vời!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,530,'a1-s3','670323ca7fdb44148fd0a3afbf22b437',NULL,NULL,'2026-07-25T12:45:24.335Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('ea846963-00ff-448a-9c52-e53e33667c2b','a1-s3-14-listen-ordering-food','Ordering Food at a Restaurant',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Grace: Good evening! Would you like to book a table?
Daniel: Yes, please. A table for two.
Grace: Here is the menu. Would you like a starter?
Daniel: Yes, I''d like some soup, please.
Grace: And for the main course?
Daniel: I''ll have the chicken with rice.
Grace: Would you like anything else?
Daniel: Yes, a bottle of water, please.
Grace: Would you like dessert?
Daniel [happy]: Yes, I''d like some ice cream.
Grace: Is that all?
Daniel: Yes, that''s all, thank you.
Grace: Here is your bill. Don''t forget to leave a tip!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,540,'a1-s3','670323ca7fdb44148fd0a3afbf22b437',NULL,NULL,'2026-07-25T12:45:24.335Z',NULL);
