INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('66d1cdee-c064-42b3-88d1-71ca0e1d5a05','ea846963-00ff-448a-9c52-e53e33667c2b',7,'multiple_choice','Does Daniel want anything else after ordering water?','["Yes", "No"]','No',NULL,NULL,NULL,'Hội thoại: ''Daniel: Yes, that''s all, thank you.''','Daniel: Yes, that''s all, thank you.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('961005b8-4f5c-4645-9527-63852b0c55e5','ea846963-00ff-448a-9c52-e53e33667c2b',8,'fill_blank','Daniel wants a table for ___.',NULL,NULL,'["two"]','["two", "three", "four"]',NULL,'Hội thoại: ''Daniel: A table for two.''','Daniel: A table for two.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('24af638d-758a-4153-aeef-8349f02dc8bd','ea846963-00ff-448a-9c52-e53e33667c2b',9,'fill_blank','For the main course, Daniel ___ the chicken with rice.',NULL,NULL,'["will have"]','["will have", "would like", "likes"]',NULL,'Hội thoại: ''Daniel: I''ll have the chicken with rice.''','Daniel: I''ll have the chicken with rice.',NULL,NULL,NULL,NULL,NULL,NULL);
