INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('514b379a-227b-43f0-b814-ea6037c221a2','ea846963-00ff-448a-9c52-e53e33667c2b',11,'fill_blank','Daniel says, ''Yes, ___ all, thank you.''',NULL,NULL,'["that''s"]','["that''s", "this", "it''s"]',NULL,'Hội thoại: ''Daniel: Yes, that''s all, thank you.''','Daniel: Yes, that''s all, thank you.',NULL,NULL,NULL,NULL,NULL,NULL);
