INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('047c1cd7-47a8-4164-9b50-50751066615b','ea846963-00ff-448a-9c52-e53e33667c2b',13,'matching','Match each course to what Daniel orders.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng món ăn với từng phần thực đơn.','Daniel orders soup as a starter and chicken with rice as the main course.','[{"left": "starter", "right": "soup"}, {"left": "main course", "right": "chicken with rice"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('5cea0b47-71de-497a-9de9-7ad1f34601d3','ea846963-00ff-448a-9c52-e53e33667c2b',14,'matching','Match each item to what Daniel orders.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng đồ uống và món tráng miệng.','Daniel orders a bottle of water and ice cream for dessert.','[{"left": "drink", "right": "bottle of water"}, {"left": "dessert", "right": "ice cream"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('c884ef82-6e81-4d47-84d6-76b87f14676a','a1-s3-15-reading-favorite-snack','Lily''s Favorite Snack',1,'reading','A1 Movers',NULL,'Lily loves snacks after school. Every afternoon, she eats a little fruit and a few crackers. Sometimes she has some cheese too. Her favorite snack is fresh strawberries with a little sugar. She doesn''t like salty chips very much, but she loves sweet things. On weekends, Lily and her mom make popcorn together. They don''t put much salt on it, just a little butter. Lily usually drinks a glass of milk with her snack. She thinks healthy snacks taste the best. Would you like to try Lily''s favorite snack?','[{"text":"Lily loves snacks after school.","ipa":"/ˈlɪli lʌvz snæks ˈæftər skul./","vi":"Lily thích ăn vặt sau giờ học."},{"text":"Every afternoon, she eats a little fruit and a few crackers.","ipa":"/ˈɛvri ˌæftərˈnun, ʃi its ə ˈlɪtəl frut ænd ə fju ˈkrækərz./","vi":"Mỗi buổi chiều, cô bé ăn một chút trái cây và vài chiếc bánh quy."},{"text":"Sometimes she has some cheese too.","ipa":"/ˈsʌmˌtaɪmz ʃi hæz sʌm tʃiz tu./","vi":"Đôi khi cô bé cũng ăn thêm một ít phô mai."},{"text":"Her favorite snack is fresh strawberries with a little sugar.","ipa":"/hər ˈfeɪvərɪt snæk ɪz frɛʃ ˈstrɔˌbɛriz wɪð ə ˈlɪtəl ˈʃʊgər./","vi":"Món ăn vặt yêu thích của cô bé là dâu tây tươi với một chút đường."},{"text":"She doesn''t like salty chips very much, but she loves sweet things.","ipa":"/ʃi ˈdʌzənt laɪk ˈsɔlti tʃɪps ˈvɛri mʌtʃ, bʌt ʃi lʌvz swit θɪŋz./","vi":"Cô bé không thích khoai tây chiên mặn lắm, nhưng lại rất thích đồ ngọt."},{"text":"On weekends, Lily and her mom make popcorn together.","ipa":"/ɑn ˈwikˌɛndz, ˈlɪli ænd hər mɑm meɪk ˈpɑpˌkɔrn təˈgɛðər./","vi":"Vào cuối tuần, Lily và mẹ cùng nhau làm bỏng ngô."},{"text":"They don''t put much salt on it, just a little butter.","ipa":"/ðeɪ doʊnt pʊt mʌtʃ sɔlt ɑn ɪt, dʒʌst ə ˈlɪtəl ˈbʌtər./","vi":"Họ không cho nhiều muối vào, chỉ một chút bơ thôi."},{"text":"Lily usually drinks a glass of milk with her snack.","ipa":"/ˈlɪli ˈjuʒəwəli drɪŋks ə glæs ʌv mɪlk wɪð hər snæk./","vi":"Lily thường uống một ly sữa cùng với món ăn vặt của mình."},{"text":"She thinks healthy snacks taste the best.","ipa":"/ʃi θɪŋks ˈhɛlθi snæks teɪst ðə bɛst./","vi":"Cô bé nghĩ rằng những món ăn vặt lành mạnh là ngon nhất."},{"text":"Would you like to try Lily''s favorite snack?","ipa":"/wʊd ju laɪk tu traɪ ˈlɪliz ˈfeɪvərɪt snæk?/","vi":"Bạn có muốn thử món ăn vặt yêu thích của Lily không?"}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,550,'a1-s3','22943413d6f34b88b0b92888d79df2b1',NULL,NULL,'2026-07-25T12:45:24.335Z',NULL);
