INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('2eed9ce2-650c-4993-8c26-51666259fe0d','c884ef82-6e81-4d47-84d6-76b87f14676a',9,'ordering','Put the words in the correct order.',NULL,'Lily loves snacks after school',NULL,NULL,NULL,'Trật tự: chủ ngữ + động từ + tân ngữ + trạng ngữ.',NULL,NULL,'["school", "after", "snacks", "loves", "Lily"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('cf19ccdf-6a8c-4ce9-b3f5-86487be01130','c884ef82-6e81-4d47-84d6-76b87f14676a',10,'categorize','Sort each snack as healthy or less healthy.',NULL,NULL,NULL,NULL,NULL,'Phân loại theo mức độ lành mạnh của món ăn trong bài.',NULL,NULL,NULL,'["Healthy", "Less healthy"]','[{"text": "fresh strawberries", "category": "Healthy"}, {"text": "salty chips", "category": "Less healthy"}, {"text": "milk", "category": "Healthy"}, {"text": "popcorn with butter", "category": "Less healthy"}]',NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('98adf6a6-3e93-432a-a9a2-7b16eda32b0c','c884ef82-6e81-4d47-84d6-76b87f14676a',11,'categorize','Sort each quantifier by countable or uncountable.',NULL,NULL,NULL,NULL,NULL,'''a few'' đi với danh từ đếm được; ''a little'' đi với danh từ không đếm được.',NULL,NULL,NULL,'["Quantifier for countable", "Quantifier for uncountable"]','[{"text": "a few crackers", "category": "Quantifier for countable"}, {"text": "a little sugar", "category": "Quantifier for uncountable"}, {"text": "a little butter", "category": "Quantifier for uncountable"}, {"text": "a few snacks", "category": "Quantifier for countable"}]',NULL,'some-any');
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('408bcafa-50a2-4df7-a5a8-6c87474592ff','a1-s3-16-mixed-checkpoint','Shopping, Cooking and Dinner',1,'mixed','A1 Movers',NULL,'On Saturday, Ben and his mom go shopping for dinner. They push a trolley around the supermarket. ''How many tomatoes do we need?'' Ben asks. His mom says, ''We need a few tomatoes and a kilo of potatoes.'' They also buy a bottle of oil and a packet of pasta. At the checkout, Ben''s mom pays with her card and gets a receipt. At home, they cook together. Ben''s mom cuts some fresh vegetables. Ben stirs the pasta in a big pot. ''Would you like to taste the sauce?'' his mom asks. ''Yes, please! It''s a little spicy, but I like it,'' Ben says. For dinner, they have pasta with vegetables and a fresh salad. ''This is delicious! Can I have some more, please?'' Ben asks. His mom smiles and says, ''Of course! There''s a lot of pasta left.'' After dinner, Ben says, ''That''s all for me, thank you!'' It was a great family dinner.','[{"text":"On Saturday, Ben and his mom go shopping for dinner.","ipa":"/ɑn ˈsætərdeɪ, bɛn ænd hɪz mɑm goʊ ˈʃɑpɪŋ fɔr ˈdɪnər./","vi":"Vào thứ Bảy, Ben và mẹ đi mua sắm cho bữa tối."},{"text":"They push a trolley around the supermarket.","ipa":"/ðeɪ pʊʃ ə ˈtrɑli əˈraʊnd ðə ˈsupərmɑrkɪt./","vi":"Họ đẩy xe hàng đi quanh siêu thị."},{"text":"''How many tomatoes do we need?'' Ben asks.","ipa":"/haʊ ˈmɛni təˈmeɪtoʊz du wi nid? bɛn æsks./","vi":"\"Chúng ta cần bao nhiêu quả cà chua ạ?\" Ben hỏi."},{"text":"His mom says, ''We need a few tomatoes and a kilo of potatoes.''","ipa":"/hɪz mɑm sɛz, wi nid ə fju təˈmeɪtoʊz ænd ə ˈkiloʊ əv pəˈteɪtoʊz./","vi":"Mẹ cậu nói: \"Chúng ta cần vài quả cà chua và một cân khoai tây.\""},{"text":"They also buy a bottle of oil and a packet of pasta.","ipa":"/ðeɪ ˈɔlsoʊ baɪ ə ˈbɑtəl əv ɔɪl ænd ə ˈpækɪt əv ˈpɑstə./","vi":"Họ cũng mua một chai dầu ăn và một gói mì ống."},{"text":"At the checkout, Ben''s mom pays with her card and gets a receipt.","ipa":"/æt ðə ˈtʃɛkaʊt, bɛnz mɑm peɪz wɪð hər kɑrd ænd gɛts ə rɪˈsit./","vi":"Tại quầy thanh toán, mẹ của Ben trả tiền bằng thẻ và nhận hóa đơn."},{"text":"At home, they cook together.","ipa":"/æt hoʊm, ðeɪ kʊk təˈɡɛðər./","vi":"Về đến nhà, họ cùng nhau nấu ăn."},{"text":"Ben''s mom cuts some fresh vegetables.","ipa":"/bɛnz mɑm kʌts sʌm frɛʃ ˈvɛdʒtəbəlz./","vi":"Mẹ của Ben thái vài loại rau tươi."},{"text":"Ben stirs the pasta in a big pot.","ipa":"/bɛn stɜrz ðə ˈpɑstə ɪn ə bɪɡ pɑt./","vi":"Ben khuấy mì ống trong một cái nồi lớn."},{"text":"''Would you like to taste the sauce?'' his mom asks.","ipa":"/wʊd ju laɪk tu teɪst ðə sɔs? hɪz mɑm æsks./","vi":"\"Con có muốn nếm thử nước sốt không?\" mẹ cậu hỏi."},{"text":"''Yes, please! It''s a little spicy, but I like it,'' Ben says.","ipa":"/jɛs, pliz! ɪts ə ˈlɪtəl ˈspaɪsi, bʌt aɪ laɪk ɪt, bɛn sɛz./","vi":"\"Dạ có ạ! Nó hơi cay một chút, nhưng con thích nó,\" Ben nói."},{"text":"For dinner, they have pasta with vegetables and a fresh salad.","ipa":"/fɔr ˈdɪnər, ðeɪ hæv ˈpɑstə wɪð ˈvɛdʒtəbəlz ænd ə frɛʃ ˈsæləd./","vi":"Cho bữa tối, họ ăn mì ống với rau củ và salad tươi."},{"text":"''This is delicious! Can I have some more, please?'' Ben asks.","ipa":"/ðɪs ɪz dɪˈlɪʃəs! kæn aɪ hæv sʌm mɔr, pliz? bɛn æsks./","vi":"\"Món này ngon quá! Con có thể ăn thêm một chút nữa được không ạ?\" Ben hỏi."},{"text":"His mom smiles and says, ''Of course! There''s a lot of pasta left.''","ipa":"/hɪz mɑm smaɪlz ænd sɛz, əv kɔrs! ðɛrz ə lɑt əv ˈpɑstə lɛft./","vi":"Mẹ cậu mỉm cười và nói: \"Tất nhiên rồi! Vẫn còn nhiều mì lắm.\""},{"text":"After dinner, Ben says, ''That''s all for me, thank you!''","ipa":"/ˈæftər ˈdɪnər, bɛn sɛz, ðæts ɔl fɔr mi, θæŋk ju!/","vi":"Sau bữa tối, Ben nói: \"Con ăn thế là đủ rồi, con cảm ơn mẹ!\""},{"text":"It was a great family dinner.","ipa":"/ɪt wʌz ə ɡreɪt ˈfæməli ˈdɪnər./","vi":"Đó là một bữa tối gia đình tuyệt vời."}]',NULL,'On Saturday, Ben and his mom go shopping for dinner. They push a trolley around the supermarket. ''How many tomatoes do we need?'' Ben asks. His mom says, ''We need a few tomatoes and a kilo of potatoes.'' They also buy a bottle of oil and a packet of pasta. At the checkout, Ben''s mom pays with her card and gets a receipt. At home, they cook together. Ben''s mom cuts some fresh vegetables. Ben stirs the pasta in a big pot. ''Would you like to taste the sauce?'' his mom asks. ''Yes, please! It''s a little spicy, but I like it,'' Ben says. For dinner, they have pasta with vegetables and a fresh salad. ''This is delicious! Can I have some more, please?'' Ben asks. His mom smiles and says, ''Of course! There''s a lot of pasta left.'' After dinner, Ben says, ''That''s all for me, thank you!'' It was a great family dinner.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mixed_all',NULL,560,'a1-s3','15af2e72a8984e9182b2b6d6fc468863',NULL,NULL,'2026-07-25T12:45:24.335Z',NULL);
