INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('ba5a7b56-1673-46a6-ac35-10bce1fabc6f','a1-s4-03-read-aloud-my-neighbourhood','My Neighbourhood',1,'reading','A1 Movers',NULL,'Welcome to my neighbourhood! There is a small park near my house. There are a lot of trees around the park. My neighbourhood is quiet in the morning, but it gets a little noisy in the afternoon. There is a bakery around the corner from my house. It is very convenient for buying fresh bread. There are a few shops on my street, but the market is crowded on Saturdays. There is a bus stop opposite my building. My best friend, Sam, lives near me too. We like to play football in the park after school. I really enjoy living in my neighbourhood!','[{"text":"Welcome to my neighbourhood!","ipa":"/ˈwɛlkəm tu maɪ ˈneɪbərˌhʊd/","vi":"Chào mừng bạn đến với khu phố của mình!"},{"text":"There is a small park near my house.","ipa":"/ðɛr ɪz ə smɔl pɑrk nɪr maɪ haʊs/","vi":"Có một công viên nhỏ gần nhà mình."},{"text":"There are a lot of trees around the park.","ipa":"/ðɛr ɑr ə lɑt əv triz əˈraʊnd ðə pɑrk/","vi":"Có rất nhiều cây cối xung quanh công viên."},{"text":"My neighbourhood is quiet in the morning, but it gets a little noisy in the afternoon.","ipa":"/maɪ ˈneɪbərˌhʊd ɪz ˈkwaɪət ɪn ðə ˈmɔrnɪŋ, bʌt ɪt gɛts ə ˈlɪtəl ˈnɔɪzi ɪn ði ˌæftərˈnun/","vi":"Khu phố của mình yên tĩnh vào buổi sáng, nhưng lại hơi ồn ào vào buổi chiều."},{"text":"There is a bakery around the corner from my house.","ipa":"/ðɛr ɪz ə ˈbeɪkəri əˈraʊnd ðə ˈkɔrnər frʌm maɪ haʊs/","vi":"Có một tiệm bánh ở ngay góc đường gần nhà mình."},{"text":"It is very convenient for buying fresh bread.","ipa":"/ɪt ɪz ˈvɛri kənˈvinjənt fɔr ˈbaɪɪŋ frɛʃ brɛd/","vi":"Nó rất tiện lợi để mua bánh mì tươi."},{"text":"There are a few shops on my street, but the market is crowded on Saturdays.","ipa":"/ðɛr ɑr ə fju ʃɑps ɑn maɪ strit, bʌt ðə ˈmɑrkət ɪz ˈkraʊdəd ɑn ˈsætərˌdeɪz/","vi":"Có vài cửa hàng trên phố mình, nhưng chợ lại rất đông đúc vào các ngày thứ Bảy."},{"text":"There is a bus stop opposite my building.","ipa":"/ðɛr ɪz ə bʌs stɑp ˈɑpəzɪt maɪ ˈbɪldɪŋ/","vi":"Có một trạm xe buýt đối diện tòa nhà của mình."},{"text":"My best friend, Sam, lives near me too.","ipa":"/maɪ bɛst frɛnd, sæm, lɪvz nɪr mi tu/","vi":"Bạn thân của mình, Sam, cũng sống gần đây."},{"text":"We like to play football in the park after school.","ipa":"/wi laɪk tu pleɪ ˈfʊtˌbɔl ɪn ðə pɑrk ˈæftər skul/","vi":"Chúng mình thích chơi bóng đá ở công viên sau giờ học."},{"text":"I really enjoy living in my neighbourhood!","ipa":"/aɪ ˈrɪli ɛnˈdʒɔɪ ˈlɪvɪŋ ɪn maɪ ˈneɪbərˌhʊd/","vi":"Mình thực sự rất thích sống ở khu phố này!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,630,'a1-s4','69bb054753494e63a89b1d4dcd2e5922',NULL,NULL,'2026-07-25T12:48:00.708Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('7a7c5e36-25cf-4d52-8bce-9244310d1b75','a1-s4-04-listen-my-street','What Is Your Neighbourhood Like?',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Jack: Hi Emma! What''s your neighbourhood like?
Emma: Hi Jack! It''s really nice. There is a park near my house.
Jack: Is it quiet or noisy?
Emma: It''s quiet in the morning, but noisy in the afternoon. Lots of kids play outside.
Jack: I see. Is there a shop near you?
Emma: Yes, there is a small shop around the corner. It''s very convenient.
Jack: Is your street crowded?
Emma: A little. There are a few cafes, so it gets busy on weekends.
Jack: What about a bus stop?
Emma: There is a bus stop opposite my house.
Jack: That''s convenient! Is there a park with a lot of trees?
Emma: Yes! There are a lot of trees in the park near my house.
Jack [happy]: Sounds like a great neighbourhood!
Emma [happy]: It is! I really like living here.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,640,'a1-s4','69bb054753494e63a89b1d4dcd2e5922',NULL,NULL,'2026-07-25T12:48:00.708Z',NULL);
