INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('3fa0a3cb-f07b-42af-a748-0e86bc73dd86','a1-s4-08-read-aloud-in-town','A Trip Around Town',1,'reading','A1 Movers',NULL,'This morning, I go into town to do some jobs. First, I go to the post office. It is open from nine o''clock. I post a letter to my grandmother. Next, I walk to the pharmacy. It is close to the post office. I buy some medicine for my little brother. After that, I visit the library. I borrow two books about animals. The library is closed on Sundays, so I always visit it during the week. Then I go to the bank. I have an appointment with the bank clerk at eleven o''clock. The bank stays open till one o''clock. I am happy because I finish all my jobs before lunch!','[{"text":"This morning, I go into town to do some jobs.","ipa":"/ðɪs ˈmɔrnɪŋ, aɪ ɡoʊ ˈɪntu taʊn tu du sʌm dʒɑbz./","vi":"Sáng nay, tôi vào thị trấn để làm một vài việc."},{"text":"First, I go to the post office.","ipa":"/fɜrst, aɪ ɡoʊ tu ðə poʊst ˈɔfɪs./","vi":"Đầu tiên, tôi đến bưu điện."},{"text":"It is open from nine o''clock.","ipa":"/ɪt ɪz ˈoʊpən frʌm naɪn əˈklɑk./","vi":"Nơi đó mở cửa từ lúc chín giờ."},{"text":"I post a letter to my grandmother.","ipa":"/aɪ poʊst ə ˈlɛtər tu maɪ ˈɡrændˌmʌðər./","vi":"Tôi gửi một lá thư cho bà của mình."},{"text":"Next, I walk to the pharmacy.","ipa":"/nɛkst, aɪ wɔk tu ðə ˈfɑrməsi./","vi":"Tiếp theo, tôi đi bộ đến hiệu thuốc."},{"text":"It is close to the post office.","ipa":"/ɪt ɪz kloʊs tu ðə poʊst ˈɔfɪs./","vi":"Nó nằm gần bưu điện."},{"text":"I buy some medicine for my little brother.","ipa":"/aɪ baɪ sʌm ˈmɛdəsən fɔr maɪ ˈlɪtəl ˈbrʌðər./","vi":"Tôi mua một ít thuốc cho em trai của mình."},{"text":"After that, I visit the library.","ipa":"/ˈæftər ðæt, aɪ ˈvɪzɪt ðə ˈlaɪˌbrɛri./","vi":"Sau đó, tôi ghé thăm thư viện."},{"text":"I borrow two books about animals.","ipa":"/aɪ ˈbɑroʊ tu bʊks əˈbaʊt ˈænəməlz./","vi":"Tôi mượn hai cuốn sách về động vật."},{"text":"The library is closed on Sundays, so I always visit it during the week.","ipa":"/ðə ˈlaɪˌbrɛri ɪz kloʊzd ɑn ˈsʌndeɪz, soʊ aɪ ˈɔlˌweɪz ˈvɪzɪt ɪt ˈdʊrɪŋ ðə wik./","vi":"Thư viện đóng cửa vào Chủ nhật, nên tôi luôn đến đó vào các ngày trong tuần."},{"text":"Then I go to the bank.","ipa":"/ðɛn aɪ ɡoʊ tu ðə bæŋk./","vi":"Sau đó tôi đến ngân hàng."},{"text":"I have an appointment with the bank clerk at eleven o''clock.","ipa":"/aɪ hæv ən əˈpɔɪntmənt wɪð ðə bæŋk klɜrk æt ɪˈlɛvən əˈklɑk./","vi":"Tôi có một cuộc hẹn với nhân viên ngân hàng lúc mười một giờ."},{"text":"The bank stays open till one o''clock.","ipa":"/ðə bæŋk steɪz ˈoʊpən tɪl wʌn əˈklɑk./","vi":"Ngân hàng mở cửa đến tận một giờ."},{"text":"I am happy because I finish all my jobs before lunch!","ipa":"/aɪ æm ˈhæpi bɪˈkəz aɪ ˈfɪnɪʃ ɔl maɪ dʒɑbz bɪˈfɔr lʌntʃ!/","vi":"Tôi rất vui vì đã hoàn thành hết mọi việc trước giờ ăn trưa!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,680,'a1-s4','5c2965f8054d436d9fc84f53172b8ded',NULL,NULL,'2026-07-25T12:48:00.708Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('035a2bc8-aa5b-472b-b696-e5415d21bbfd','a1-s4-09-listen-in-town','Jobs in Town',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Noah: Hi Olivia! Are you free this afternoon?
Olivia: Hi Noah! Yes, I need to go to the post office. It''s open until five.
Noah: Great! Can we go to the library too?
Olivia [worried]: Sure, but the library is closed on Mondays. Is today Monday?
Noah [relieved]: No, it''s Tuesday. We''re fine!
Olivia: Perfect. I also need to visit the pharmacy for some medicine.
Noah: Is the pharmacy near the post office?
Olivia: Yes, it''s very close. Just around the corner.
Noah: What about the bank? I have an appointment at three o''clock.
Olivia: The bank stays open till four, so we have time.
Noah: Good. Let''s go to the post office first, then the pharmacy, then the bank.
Olivia: And after that, we can borrow some books from the library!
Noah [happy]: Sounds like a good plan!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,690,'a1-s4','5c2965f8054d436d9fc84f53172b8ded',NULL,NULL,'2026-07-25T12:48:00.708Z',NULL);
