INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('22e95cff-6007-48f2-98b2-4def5440d702','a1-s4-13-read-aloud-getting-there','How I Get to School',1,'reading','A1 Movers',NULL,'Every morning, I take the bus to school. First, I get on the bus near my house. I buy a ticket from the driver. The bus stop is on platform two. After ten minutes, I get off the bus in the town centre. Then I change to another bus. I get on the second bus and go straight on for about ten more minutes. Finally, I get off near my school. The whole trip takes about twenty minutes. Sometimes, my mum picks me up by car, but I like taking the bus with my friends!','[{"text":"Every morning, I take the bus to school.","ipa":"/ˈɛvri ˈmɔrnɪŋ, aɪ teɪk ðə bʌs tu skul./","vi":"Mỗi buổi sáng, tôi đi xe buýt đến trường."},{"text":"First, I get on the bus near my house.","ipa":"/fɜrst, aɪ ɡɛt ɑn ðə bʌs nɪr maɪ haʊs./","vi":"Đầu tiên, tôi lên xe buýt gần nhà."},{"text":"I buy a ticket from the driver.","ipa":"/aɪ baɪ ə ˈtɪkɪt frʌm ðə ˈdraɪvər./","vi":"Tôi mua vé từ bác tài xế."},{"text":"The bus stop is on platform two.","ipa":"/ðə bʌs stɑp ɪz ɑn ˈplætfɔrm tu./","vi":"Trạm xe buýt nằm ở bến số hai."},{"text":"After ten minutes, I get off the bus in the town centre.","ipa":"/ˈæftər tɛn ˈmɪnɪts, aɪ ɡɛt ɔf ðə bʌs ɪn ðə taʊn ˈsɛntər./","vi":"Sau mười phút, tôi xuống xe ở trung tâm thị trấn."},{"text":"Then I change to another bus.","ipa":"/ðɛn aɪ tʃeɪndʒ tu əˈnʌðər bʌs./","vi":"Sau đó tôi đổi sang một chuyến xe buýt khác."},{"text":"I get on the second bus and go straight on for about ten more minutes.","ipa":"/aɪ ɡɛt ɑn ðə ˈsɛkənd bʌs ænd ɡoʊ streɪt ɑn fɔr əˈbaʊt tɛn mɔr ˈmɪnɪts./","vi":"Tôi lên chuyến xe thứ hai và đi thẳng thêm khoảng mười phút nữa."},{"text":"Finally, I get off near my school.","ipa":"/ˈfaɪnəli, aɪ ɡɛt ɔf nɪr maɪ skul./","vi":"Cuối cùng, tôi xuống xe gần trường học của mình."},{"text":"The whole trip takes about twenty minutes.","ipa":"/ðə hoʊl trɪp teɪks əˈbaʊt ˈtwɛnti ˈmɪnɪts./","vi":"Toàn bộ chuyến đi mất khoảng hai mươi phút."},{"text":"Sometimes, my mum picks me up by car, but I like taking the bus with my friends!","ipa":"/ˈsʌmˌtaɪmz, maɪ mʌm pɪks mi ʌp baɪ kɑr, bʌt aɪ laɪk ˈteɪkɪŋ ðə bʌs wɪð maɪ frɛndz!/","vi":"Thỉnh thoảng, mẹ đón tôi bằng ô tô, nhưng tôi thích đi xe buýt cùng bạn bè hơn!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,730,'a1-s4','9cf2d02066734c1c8083ee7cd43e1fb2',NULL,NULL,'2026-07-25T12:48:00.708Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('53a9ec75-c12f-4b44-b4ea-0c3cab185a00','a1-s4-14-listen-getting-there','How Does Ethan Get to School?',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Sophie: Hi Ethan! How do you get to school?
Ethan: Hi Sophie! I take the bus every morning.
Sophie: Really? Where do you get on?
Ethan: I get on near my house, at the bus stop on Green Street.
Sophie: Do you need a ticket?
Ethan: Yes, I buy a ticket from the driver. It''s on platform two.
Sophie: How long does it take?
Ethan: About twenty minutes. But I change buses in the town centre.
Sophie [confused]: Oh, so you get off and get on a different bus?
Ethan: Exactly. I get off the first bus, then get on the second one.
Sophie: What do you do after that?
Ethan: I go straight on for about ten minutes, then I get off near school.
Sophie [happy]: That sounds easy! I usually walk to school.
Ethan [happy]: That''s nice too! Maybe I''ll walk with you sometimes.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,740,'a1-s4','9cf2d02066734c1c8083ee7cd43e1fb2',NULL,NULL,'2026-07-25T12:48:00.708Z',NULL);
