INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('fe8f18a13469b9c58dd25cafb7e91c80','53a9ec75-c12f-4b44-b4ea-0c3cab185a00',10,'matching','Match each bus to its route.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng chuyến xe với hành trình.','Ethan: get on near my house...change buses in the town centre...get off near school.','[{"left":"First bus","right":"Green Street to town centre"},{"left":"Second bus","right":"Town centre to school"}]',NULL,NULL,NULL,NULL,NULL);
