INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('262e9dd0-7245-44a1-b0e3-82a8e3572efb','a1-s4-15-reading-home-in-the-city','A Home in the City',1,'reading','A1 Movers',NULL,'My family lives in a small flat in the city. There are three rooms: a bedroom, a kitchen, and a living room. Our flat is on the second floor of a tall building. There is a park near our building, and there are a lot of shops around the corner. It is very convenient because the supermarket, the pharmacy, and the library are all close by. Our street is quiet at night but a little noisy in the morning when people go to work. My favourite place is the balcony because I can see the whole street from there. We live opposite a small school. I like living in the city because everything I need is near my home.','[{"text":"My family lives in a small flat in the city.","ipa":"/maɪ ˈfæməli lɪvz ɪn ə smɔl flæt ɪn ðə ˈsɪti./","vi":"Gia đình tôi sống trong một căn hộ nhỏ ở thành phố."},{"text":"There are three rooms: a bedroom, a kitchen, and a living room.","ipa":"/ðɛr ɑr θri rumz: ə ˈbɛdrum, ə ˈkɪtʃən, ænd ə ˈlɪvɪŋ rum./","vi":"Có ba phòng: một phòng ngủ, một nhà bếp và một phòng khách."},{"text":"Our flat is on the second floor of a tall building.","ipa":"/ˈaʊər flæt ɪz ɑn ðə ˈsɛkənd flɔr ʌv ə tɔl ˈbɪldɪŋ./","vi":"Căn hộ của chúng tôi nằm ở tầng hai của một tòa nhà cao tầng."},{"text":"There is a park near our building, and there are a lot of shops around the corner.","ipa":"/ðɛr ɪz ə pɑrk nɪr ˈaʊər ˈbɪldɪŋ, ænd ðɛr ɑr ə lɑt ʌv ʃɑps əˈraʊnd ðə ˈkɔrnər./","vi":"Có một công viên gần tòa nhà của chúng tôi, và có rất nhiều cửa hàng ở ngay góc phố."},{"text":"It is very convenient because the supermarket, the pharmacy, and the library are all close by.","ipa":"/ɪt ɪz ˈvɛri kənˈvinjənt bɪˈkəz ðə ˈsupərmɑrkət, ðə ˈfɑrməsi, ænd ðə ˈlaɪˌbrɛri ɑr ɔl kloʊs baɪ./","vi":"Nơi này rất tiện lợi vì siêu thị, hiệu thuốc và thư viện đều ở gần đây."},{"text":"Our street is quiet at night but a little noisy in the morning when people go to work.","ipa":"/ˈaʊər strit ɪz ˈkwaɪət æt naɪt bʌt ə ˈlɪtəl ˈnɔɪzi ɪn ðə ˈmɔrnɪŋ wɛn ˈpipəl goʊ tu wɜrk./","vi":"Phố của chúng tôi yên tĩnh vào ban đêm nhưng hơi ồn ào vào buổi sáng khi mọi người đi làm."},{"text":"My favourite place is the balcony because I can see the whole street from there.","ipa":"/maɪ ˈfeɪvərɪt pleɪs ɪz ðə ˈbælkəni bɪˈkəz aɪ kæn si ðə hoʊl strit frʌm ðɛr./","vi":"Nơi yêu thích của tôi là ban công vì tôi có thể nhìn thấy cả con phố từ đó."},{"text":"We live opposite a small school.","ipa":"/wi lɪv ˈɑpəzɪt ə smɔl skul./","vi":"Chúng tôi sống đối diện một ngôi trường nhỏ."},{"text":"I like living in the city because everything I need is near my home.","ipa":"/aɪ laɪk ˈlɪvɪŋ ɪn ðə ˈsɪti bɪˈkəz ˈɛvriˌθɪŋ aɪ nid ɪz nɪr maɪ hoʊm./","vi":"Tôi thích sống ở thành phố vì mọi thứ tôi cần đều ở gần nhà."}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'reading_comprehension',NULL,750,'a1-s4','d4cadd38a47d470f8078fa093542e5bf',NULL,NULL,'2026-07-25T12:48:00.708Z',NULL);
