INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('f4385a60-4ecb-4dc3-81ae-fa2f2b21c6b4','a1-s4-16-mixed-checkpoint','A Busy Day in Town',1,'mixed','A1 Movers',NULL,'Good morning! Today I have a busy day in town. I live in a small house near the park. There is a garden with a few flowers in front of my house. First, I go to the post office to send a parcel. ''How much is this parcel?'' I ask. ''It''s two dollars,'' says the clerk. I pay and say thank you. Next, I need to find the library. I ask a woman, ''Excuse me, how do I get to the library?'' She says, ''Go straight on, then turn left. It''s opposite the bank.'' I say thank you and walk there. At the library, I borrow two books. After that, I take the bus home. I get on the bus near the library and get off near my house. It takes about fifteen minutes. My neighbourhood is quiet and convenient. It was a busy but wonderful day!','[{"text":"Good morning!","ipa":"/ɡʊd ˈmɔrnɪŋ/","vi":"Chào buổi sáng!"},{"text":"Today I have a busy day in town.","ipa":"/təˈdeɪ aɪ hæv ə ˈbɪzi deɪ ɪn taʊn/","vi":"Hôm nay tôi có một ngày bận rộn trong thị trấn."},{"text":"I live in a small house near the park.","ipa":"/aɪ lɪv ɪn ə smɔl haʊs nɪr ðə pɑrk/","vi":"Tôi sống trong một ngôi nhà nhỏ gần công viên."},{"text":"There is a garden with a few flowers in front of my house.","ipa":"/ðɛr ɪz ə ˈɡɑrdən wɪð ə fju ˈflaʊərz ɪn frʌnt ʌv maɪ haʊs/","vi":"Có một khu vườn với vài bông hoa trước nhà tôi."},{"text":"First, I go to the post office to send a parcel.","ipa":"/fɜrst, aɪ ɡoʊ tu ðə poʊst ˈɔfɪs tu sɛnd ə ˈpɑrsəl/","vi":"Đầu tiên, tôi đến bưu điện để gửi một bưu kiện."},{"text":"''How much is this parcel?'' I ask.","ipa":"/haʊ mʌtʃ ɪz ðɪs ˈpɑrsəl? aɪ æsk/","vi":"\"Bưu kiện này giá bao nhiêu?\" tôi hỏi."},{"text":"''It''s two dollars,'' says the clerk.","ipa":"/ɪts tu ˈdɑlərz, sɛz ðə klɜrk/","vi":"\"Hai đô la,\" nhân viên nói."},{"text":"I pay and say thank you.","ipa":"/aɪ peɪ ænd seɪ θæŋk ju/","vi":"Tôi trả tiền và nói cảm ơn."},{"text":"Next, I need to find the library.","ipa":"/nɛkst, aɪ nid tu faɪnd ðə ˈlaɪˌbrɛri/","vi":"Tiếp theo, tôi cần tìm thư viện."},{"text":"I ask a woman, ''Excuse me, how do I get to the library?''","ipa":"/aɪ æsk ə ˈwʊmən, ɪkˈskjuz mi, haʊ du aɪ ɡɛt tu ðə ˈlaɪˌbrɛri?/","vi":"Tôi hỏi một người phụ nữ, \"Xin lỗi, làm thế nào để tôi đến thư viện?\""},{"text":"She says, ''Go straight on, then turn left.","ipa":"/ʃi sɛz, ɡoʊ streɪt ɑn, ðɛn tɜrn lɛft/","vi":"Bà ấy nói, \"Đi thẳng, sau đó rẽ trái."},{"text":"It''s opposite the bank.''","ipa":"/ɪts ˈɑpəzɪt ðə bæŋk/","vi":"Nó nằm đối diện ngân hàng.\""},{"text":"I say thank you and walk there.","ipa":"/aɪ seɪ θæŋk ju ænd wɔk ðɛr/","vi":"Tôi cảm ơn và đi bộ đến đó."},{"text":"At the library, I borrow two books.","ipa":"/æt ðə ˈlaɪˌbrɛri, aɪ ˈbɑroʊ tu bʊks/","vi":"Tại thư viện, tôi mượn hai cuốn sách."},{"text":"After that, I take the bus home.","ipa":"/ˈæftər ðæt, aɪ teɪk ðə bʌs hoʊm/","vi":"Sau đó, tôi bắt xe buýt về nhà."},{"text":"I get on the bus near the library and get off near my house.","ipa":"/aɪ ɡɛt ɑn ðə bʌs nɪr ðə ˈlaɪˌbrɛri ænd ɡɛt ɔf nɪr maɪ haʊs/","vi":"Tôi lên xe buýt gần thư viện và xuống gần nhà mình."},{"text":"It takes about fifteen minutes.","ipa":"/ɪt teɪks əˈbaʊt ˈfɪfˈtin ˈmɪnɪts/","vi":"Mất khoảng mười lăm phút."},{"text":"My neighbourhood is quiet and convenient.","ipa":"/maɪ ˈneɪbərˌhʊd ɪz ˈkwaɪət ænd kənˈvinjənt/","vi":"Khu phố của tôi yên tĩnh và thuận tiện."},{"text":"It was a busy but wonderful day!","ipa":"/ɪt wʌz ə ˈbɪzi bʌt ˈwʌndərfəl deɪ/","vi":"Đó là một ngày bận rộn nhưng tuyệt vời!"}]',NULL,'Good morning! Today I have a busy day in town. I live in a small house near the park. There is a garden with a few flowers in front of my house. First, I go to the post office to send a parcel. ''How much is this parcel?'' I ask. ''It''s two dollars,'' says the clerk. I pay and say thank you. Next, I need to find the library. I ask a woman, ''Excuse me, how do I get to the library?'' She says, ''Go straight on, then turn left. It''s opposite the bank.'' I say thank you and walk there. At the library, I borrow two books. After that, I take the bus home. I get on the bus near the library and get off near my house. It takes about fifteen minutes. My neighbourhood is quiet and convenient. It was a busy but wonderful day!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mixed_all',NULL,760,'a1-s4','733c9adf9f4c49058dec05e7d957cf16',NULL,NULL,'2026-07-25T12:48:00.708Z',NULL);
