INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('c58f00f0-d473-47d9-a1b3-96101f17210e','8a70fe8f-9632-4ee6-955e-e381055c9087',11,'fill_blank','He hasn''t ___ a stomach ache.',NULL,NULL,'["got"]',NULL,NULL,'Thể phủ định ''hasn''t got''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
