INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('d6da1c73-52c2-4a1d-a7ca-3426e3bc92cc','8a70fe8f-9632-4ee6-955e-e381055c9087',13,'ordering','Put the words in the correct order.',NULL,'I''ve got a fever',NULL,NULL,NULL,'''I''ve got'' = ''I have got''.',NULL,NULL,'["got", "I''ve", "a", "fever"]',NULL,NULL,NULL,NULL);
