INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('78abcf65-96d6-4b5d-b713-13c9a3b5007b','8a70fe8f-9632-4ee6-955e-e381055c9087',15,'categorize','Sort each sentence by the correct ''got'' form.',NULL,NULL,NULL,NULL,NULL,'Chia theo chủ ngữ: I/you/we/they → have got; he/she/it → has got.',NULL,NULL,NULL,'["have got", "has got"]','[{"text": "I''ve got a headache.", "category": "have got"}, {"text": "He''s got a fever.", "category": "has got"}, {"text": "They''ve got sore throats.", "category": "have got"}, {"text": "She''s got a cough.", "category": "has got"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('22d63318-c64f-41ec-905c-1c3a9ddacf77','a1-s5-03-read-aloud-doctor-visit','Leo Doesn''t Feel Well',1,'reading','A1 Movers',NULL,'Yesterday, Leo didn''t feel well. He had a fever and a bad cough. His throat was sore, and his head hurt too. In the morning, he told his mom, ''I feel sick. I''ve got a headache and a sore throat.'' His mom said, ''You''ve got a fever since yesterday. Let''s go to the pharmacy.'' At the pharmacy, the pharmacist gave Leo some medicine. ''Take this medicine twice a day,'' she said. ''One in the morning and one at night.'' Leo took the medicine and rested at home. The next day, his fever was gone, and his throat felt better. ''I feel much better now,'' he said with a smile.','[{"text":"Yesterday, Leo didn''t feel well.","ipa":"/ˈjɛstərdeɪ, ˈlioʊ ˈdɪdənt fiːl wɛl./","vi":"Hôm qua, Leo cảm thấy không khỏe."},{"text":"He had a fever and a bad cough.","ipa":"/hi hæd ə ˈfiːvər ænd ə bæd kɑf./","vi":"Cậu ấy bị sốt và ho nặng."},{"text":"His throat was sore, and his head hurt too.","ipa":"/hɪz θroʊt wʌz sɔr, ænd hɪz hɛd hɜrt tu./","vi":"Cậu ấy bị đau họng và đau đầu nữa."},{"text":"In the morning, he told his mom, ''I feel sick.''","ipa":"/ɪn ðə ˈmɔrnɪŋ, hi toʊld hɪz mɑm, ''aɪ fiːl sɪk.''/ ","vi":"Vào buổi sáng, cậu ấy nói với mẹ: ''Con thấy mệt quá.''"},{"text":"''I''ve got a headache and a sore throat.''","ipa":"/''aɪv gɑt ə ˈhɛdeɪk ænd ə sɔr θroʊt.''/ ","vi":"''Con bị đau đầu và đau họng ạ.''"},{"text":"His mom said, ''You''ve got a fever since yesterday.''","ipa":"/hɪz mɑm sɛd, ''juːv gɑt ə ˈfiːvər sɪns ˈjɛstərdeɪ.''/ ","vi":"Mẹ cậu ấy nói: ''Con đã bị sốt từ hôm qua rồi.''"},{"text":"Let''s go to the pharmacy.","ipa":"/lɛts goʊ tu ðə ˈfɑrməsi./","vi":"Để mẹ đưa con đi hiệu thuốc nhé."},{"text":"At the pharmacy, the pharmacist gave Leo some medicine.","ipa":"/æt ðə ˈfɑrməsi, ðə ˈfɑrməsɪst geɪv ˈlioʊ sʌm ˈmɛdəsɪn./","vi":"Tại hiệu thuốc, dược sĩ đã đưa cho Leo một ít thuốc."},{"text":"''Take this medicine twice a day,'' she said.","ipa":"/''teɪk ðɪs ˈmɛdəsɪn twaɪs ə deɪ,'' ʃi sɛd./","vi":"''Cháu uống thuốc này hai lần một ngày nhé,'' bà ấy nói."},{"text":"''One in the morning and one at night.''","ipa":"/''wʌn ɪn ðə ˈmɔrnɪŋ ænd wʌn æt naɪt.''/ ","vi":"''Một lần vào buổi sáng và một lần vào buổi tối.''"},{"text":"Leo took the medicine and rested at home.","ipa":"/ˈlioʊ tʊk ðə ˈmɛdəsɪn ænd ˈrɛstəd æt hoʊm./","vi":"Leo uống thuốc và nghỉ ngơi ở nhà."},{"text":"The next day, his fever was gone, and his throat felt better.","ipa":"/ðə nɛkst deɪ, hɪz ˈfiːvər wʌz gɑn, ænd hɪz θroʊt fɛlt ˈbɛtər./","vi":"Ngày hôm sau, cậu ấy đã hết sốt và họng cũng đỡ đau hơn."},{"text":"''I feel much better now,'' he said with a smile.","ipa":"/''aɪ fiːl mʌtʃ ˈbɛtər naʊ,'' hi sɛd wɪð ə smaɪl./","vi":"''Bây giờ con thấy khỏe hơn nhiều rồi ạ,'' cậu ấy nói với một nụ cười."}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,830,'a1-s5','3bb7e20742c947778796c90f397661a4',NULL,NULL,'2026-07-25T12:43:00.317Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('8a3e0818-8cdc-4b4c-a616-dc1c56e7d404','a1-s5-04-listen-liam-sick','Liam Doesn''t Feel Well',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Emma [worried]: Hi Liam! Are you okay? You don''t look well.
Liam [sad]: Hi Emma. No, I don''t feel well. I''ve got a fever and a bad cough.
Emma [worried]: Oh no! Have you got a sore throat too?
Liam [sad]: Yes, I have. My throat hurts since yesterday, and I have a headache too.
Emma [gentle]: You should go to the pharmacy. Have you got any medicine?
Liam: Not yet. My mom bought some medicine this morning.
Emma: How often do you take it?
Liam: Twice a day - one in the morning and one at night.
Emma [hopeful]: I hope you feel better soon!
Liam [sad]: Thanks, Emma. I also have a stomach ache, so I''m going to rest now.
Emma [gentle]: Good idea. Get some rest and drink water.
Liam [hopeful]: I will. See you at school when I feel better!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,840,'a1-s5','3bb7e20742c947778796c90f397661a4',NULL,NULL,'2026-07-25T12:43:00.317Z',NULL);
