INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('61b6ac91-21eb-47a7-b40c-b8a0464db954','a1-s5-08-read-aloud-stay-healthy','How to Stay Healthy',1,'reading','A1 Movers',NULL,'Staying healthy is not difficult. First, you should drink more water every day. Water helps your body work well. Second, you should exercise. You don''t need a gym - you can just walk, run, or ride a bike. Third, you should sleep early. Sleeping early gives your body time to rest. Why don''t you try going to bed at nine o''clock tonight? You shouldn''t eat too much junk food, and you shouldn''t stay up late every night. Too much stress is also unhealthy, so try to relax and have fun with your friends. If you follow these simple habits, you will feel healthy and happy every day.','[{"text":"Staying healthy is not difficult.","ipa":"/ˈsteɪɪŋ ˈhɛlθi ɪz nɑt ˈdɪfɪkəlt./","vi":"Giữ gìn sức khỏe không hề khó."},{"text":"First, you should drink more water every day.","ipa":"/fɜrst, ju ʃʊd drɪŋk mɔr ˈwɔtər ˈɛvri deɪ./","vi":"Đầu tiên, bạn nên uống nhiều nước mỗi ngày."},{"text":"Water helps your body work well.","ipa":"/ˈwɔtər hɛlps jʊr ˈbɑdi wɜrk wɛl./","vi":"Nước giúp cơ thể bạn hoạt động tốt."},{"text":"Second, you should exercise.","ipa":"/ˈsɛkənd, ju ʃʊd ˈɛksərˌsaɪz./","vi":"Thứ hai, bạn nên tập thể dục."},{"text":"You don''t need a gym - you can just walk, run, or ride a bike.","ipa":"/ju doʊnt nid ə dʒɪm - ju kæn dʒʌst wɔk, rʌn, ɔr raɪd ə baɪk./","vi":"Bạn không cần đến phòng tập - bạn chỉ cần đi bộ, chạy bộ hoặc đạp xe."},{"text":"Third, you should sleep early.","ipa":"/θɜrd, ju ʃʊd slip ˈɜrli./","vi":"Thứ ba, bạn nên đi ngủ sớm."},{"text":"Sleeping early gives your body time to rest.","ipa":"/ˈslipɪŋ ˈɜrli ɡɪvz jʊr ˈbɑdi taɪm tu rɛst./","vi":"Đi ngủ sớm giúp cơ thể bạn có thời gian nghỉ ngơi."},{"text":"Why don''t you try going to bed at nine o''clock tonight?","ipa":"/waɪ doʊnt ju traɪ ˈɡoʊɪŋ tu bɛd æt naɪn əˈklɑk təˈnaɪt?/","vi":"Tại sao bạn không thử đi ngủ lúc chín giờ tối nay nhỉ?"},{"text":"You shouldn''t eat too much junk food, and you shouldn''t stay up late every night.","ipa":"/ju ˈʃʊdənt it tu mʌtʃ dʒʌŋk fud, ænd ju ˈʃʊdənt steɪ ʌp leɪt ˈɛvri naɪt./","vi":"Bạn không nên ăn quá nhiều đồ ăn vặt và không nên thức khuya mỗi đêm."},{"text":"Too much stress is also unhealthy, so try to relax and have fun with your friends.","ipa":"/tu mʌtʃ strɛs ɪz ˈɔlsoʊ ʌnˈhɛlθi, soʊ traɪ tu riˈlæks ænd hæv fʌn wɪð jʊr frɛndz./","vi":"Căng thẳng quá mức cũng không tốt cho sức khỏe, vì vậy hãy cố gắng thư giãn và vui chơi cùng bạn bè."},{"text":"If you follow these simple habits, you will feel healthy and happy every day.","ipa":"/ɪf ju ˈfɑloʊ ðiz ˈsɪmpəl ˈhæbɪts, ju wɪl fil ˈhɛlθi ænd ˈhæpi ˈɛvri deɪ./","vi":"Nếu bạn tuân theo những thói quen đơn giản này, bạn sẽ cảm thấy khỏe mạnh và hạnh phúc mỗi ngày."}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,880,'a1-s5','d1f37508d1504ea5b20588bddc4de138',NULL,NULL,'2026-07-25T12:43:00.317Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('be3af98f-891b-42b6-8d85-1e722bde5685','a1-s5-09-listen-advice-for-jack','Some Advice for Jack',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Sophie [worried]: Jack, you look tired. Are you okay?
Jack [worried]: Not really. I feel stressed about my exams, and I don''t sleep well.
Sophie [gentle]: You should sleep early. Why don''t you go to bed at nine tonight?
Jack: Maybe. But I also don''t exercise much these days.
Sophie [gentle]: You should exercise every day, even just a short walk.
Jack: That''s a good idea. What about food? I eat a lot of junk food.
Sophie [gentle]: You shouldn''t eat too much junk food. You should drink more water too.
Jack: Okay, I should drink more water and get some rest.
Sophie [gentle]: Exactly! And you shouldn''t be so stressed about exams. Just do your best.
Jack [hopeful]: Thanks, Sophie. Why don''t we go for a walk now?
Sophie [happy]: Great idea! That''s healthy and fun.
Jack [relieved]: I feel better already, just talking about it.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,890,'a1-s5','d1f37508d1504ea5b20588bddc4de138',NULL,NULL,'2026-07-25T12:43:00.317Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('7438432a-0598-4fe2-92db-aeacabf5ccc9','be3af98f-891b-42b6-8d85-1e722bde5685',0,'multiple_choice','Why does Jack feel stressed?','["About his exams", "About his family", "About the weather", "About his bag"]','About his exams',NULL,NULL,NULL,'Jack nói ''I feel stressed about my exams.''','Jack: Not really. I feel stressed about my exams, and I don''t sleep well.',NULL,NULL,NULL,NULL,NULL,NULL);
