INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('addadde0-7197-4a82-9fdb-c39f7a18a91d','be3af98f-891b-42b6-8d85-1e722bde5685',8,'matching','Match each piece of advice to what it is about.',NULL,NULL,NULL,NULL,NULL,'Ghép lời khuyên với chủ đề tương ứng trong hội thoại.','Sophie: You should sleep early. Why don''t you go to bed at nine tonight?','[{"left": "Sleep early", "right": "Rest"}, {"left": "Drink more water", "right": "Water"}, {"left": "Go for a walk", "right": "Exercise"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('776a8a0f-fd7d-49b5-aafb-d7437250bf97','be3af98f-891b-42b6-8d85-1e722bde5685',9,'matching','Match each person to what they say.',NULL,NULL,NULL,NULL,NULL,'Xác định ai nói câu nào trong hội thoại.','Jack: Not really. I feel stressed about my exams, and I don''t sleep well.','[{"left": "You should sleep early.", "right": "Sophie"}, {"left": "I feel stressed about my exams.", "right": "Jack"}]',NULL,NULL,NULL,NULL,NULL);
