INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('64408d69-a7f9-4608-91d5-793c88b09ba7','48e72122-f83a-4e96-a6ec-5c74cc309ce3',13,'ordering','Put the words in the correct order.',NULL,'I enjoy playing football',NULL,NULL,NULL,'Chủ ngữ + enjoy + V-ing.',NULL,NULL,'["playing", "I", "football", "enjoy"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('edb70c32-4d8c-4174-b646-e3f420afad3c','48e72122-f83a-4e96-a6ec-5c74cc309ce3',14,'ordering','Put the words in the correct order.',NULL,'She prefers cycling to hiking',NULL,NULL,NULL,'''prefer A to B'' - thích A hơn B.',NULL,NULL,'["prefers", "cycling", "hiking", "She", "to"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('ed167c63-7e21-4f72-a69e-373483ae0ec6','48e72122-f83a-4e96-a6ec-5c74cc309ce3',15,'categorize','Sort each activity by how the person feels about it.',NULL,NULL,NULL,NULL,NULL,'Phân loại theo cảm xúc: enjoy (thích) và hate (ghét).',NULL,NULL,NULL,'["Enjoy", "Hate"]','[{"text": "I enjoy cycling.", "category": "Enjoy"}, {"text": "He hates fishing.", "category": "Hate"}, {"text": "They enjoy hiking.", "category": "Enjoy"}, {"text": "She hates camping.", "category": "Hate"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('2f5aed4f-cd5a-497b-8d7e-da487e9733b4','a1-s5-13-read-aloud-weekend-hobby','My Weekend Hobbies',1,'reading','A1 Movers',NULL,'At the weekend, I love spending my free time outdoors. I enjoy hiking in the hills because the fresh air makes me feel relaxing and happy. My sister prefers cycling to hiking - she thinks cycling is more exciting. My brother hates staying inside; he says it''s boring. Instead, he enjoys fishing by the river at least once a week. Sometimes we join a sports club together on Saturdays. We enjoy playing outdoor games because they are fun and we can be with our friends. In my free time, I also like camping with my family. We think outdoor hobbies are the best way to relax and have fun.','[{"text":"At the weekend, I love spending my free time outdoors.","ipa":"/æt ðə ˈwiːkˌɛnd, aɪ lʌv ˈspɛndɪŋ maɪ friː taɪm aʊtˈdɔrz./","vi":"Vào cuối tuần, tôi thích dành thời gian rảnh rỗi ở ngoài trời."},{"text":"I enjoy hiking in the hills because the fresh air makes me feel relaxing and happy.","ipa":"/aɪ ɛnˈdʒɔɪ ˈhaɪkɪŋ ɪn ðə hɪlz bɪˈkəz ðə frɛʃ ɛr meɪks miː fiːl rɪˈlæksɪŋ ænd ˈhæpi./","vi":"Tôi thích đi bộ đường dài trên đồi vì không khí trong lành làm tôi cảm thấy thư giãn và vui vẻ."},{"text":"My sister prefers cycling to hiking - she thinks cycling is more exciting.","ipa":"/maɪ ˈsɪstər prɪˈfɜrz ˈsaɪklɪŋ tuː ˈhaɪkɪŋ - ʃiː θɪŋks ˈsaɪklɪŋ ɪz mɔr ɪkˈsaɪtɪŋ./","vi":"Chị gái tôi thích đạp xe hơn là đi bộ - chị ấy nghĩ đạp xe thú vị hơn."},{"text":"My brother hates staying inside; he says it''s boring.","ipa":"/maɪ ˈbrʌðər heɪts ˈsteɪɪŋ ɪnˈsaɪd; hiː sɛz ɪts ˈbɔrɪŋ./","vi":"Anh trai tôi ghét ở trong nhà; anh ấy nói việc đó rất chán."},{"text":"Instead, he enjoys fishing by the river at least once a week.","ipa":"/ɪnˈstɛd, hiː ɛnˈdʒɔɪz ˈfɪʃɪŋ baɪ ðə ˈrɪvər æt list wʌns ə wiːk./","vi":"Thay vào đó, anh ấy thích đi câu cá bên bờ sông ít nhất một lần mỗi tuần."},{"text":"Sometimes we join a sports club together on Saturdays.","ipa":"/ˈsʌmˌtaɪmz wiː dʒɔɪn ə spɔrts klʌb təˈɡɛðər ɑn ˈsætərˌdeɪz./","vi":"Đôi khi chúng tôi cùng tham gia một câu lạc bộ thể thao vào các ngày thứ Bảy."},{"text":"We enjoy playing outdoor games because they are fun and we can be with our friends.","ipa":"/wiː ɛnˈdʒɔɪ ˈpleɪɪŋ aʊtˈdɔr ɡeɪmz bɪˈkəz ðeɪ ɑr fʌn ænd wiː kæn biː wɪð ˈaʊər frɛndz./","vi":"Chúng tôi thích chơi các trò chơi ngoài trời vì chúng rất vui và chúng tôi có thể ở bên bạn bè."},{"text":"In my free time, I also like camping with my family.","ipa":"/ɪn maɪ friː taɪm, aɪ ˈɔlsoʊ laɪk ˈkæmpɪŋ wɪð maɪ ˈfæməli./","vi":"Vào thời gian rảnh, tôi cũng thích đi cắm trại cùng gia đình."},{"text":"We think outdoor hobbies are the best way to relax and have fun.","ipa":"/wiː θɪŋk aʊtˈdɔr ˈhɑbiz ɑr ðə bɛst weɪ tuː rɪˈlæks ænd hæv fʌn./","vi":"Chúng tôi nghĩ các sở thích ngoài trời là cách tốt nhất để thư giãn và vui chơi."}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,930,'a1-s5','e58bd17a05014fcf8e916bb079f5d280',NULL,NULL,'2026-07-25T12:43:00.317Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('0b786f65-7259-43b7-8ddf-411050baede5','a1-s5-14-listen-hobbies-chat','What Do You Do in Your Free Time?',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Noah: Ava, what do you do in your free time?
Ava [happy]: I enjoy hiking because it''s relaxing and I love nature.
Noah [excited]: Really? I prefer cycling to hiking. It''s more exciting for me.
Ava: Do you join a sports club?
Noah: Yes, I join a cycling club at least once a week.
Ava: That sounds fun! My brother hates cycling, though. He thinks it''s boring.
Noah: What does he enjoy doing instead?
Ava: He enjoys fishing by the river because it''s calm and quiet.
Noah [disgusted]: I hate fishing - I think it''s boring, not exciting!
Ava [hopeful]: Everyone likes different things. Why don''t we go hiking together this weekend?
Noah [happy]: Good idea! I enjoy trying new outdoor hobbies with friends.
Ava [happy]: Great, let''s join the hiking group on Saturday.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,940,'a1-s5','e58bd17a05014fcf8e916bb079f5d280',NULL,NULL,'2026-07-25T12:43:00.317Z',NULL);
