INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('42b337e2-a399-4c83-ae9b-d490c46d33d4','a1-s5-15-reading-outdoor-and-healthy','Mia''s Healthy Hobby',1,'reading','A1 Movers',NULL,'Mia loves her free time. On Saturdays, she likes hiking with her family in the hills near her house. She thinks it is relaxing and it also keeps her healthy. Her doctor once told her, ''You should exercise every week to stay healthy.'' Mia enjoys hiking because it is exciting and fun, not boring at all. Before, Mia used to feel stressed after school, but now she feels much better. She joins a hiking club at least once a month with her friends. Her friend Leo prefers cycling to hiking, but they still enjoy going outdoors together. Mia says outdoor hobbies are the best way to stay both happy and healthy.','[{"text":"Mia loves her free time.","ipa":"/ˈmiə lʌvz hər fri taɪm./","vi":"Mia rất thích thời gian rảnh của mình."},{"text":"On Saturdays, she likes hiking with her family in the hills near her house.","ipa":"/ɑn ˈsætərˌdeɪz, ʃi laɪks ˈhaɪkɪŋ wɪð hər ˈfæməli ɪn ðə hɪlz nɪr hər haʊs./","vi":"Vào các ngày thứ Bảy, cô ấy thích đi bộ đường dài cùng gia đình trên những ngọn đồi gần nhà."},{"text":"She thinks it is relaxing and it also keeps her healthy.","ipa":"/ʃi θɪŋks ɪt ɪz rɪˈlæksɪŋ ænd ɪt ˈɔlsoʊ kips hər ˈhɛlθi./","vi":"Cô ấy nghĩ rằng việc đó rất thư giãn và cũng giúp cô ấy khỏe mạnh."},{"text":"Her doctor once told her, ''You should exercise every week to stay healthy.''","ipa":"/hər ˈdɑktər wʌns toʊld hər, ''ju ʃʊd ˈɛksərˌsaɪz ˈɛvri wik tu steɪ ˈhɛlθi.''/","vi":"Bác sĩ của cô ấy từng nói: ''Bạn nên tập thể dục mỗi tuần để giữ gìn sức khỏe.''"},{"text":"Mia enjoys hiking because it is exciting and fun, not boring at all.","ipa":"/ˈmiə ɛnˈdʒɔɪz ˈhaɪkɪŋ bɪˈkəz ɪt ɪz ɪkˈsaɪtɪŋ ænd fʌn, nɑt ˈbɔrɪŋ æt ɔl./","vi":"Mia thích đi bộ đường dài vì nó rất thú vị và vui vẻ, không hề nhàm chán chút nào."},{"text":"Before, Mia used to feel stressed after school, but now she feels much better.","ipa":"/bɪˈfɔr, ˈmiə juzd tu fil strɛst ˈæftər skul, bʌt naʊ ʃi filz mʌtʃ ˈbɛtər./","vi":"Trước đây, Mia thường cảm thấy căng thẳng sau giờ học, nhưng bây giờ cô ấy cảm thấy tốt hơn nhiều."},{"text":"She joins a hiking club at least once a month with her friends.","ipa":"/ʃi dʒɔɪnz ə ˈhaɪkɪŋ klʌb æt list wʌns ə mʌnθ wɪð hər frɛndz./","vi":"Cô ấy tham gia một câu lạc bộ đi bộ đường dài ít nhất mỗi tháng một lần cùng bạn bè."},{"text":"Her friend Leo prefers cycling to hiking, but they still enjoy going outdoors together.","ipa":"/hər frɛnd ˈlioʊ priˈfərz ˈsaɪklɪŋ tu ˈhaɪkɪŋ, bʌt ðeɪ stɪl ɛnˈdʒɔɪ ˈgoʊɪŋ ˈaʊtˌdɔrz təˈgɛðər./","vi":"Bạn của cô ấy là Leo thích đạp xe hơn là đi bộ đường dài, nhưng họ vẫn thích cùng nhau ra ngoài trời."},{"text":"Mia says outdoor hobbies are the best way to stay both happy and healthy.","ipa":"/ˈmiə sɛz ˈaʊtˌdɔr ˈhɑbiz ɑr ðə bɛst weɪ tu steɪ boʊθ ˈhæpi ænd ˈhɛlθi./","vi":"Mia nói rằng các sở thích ngoài trời là cách tốt nhất để vừa hạnh phúc vừa khỏe mạnh."}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'reading_comprehension',NULL,950,'a1-s5','d1f37508d1504ea5b20588bddc4de138',NULL,NULL,'2026-07-25T12:43:00.317Z',NULL);
