INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('63b0f2e6-253a-4640-be20-feffeada7630','42b337e2-a399-4c83-ae9b-d490c46d33d4',5,'fill_blank','Mia used to feel ___ after school before.',NULL,NULL,'["stressed"]',NULL,NULL,'Đoạn văn: ''Mia used to feel stressed after school.''',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('59b7eb27-add3-4fd6-a244-9d3efcd0d146','42b337e2-a399-4c83-ae9b-d490c46d33d4',6,'ordering','Put the words in the correct order.',NULL,'Outdoor hobbies are the best way',NULL,NULL,NULL,'Sắp xếp lại theo câu trong bài: ''Outdoor hobbies are the best way ...''.',NULL,NULL,'["hobbies", "best", "are", "Outdoor", "the", "way"]',NULL,NULL,NULL,NULL);
