INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('281aa63c-acf8-4735-b629-79095d50ac17','a1-s5-16-mixed-checkpoint','My Friend Is Stressed',1,'mixed','A1 Movers',NULL,'Today, I noticed that my friend Sam looked tired and stressed at school. I asked him, ''Are you okay?'' Sam said, ''Not really. I''ve got a headache, and I feel sick. I think it''s because of my exams.'' I told him, ''You should get some rest. Why don''t you sleep early tonight?'' Sam said, ''That''s a good idea. I also shouldn''t drink so much coffee.'' Then I said, ''You know, I enjoy playing football in the park. It''s really relaxing, not boring at all. Why don''t you join me this weekend?'' Sam smiled and said, ''I''d love that! I prefer football to studying all day.'' We agreed to meet at least once a week to play together and stay healthy.','[{"text":"Today, I noticed that my friend Sam looked tired and stressed at school.","ipa":"/təˈdeɪ, aɪ ˈnoʊtɪst ðæt maɪ frɛnd sæm lʊkt ˈtaɪərd ænd strɛst æt skul./","vi":"Hôm nay, mình để ý thấy bạn Sam trông có vẻ mệt mỏi và căng thẳng ở trường."},{"text":"I asked him, ''Are you okay?''","ipa":"/aɪ æskt hɪm, /ɑr ju oʊˈkeɪ?''''/","vi":"Mình hỏi cậu ấy: ''Bạn ổn không?''"},{"text":"Sam said, ''Not really.''","ipa":"/sæm sɛd, /nɑt ˈrɪli.''''/","vi":"Sam đáp: ''Không hẳn là vậy.''"},{"text":"I''ve got a headache, and I feel sick.","ipa":"/aɪv gɑt ə ˈhɛdeɪk, ænd aɪ fil sɪk./","vi":"Mình bị đau đầu và thấy không khỏe."},{"text":"I think it''s because of my exams.","ipa":"/aɪ θɪŋk ɪts bɪˈkəz ʌv maɪ ɪgˈzæmz./","vi":"Mình nghĩ là do mấy bài kiểm tra."},{"text":"I told him, ''You should get some rest.''","ipa":"/aɪ toʊld hɪm, /ju ʃʊd gɛt sʌm rɛst.''''/","vi":"Mình bảo cậu ấy: ''Bạn nên nghỉ ngơi đi.''"},{"text":"Why don''t you sleep early tonight?","ipa":"/waɪ doʊnt ju slip ˈɜrli təˈnaɪt?/","vi":"Sao tối nay bạn không ngủ sớm?"},{"text":"Sam said, ''That''s a good idea.''","ipa":"/sæm sɛd, /ðæts ə gʊd aɪˈdiə.''''/","vi":"Sam nói: ''Ý hay đấy.''"},{"text":"I also shouldn''t drink so much coffee.","ipa":"/aɪ ˈɔlsoʊ ˈʃʊdnt drɪŋk soʊ mʌtʃ ˈkɑfi./","vi":"Mình cũng không nên uống quá nhiều cà phê nữa."},{"text":"Then I said, ''You know, I enjoy playing football in the park.''","ipa":"/ðɛn aɪ sɛd, /ju noʊ, aɪ ɛnˈdʒɔɪ ˈpleɪɪŋ ˈfʊtbɔl ɪn ðə pɑrk.''''/","vi":"Sau đó mình bảo: ''Bạn biết không, mình rất thích đá bóng ở công viên.''"},{"text":"It''s really relaxing, not boring at all.","ipa":"/ɪts ˈrɪli rɪˈlæksɪŋ, nɑt ˈbɔrɪŋ æt ɔl./","vi":"Nó rất thư giãn, không hề nhàm chán chút nào."},{"text":"Why don''t you join me this weekend?","ipa":"/waɪ doʊnt ju dʒɔɪn mi ðɪs ˈwikˌɛnd?/","vi":"Cuối tuần này bạn tham gia cùng mình nhé?"},{"text":"Sam smiled and said, ''I''d love that!''","ipa":"/sæm smaɪld ænd sɛd, /aɪd lʌv ðæt!''''/","vi":"Sam mỉm cười và nói: ''Mình rất sẵn lòng!''"},{"text":"I prefer football to studying all day.","ipa":"/aɪ priˈfɜr ˈfʊtbɔl tu ˈstʌdiɪŋ ɔl deɪ./","vi":"Mình thích đá bóng hơn là ngồi học cả ngày."},{"text":"We agreed to meet at least once a week to play together and stay healthy.","ipa":"/wi əˈgrid tu mit æt list wʌns ə wik tu pleɪ təˈgɛðər ænd steɪ ˈhɛlθi./","vi":"Chúng mình đồng ý gặp nhau ít nhất mỗi tuần một lần để chơi cùng nhau và giữ gìn sức khỏe."}]',NULL,'Today, I noticed that my friend Sam looked tired and stressed at school. I asked him, ''Are you okay?'' Sam said, ''Not really. I''ve got a headache, and I feel sick. I think it''s because of my exams.'' I told him, ''You should get some rest. Why don''t you sleep early tonight?'' Sam said, ''That''s a good idea. I also shouldn''t drink so much coffee.'' Then I said, ''You know, I enjoy playing football in the park. It''s really relaxing, not boring at all. Why don''t you join me this weekend?'' Sam smiled and said, ''I''d love that! I prefer football to studying all day.'' We agreed to meet at least once a week to play together and stay healthy.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mixed_all',NULL,960,'a1-s5','4ca2f9457e8c4a98810e8617e857be10',NULL,NULL,'2026-07-25T12:43:00.317Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('275f4f83-01b0-44c5-aa2b-b3fb93f2ee1e','281aa63c-acf8-4735-b629-79095d50ac17',0,'multiple_choice','What is wrong with Sam?','["He has a headache and feels sick", "He has a broken leg", "He is very happy", "He is hungry"]','He has a headache and feels sick',NULL,NULL,NULL,'Sam nói ''I''ve got a headache, and I feel sick.''',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
