INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('2b03518b-fa1d-4b5a-b363-d34cc3eba5f1','a1-s6-03-read-aloud-weather-day','A Rainy Day in Spring',1,'reading','A1 Movers',NULL,'It''s spring, and the weather is changing every day. This morning, it was sunny and warm. Now, dark clouds are in the sky, and it''s raining. The wind is blowing, and it feels much colder. The forecast says it will be wet all afternoon. My little sister loves the rain. She is standing by the window and watching the drops fall. "Look, the street is wet!" she says. In summer, the weather is usually dry and hot, but spring is different. Sometimes it''s twenty degrees and sunny; sometimes it''s cold and wet, right now. I like spring because the weather is always a surprise. Tomorrow, the forecast says it will be dry again, so we can play outside.','[{"text":"It''s spring, and the weather is changing every day.","ipa":"/ɪts sprɪŋ, ænd ðə ˈwɛðər ɪz ˈtʃeɪndʒɪŋ ˈɛvri deɪ./","vi":"Đang là mùa xuân, và thời tiết thay đổi mỗi ngày."},{"text":"This morning, it was sunny and warm.","ipa":"/ðɪs ˈmɔrnɪŋ, ɪt wʌz ˈsʌni ænd wɔrm./","vi":"Sáng nay, trời nắng và ấm áp."},{"text":"Now, dark clouds are in the sky, and it''s raining.","ipa":"/naʊ, dɑrk klaʊdz ɑr ɪn ðə skaɪ, ænd ɪts ˈreɪnɪŋ./","vi":"Bây giờ, những đám mây đen đang bao phủ bầu trời và trời đang mưa."},{"text":"The wind is blowing, and it feels much colder.","ipa":"/ðə wɪnd ɪz ˈbloʊɪŋ, ænd ɪt filz mʌtʃ ˈkoʊldər./","vi":"Gió đang thổi và cảm thấy lạnh hơn nhiều."},{"text":"The forecast says it will be wet all afternoon.","ipa":"/ðə ˈfɔrkæst sɛz ɪt wɪl bi wɛt ɔl ˌæftərˈnun./","vi":"Dự báo thời tiết cho biết trời sẽ mưa suốt cả buổi chiều."},{"text":"My little sister loves the rain.","ipa":"/maɪ ˈlɪtəl ˈsɪstər lʌvz ðə reɪn./","vi":"Em gái nhỏ của tôi rất thích mưa."},{"text":"She is standing by the window and watching the drops fall.","ipa":"/ʃi ɪz ˈstændɪŋ baɪ ðə ˈwɪndoʊ ænd ˈwɑtʃɪŋ ðə drɑps fɔl./","vi":"Con bé đang đứng bên cửa sổ và ngắm nhìn những giọt mưa rơi."},{"text":"\"Look, the street is wet!\" she says.","ipa":"/lʊk, ðə strit ɪz wɛt! ʃi sɛz./","vi":"\"Nhìn kìa, đường ướt hết rồi!\" con bé nói."},{"text":"In summer, the weather is usually dry and hot, but spring is different.","ipa":"/ɪn ˈsʌmər, ðə ˈwɛðər ɪz ˈjuʒəwəli draɪ ænd hɑt, bʌt sprɪŋ ɪz ˈdɪfrənt./","vi":"Vào mùa hè, thời tiết thường khô và nóng, nhưng mùa xuân thì khác."},{"text":"Sometimes it''s twenty degrees and sunny; sometimes it''s cold and wet, right now.","ipa":"/ˈsʌmˌtaɪmz ɪts ˈtwɛnti dɪˈgriz ænd ˈsʌni; ˈsʌmˌtaɪmz ɪts koʊld ænd wɛt, raɪt naʊ./","vi":"Đôi khi trời nắng và khoảng hai mươi độ; đôi khi trời lại lạnh và ẩm ướt như bây giờ."},{"text":"I like spring because the weather is always a surprise.","ipa":"/aɪ laɪk sprɪŋ bɪˈkəz ðə ˈwɛðər ɪz ˈɔlˌweɪz ə sərˈpraɪz./","vi":"Tôi thích mùa xuân vì thời tiết luôn là một điều bất ngờ."},{"text":"Tomorrow, the forecast says it will be dry again, so we can play outside.","ipa":"/təˈmɑroʊ, ðə ˈfɔrkæst sɛz ɪt wɪl bi draɪ əˈgɛn, soʊ wi kæn pleɪ ˌaʊtˈsaɪd./","vi":"Ngày mai, dự báo thời tiết nói rằng trời sẽ khô ráo trở lại, nên chúng tôi có thể ra ngoài chơi."}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,1030,'a1-s6','1719a4f2c51f48e7b8274e09ff71bc40',NULL,NULL,'2026-07-25T12:45:19.398Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('c7081c30-0015-4964-95b8-6f8a4373ff48','a1-s6-04-listen-choose-weather','What''s the Weather Like Today?',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Emma (F): Hi James! Do you know the weather forecast for today?
James (M): Hi Emma! Yes, it''s cloudy right now, but it''s going to rain this afternoon.
Emma (F) [sad]: Oh no! I wanted to go to the park. What''s the temperature?
James (M): It''s about eighteen degrees at the moment. Not too cold.
Emma (F): That''s okay then. Is it windy too?
James (M): A little bit. The wind is blowing, but it''s not too strong.
Emma (F): What about tomorrow? Is it still autumn weather?
James (M): Yes, it''s still autumn, so it will probably be wet again.
Emma (F) [happy]: I prefer summer. It''s always dry and sunny then.
James (M) [happy]: Me too! But I also like winter because I love the snow.
Emma (F): True! Okay, let''s bring an umbrella today, just in case.
James (M): Good idea. Let''s check the forecast again tonight.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,1040,'a1-s6','1719a4f2c51f48e7b8274e09ff71bc40',NULL,NULL,'2026-07-25T12:45:19.398Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('10201106-cf61-4780-b584-69e380734129','c7081c30-0015-4964-95b8-6f8a4373ff48',0,'multiple_choice','What is the weather like right now?','["Cloudy", "Sunny", "Snowy", "Windy and stormy"]','Cloudy',NULL,NULL,NULL,'James nói ''it''s cloudy right now''.','James (M): Hi Emma! Yes, it''s cloudy right now, but it''s going to rain this afternoon.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('f00ed188-8b9d-48b0-91bc-279b5c30e23c','c7081c30-0015-4964-95b8-6f8a4373ff48',1,'multiple_choice','What is the temperature at the moment?','["Eighteen degrees", "Eight degrees", "Twenty degrees", "Thirty degrees"]','Eighteen degrees',NULL,NULL,NULL,'James nói ''eighteen degrees''.','James (M): It''s about eighteen degrees at the moment.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('a28255c4-85a4-4320-8bc9-7f2639be33f5','c7081c30-0015-4964-95b8-6f8a4373ff48',2,'multiple_choice','What season is it now?','["Autumn", "Summer", "Winter", "Spring"]','Autumn',NULL,NULL,NULL,'James nói ''it''s still autumn''.','James (M): Yes, it''s still autumn, so it will probably be wet again.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('f254ebba-cd83-44a7-b806-35a6ef2843a2','c7081c30-0015-4964-95b8-6f8a4373ff48',3,'multiple_choice','What season does Emma prefer?','["Summer", "Autumn", "Winter", "Spring"]','Summer',NULL,NULL,NULL,'Emma nói ''I prefer summer''.','Emma (F): I prefer summer. It''s always dry and sunny then.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('0b1e3ac7-474d-4c62-acff-99a68981614e','c7081c30-0015-4964-95b8-6f8a4373ff48',4,'fill_blank','It''s going to ___ this afternoon.',NULL,'rain','["rain"]','["rain", "snow", "shine"]',NULL,'James nói ''going to rain''.','James (M): Yes, it''s cloudy right now, but it''s going to rain this afternoon.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('47ef0992-69d9-4a37-8e54-aa764c803fca','c7081c30-0015-4964-95b8-6f8a4373ff48',5,'fill_blank','The wind ___ blowing, but it''s not too strong.',NULL,'is','["is"]','["is", "was"]',NULL,'Hiện tại tiếp diễn: ''is blowing''.','James (M): A little bit. The wind is blowing, but it''s not too strong.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('9c6f3630-a518-431f-9326-58a6f6e2f2e0','c7081c30-0015-4964-95b8-6f8a4373ff48',6,'fill_blank','James likes winter because he loves the ___.',NULL,'snow','["snow"]','["snow", "rain"]',NULL,'James nói ''I love the snow''.','James (M): But I also like winter because I love the snow.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('c317fa2a-4b77-4db4-86e1-a151d5b0a276','c7081c30-0015-4964-95b8-6f8a4373ff48',7,'fill_blank','They decide to bring an ___ today.',NULL,'umbrella','["umbrella"]','["umbrella", "coat"]',NULL,'Emma nói ''bring an umbrella''.','Emma (F): True! Okay, let''s bring an umbrella today, just in case.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('cd7bba0c-b4c1-4cb4-bbfc-dbc2099817ef','c7081c30-0015-4964-95b8-6f8a4373ff48',8,'matching','Match each person to their favourite season.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng người với mùa họ thích theo hội thoại.','Emma: I prefer summer. James: I also like winter.','[{"left": "Emma", "right": "Summer"}, {"left": "James", "right": "Winter"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('f86f4358-eb82-47f1-a1c7-d426fbf96b4f','c7081c30-0015-4964-95b8-6f8a4373ff48',9,'matching','Match each weather word to what it describes today.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng thời điểm với thời tiết tương ứng.','cloudy right now... rain this afternoon... wet again tomorrow.','[{"left": "Right now", "right": "Cloudy"}, {"left": "This afternoon", "right": "Rain"}, {"left": "Tomorrow", "right": "Wet, autumn weather"}]',NULL,NULL,NULL,NULL,NULL);
