INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('e2aa7d5e-1187-4a1f-ac01-c6e0f1e4c861','28f5f271-9117-45c5-9440-f4e0350b8bd2',0,'multiple_choice','___ shirt (near me) is too small.','["This", "That", "These", "Those"]','This',NULL,NULL,NULL,'Vật số ít ở GẦN dùng ''this''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
