INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('15cd7151-e4ce-4eef-9887-6576fbb281db','28f5f271-9117-45c5-9440-f4e0350b8bd2',3,'multiple_choice','Can I try on ___ trousers (near the mirror, far from me)?','["those", "this", "that", "these"]','those',NULL,NULL,NULL,'Vật số nhiều ở XA dùng ''those''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('e5bd0689-2f89-4245-b1ca-c3d32bf0b9e4','28f5f271-9117-45c5-9440-f4e0350b8bd2',4,'multiple_choice','Choose the correct sentence.','["These socks are too tight.", "This socks are too tight.", "That socks is too tight.", "These sock are too tight."]','These socks are too tight.',NULL,NULL,NULL,'''socks'' số nhiều gần → ''These socks are''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
