INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('71e41143-e7e8-4d05-82b9-89cb2d436a4b','28f5f271-9117-45c5-9440-f4e0350b8bd2',8,'fill_blank','Do you have ___ (far) trousers in another colour?',NULL,'those','["those"]','["those", "these"]',NULL,'Vật số nhiều xa → ''those''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('e8e8abe6-7180-4fe7-8139-a1c1c7e69514','28f5f271-9117-45c5-9440-f4e0350b8bd2',9,'ordering','Put the words in the correct order.',NULL,'This shirt is too small',NULL,NULL,NULL,'Trật tự: This + danh từ (shirt) + is + too + tính từ (small).',NULL,NULL,'["This", "shirt", "small", "too", "is"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('abd466dd-ca49-4784-80e5-7b2771230fdc','28f5f271-9117-45c5-9440-f4e0350b8bd2',10,'ordering','Put the words in the correct order.',NULL,'Those shoes are very nice',NULL,NULL,NULL,'Trật tự: Those + danh từ (shoes) + are + trạng từ (very) + tính từ (nice).',NULL,NULL,'["Those", "nice", "shoes", "are", "very"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('ea3a6c32-4905-4576-a65c-c9051f6ded45','28f5f271-9117-45c5-9440-f4e0350b8bd2',11,'ordering','Put the words in the correct order.',NULL,'These trousers fit me',NULL,NULL,NULL,'Trật tự: These + danh từ (trousers) + động từ (fit) + tân ngữ (me).',NULL,NULL,'["These", "fit", "trousers", "me"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('28c48f85-a4ee-4839-88d8-97fce87c3aae','a1-s6-08-read-aloud-fitting-room','In the Fitting Room',1,'reading','A1 Movers',NULL,'Today, I am shopping for new clothes with my mom. I see a red jacket, and I want to try it on. "What size is it?" my mom asks. I look at the tag and say, "It''s a medium." I go into the fitting room and put it on. Oh no, this jacket is too small! I can''t move my arms. I ask the shop assistant, "Do you have a bigger size?" She brings me another jacket. This one fits me perfectly! Then I see some blue trousers. They look nice, but they are too tight. "Can I change it for a bigger size?" I ask. The shop assistant says, "Of course! Do you want another colour too?" I try on the new trousers, and they suit me very well. "I''ll take it!" I say happily. Shopping for clothes is fun when everything fits!','[{"text":"Today, I am shopping for new clothes with my mom.","ipa":"/təˈdeɪ, aɪ æm ˈʃɑpɪŋ fɔr nu kloʊðz wɪð maɪ mɑm./","vi":"Hôm nay, mình đi mua quần áo mới cùng với mẹ."},{"text":"I see a red jacket, and I want to try it on.","ipa":"/aɪ si ə rɛd ˈdʒækɪt, ænd aɪ wɑnt tu traɪ ɪt ɑn./","vi":"Mình thấy một chiếc áo khoác màu đỏ và muốn mặc thử."},{"text":"\"What size is it?\" my mom asks.","ipa":"/wʌt saɪz ɪz ɪt? maɪ mɑm æsks./","vi":"\"Cái này cỡ bao nhiêu?\" mẹ mình hỏi."},{"text":"I look at the tag and say, \"It''s a medium.\"","ipa":"/aɪ lʊk æt ðə tæg ænd seɪ, ɪts ə ˈmidiəm./","vi":"Mình nhìn vào nhãn mác và nói: \"Nó là cỡ trung bình ạ.\""},{"text":"I go into the fitting room and put it on.","ipa":"/aɪ goʊ ˈɪntu ðə ˈfɪtɪŋ rum ænd pʊt ɪt ɑn./","vi":"Mình đi vào phòng thử đồ và mặc nó vào."},{"text":"Oh no, this jacket is too small!","ipa":"/oʊ noʊ, ðɪs ˈdʒækɪt ɪz tu smɔl!/","vi":"Ôi không, chiếc áo khoác này nhỏ quá!"},{"text":"I can''t move my arms.","ipa":"/aɪ kænt muv maɪ ɑrmz./","vi":"Mình không thể cử động tay được."},{"text":"I ask the shop assistant, \"Do you have a bigger size?\"","ipa":"/aɪ æsk ðə ʃɑp əˈsɪstənt, du ju hæv ə ˈbɪgər saɪz?/","vi":"Mình hỏi nhân viên cửa hàng: \"Cô có cỡ lớn hơn không ạ?\""},{"text":"She brings me another jacket.","ipa":"/ʃi brɪŋz mi əˈnʌðər ˈdʒækɪt./","vi":"Cô ấy mang cho mình một chiếc áo khoác khác."},{"text":"This one fits me perfectly!","ipa":"/ðɪs wʌn fɪts mi ˈpɜrfɪktli!/","vi":"Chiếc này vừa với mình lắm!"},{"text":"Then I see some blue trousers.","ipa":"/ðɛn aɪ si sʌm blu ˈtraʊzərz./","vi":"Sau đó mình thấy vài chiếc quần dài màu xanh."},{"text":"They look nice, but they are too tight.","ipa":"/ðeɪ lʊk naɪs, bʌt ðeɪ ɑr tu taɪt./","vi":"Chúng trông rất đẹp nhưng lại quá chật."},{"text":"\"Can I change it for a bigger size?\" I ask.","ipa":"/kæn aɪ tʃeɪndʒ ɪt fɔr ə ˈbɪgər saɪz? aɪ æsk./","vi":"\"Cháu có thể đổi lấy cỡ lớn hơn được không ạ?\" mình hỏi."},{"text":"The shop assistant says, \"Of course! Do you want another colour too?\"","ipa":"/ðə ʃɑp əˈsɪstənt sɛz, əv kɔrs! du ju wɑnt əˈnʌðər ˈkʌlər tu?/","vi":"Nhân viên cửa hàng nói: \"Tất nhiên rồi! Cháu có muốn đổi màu khác không?\""},{"text":"I try on the new trousers, and they suit me very well.","ipa":"/aɪ traɪ ɑn ðə nu ˈtraʊzərz, ænd ðeɪ sut mi ˈvɛri wɛl./","vi":"Mình mặc thử chiếc quần mới và nó rất hợp với mình."},{"text":"\"I''ll take it!\" I say happily.","ipa":"/aɪl teɪk ɪt! aɪ seɪ ˈhæpɪli./","vi":"\"Cháu lấy cái này ạ!\" mình vui vẻ nói."},{"text":"Shopping for clothes is fun when everything fits!","ipa":"/ˈʃɑpɪŋ fɔr kloʊðz ɪz fʌn wɛn ˈɛvriθɪŋ fɪts!/","vi":"Đi mua sắm quần áo thật vui khi mọi thứ đều vừa vặn!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,1080,'a1-s6','6dfee43db46b487c9b83b8612c48de61',NULL,NULL,'2026-07-25T12:45:19.398Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('599a1b0f-c21c-434e-b048-a7be6936e0f0','a1-s6-09-listen-choose-shop','At the Clothes Shop',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Olivia (F): Excuse me, can I try on this jacket?
Daniel (M): Of course! The fitting room is over there.
Olivia (F): Thank you. Hmm, this size is too small for me.
Daniel (M): No problem. What size do you need?
Olivia (F): I think I need a large, please.
Daniel (M): Here you are. Try this one on.
Olivia (F) [happy]: This fits much better! I really like it.
Daniel (M) [happy]: Great! Do you want another colour, maybe blue?
Olivia (F) [happy]: No, I love this colour. I''ll take it!
Daniel (M): Perfect. Do you need anything else today?
Olivia (F): Yes, these trousers are too tight. Can I change it for a bigger size?
Daniel (M): Sure, one moment please. Here''s a bigger pair.
Olivia (F) [happy]: These suit me much better. Thank you for your help!
Daniel (M): You''re welcome. Enjoy your new clothes!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,1090,'a1-s6','6dfee43db46b487c9b83b8612c48de61',NULL,NULL,'2026-07-25T12:45:19.398Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('5d776ded-a30f-4d1b-8491-b2ca2eecc256','599a1b0f-c21c-434e-b048-a7be6936e0f0',0,'multiple_choice','What does Olivia want to try on first?','["A jacket", "A dress", "Trousers", "Shoes"]','A jacket',NULL,NULL,NULL,'Olivia hỏi thử chiếc áo khoác.','Olivia (F): Excuse me, can I try on this jacket?',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('16b4e009-2b03-45ef-885f-4e9d428377fd','599a1b0f-c21c-434e-b048-a7be6936e0f0',1,'multiple_choice','What is wrong with the first jacket?','["It''s too small", "It''s too big", "It''s too long", "It''s the wrong colour"]','It''s too small',NULL,NULL,NULL,'Olivia nói ''this size is too small''.','Olivia (F): Hmm, this size is too small for me.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('79ff7408-ba25-499a-bfd2-e7c06b4e6b5b','599a1b0f-c21c-434e-b048-a7be6936e0f0',2,'multiple_choice','What size does Olivia need?','["Large", "Small", "Medium", "Extra small"]','Large',NULL,NULL,NULL,'Olivia nói ''I need a large''.','Olivia (F): I think I need a large, please.',NULL,NULL,NULL,NULL,NULL,NULL);
