INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('5813bc04-1dc0-41f4-8818-bfe4ccbd1bdf','599a1b0f-c21c-434e-b048-a7be6936e0f0',4,'fill_blank','The fitting room is ___ there.',NULL,'over','["over"]','["over", "under"]',NULL,'Daniel nói ''over there''.','Daniel (M): Of course! The fitting room is over there.',NULL,NULL,NULL,NULL,NULL,NULL);
