INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('b33d6f66-334e-473c-b86e-f63ef9b0b2a8','a1-s6-13-read-aloud-wild-forest','A Walk in the Wild Forest',1,'reading','A1 Movers',NULL,'Today, my family and I are walking in a beautiful forest. There is a big mountain behind us, and there is a small lake in front of us. My dad says, "Look, there are wild animals here! We must be careful." I see a fox near a tree. Foxes are wild animals, but they are not very dangerous to people. "Some animals in the forest can be dangerous," my mom explains. "That''s why rangers look after and protect this forest." We walk to the lake and sit down. There are birds flying over the water. It''s so quiet and beautiful here. Later, we walk to a nearby beach and watch the sunset. My mom says, "We must always protect nature, so it stays beautiful for everyone." I agree — nature is amazing!','[{"text":"Today, my family and I are walking in a beautiful forest.","ipa":"/təˈdeɪ/, /maɪ/ /ˈfæməli/ /ænd/ /aɪ/ /ɑr/ /ˈwɔkɪŋ/ /ɪn/ /ə/ /ˈbyutəfəl/ /ˈfɔrəst/.","vi":"Hôm nay, gia đình tôi đang đi dạo trong một khu rừng tuyệt đẹp."},{"text":"There is a big mountain behind us, and there is a small lake in front of us.","ipa":"/ðɛr/ /ɪz/ /ə/ /bɪg/ /ˈmaʊntən/ /bɪˈhaɪnd/ /ʌs/, /ænd/ /ðɛr/ /ɪz/ /ə/ /smɔl/ /leɪk/ /ɪn/ /frʌnt/ /ʌv/ /ʌs/.","vi":"Có một ngọn núi lớn ở phía sau chúng tôi, và một cái hồ nhỏ ở phía trước."},{"text":"My dad says, \"Look, there are wild animals here!\"","ipa":"/maɪ/ /dæd/ /sɛz/, /lʊk/, /ðɛr/ /ɑr/ /waɪld/ /ˈænəməlz/ /hir/!","vi":"Bố tôi nói: \"Nhìn kìa, có những loài động vật hoang dã ở đây!\""},{"text":"We must be careful.","ipa":"/wi/ /mʌst/ /bi/ /ˈkɛrfəl/.","vi":"Chúng ta phải cẩn thận."},{"text":"I see a fox near a tree.","ipa":"/aɪ/ /si/ /ə/ /fɑks/ /nɪr/ /ə/ /tri/.","vi":"Tôi thấy một con cáo gần cái cây."},{"text":"Foxes are wild animals, but they are not very dangerous to people.","ipa":"/ˈfɑksəz/ /ɑr/ /waɪld/ /ˈænəməlz/, /bʌt/ /ðeɪ/ /ɑr/ /nɑt/ /ˈvɛri/ /ˈdeɪndʒərəs/ /tu/ /ˈpipəl/.","vi":"Cáo là động vật hoang dã, nhưng chúng không quá nguy hiểm với con người."},{"text":"\"Some animals in the forest can be dangerous,\" my mom explains.","ipa":"/sʌm/ /ˈænəməlz/ /ɪn/ /ðə/ /ˈfɔrəst/ /kæn/ /bi/ /ˈdeɪndʒərəs/, /maɪ/ /mɑm/ /ɪkˈspleɪnz/.","vi":"\"Một số loài động vật trong rừng có thể rất nguy hiểm,\" mẹ tôi giải thích."},{"text":"\"That''s why rangers look after and protect this forest.\"","ipa":"/ðæts/ /waɪ/ /ˈreɪndʒərz/ /lʊk/ /ˈæftər/ /ænd/ /prəˈtɛkt/ /ðɪs/ /ˈfɔrəst/.","vi":"\"Đó là lý do tại sao các kiểm lâm viên chăm sóc và bảo vệ khu rừng này.\""},{"text":"We walk to the lake and sit down.","ipa":"/wi/ /wɔk/ /tu/ /ðə/ /leɪk/ /ænd/ /sɪt/ /daʊn/.","vi":"Chúng tôi đi bộ đến hồ và ngồi xuống."},{"text":"There are birds flying over the water.","ipa":"/ðɛr/ /ɑr/ /bɜrdz/ /ˈflaɪɪŋ/ /ˈoʊvər/ /ðə/ /ˈwɔtər/.","vi":"Có những chú chim đang bay trên mặt nước."},{"text":"It''s so quiet and beautiful here.","ipa":"/ɪts/ /soʊ/ /ˈkwaɪət/ /ænd/ /ˈbyutəfəl/ /hir/.","vi":"Ở đây thật yên tĩnh và xinh đẹp."},{"text":"Later, we walk to a nearby beach and watch the sunset.","ipa":"/ˈleɪtər/, /wi/ /wɔk/ /tu/ /ə/ /ˈnɪrbaɪ/ /bitʃ/ /ænd/ /wɑtʃ/ /ðə/ /ˈsʌnsɛt/.","vi":"Sau đó, chúng tôi đi bộ đến một bãi biển gần đó và ngắm hoàng hôn."},{"text":"My mom says, \"We must always protect nature, so it stays beautiful for everyone.\"","ipa":"/maɪ/ /mɑm/ /sɛz/, /wi/ /mʌst/ /ˈɔlˌweɪz/ /prəˈtɛkt/ /ˈneɪtʃər/, /soʊ/ /ɪt/ /steɪz/ /ˈbyutəfəl/ /fɔr/ /ˈɛvriˌwʌn/.","vi":"Mẹ tôi nói: \"Chúng ta phải luôn bảo vệ thiên nhiên để nó mãi tươi đẹp cho mọi người.\""},{"text":"I agree — nature is amazing!","ipa":"/aɪ/ /əˈgri/ — /ˈneɪtʃər/ /ɪz/ /əˈmeɪzɪŋ/!","vi":"Tôi đồng ý — thiên nhiên thật tuyệt vời!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,1130,'a1-s6','f868e593c1d444a5962055104fc558b7',NULL,NULL,'2026-07-25T12:45:19.398Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('cd05f862-ffcd-4fcc-a512-71aa5190ba0f','a1-s6-14-listen-choose-nature-trip','A Trip to the National Park',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Sophie (F) [excited]: Wow, look at this forest! It''s so beautiful.
Noah (M) [excited]: Yes! There is a big mountain over there too.
Sophie (F): Are there any wild animals here?
Noah (M): Yes, there are deer and foxes in this forest.
Sophie (F) [worried]: Are they dangerous?
Noah (M) [calm]: No, they aren''t. But some snakes near the lake can be dangerous.
Sophie (F) [worried]: Oh, we should be careful near the lake then.
Noah (M): Yes. Look, there''s a ranger. She helps look after the animals.
Sophie (F) [happy]: That''s a great job. She must protect the forest every day.
Noah (M): Exactly. There are also many birds living in the trees.
Sophie (F) [happy]: I love birds! Can we walk to the beach after this?
Noah (M): Sure! There''s a beautiful beach near the park entrance.
Sophie (F) [excited]: Perfect! I want to see more wild animals and nature today.
Noah (M) [excited]: Me too. Let''s go and explore!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,1140,'a1-s6','f868e593c1d444a5962055104fc558b7',NULL,NULL,'2026-07-25T12:45:19.398Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('f62fb1e6-250b-4b4e-8feb-295f5cf61923','cd05f862-ffcd-4fcc-a512-71aa5190ba0f',0,'multiple_choice','What is behind the forest?','["A mountain", "A lake", "A beach", "A city"]','A mountain',NULL,NULL,NULL,'Noah nói ''a big mountain over there''.','Noah (M): Yes! There is a big mountain over there too.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('be3dd002-016b-4bb9-88c6-ab7477f28513','cd05f862-ffcd-4fcc-a512-71aa5190ba0f',1,'multiple_choice','Which wild animals live in the forest?','["Deer and foxes", "Lions and tigers", "Sheep and cows", "Bears and wolves"]','Deer and foxes',NULL,NULL,NULL,'Noah nói ''deer and foxes''.','Noah (M): Yes, there are deer and foxes in this forest.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('7ce5c1db-4e04-4e20-a3f1-5a0ee3f3af7c','cd05f862-ffcd-4fcc-a512-71aa5190ba0f',2,'multiple_choice','What can be dangerous near the lake?','["Snakes", "Foxes", "Birds", "Deer"]','Snakes',NULL,NULL,NULL,'Noah nói ''some snakes near the lake can be dangerous''.','Noah (M): But some snakes near the lake can be dangerous.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('012b031d-20e4-4e29-a7b2-d98e98a16f30','cd05f862-ffcd-4fcc-a512-71aa5190ba0f',3,'multiple_choice','Who helps look after the animals?','["A ranger", "A teacher", "A doctor", "A driver"]','A ranger',NULL,NULL,NULL,'Noah nói ''a ranger... helps look after the animals''.','Noah (M): Look, there''s a ranger. She helps look after the animals.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('0624d21c-5b04-496a-b4a4-88c71ea2721f','cd05f862-ffcd-4fcc-a512-71aa5190ba0f',4,'fill_blank','Sophie wants to walk to the ___ after the forest.',NULL,'beach','["beach"]','["beach", "lake"]',NULL,'Sophie nói ''walk to the beach''.','Sophie (F): I love birds! Can we walk to the beach after this?',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('98d09617-b05d-41aa-bdee-40b57e9847ee','cd05f862-ffcd-4fcc-a512-71aa5190ba0f',5,'fill_blank','The ranger must ___ the forest every day.',NULL,'protect','["protect"]','["protect", "clean"]',NULL,'Sophie nói ''She must protect the forest''.','Sophie (F): She must protect the forest every day.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('5cc90ebe-531e-4f34-b414-d1202e2e70e5','cd05f862-ffcd-4fcc-a512-71aa5190ba0f',6,'fill_blank','There are also many ___ living in the trees.',NULL,'birds','["birds"]','["birds", "foxes"]',NULL,'Noah nói ''many birds living in the trees''.','Noah (M): There are also many birds living in the trees.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('ed81d43e-dd0e-4f93-8e68-5c28910c637e','cd05f862-ffcd-4fcc-a512-71aa5190ba0f',7,'fill_blank','Sophie wants to see more wild animals and ___ today.',NULL,'nature','["nature"]','["nature", "cities"]',NULL,'Sophie nói ''wild animals and nature''.','Sophie (F): I want to see more wild animals and nature today.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('98ffd57e-8bac-45d1-b343-5cc8220b26f7','cd05f862-ffcd-4fcc-a512-71aa5190ba0f',8,'matching','Match each place to what is there.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng nơi chốn với động vật/đặc điểm.','deer and foxes in this forest... snakes near the lake... birds living in the trees.','[{"left": "Forest", "right": "Deer and foxes"}, {"left": "Lake", "right": "Dangerous snakes"}, {"left": "Trees", "right": "Many birds"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('9db2c777-3a5e-4984-a40b-14885d0a2ce4','cd05f862-ffcd-4fcc-a512-71aa5190ba0f',9,'matching','Match each person to what they say.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng câu nói với người nói.','Sophie: I love birds! Noah: Let''s go and explore!','[{"left": "Sophie", "right": "I love birds!"}, {"left": "Noah", "right": "Let''s go and explore!"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('282a26ef-557c-4ca2-ad6d-0f826f0d49e0','a1-s6-15-reading-rainy-day','A Rainy Day at the Lake',1,'reading','A1 Movers',NULL,'Last weekend, the forecast said it would be dry and sunny, so my family planned a trip to the lake near the mountain. But on Saturday morning, dark clouds filled the sky. "It''s raining!" my brother shouted. We were sad because we couldn''t go swimming. "Let''s still go," my dad said. "We can wear raincoats and boots." At the lake, everything was wet, but it was still beautiful. There were ducks swimming near the shore, and the mountain looked amazing through the rain. "Look, there are wild birds over there!" my mom said. We put on our raincoats and walked around the lake. It was about fifteen degrees, so we felt a little cold, but we were happy together. By the afternoon, the rain stopped, and the sun came out. "See, the weather always changes," my dad laughed. We had a wonderful day, even though it started wet and cold!','[{"text":"Last weekend, the forecast said it would be dry and sunny, so my family planned a trip to the lake near the mountain.","ipa":"/læst ˈwikˌɛnd, ðə ˈfɔrˌkæst sɛd ɪt wʊd bi draɪ ænd ˈsʌni, soʊ maɪ ˈfæməli plænd ə trɪp tu ðə leɪk nɪr ðə ˈmaʊntən./","vi":"Cuối tuần trước, dự báo thời tiết nói trời sẽ khô ráo và có nắng, nên gia đình tôi đã lên kế hoạch đi chơi ở hồ gần ngọn núi."},{"text":"But on Saturday morning, dark clouds filled the sky.","ipa":"/bʌt ɑn ˈsætərdeɪ ˈmɔrnɪŋ, dɑrk klaʊdz fɪld ðə skaɪ./","vi":"Nhưng vào sáng thứ Bảy, những đám mây đen bao phủ bầu trời."},{"text":"\"It''s raining!\" my brother shouted.","ipa":"/ɪts ˈreɪnɪŋ! maɪ ˈbrʌðər ˈʃaʊtəd./","vi":"\"Trời đang mưa rồi!\" anh trai tôi hét lên."},{"text":"We were sad because we couldn''t go swimming.","ipa":"/wi wɜr sæd bɪˈkəz wi ˈkʊdənt goʊ ˈswɪmɪŋ./","vi":"Chúng tôi rất buồn vì không thể đi bơi được."},{"text":"\"Let''s still go,\" my dad said.","ipa":"/lɛts stɪl goʊ, maɪ dæd sɛd./","vi":"\"Chúng ta cứ đi thôi,\" bố tôi nói."},{"text":"\"We can wear raincoats and boots.\"","ipa":"/wi kæn wɛr ˈreɪnˌkoʊts ænd buts./","vi":"\"Chúng ta có thể mặc áo mưa và đi ủng.\""},{"text":"At the lake, everything was wet, but it was still beautiful.","ipa":"/æt ðə leɪk, ˈɛvriˌθɪŋ wʌz wɛt, bʌt ɪt wʌz stɪl ˈbjutəfəl./","vi":"Tại hồ, mọi thứ đều ướt át, nhưng cảnh vật vẫn rất đẹp."},{"text":"There were ducks swimming near the shore, and the mountain looked amazing through the rain.","ipa":"/ðɛr wɜr dʌks ˈswɪmɪŋ nɪr ðə ʃɔr, ænd ðə ˈmaʊntən lʊkt əˈmeɪzɪŋ θru ðə reɪn./","vi":"Có những chú vịt đang bơi gần bờ, và ngọn núi trông thật tuyệt vời trong làn mưa."},{"text":"\"Look, there are wild birds over there!\" my mom said.","ipa":"/lʊk, ðɛr ɑr waɪld bɜrdz ˈoʊvər ðɛr! maɪ mɑm sɛd./","vi":"\"Nhìn kìa, có những chú chim hoang dã ở đằng kia!\" mẹ tôi nói."},{"text":"We put on our raincoats and walked around the lake.","ipa":"/wi pʊt ɑn ˈaʊər ˈreɪnˌkoʊts ænd wɔkt əˈraʊnd ðə leɪk./","vi":"Chúng tôi mặc áo mưa vào và đi dạo quanh hồ."},{"text":"It was about fifteen degrees, so we felt a little cold, but we were happy together.","ipa":"/ɪt wʌz əˈbaʊt ˈfɪfˈtin dɪˈgriz, soʊ wi fɛlt ə ˈlɪtəl koʊld, bʌt wi wɜr ˈhæpi təˈgɛðər./","vi":"Trời khoảng mười lăm độ, nên chúng tôi thấy hơi lạnh, nhưng chúng tôi rất vui khi ở bên nhau."},{"text":"By the afternoon, the rain stopped, and the sun came out.","ipa":"/baɪ ðə ˈæftərˌnun, ðə reɪn stɑpt, ænd ðə sʌn keɪm aʊt./","vi":"Đến chiều, mưa tạnh và mặt trời ló dạng."},{"text":"\"See, the weather always changes,\" my dad laughed.","ipa":"/si, ðə ˈwɛðər ˈɔlˌweɪz ˈtʃeɪnˌdʒəz, maɪ dæd læft./","vi":"\"Thấy chưa, thời tiết luôn thay đổi mà,\" bố tôi cười nói."},{"text":"We had a wonderful day, even though it started wet and cold!","ipa":"/wi hæd ə ˈwʌndərfəl deɪ, ˈivən ðoʊ ɪt ˈstɑrtəd wɛt ænd koʊld!/","vi":"Chúng tôi đã có một ngày tuyệt vời, mặc dù lúc đầu trời mưa và lạnh!"}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'reading_comprehension',NULL,1150,'a1-s6','bd42b01c44924e82a78131b1bf5b7c75',NULL,NULL,'2026-07-25T12:45:19.398Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('21fbf334-7b03-4095-a7b1-29cc54aaecfe','282a26ef-557c-4ca2-ad6d-0f826f0d49e0',0,'multiple_choice','What did the forecast say for Saturday?','["Dry and sunny", "Wet and cold", "Windy and stormy", "Snowy"]','Dry and sunny',NULL,NULL,NULL,'Đoạn ghi ''the forecast said it would be dry and sunny''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('fe931e4b-58d0-40e2-ad5d-02569f31921c','282a26ef-557c-4ca2-ad6d-0f826f0d49e0',1,'multiple_choice','Why was the family sad at first?','["They couldn''t go swimming", "They lost their car keys", "The lake was closed", "It was too hot"]','They couldn''t go swimming',NULL,NULL,NULL,'Đoạn ghi họ buồn vì trời mưa nên không đi bơi được.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('0d61e83c-d4b2-40d5-87e3-05ae5f5658cc','282a26ef-557c-4ca2-ad6d-0f826f0d49e0',2,'multiple_choice','What did they wear at the lake?','["Raincoats and boots", "Swimsuits", "Warm coats and hats", "T-shirts and shorts"]','Raincoats and boots',NULL,NULL,NULL,'Đoạn ghi ''we can wear raincoats and boots''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('577d5ace-a370-4f3f-a86b-b136a1fe3f01','282a26ef-557c-4ca2-ad6d-0f826f0d49e0',3,'multiple_choice','What did they see near the shore?','["Ducks", "Foxes", "Sheep", "Fish"]','Ducks',NULL,NULL,NULL,'Đoạn ghi ''ducks swimming near the shore''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('8a5fa802-1bca-4fa4-b84e-a0ba76a51bd6','282a26ef-557c-4ca2-ad6d-0f826f0d49e0',4,'multiple_choice','What was the temperature at the lake?','["About fifteen degrees", "About thirty degrees", "About five degrees", "About twenty degrees"]','About fifteen degrees',NULL,NULL,NULL,'Đoạn ghi ''It was about fifteen degrees''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('d009f623-8756-49c5-a07e-b526584cd541','282a26ef-557c-4ca2-ad6d-0f826f0d49e0',5,'multiple_choice','What happened in the afternoon?','["The rain stopped and the sun came out", "It started snowing", "They went home early", "The wind got stronger"]','The rain stopped and the sun came out',NULL,NULL,NULL,'Đoạn ghi ''the rain stopped, and the sun came out''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('086c07a1-adbf-4aca-a835-b38eb831f346','282a26ef-557c-4ca2-ad6d-0f826f0d49e0',6,'fill_blank','"It''s ___!" my brother shouted.',NULL,'raining','["raining"]','["raining", "snowing"]',NULL,'Đoạn ghi ''It''s raining!''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('06be5720-5416-4b63-bd9b-0355f3aab812','282a26ef-557c-4ca2-ad6d-0f826f0d49e0',7,'fill_blank','There were wild ___ over there, near the lake.',NULL,'birds','["birds"]','["birds", "foxes"]',NULL,'Đoạn ghi ''there are wild birds over there''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('98c87d2d-d041-4d81-a77c-935da758e7f2','282a26ef-557c-4ca2-ad6d-0f826f0d49e0',8,'fill_blank','"The weather always ___," my dad laughed.',NULL,'changes','["changes"]','["changes", "stays"]',NULL,'Đoạn ghi ''the weather always changes''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('bc3a85db-51d7-49da-b558-16ce812ef7b5','282a26ef-557c-4ca2-ad6d-0f826f0d49e0',9,'matching','Match each person to what they said.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng câu nói với người nói trong bài.',NULL,'[{"left": "Brother", "right": "It''s raining!"}, {"left": "Dad", "right": "Let''s still go."}, {"left": "Mom", "right": "There are wild birds over there!"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('6b6d647c-1343-44af-83c0-e73fc0c36f4a','282a26ef-557c-4ca2-ad6d-0f826f0d49e0',10,'categorize','Sort each detail by when it happened.',NULL,NULL,NULL,NULL,NULL,'Phân loại chi tiết theo buổi sáng và buổi chiều trong bài.',NULL,NULL,NULL,'["Morning", "Afternoon"]','[{"text": "Dark clouds filled the sky", "category": "Morning"}, {"text": "It was raining", "category": "Morning"}, {"text": "The rain stopped", "category": "Afternoon"}, {"text": "The sun came out", "category": "Afternoon"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('2ac57d2b-5a57-4f10-8c78-4d0da808ac5a','a1-s6-16-mixed-weekend-trip','A Weekend Trip',1,'mixed','A1 Movers',NULL,'This weekend, we are going on a trip to the mountains. The forecast says it will be cold, so I am wearing a warm coat and boots. My sister is wearing a scarf because it''s windy at the moment. We are driving to a small village near a beautiful lake. "There are wild animals in this area," our guide says. "You must look after your things and protect nature here." When we arrive, we see a fox near the forest. "Is it dangerous?" my sister asks. "No, it isn''t," the guide answers. "But please don''t get too close." Later, the weather changes — the sun comes out, and it feels much warmer. We take off our coats and walk to the lake. There are birds flying over the water, and the view is amazing. In the shop nearby, my sister tries on a new hat. "This one is too small," she says. "Can I try on another colour?" The shop assistant brings a bigger, blue hat. "This fits you perfectly!" I say. It was a wonderful weekend trip — we saw wild animals, beautiful nature, and even went shopping!','[{"text":"This weekend, we are going on a trip to the mountains.","ipa":"/ðɪs ˈwiːkˌɛnd, wi ɑr ˈɡoʊɪŋ ɑn ə trɪp tu ðə ˈmaʊntənz./","vi":"Cuối tuần này, chúng tôi sẽ đi du lịch đến vùng núi."},{"text":"The forecast says it will be cold, so I am wearing a warm coat and boots.","ipa":"/ðə ˈfɔrˌkæst sɛz ɪt wɪl bi koʊld, soʊ aɪ æm ˈwɛrɪŋ ə wɔrm koʊt ænd buːts./","vi":"Dự báo thời tiết nói rằng trời sẽ lạnh, nên tôi mặc áo khoác ấm và đi ủng."},{"text":"My sister is wearing a scarf because it''s windy at the moment.","ipa":"/maɪ ˈsɪstər ɪz ˈwɛrɪŋ ə skɑrf bɪˈkəz ɪts ˈwɪndi æt ðə ˈmoʊmənt./","vi":"Chị gái tôi đang quàng khăn vì lúc này trời đang có gió."},{"text":"We are driving to a small village near a beautiful lake.","ipa":"/wi ɑr ˈdraɪvɪŋ tu ə smɔl ˈvɪlɪdʒ nɪr ə ˈbjuːtəfəl leɪk./","vi":"Chúng tôi đang lái xe đến một ngôi làng nhỏ gần một hồ nước tuyệt đẹp."},{"text":"\"There are wild animals in this area,\" our guide says.","ipa":"/ðɛr ɑr waɪld ˈænəməlz ɪn ðɪs ˈɛriə, ˈaʊər ɡaɪd sɛz./","vi":"\"Có nhiều động vật hoang dã trong khu vực này,\" hướng dẫn viên của chúng tôi nói."},{"text":"\"You must look after your things and protect nature here.\"","ipa":"/ju mʌst lʊk ˈæftər jɔr θɪŋz ænd prəˈtɛkt ˈneɪtʃər hɪr./","vi":"\"Các bạn phải giữ gìn đồ đạc và bảo vệ thiên nhiên ở đây.\""},{"text":"When we arrive, we see a fox near the forest.","ipa":"/wɛn wi əˈraɪv, wi si ə fɑks nɪr ðə ˈfɔrəst./","vi":"Khi đến nơi, chúng tôi nhìn thấy một con cáo gần khu rừng."},{"text":"\"Is it dangerous?\" my sister asks.","ipa":"/ɪz ɪt ˈdeɪndʒərəs? maɪ ˈsɪstər æsks./","vi":"\"Nó có nguy hiểm không?\" chị tôi hỏi."},{"text":"\"No, it isn''t,\" the guide answers.","ipa":"/noʊ, ɪt ˈɪzənt, ðə ɡaɪd ˈænsərz./","vi":"\"Không, không nguy hiểm đâu,\" người hướng dẫn trả lời."},{"text":"\"But please don''t get too close.\"","ipa":"/bʌt pliz doʊnt ɡɛt tu kloʊs./","vi":"\"Nhưng làm ơn đừng lại quá gần nhé.\""},{"text":"Later, the weather changes — the sun comes out, and it feels much warmer.","ipa":"/ˈleɪtər, ðə ˈwɛðər ˈtʃeɪndʒəz — ðə sʌn kʌmz aʊt, ænd ɪt fiːlz mʌtʃ ˈwɔrmər./","vi":"Sau đó, thời tiết thay đổi — mặt trời ló dạng và trời cảm thấy ấm áp hơn nhiều."},{"text":"We take off our coats and walk to the lake.","ipa":"/wi teɪk ɔf ˈaʊər koʊts ænd wɔk tu ðə leɪk./","vi":"Chúng tôi cởi áo khoác ra và đi bộ đến hồ."},{"text":"There are birds flying over the water, and the view is amazing.","ipa":"/ðɛr ɑr bɜrdz ˈflaɪɪŋ ˈoʊvər ðə ˈwɔtər, ænd ðə vju ɪz əˈmeɪzɪŋ./","vi":"Có những chú chim đang bay trên mặt nước, và khung cảnh thật tuyệt vời."},{"text":"In the shop nearby, my sister tries on a new hat.","ipa":"/ɪn ðə ʃɑp ˈnɪrˌbaɪ, maɪ ˈsɪstər traɪz ɑn ə nu hæt./","vi":"Tại cửa hàng gần đó, chị tôi thử một chiếc mũ mới."},{"text":"\"This one is too small,\" she says.","ipa":"/ðɪs wʌn ɪz tu smɔl, ʃi sɛz./","vi":"\"Cái này nhỏ quá,\" chị ấy nói."},{"text":"\"Can I try on another colour?\"","ipa":"/kæn aɪ traɪ ɑn əˈnʌðər ˈkʌlər?/","vi":"\"Tôi có thể thử màu khác được không?\""},{"text":"The shop assistant brings a bigger, blue hat.","ipa":"/ðə ʃɑp əˈsɪstənt brɪŋz ə ˈbɪɡər, blu hæt./","vi":"Người bán hàng mang ra một chiếc mũ màu xanh lớn hơn."},{"text":"\"This fits you perfectly!\" I say.","ipa":"/ðɪs fɪts ju ˈpɜrfɪktli! aɪ seɪ./","vi":"\"Cái này vừa với bạn hoàn hảo luôn!\" tôi nói."},{"text":"It was a wonderful weekend trip — we saw wild animals, beautiful nature, and even went shopping!","ipa":"/ɪt wʌz ə ˈwʌndərfəl ˈwiːkˌɛnd trɪp — wi sɔ waɪld ˈænəməlz, ˈbjuːtəfəl ˈneɪtʃər, ænd ˈivən wɛnt ˈʃɑpɪŋ!/","vi":"Đó là một chuyến đi cuối tuần tuyệt vời — chúng tôi đã thấy động vật hoang dã, thiên nhiên tươi đẹp và thậm chí còn đi mua sắm nữa!"}]',NULL,'This weekend, we are going on a trip to the mountains. The forecast says it will be cold, so I am wearing a warm coat and boots. My sister is wearing a scarf because it''s windy at the moment. We are driving to a small village near a beautiful lake. "There are wild animals in this area," our guide says. "You must look after your things and protect nature here." When we arrive, we see a fox near the forest. "Is it dangerous?" my sister asks. "No, it isn''t," the guide answers. "But please don''t get too close." Later, the weather changes — the sun comes out, and it feels much warmer. We take off our coats and walk to the lake. There are birds flying over the water, and the view is amazing. In the shop nearby, my sister tries on a new hat. "This one is too small," she says. "Can I try on another colour?" The shop assistant brings a bigger, blue hat. "This fits you perfectly!" I say. It was a wonderful weekend trip — we saw wild animals, beautiful nature, and even went shopping!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mixed_all',NULL,1160,'a1-s6','35424d3e4a804ab590f575fdab989ccd',NULL,NULL,'2026-07-25T12:45:19.398Z',NULL);
