INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('5d562cac-1209-4232-9ca6-1104f86ee20c','2ac57d2b-5a57-4f10-8c78-4d0da808ac5a',10,'fill_blank','My sister asks, "Can I try on ___ colour?"',NULL,'another','["another"]','["another", "this"]',NULL,'Đoạn ghi ''Can I try on another colour?''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('30d76887-45ad-4c7a-9af8-242354c9a3b2','2ac57d2b-5a57-4f10-8c78-4d0da808ac5a',11,'matching','Match each person to what they wear or say.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng người với trang phục/lời nói trong bài.',NULL,'[{"left": "I", "right": "Wear a warm coat and boots"}, {"left": "Sister", "right": "Wear a scarf"}, {"left": "Guide", "right": "Warns about wild animals"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('eb0d1c20-69be-486b-9b96-78b8ccbcca8c','2ac57d2b-5a57-4f10-8c78-4d0da808ac5a',12,'matching','Match each place to what happens there.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng địa điểm với sự việc xảy ra.',NULL,'[{"left": "Near the forest", "right": "They see a fox"}, {"left": "At the lake", "right": "They see birds flying"}, {"left": "In the shop", "right": "Sister tries on a hat"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('49be0d6d-2a03-49e1-ae53-e8013c3d0bc9','2ac57d2b-5a57-4f10-8c78-4d0da808ac5a',13,'ordering','Put the words in the correct order.',NULL,'There are wild animals in this area',NULL,NULL,NULL,'Trật tự: There + are + tính từ (wild) + danh từ (animals) + in this area.',NULL,NULL,'["are", "wild", "There", "in", "animals", "area", "this"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('65dad523-0a05-4c6c-b082-2832a29da19e','2ac57d2b-5a57-4f10-8c78-4d0da808ac5a',14,'ordering','Put the words in the correct order.',NULL,'This hat is too small',NULL,NULL,NULL,'Trật tự: This + danh từ (hat) + is + too + tính từ (small).',NULL,NULL,'["This", "small", "too", "hat", "is"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('ef8d60b6-ca4e-43db-99e0-b70424ced607','2ac57d2b-5a57-4f10-8c78-4d0da808ac5a',15,'ordering','Put the words in the correct order.',NULL,'It is windy at the moment',NULL,NULL,NULL,'Trật tự: It + is + tính từ (windy) + at the moment.',NULL,NULL,'["is", "windy", "It", "moment", "the", "at"]',NULL,NULL,NULL,NULL);
