INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('744db3f6-06ff-4777-a4eb-b32fdbe2d671','d00fbf26-d6e8-4653-a188-e0ea2a2065e5',19,'categorize','Sort each sentence by the grammar point it uses.',NULL,NULL,NULL,NULL,NULL,'Phân loại đúng theo nội dung: Present Continuous: It is raining right now., We are wearing warm coats.; This/That/These/Those: This shirt is too small., Those shoes are too tight..',NULL,NULL,NULL,'["Present Continuous", "This/That/These/Those"]','[{"text": "It is raining right now.", "category": "Present Continuous"}, {"text": "This shirt is too small.", "category": "This/That/These/Those"}, {"text": "We are wearing warm coats.", "category": "Present Continuous"}, {"text": "Those shoes are too tight.", "category": "This/That/These/Those"}]',NULL,'present-continuous');
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('f8d6669f-412a-402f-84ac-775bdf43fca3','d00fbf26-d6e8-4653-a188-e0ea2a2065e5',20,'categorize','Sort each sentence by the grammar point it uses.',NULL,NULL,NULL,NULL,NULL,'Phân loại đúng theo nội dung: There is / There are: There is a lake near the forest., There are wild animals here.; Present Continuous: The wind is blowing hard., It is snowing in winter..',NULL,NULL,NULL,'["There is / There are", "Present Continuous"]','[{"text": "There is a lake near the forest.", "category": "There is / There are"}, {"text": "The wind is blowing hard.", "category": "Present Continuous"}, {"text": "There are wild animals here.", "category": "There is / There are"}, {"text": "It is snowing in winter.", "category": "Present Continuous"}]',NULL,'there-is-are');
