INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('898e4587-1569-4815-8c35-33f3b02c2abf','3b989d7d-738e-4d0e-a3ea-32df0de0e6d0',18,'categorize','Sort each time word by the tense it signals.',NULL,NULL,NULL,NULL,NULL,'Từ/động từ chỉ việc đang xảy ra dùng tiếp diễn; từ/động từ chỉ thói quen dùng hiện tại đơn.',NULL,NULL,NULL,'["Now (Present Continuous)", "Usually (Present Simple)"]','[{"text": "at the moment", "category": "Now (Present Continuous)"}, {"text": "normally", "category": "Usually (Present Simple)"}, {"text": "right now", "category": "Now (Present Continuous)"}, {"text": "every day", "category": "Usually (Present Simple)"}, {"text": "still", "category": "Now (Present Continuous)"}, {"text": "usually", "category": "Usually (Present Simple)"}]',NULL,'present-continuous');
