INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('751ed334-c756-49bd-8a12-cf8efe01a03e','a1-s7-03-read-aloud-daily-routine','My Daily Routine (Now & Usually)',1,'reading','A1 Movers',NULL,'Every day, I have a busy routine. I normally wake up at seven o''clock and eat breakfast with my family. Right now, at the moment, I am getting ready for school. These days, I am busy with my homework every evening. This week, I am working on a big school project. I am still trying to finish it before Friday. Today, I already did my English homework. I am also practicing my speaking every night.','[{"text":"Every day, I have a busy routine.","ipa":"/ˈɛvri deɪ, aɪ hæv ə ˈbɪzi ruˈtin./","vi":"Mỗi ngày, tôi đều có một lịch trình bận rộn."},{"text":"I normally wake up at seven o''clock and eat breakfast with my family.","ipa":"/aɪ ˈnɔrməli weɪk ʌp æt ˈsɛvən əˈklɑk ænd it ˈbrɛkfəst wɪð maɪ ˈfæməli./","vi":"Tôi thường thức dậy lúc bảy giờ và ăn sáng cùng gia đình."},{"text":"Right now, at the moment, I am getting ready for school.","ipa":"/raɪt naʊ, æt ðə ˈmoʊmənt, aɪ æm ˈɡɛtɪŋ ˈrɛdi fɔr skul./","vi":"Ngay lúc này, tôi đang chuẩn bị để đến trường."},{"text":"These days, I am busy with my homework every evening.","ipa":"/ðiz deɪz, aɪ æm ˈbɪzi wɪð maɪ ˈhoʊmwɜrk ˈɛvri ˈivnɪŋ./","vi":"Dạo này, tối nào tôi cũng bận rộn với bài tập về nhà."},{"text":"This week, I am working on a big school project.","ipa":"/ðɪs wik, aɪ æm ˈwɜrkɪŋ ɑn ə bɪɡ skul ˈprɑdʒɛkt./","vi":"Tuần này, tôi đang thực hiện một dự án lớn ở trường."},{"text":"I am still trying to finish it before Friday.","ipa":"/aɪ æm stɪl ˈtraɪɪŋ tu ˈfɪnɪʃ ɪt bɪˈfɔr ˈfraɪdeɪ./","vi":"Tôi vẫn đang cố gắng hoàn thành nó trước thứ Sáu."},{"text":"Today, I already did my English homework.","ipa":"/təˈdeɪ, aɪ ɔlˈrɛdi dɪd maɪ ˈɪŋɡlɪʃ ˈhoʊmwɜrk./","vi":"Hôm nay, tôi đã làm xong bài tập tiếng Anh rồi."},{"text":"I am also practicing my speaking every night.","ipa":"/aɪ æm ˈɔlsoʊ ˈpræktɪsɪŋ maɪ ˈspikɪŋ ˈɛvri naɪt./","vi":"Tôi cũng đang luyện nói mỗi tối."}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,1230,'a1-s7','98253879c87a47b0b55fbf5205991da4',NULL,NULL,'2026-07-25T12:47:43.761Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('41a45033-01fe-408b-b1fc-49077f8ffe01','a1-s7-04-listen-choose','What Are You Doing?',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Ethan (M): Hi Sophie! What are you doing right now?
Sophie (F): Hi Ethan! At the moment, I am doing my homework.
Ethan (M): Oh, I am working on a school project this week.
Sophie (F): Nice! Do you usually do homework in the evening?
Ethan (M): Yes, I normally do my homework at six o''clock. But today, I am still trying to finish my project.
Sophie (F): These days, I am also busy with my English class.
Ethan (M): Do you already know your speaking topic?
Sophie (F): Yes, I already chose ''My Family.''',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,1240,'a1-s7','98253879c87a47b0b55fbf5205991da4',NULL,NULL,'2026-07-25T12:47:43.761Z',NULL);
