INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('ae1064e7-bbb0-43d0-b4bb-a1cdf2a1697c','3bc850d2-c8a1-4a18-8519-8dab9020e6e4',18,'categorize','Sort each sentence: is it a future plan or a habit?',NULL,NULL,NULL,NULL,NULL,'''be going to'' diễn tả dự định tương lai; hiện tại đơn diễn tả thói quen.',NULL,NULL,NULL,'["Plan (be going to)", "Not a plan"]','[{"text": "we are going to travel", "category": "Plan (be going to)"}, {"text": "we travel every year", "category": "Not a plan"}, {"text": "she is going to book a room", "category": "Plan (be going to)"}, {"text": "she books a room every trip", "category": "Not a plan"}]',NULL,'future-going-to');
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('590d5035-fb71-42cb-b325-ed811f5869d0','3bc850d2-c8a1-4a18-8519-8dab9020e6e4',19,'categorize','Sort each sentence: is it a future plan or a habit?',NULL,NULL,NULL,NULL,NULL,'''be going to'' diễn tả dự định tương lai; hiện tại đơn diễn tả thói quen.',NULL,NULL,NULL,'["Plan (be going to)", "Not a plan"]','[{"text": "they are going to pack tonight", "category": "Plan (be going to)"}, {"text": "they pack every morning", "category": "Not a plan"}, {"text": "he is going to visit Rome", "category": "Plan (be going to)"}, {"text": "he visits his aunt every summer", "category": "Not a plan"}]',NULL,'future-going-to');
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('2c348197-f3e8-4d66-80fa-7bb498dc6345','a1-s7-08-read-aloud-holiday-plans','Our Holiday Plan',1,'reading','A1 Movers',NULL,'My family has a big plan for the summer. We are going to visit Spain in July. We are going to book the flight next weekend. My mom is going to pack our bags a few days before. We are going to stay at a small hotel near the beach. Maybe we are going to visit a castle too. We are going to come back home at the end of July.','[{"text":"My family has a big plan for the summer.","ipa":"/maɪ ˈfæməli hæz ə bɪɡ plæn fɔr ðə ˈsʌmər./","vi":"Gia đình tôi có một kế hoạch lớn cho mùa hè này."},{"text":"We are going to visit Spain in July.","ipa":"/wi ɑr ˈɡoʊɪŋ tu ˈvɪzɪt speɪn ɪn dʒuˈlaɪ./","vi":"Chúng tôi sẽ đi thăm Tây Ban Nha vào tháng Bảy."},{"text":"We are going to book the flight next weekend.","ipa":"/wi ɑr ˈɡoʊɪŋ tu bʊk ðə flaɪt nɛkst ˈwikˌɛnd./","vi":"Chúng tôi sẽ đặt vé máy bay vào cuối tuần tới."},{"text":"My mom is going to pack our bags a few days before.","ipa":"/maɪ mɑm ɪz ˈɡoʊɪŋ tu pæk ˈaʊər bæɡz ə fju deɪz bɪˈfɔr./","vi":"Mẹ tôi sẽ chuẩn bị hành lý vài ngày trước khi đi."},{"text":"We are going to stay at a small hotel near the beach.","ipa":"/wi ɑr ˈɡoʊɪŋ tu steɪ æt ə smɔl hoʊˈtɛl nɪr ðə bitʃ./","vi":"Chúng tôi sẽ ở tại một khách sạn nhỏ gần bãi biển."},{"text":"Maybe we are going to visit a castle too.","ipa":"/ˈmeɪbi wi ɑr ˈɡoʊɪŋ tu ˈvɪzɪt ə ˈkæsəl tu./","vi":"Có lẽ chúng tôi cũng sẽ đi thăm một lâu đài."},{"text":"We are going to come back home at the end of July.","ipa":"/wi ɑr ˈɡoʊɪŋ tu kʌm bæk hoʊm æt ði ɛnd ʌv dʒuˈlaɪ./","vi":"Chúng tôi sẽ trở về nhà vào cuối tháng Bảy."}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,1280,'a1-s7','b17e20653b1e4ed59b704fd16d21ac1a',NULL,NULL,'2026-07-25T12:47:43.761Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('3f097a14-f59d-411e-b436-4d982d830304','a1-s7-09-listen-choose','Planning Our Holiday',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Oliver (M): Hi Grace! Are you going to travel this summer?
Grace (F) [excited]: Yes! We are going to visit Portugal in July.
Oliver (M): Nice! Are you going to book the flights soon?
Grace (F): We are going to book them next weekend.
Oliver (M): Where are you going to stay?
Grace (F): We are going to stay at a small hotel near the beach.
Oliver (M): Are you going to visit any cities?
Grace (F): Maybe! We are going to visit Lisbon for two days.
Oliver (M): When are you going to come back?
Grace (F): We are going to come back at the end of July.
Oliver (M) [happy]: That sounds like a great plan!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,1290,'a1-s7','b17e20653b1e4ed59b704fd16d21ac1a',NULL,NULL,'2026-07-25T12:47:43.761Z',NULL);
