INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('2c4c74d9-add1-4bb4-9e7f-9de8d41e4833','40c0ae04-f538-460a-8c9b-936dedfd2288',11,'fill_blank','Is this your bag? Yes, it ___.',NULL,NULL,'["is"]','["is", "does", "am"]',NULL,'Câu trả lời ngắn với ''Is this...?'' dùng ''is''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('3fe7a652-3665-47d5-be42-f703be224eec','40c0ae04-f538-460a-8c9b-936dedfd2288',12,'fill_blank','Do you have your ticket? No, I ___.',NULL,NULL,'["don''t"]','["don''t", "doesn''t", "isn''t"]',NULL,'Câu trả lời ngắn với ''Do you...?'' phủ định dùng ''don''t''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('3cd8a9a2-16a7-4133-ae96-96a05acad60e','40c0ae04-f538-460a-8c9b-936dedfd2288',13,'fill_blank','___ is your luggage — big or small?',NULL,NULL,'["What"]','["What", "Who", "When"]',NULL,'Hỏi đặc điểm dùng ''What''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('b5bcf394-5bfb-4267-a9f8-951ad880f3b9','40c0ae04-f538-460a-8c9b-936dedfd2288',14,'ordering','Put the words in the correct order.',NULL,'What time is the flight',NULL,NULL,NULL,'Trật tự: What time + is + chủ ngữ.',NULL,NULL,'["is", "time", "flight", "What", "the"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('7fd398e8-fd9f-4ab2-a81b-cc4d6e50ee1f','40c0ae04-f538-460a-8c9b-936dedfd2288',15,'ordering','Put the words in the correct order.',NULL,'Could you tell me the gate number',NULL,NULL,NULL,'Câu hỏi lịch sự: Could you tell me + trật tự câu thường.',NULL,NULL,'["number", "tell", "me", "the", "Could", "you", "gate"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('9cf81662-7c69-4263-8e09-657762c290e9','40c0ae04-f538-460a-8c9b-936dedfd2288',16,'ordering','Put the words in the correct order.',NULL,'Did you check in online',NULL,NULL,NULL,'Câu hỏi quá khứ đơn: Did + chủ ngữ + động từ nguyên mẫu.',NULL,NULL,'["online", "check", "in", "Did", "you"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('48fbdbdb-5caf-4abb-931e-10ac589fc23b','40c0ae04-f538-460a-8c9b-936dedfd2288',17,'ordering','Put the words in the correct order.',NULL,'Is this your luggage',NULL,NULL,NULL,'Câu hỏi Yes/No với ''to be'': Is + this + your + luggage.',NULL,NULL,'["luggage", "this", "your", "Is"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('ef78a846-a4ee-4a6d-b033-78b23c5a7fb6','40c0ae04-f538-460a-8c9b-936dedfd2288',18,'categorize','Sort each line: question or short answer?',NULL,NULL,NULL,NULL,NULL,'Câu hỏi có từ để hỏi/trợ động từ đầu câu; câu trả lời ngắn dùng Yes/No + trợ động từ.',NULL,NULL,NULL,'["Question", "Short answer"]','[{"text": "What time is it?", "category": "Question"}, {"text": "Yes, it is.", "category": "Short answer"}, {"text": "Where is the gate?", "category": "Question"}, {"text": "No, I don''t.", "category": "Short answer"}]',NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('fdb440ef-a203-476e-b6e5-56d5fc159ba5','40c0ae04-f538-460a-8c9b-936dedfd2288',19,'categorize','Sort each line: question or short answer?',NULL,NULL,NULL,NULL,NULL,'Câu hỏi có từ để hỏi/trợ động từ đầu câu; câu trả lời ngắn dùng Yes/No + trợ động từ.',NULL,NULL,NULL,'["Question", "Short answer"]','[{"text": "Did you check in?", "category": "Question"}, {"text": "Yes, I did.", "category": "Short answer"}, {"text": "Is this your bag?", "category": "Question"}, {"text": "No, it isn''t.", "category": "Short answer"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('a1b5568a-e57c-4b6c-b3af-3507b60b2cbe','a1-s7-13-read-aloud-at-the-airport','At the Airport',1,'reading','A1 Movers',NULL,'Today, we are at the airport. First, we check in and give our passports. Then we go to the gate. My dad asks, ''What time is the flight?'' The clerk says, ''It''s at ten o''clock.'' We put our luggage on the belt. My sister asks, ''Could you tell me the wifi password?'' The airport worker smiles and tells her. We wait at the gate and read our books before the flight.','[{"text":"Today, we are at the airport.","ipa":"/təˈdeɪ, wi ɑr æt ði ˈɛrˌpɔrt./","vi":"Hôm nay, chúng tôi đang ở sân bay."},{"text":"First, we check in and give our passports.","ipa":"/fɜrst, wi tʃɛk ɪn ænd ɡɪv ˈaʊər ˈpæsˌpɔrts./","vi":"Đầu tiên, chúng tôi làm thủ tục và đưa hộ chiếu."},{"text":"Then we go to the gate.","ipa":"/ðɛn wi ɡoʊ tu ðə ɡeɪt./","vi":"Sau đó chúng tôi đi đến cổng ra máy bay."},{"text":"My dad asks, ''What time is the flight?''","ipa":"/maɪ dæd æsks, ''wʌt taɪm ɪz ðə flaɪt?''/","vi":"Bố tôi hỏi: ''Mấy giờ thì chuyến bay khởi hành?''"},{"text":"The clerk says, ''It''s at ten o''clock.''","ipa":"/ðə klɜrk sɛz, ''ɪts æt tɛn əˈklɑk.''/","vi":"Nhân viên trả lời: ''Đó là lúc mười giờ.''"},{"text":"We put our luggage on the belt.","ipa":"/wi pʊt ˈaʊər ˈlʌɡɪdʒ ɑn ðə bɛlt./","vi":"Chúng tôi đặt hành lý lên băng chuyền."},{"text":"My sister asks, ''Could you tell me the wifi password?''","ipa":"/maɪ ˈsɪstər æsks, ''kʊd ju tɛl mi ðə ˈwaɪˌfaɪ ˈpæsˌwɜrd?''/","vi":"Em gái tôi hỏi: ''Bạn có thể cho mình biết mật khẩu wifi không?''"},{"text":"The airport worker smiles and tells her.","ipa":"/ði ˈɛrˌpɔrt ˈwɜrkər smaɪlz ænd tɛlz hɜr./","vi":"Nhân viên sân bay mỉm cười và nói cho cô bé biết."},{"text":"We wait at the gate and read our books before the flight.","ipa":"/wi weɪt æt ðə ɡeɪt ænd rid ˈaʊər bʊks bɪˈfɔr ðə flaɪt./","vi":"Chúng tôi đợi ở cổng và đọc sách trước khi lên máy bay."}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,1330,'a1-s7','abb88706e6164592b85496f4f480f2ba',NULL,NULL,'2026-07-25T12:47:43.761Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('237b3603-dde8-45c1-9b8d-47659694814b','a1-s7-14-listen-choose','At the Check-in Desk',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Daniel (M): Good morning! Could you tell me your name, please?
Emma (F): Good morning! My name is Emma Wilson.
Daniel (M): Thank you. What time is your flight?
Emma (F): I think it is at eleven o''clock.
Daniel (M): That''s right. Do you have your passport?
Emma (F): Yes, here it is.
Daniel (M): Great. How many bags of luggage do you have?
Emma (F): I have two bags.
Daniel (M): Okay, please put your luggage here. Your gate is number twelve.
Emma (F): Thank you! Could you also tell me the wifi password?
Daniel (M): Sure, it''s ''Airport2026''.
Emma (F) [happy]: Thank you so much!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,1340,'a1-s7','abb88706e6164592b85496f4f480f2ba',NULL,NULL,'2026-07-25T12:47:43.761Z',NULL);
