INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('8ff4ca68-faae-4cce-a718-59e9f363f1e2','237b3603-dde8-45c1-9b8d-47659694814b',6,'multiple_choice','What is the wifi password?','["Airport2026", "Flight2026", "Gate2026", "Wifi2026"]','Airport2026',NULL,NULL,NULL,'Nghe kỹ đoạn hội thoại để chọn đáp án đúng.','Sure, it''s ''Airport2026''.',NULL,NULL,NULL,NULL,NULL,NULL);
