INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('65af6286-b9ce-4c4f-9319-c48292ea2757','a1-s7-15-reading-travel-plans','A Family Travel Story',1,'reading','A1 Movers',NULL,'The Parker family loves to travel. Every summer, they visit a new country. This year, they are going to visit Greece in July. First, they book their flights and a small hotel near the sea. Mr. Parker packs the big suitcases, and Mrs. Parker packs the small bags. Their daughter, Lily, is excited. She says, ''Maybe we can visit an old castle!'' On the day of the trip, they check in at the airport and wait at the gate. The flight is at nine o''clock. After a long flight, they arrive and go to their hotel. They are going to stay there for one week. Every day, they visit a new beach or town. At the end of the week, they pack their bags again and come back home. It is always a wonderful trip!','[{"text":"The Parker family loves to travel.","ipa":"/ðə ˈpɑrkər ˈfæməli lʌvz tu ˈtrævəl./","vi":"Gia đình nhà Parker rất thích đi du lịch."},{"text":"Every summer, they visit a new country.","ipa":"/ˈɛvəri ˈsʌmər, ðeɪ ˈvɪzɪt ə nu ˈkʌntri./","vi":"Mỗi mùa hè, họ lại đến thăm một đất nước mới."},{"text":"This year, they are going to visit Greece in July.","ipa":"/ðɪs jɪr, ðeɪ ɑr ˈgoʊɪŋ tu ˈvɪzɪt gris ɪn dʒuˈlaɪ./","vi":"Năm nay, họ sẽ đi thăm Hy Lạp vào tháng Bảy."},{"text":"First, they book their flights and a small hotel near the sea.","ipa":"/fɜrst, ðeɪ bʊk ðɛr flaɪts ænd ə smɔl hoʊˈtɛl nɪr ðə si./","vi":"Đầu tiên, họ đặt vé máy bay và một khách sạn nhỏ gần biển."},{"text":"Mr. Parker packs the big suitcases, and Mrs. Parker packs the small bags.","ipa":"/ˈmɪstər ˈpɑrkər pæks ðə bɪg ˈsutˌkeɪsəz, ænd ˈmɪsəz ˈpɑrkər pæks ðə smɔl bægz./","vi":"Ông Parker đóng gói những chiếc vali lớn, còn bà Parker đóng gói những chiếc túi nhỏ."},{"text":"Their daughter, Lily, is excited.","ipa":"/ðɛr ˈdɔtər, ˈlɪli, ɪz ɪkˈsaɪtəd./","vi":"Cô con gái của họ, Lily, rất hào hứng."},{"text":"She says, ''Maybe we can visit an old castle!''","ipa":"/ʃi sɛz, ˈmeɪbi wi kæn ˈvɪzɪt ən oʊld ˈkæsəl!/","vi":"Con bé nói: ''Có lẽ chúng ta có thể đi thăm một tòa lâu đài cổ!''"},{"text":"On the day of the trip, they check in at the airport and wait at the gate.","ipa":"/ɑn ðə deɪ ʌv ðə trɪp, ðeɪ tʃɛk ɪn æt ði ˈɛrˌpɔrt ænd weɪt æt ðə geɪt./","vi":"Vào ngày khởi hành, họ làm thủ tục tại sân bay và chờ ở cửa ra máy bay."},{"text":"The flight is at nine o''clock.","ipa":"/ðə flaɪt ɪz æt naɪn əˈklɑk./","vi":"Chuyến bay khởi hành lúc chín giờ."},{"text":"After a long flight, they arrive and go to their hotel.","ipa":"/ˈæftər ə lɔŋ flaɪt, ðeɪ əˈraɪv ænd goʊ tu ðɛr hoʊˈtɛl./","vi":"Sau một chuyến bay dài, họ đến nơi và về khách sạn."},{"text":"They are going to stay there for one week.","ipa":"/ðeɪ ɑr ˈgoʊɪŋ tu steɪ ðɛr fɔr wʌn wik./","vi":"Họ sẽ ở đó trong một tuần."},{"text":"Every day, they visit a new beach or town.","ipa":"/ˈɛvəri deɪ, ðeɪ ˈvɪzɪt ə nu bitʃ ɔr taʊn./","vi":"Mỗi ngày, họ lại đi thăm một bãi biển hoặc thị trấn mới."},{"text":"At the end of the week, they pack their bags again and come back home.","ipa":"/æt ði ɛnd ʌv ðə wik, ðeɪ pæk ðɛr bægz əˈgɛn ænd kʌm bæk hoʊm./","vi":"Vào cuối tuần, họ lại đóng gói hành lý và trở về nhà."},{"text":"It is always a wonderful trip!","ipa":"/ɪt ɪz ˈɔlˌweɪz ə ˈwʌndərfəl trɪp!/","vi":"Đó luôn là một chuyến đi tuyệt vời!"}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mixed_all',NULL,1350,'a1-s7','b17e20653b1e4ed59b704fd16d21ac1a',NULL,NULL,'2026-07-25T12:47:43.761Z',NULL);
