INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('88f6894b-a128-467b-b7ec-a51d7988fbd3','a1-s7-16-mixed-checkpoint','Planning a Trip',1,'mixed','A1 Movers',NULL,'Our family has an exciting plan. We are going to visit Italy in July. First, we are going to book our flights next weekend. Then, my dad is going to book a room at a small hotel. We are going to stay at the hotel for five days. My mom is packing our suitcases now. She is still trying to fit everything in one bag. Maybe we are also going to visit a famous museum. We are going to come back home before school starts again.','[{"text":"Our family has an exciting plan.","ipa":"/ˈaʊər ˈfæməli hæz ən ɪkˈsaɪtɪŋ plæn./","vi":"Gia đình chúng tôi có một kế hoạch rất thú vị."},{"text":"We are going to visit Italy in July.","ipa":"/wi ɑr ˈgoʊɪŋ tu ˈvɪzɪt ˈɪtəli ɪn dʒuˈlaɪ./","vi":"Chúng tôi sẽ đi thăm nước Ý vào tháng Bảy."},{"text":"First, we are going to book our flights next weekend.","ipa":"/fɜrst, wi ɑr ˈgoʊɪŋ tu bʊk ˈaʊər flaɪts nɛkst ˈwikˌɛnd./","vi":"Đầu tiên, chúng tôi sẽ đặt vé máy bay vào cuối tuần tới."},{"text":"Then, my dad is going to book a room at a small hotel.","ipa":"/ðɛn, maɪ dæd ɪz ˈgoʊɪŋ tu bʊk ə rum æt ə smɔl hoʊˈtɛl./","vi":"Sau đó, bố tôi sẽ đặt phòng tại một khách sạn nhỏ."},{"text":"We are going to stay at the hotel for five days.","ipa":"/wi ɑr ˈgoʊɪŋ tu steɪ æt ðə hoʊˈtɛl fɔr faɪv deɪz./","vi":"Chúng tôi sẽ ở khách sạn đó trong năm ngày."},{"text":"My mom is packing our suitcases now.","ipa":"/maɪ mɑm ɪz ˈpækɪŋ ˈaʊər ˈsutˌkeɪsəz naʊ./","vi":"Mẹ tôi đang xếp hành lý ngay bây giờ."},{"text":"She is still trying to fit everything in one bag.","ipa":"/ʃi ɪz stɪl ˈtraɪɪŋ tu fɪt ˈɛvriˌθɪŋ ɪn wʌn bæg./","vi":"Mẹ vẫn đang cố gắng nhét mọi thứ vào một chiếc túi."},{"text":"Maybe we are also going to visit a famous museum.","ipa":"/ˈmeɪbi wi ɑr ˈɔlsoʊ ˈgoʊɪŋ tu ˈvɪzɪt ə ˈfeɪməs mjuˈziəm./","vi":"Có lẽ chúng tôi cũng sẽ đi thăm một bảo tàng nổi tiếng."},{"text":"We are going to come back home before school starts again.","ipa":"/wi ɑr ˈgoʊɪŋ tu kʌm bæk hoʊm bɪˈfɔr skul stɑrts əˈgɛn./","vi":"Chúng tôi sẽ trở về nhà trước khi trường học bắt đầu lại."}]',NULL,'Our family has an exciting plan. We are going to visit Italy in July. First, we are going to book our flights next weekend. Then, my dad is going to book a room at a small hotel. We are going to stay at the hotel for five days. My mom is packing our suitcases now. She is still trying to fit everything in one bag. Maybe we are also going to visit a famous museum. We are going to come back home before school starts again.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mixed_all',NULL,1360,'a1-s7','b17e20653b1e4ed59b704fd16d21ac1a',NULL,NULL,'2026-07-25T12:47:43.761Z',NULL);
