INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('0b9f422d-37dd-4c31-a6f5-fa3512f418fc','a1-s8-03-read-aloud-can-i-speak-to-you','Can I Speak to You? (Read Aloud)',1,'reading','A1 Movers',NULL,'Hello! My name is Tom, and I have a new phone. I use it to call my friends every day. When I call my friend Alice, she says, ''Speaking!'' Sometimes I text my friends instead of calling. If my friend is busy, I leave a message for her. Later, she can call me back. I also check my social media account and post photos from school. When my friends reply to my post, I feel happy. I always hold on for a moment before I answer the phone. Talking on the phone is a lot of fun!','[{"text":"Hello!","ipa":"/həˈloʊ/","vi":"Xin chào!"},{"text":"My name is Tom, and I have a new phone.","ipa":"/maɪ neɪm ɪz tɑm, ænd aɪ hæv ə nu foʊn./","vi":"Tên mình là Tom, và mình mới có một chiếc điện thoại mới."},{"text":"I use it to call my friends every day.","ipa":"/aɪ juz ɪt tu kɔl maɪ frɛndz ˈɛvri deɪ./","vi":"Mình dùng nó để gọi cho bạn bè mỗi ngày."},{"text":"When I call my friend Alice, she says, ''Speaking!''","ipa":"/wɛn aɪ kɔl maɪ frɛnd ˈælɪs, ʃi sɛz, ˈspiːkɪŋ!/","vi":"Khi mình gọi cho bạn Alice, bạn ấy nói: ''Mình nghe đây!''"},{"text":"Sometimes I text my friends instead of calling.","ipa":"/ˈsʌmˌtaɪmz aɪ tɛkst maɪ frɛndz ɪnˈstɛd ʌv ˈkɔlɪŋ./","vi":"Đôi khi mình nhắn tin cho bạn bè thay vì gọi điện."},{"text":"If my friend is busy, I leave a message for her.","ipa":"/ɪf maɪ frɛnd ɪz ˈbɪzi, aɪ liv ə ˈmɛsɪdʒ fɔr hɜr./","vi":"Nếu bạn mình bận, mình sẽ để lại tin nhắn cho bạn ấy."},{"text":"Later, she can call me back.","ipa":"/ˈleɪtər, ʃi kæn kɔl mi bæk./","vi":"Sau đó, bạn ấy có thể gọi lại cho mình."},{"text":"I also check my social media account and post photos from school.","ipa":"/aɪ ˈɔlsoʊ tʃɛk maɪ ˈsoʊʃəl ˈmidiə əˈkaʊnt ænd poʊst ˈfoʊtoʊz frʌm skul./","vi":"Mình cũng kiểm tra tài khoản mạng xã hội và đăng ảnh ở trường."},{"text":"When my friends reply to my post, I feel happy.","ipa":"/wɛn maɪ frɛndz rɪˈplaɪ tu maɪ poʊst, aɪ fil ˈhæpi./","vi":"Khi bạn bè trả lời bài đăng của mình, mình cảm thấy rất vui."},{"text":"I always hold on for a moment before I answer the phone.","ipa":"/aɪ ˈɔlweɪz hoʊld ɑn fɔr ə ˈmoʊmənt bɪˈfɔr aɪ ˈænsər ðə foʊn./","vi":"Mình luôn đợi một chút trước khi bắt máy."},{"text":"Talking on the phone is a lot of fun!","ipa":"/ˈtɔkɪŋ ɑn ðə foʊn ɪz ə lɑt ʌv fʌn!/","vi":"Nói chuyện điện thoại thật là vui!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,1430,'a1-s8','0e20fa95fddf49fe947816e9be7165aa',NULL,NULL,'2026-07-25T12:48:06.937Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('8d485132-62c4-4c49-ab4a-04d368a3d14e','a1-s8-04-listen-choose-phone-call','A Phone Call',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Emma (F): Hello, can I speak to Jack, please?
Jack (M) [happy]: Speaking! Hi Emma.
Emma (F): Hi Jack! Are you busy right now?
Jack (M): No, I''m not busy. What''s up?
Emma (F) [worried]: Can you send me the homework? I don''t have it.
Jack (M): Sure, I''ll text you the photo now.
Emma (F) [worried]: Thanks! Oh, and can you reply quickly? My phone battery is low.
Jack (M): OK, hold on... I''m sending it now.
Emma (F) [relieved]: Got it! Thank you so much.
Jack (M): No problem. Oh, I have to go. I''ll call you back later.
Emma (F): OK, bye!
Jack (M): Bye!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,1440,'a1-s8','0e20fa95fddf49fe947816e9be7165aa',NULL,NULL,'2026-07-25T12:48:06.937Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('98841ed7-0616-42ba-851e-3a6cea76676d','8d485132-62c4-4c49-ab4a-04d368a3d14e',0,'multiple_choice','Who does Emma want to speak to?','["Jack", "Anna", "Leo", "Mia"]','Jack',NULL,NULL,NULL,'Lời thoại nêu: "Hello, can I speak to Jack, please?" — khớp với đáp án "Jack".','Emma: can I speak to Jack, please?',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('cefc3351-a9b0-4086-8e71-7455f4cb1a80','8d485132-62c4-4c49-ab4a-04d368a3d14e',1,'multiple_choice','Is Jack busy?','["Yes", "No"]','No',NULL,NULL,NULL,'Jack đáp "No, I''m not busy. What''s up?" — nghĩa là Jack không bận.','Jack: No, I''m not busy.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('1f9302a6-23a0-46aa-a3ba-e223a14c980f','8d485132-62c4-4c49-ab4a-04d368a3d14e',2,'multiple_choice','What does Emma need?','["The homework", "A pen", "A book", "Money"]','The homework',NULL,NULL,NULL,'Lời thoại nêu: "Can you send me the homework? I don''t have it." — khớp với đáp án "The homework".','Emma: Can you send me the homework?',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('ea1a0107-3ccd-47cb-9801-ca21af212742','8d485132-62c4-4c49-ab4a-04d368a3d14e',3,'multiple_choice','How will Jack send the homework?','["By text", "By email", "By post", "By phone call"]','By text',NULL,NULL,NULL,'Lời thoại nêu: "Sure, I''ll text you the photo now." — khớp với đáp án "By text".','Jack: I''ll text you the photo now.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('36f904ea-413f-42c6-8681-99a64f4ffd2a','8d485132-62c4-4c49-ab4a-04d368a3d14e',4,'multiple_choice','Why does Emma want a quick reply?','["Her battery is low", "She is busy", "She is late", "She is happy"]','Her battery is low',NULL,NULL,NULL,'Lời thoại nêu: "Thanks! Oh, and can you reply quickly? My phone battery is low." — khớp với đáp án "Her battery is low".','Emma: my phone battery is low.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('852870b1-8526-4eaf-8e4d-686af5a993c1','8d485132-62c4-4c49-ab4a-04d368a3d14e',5,'multiple_choice','What does Jack say before sending?','["Hold on", "Speaking", "Goodbye", "Sorry"]','Hold on',NULL,NULL,NULL,'Lời thoại nêu: "OK, hold on... I''m sending it now." — khớp với đáp án "Hold on".','Jack: OK, hold on...',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('0a160ef8-408f-4622-b35e-1e681f085a18','8d485132-62c4-4c49-ab4a-04d368a3d14e',6,'multiple_choice','What will Jack do later?','["Call Emma back", "Text Jack", "Send an email", "Leave a message"]','Call Emma back',NULL,NULL,NULL,'Lời thoại/đoạn văn nêu: "No problem. Oh, I have to go. I''ll call you back later." — khớp với đáp án "Call Emma back".','Jack: I''ll call you back later.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('46e83feb-b205-4b40-a3bf-86fe0fa02604','8d485132-62c4-4c49-ab4a-04d368a3d14e',7,'multiple_choice','How does Jack answer the phone?','["Speaking!", "Hello!", "Who is this?", "Bye!"]','Speaking!',NULL,NULL,NULL,'Lời thoại nêu: "Speaking! Hi Emma." — khớp với đáp án "Speaking!".','Jack: Speaking! Hi Emma.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('cd98104b-05e5-4cd5-bb58-a7e78a501dd3','8d485132-62c4-4c49-ab4a-04d368a3d14e',8,'fill_blank','Emma wants to speak to ___.',NULL,NULL,'["Jack"]','["Jack", "Leo", "Mia"]',NULL,'Câu trong bài: "Hello, can I speak to Jack, please?" — từ cần điền là "Jack".','Emma: can I speak to Jack, please?',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('4f2a9b38-9f39-45fa-a659-b5362ed32f61','8d485132-62c4-4c49-ab4a-04d368a3d14e',9,'fill_blank','Jack is not ___ right now.',NULL,NULL,'["busy"]','["busy", "tired", "happy"]',NULL,'Câu trong bài: "Hi Jack! Are you busy right now?" — từ cần điền là "busy".','Jack: No, I''m not busy.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('b91ec9d8-00eb-44a2-b101-b5bce7929eb2','8d485132-62c4-4c49-ab4a-04d368a3d14e',10,'fill_blank','Jack will ___ Emma the photo.',NULL,NULL,'["text"]','["text", "call", "post"]',NULL,'Câu trong bài: "Sure, I''ll text you the photo now." — từ cần điền là "text".','Jack: I''ll text you the photo now.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('700bbca9-76fd-4e88-91f9-261d65900b72','8d485132-62c4-4c49-ab4a-04d368a3d14e',11,'fill_blank','Emma''s phone ___ is low.',NULL,NULL,'["battery"]','["battery", "signal", "screen"]',NULL,'Câu trong bài: "Thanks! Oh, and can you reply quickly? My phone battery is low." — từ cần điền là "battery".','Emma: my phone battery is low.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('134b3594-f539-49c6-bea3-0671c1fea35e','8d485132-62c4-4c49-ab4a-04d368a3d14e',12,'fill_blank','Jack will ___ Emma later.',NULL,NULL,'["call back"]','["call back", "text", "reply"]',NULL,'Câu trong bài: "No problem. Oh, I have to go. I''ll call you back later." — từ cần điền là "call back".','Jack: I''ll call you back later.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('f15b9758-5b1b-4a7a-8eb5-54696056e064','8d485132-62c4-4c49-ab4a-04d368a3d14e',13,'matching','Match each person to what they need.',NULL,NULL,NULL,NULL,NULL,'Ghép theo nội dung bài: "Emma" ↔ "wants the homework" (dựa trên: "Can you send me the homework? I don''t have it."); "Jack" ↔ "sends a text" (dựa trên: "Sure, I''ll text you the photo now.").','Emma: send me the homework. Jack: I''ll text you the photo.','[{"left": "Emma", "right": "wants the homework"}, {"left": "Jack", "right": "sends a text"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('082d89b8-d5c9-4681-83ba-e0dc476e0c57','8d485132-62c4-4c49-ab4a-04d368a3d14e',14,'matching','Match each phrase to what it means in the call.',NULL,NULL,NULL,NULL,NULL,'Ghép theo nội dung bài: "Speaking!" ↔ "Jack answers the phone" (dựa trên: "Hello, can I speak to Jack, please?"); "Hold on..." ↔ "Jack is sending something" (dựa trên: "OK, hold on... I''m sending it now.").','Jack: Speaking! ... OK, hold on...','[{"left": "Speaking!", "right": "Jack answers the phone"}, {"left": "Hold on...", "right": "Jack is sending something"}]',NULL,NULL,NULL,NULL,NULL);
