INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('f662a5fd-fb97-4157-81ae-52689786a2d9','ded18fe8-4092-4f58-8fe0-b1938af6ed30',20,'categorize','Sort each sentence into the correct group.',NULL,NULL,NULL,NULL,NULL,'Phân biệt câu mời và câu đáp lại lời mời.',NULL,NULL,NULL,'["Invitation", "Reply"]','[{"text": "Would you like to come?", "category": "Invitation"}, {"text": "I''d love to!", "category": "Reply"}, {"text": "How about a party?", "category": "Invitation"}, {"text": "I''m afraid I can''t.", "category": "Reply"}]',NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('da4a2ee3-95a1-4dce-a07e-e45df8815d30','ded18fe8-4092-4f58-8fe0-b1938af6ed30',21,'categorize','Sort each sentence into the correct group.',NULL,NULL,NULL,NULL,NULL,'Phân loại cách đồng ý và từ chối lịch sự.',NULL,NULL,NULL,'["Polite accept", "Polite refuse"]','[{"text": "I''d love to!", "category": "Polite accept"}, {"text": "I''m afraid I can''t.", "category": "Polite refuse"}, {"text": "Yes, I''d like that.", "category": "Polite accept"}, {"text": "Sorry, I can''t come.", "category": "Polite refuse"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('88df75c0-3231-4d70-b2bc-b355dd4b64c2','a1-s8-08-read-aloud-party-time','Party Time (Read Aloud)',1,'reading','A1 Movers',NULL,'Today is a special day. My family is going to celebrate my grandmother''s birthday. We decorate the living room with balloons and flowers. My mother says, ''Would you like to help me make the cake?'' I say, ''I''d love to!'' We invite all our family and friends to the party. Every guest brings a small gift. It is a tradition in our family to sing a special song before we eat the cake. My cousin asks, ''How about some music too?'' We all say yes and start dancing. It is a wonderful celebration!','[{"text":"Today is a special day.","ipa":"/təˈdeɪ ɪz ə ˈspɛʃəl deɪ./","vi":"Hôm nay là một ngày đặc biệt."},{"text":"My family is going to celebrate my grandmother''s birthday.","ipa":"/maɪ ˈfæməli ɪz ˈgoʊɪŋ tu ˈsɛləˌbreɪt maɪ ˈgrændˌmʌðərz ˈbɜrθˌdeɪ./","vi":"Gia đình tôi sắp tổ chức sinh nhật cho bà."},{"text":"We decorate the living room with balloons and flowers.","ipa":"/wi ˈdɛkəˌreɪt ðə ˈlɪvɪŋ rum wɪð bəˈlunz ænd ˈflaʊərz./","vi":"Chúng tôi trang trí phòng khách bằng bóng bay và hoa."},{"text":"My mother says, ''Would you like to help me make the cake?''","ipa":"/maɪ ˈmʌðər sɛz, ''wʊd ju laɪk tu hɛlp mi meɪk ðə keɪk?''/","vi":"Mẹ tôi hỏi: ''Con có muốn giúp mẹ làm bánh không?''"},{"text":"I say, ''I''d love to!''","ipa":"/aɪ seɪ, ''aɪd lʌv tu!''/","vi":"Tôi đáp: ''Con rất sẵn lòng!''"},{"text":"We invite all our family and friends to the party.","ipa":"/wi ɪnˈvaɪt ɔl ˈaʊər ˈfæməli ænd frɛndz tu ðə ˈpɑrti./","vi":"Chúng tôi mời tất cả người thân và bạn bè đến dự tiệc."},{"text":"Every guest brings a small gift.","ipa":"/ˈɛvəri gɛst brɪŋz ə smɔl gɪft./","vi":"Mỗi vị khách đều mang theo một món quà nhỏ."},{"text":"It is a tradition in our family to sing a special song before we eat the cake.","ipa":"/ɪt ɪz ə trəˈdɪʃən ɪn ˈaʊər ˈfæməli tu sɪŋ ə ˈspɛʃəl sɔŋ bɪˈfɔr wi it ðə keɪk./","vi":"Truyền thống của gia đình tôi là hát một bài hát đặc biệt trước khi ăn bánh."},{"text":"My cousin asks, ''How about some music too?''","ipa":"/maɪ ˈkʌzən æsks, ''haʊ əˈbaʊt sʌm ˈmjuzɪk tu?''/","vi":"Anh/chị/em họ của tôi hỏi: ''Thêm chút nhạc nữa thì sao nhỉ?''"},{"text":"We all say yes and start dancing.","ipa":"/wi ɔl seɪ jɛs ænd stɑrt ˈdænsɪŋ./","vi":"Tất cả chúng tôi đều đồng ý và bắt đầu nhảy múa."},{"text":"It is a wonderful celebration!","ipa":"/ɪt ɪz ə ˈwʌndərfəl ˌsɛləˈbreɪʃən!/","vi":"Đó là một buổi tiệc thật tuyệt vời!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,1480,'a1-s8','286d6732f02b4921a3a370283a7475cf',NULL,NULL,'2026-07-25T12:48:06.937Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('4d806035-a238-4c39-afa8-fb1881469d8b','a1-s8-09-listen-choose-invitation','An Invitation',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Sofia (F) [happy]: Hi Daniel! Would you like to come to my birthday party?
Daniel (M) [happy]: I''d love to! When is it?
Sofia (F): It''s on Saturday. We''re going to decorate the house and have a big cake.
Daniel (M): Great! Can I invite my sister too?
Sofia (F) [happy]: Of course! The more guests, the better.
Daniel (M): How about Ben? Can he come as well?
Sofia (F) [happy]: Yes, let''s invite him too!
Daniel (M) [regretful]: I''m afraid Ben can''t come. He has a football match on Saturday.
Sofia (F): That''s OK. It''s a tradition in my family to celebrate with a lot of games.
Daniel (M) [happy]: Sounds fun! What time should we come?
Sofia (F): Please come at four o''clock.
Daniel (M) [happy]: Great, see you then!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,1490,'a1-s8','286d6732f02b4921a3a370283a7475cf',NULL,NULL,'2026-07-25T12:48:06.937Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('c0d1d313-0316-4706-899c-ebc5ba9265f6','4d806035-a238-4c39-afa8-fb1881469d8b',0,'multiple_choice','What is Sofia inviting Daniel to?','["Her birthday party", "A football match", "A school trip", "A movie"]','Her birthday party',NULL,NULL,NULL,'Lời thoại nêu: "Hi Daniel! Would you like to come to my birthday party?" — khớp với đáp án "Her birthday party".','Sofia: Would you like to come to my birthday party?',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('cde9f971-b35b-4659-95ce-42b11e6a54ff','4d806035-a238-4c39-afa8-fb1881469d8b',1,'multiple_choice','When is the party?','["Saturday", "Sunday", "Friday", "Monday"]','Saturday',NULL,NULL,NULL,'Lời thoại nêu: "It''s on Saturday. We''re going to decorate the house and have a big cake." — khớp với đáp án "Saturday".','Sofia: It''s on Saturday.',NULL,NULL,NULL,NULL,NULL,NULL);
