INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('386106c5-967e-4a4b-9a43-d5467c83816d','4d806035-a238-4c39-afa8-fb1881469d8b',3,'multiple_choice','Who does Daniel want to invite?','["His sister", "His teacher", "His dog", "His cousin"]','His sister',NULL,NULL,NULL,'Lời thoại nêu: "Great! Can I invite my sister too?" — khớp với đáp án "His sister".','Daniel: Can I invite my sister too?',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('1d9ebcfa-2be4-4c36-8d6b-ca3a3411257d','4d806035-a238-4c39-afa8-fb1881469d8b',4,'multiple_choice','Can Ben come to the party?','["No", "Yes", "Maybe", "He doesn''t know"]','No',NULL,NULL,NULL,'Daniel nói "I''m afraid Ben can''t come. He has a football match on Saturday." nên Ben không thể đến dự tiệc.','Daniel: I''m afraid Ben can''t come.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('f7acde64-3ba7-4fc5-ad1b-458d3cbff2e1','4d806035-a238-4c39-afa8-fb1881469d8b',5,'multiple_choice','Why can''t Ben come?','["He has a football match", "He is sick", "He is on holiday", "He doesn''t like parties"]','He has a football match',NULL,NULL,NULL,'Lời thoại nêu: "I''m afraid Ben can''t come. He has a football match on Saturday." — khớp với đáp án "He has a football match".','Daniel: He has a football match on Saturday.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('5f4df93d-9025-45c1-a399-2d21413f7c51','4d806035-a238-4c39-afa8-fb1881469d8b',6,'multiple_choice','What is a tradition in Sofia''s family?','["Celebrating with games", "Watching TV", "Going shopping", "Cooking alone"]','Celebrating with games',NULL,NULL,NULL,'Lời thoại/đoạn văn nêu: "That''s OK. It''s a tradition in my family to celebrate with a lot of games." — khớp với đáp án "Celebrating with games".','Sofia: It''s a tradition in my family to celebrate with a lot of games.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('05663c81-d052-4a3c-a2e2-de53a4c0144c','4d806035-a238-4c39-afa8-fb1881469d8b',7,'multiple_choice','What time should Daniel come?','["Four o''clock", "Two o''clock", "Six o''clock", "Eight o''clock"]','Four o''clock',NULL,NULL,NULL,'Lời thoại nêu: "Please come at four o''clock." — khớp với đáp án "Four o''clock".','Sofia: Please come at four o''clock.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('1694454c-cba4-4a93-9384-1b0cbf5a36c6','4d806035-a238-4c39-afa8-fb1881469d8b',8,'fill_blank','Sofia invites Daniel to her ___ party.',NULL,NULL,'["birthday"]','["birthday", "football", "school"]',NULL,'Câu trong bài: "Hi Daniel! Would you like to come to my birthday party?" — từ cần điền là "birthday".','Sofia: my birthday party.',NULL,NULL,NULL,NULL,NULL,NULL);
