INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('e95743c6-2e21-4c7b-a663-39e85610adab','4d806035-a238-4c39-afa8-fb1881469d8b',10,'fill_blank','Daniel wants to bring his ___.',NULL,NULL,'["sister"]','["sister", "brother", "dog"]',NULL,'Câu trong bài: "Great! Can I invite my sister too?" — từ cần điền là "sister".','Daniel: Can I invite my sister too?',NULL,NULL,NULL,NULL,NULL,NULL);
