INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('12d67f3a-f9cf-47cd-a86a-0337b7c05764','4d806035-a238-4c39-afa8-fb1881469d8b',12,'fill_blank','Please come at ___ o''clock.',NULL,NULL,'["four"]','["four", "two", "six"]',NULL,'Câu trong bài: "Please come at four o''clock." — từ cần điền là "four".','Sofia: Please come at four o''clock.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('4001c397-46b0-4b1d-9533-b5eb87d55444','4d806035-a238-4c39-afa8-fb1881469d8b',13,'matching','Match each person to what they do.',NULL,NULL,NULL,NULL,NULL,'Ghép theo nội dung bài: "Sofia" ↔ "invites Daniel" (dựa trên: "Hi Daniel! Would you like to come to my birthday party?"); "Daniel" ↔ "invites his sister" (dựa trên: "Great! Can I invite my sister too?").','Sofia: Would you like to come? Daniel: Can I invite my sister too?','[{"left": "Sofia", "right": "invites Daniel"}, {"left": "Daniel", "right": "invites his sister"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('616239c3-df6b-45f6-82d3-97d9b0626f66','4d806035-a238-4c39-afa8-fb1881469d8b',14,'matching','Match each action to what it means.',NULL,NULL,NULL,NULL,NULL,'Ghép theo nội dung bài: "decorate" ↔ "the house" (dựa trên: "It''s on Saturday. We''re going to decorate the house and have a big cake."); "celebrate" ↔ "with games" (dựa trên: "That''s OK. It''s a tradition in my family to celebrate with a lot of games.").','We''re going to decorate the house. ... celebrate with a lot of games.','[{"left": "decorate", "right": "the house"}, {"left": "celebrate", "right": "with games"}]',NULL,NULL,NULL,NULL,NULL);
