INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('1cf4e8cf-b18c-4cd3-8c85-a340737e8662','3a89a8ff-892c-4045-a973-bf5d1efa3662',20,'categorize','Sort each comparative form into the correct group.',NULL,NULL,NULL,NULL,NULL,'Tính từ ngắn thêm ''-er''; tính từ dài dùng ''more''.',NULL,NULL,NULL,'["-er", "more + adjective"]','[{"text": "faster", "category": "-er"}, {"text": "easier", "category": "-er"}, {"text": "more difficult", "category": "more + adjective"}, {"text": "more popular", "category": "more + adjective"}]',NULL,'comparative-adjectives');
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('cc511c90-6ba7-4bbd-bbbd-dd80ca4593b0','3a89a8ff-892c-4045-a973-bf5d1efa3662',21,'categorize','Sort each comparative form into the correct group.',NULL,NULL,NULL,NULL,NULL,'''better'' và ''worse'' là dạng so sánh hơn bất quy tắc.',NULL,NULL,NULL,'["Regular", "Irregular"]','[{"text": "faster", "category": "Regular"}, {"text": "easier", "category": "Regular"}, {"text": "better", "category": "Irregular"}, {"text": "worse", "category": "Irregular"}]',NULL,'comparative-adjectives');
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('93a3cf19-b659-41ac-b114-55af1e2e3137','a1-s8-13-read-aloud-the-big-match','The Big Match (Read Aloud)',1,'reading','A1 Movers',NULL,'Today is the big match! My team is playing against the best team in town. Our team is faster than the other team, but they are more difficult to beat this year. My coach says our team is better than last year. I hope we don''t lose today! A lot of people come to watch because our team is very popular. The other team scored first, but we don''t give up. In the last five minutes, we score two goals and win the match! Everyone is so happy. It was an easier win than we expected!','[{"text":"Today is the big match!","ipa":"/təˈdeɪ ɪz ðə bɪg mætʃ/","vi":"Hôm nay là trận đấu lớn!"},{"text":"My team is playing against the best team in town.","ipa":"/maɪ tiːm ɪz ˈpleɪɪŋ əˈgɛnst ðə bɛst tiːm ɪn taʊn/","vi":"Đội của tôi đang đấu với đội mạnh nhất trong thị trấn."},{"text":"Our team is faster than the other team, but they are more difficult to beat this year.","ipa":"/ˈaʊər tiːm ɪz ˈfæstər ðæn ði ˈʌðər tiːm, bʌt ðeɪ ɑːr mɔːr ˈdɪfɪkəlt tuː biːt ðɪs jɪər/","vi":"Đội chúng tôi nhanh hơn đội bạn, nhưng năm nay họ khó đánh bại hơn."},{"text":"My coach says our team is better than last year.","ipa":"/maɪ koʊtʃ sɛz ˈaʊər tiːm ɪz ˈbɛtər ðæn læst jɪər/","vi":"Huấn luyện viên nói đội chúng tôi giỏi hơn năm ngoái."},{"text":"I hope we don''t lose today!","ipa":"/aɪ hoʊp wiː doʊnt luːz təˈdeɪ/","vi":"Tôi hy vọng hôm nay chúng ta không thua!"},{"text":"A lot of people come to watch because our team is very popular.","ipa":"/ə lɑːt əv ˈpiːpəl kʌm tuː wɑːtʃ bɪˈkəz ˈaʊər tiːm ɪz ˈvɛri ˈpɑːpjələr/","vi":"Rất nhiều người đến xem vì đội chúng tôi rất nổi tiếng."},{"text":"The other team scored first, but we don''t give up.","ipa":"/ði ˈʌðər tiːm skɔːrd fɜːrst, bʌt wiː doʊnt gɪv ʌp/","vi":"Đội bạn ghi bàn trước, nhưng chúng tôi không bỏ cuộc."},{"text":"In the last five minutes, we score two goals and win the match!","ipa":"/ɪn ðə læst faɪv ˈmɪnɪts, wiː skɔːr tuː goʊlz ænd wɪn ðə mætʃ/","vi":"Trong năm phút cuối, chúng tôi ghi hai bàn và thắng trận đấu!"},{"text":"Everyone is so happy.","ipa":"/ˈɛvriˌwʌn ɪz soʊ ˈhæpi/","vi":"Mọi người đều rất vui."},{"text":"It was an easier win than we expected!","ipa":"/ɪt wʌz ən ˈiːziər wɪn ðæn wiː ɪkˈspɛktɪd/","vi":"Đó là một chiến thắng dễ dàng hơn chúng tôi mong đợi!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,1530,'a1-s8','92fa7fe4a3ba4085b94cbbb85fe1ee2f',NULL,NULL,'2026-07-25T12:48:06.937Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('bf9e8e27-16cc-44e2-a8b6-33611f17e1e0','a1-s8-14-listen-choose-team-talk','Team Talk',1,'listening','A1 Movers',NULL,NULL,NULL,NULL,'Marco (M) [happy]: Our team is better than yours this year, Grace!
Grace (F) [happy]: No way! My team is faster and stronger.
Marco (M) [happy]: Maybe, but my team wins more matches.
Grace (F): That''s true, but our last match was easier than yours.
Marco (M) [serious]: Our next match is more difficult. We''re playing the best team in town.
Grace (F) [worried]: I hope you don''t lose!
Marco (M) [happy]: Me too! Our team is very popular now.
Grace (F) [happy]: My team is popular too. Everyone comes to watch us play.
Marco (M): Let''s watch each other''s matches this weekend.
Grace (F) [happy]: Good idea! I''d love to see your team play.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,1540,'a1-s8','92fa7fe4a3ba4085b94cbbb85fe1ee2f',NULL,NULL,'2026-07-25T12:48:06.937Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('bb9e9070-7754-4e50-ae23-0a9d8c932e0f','bf9e8e27-16cc-44e2-a8b6-33611f17e1e0',0,'multiple_choice','Whose team wins more matches, according to Marco?','["His team", "Grace''s team", "Both teams", "Neither team"]','His team',NULL,NULL,NULL,'Lời thoại nêu: "Our team is better than yours this year, Grace!" — khớp với đáp án "His team".','Marco: my team wins more matches.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('f7f3b607-111f-4321-a870-66717aa98911','bf9e8e27-16cc-44e2-a8b6-33611f17e1e0',1,'multiple_choice','What does Grace say about her team''s speed?','["It''s faster", "It''s slower", "It''s the same", "It''s tired"]','It''s faster',NULL,NULL,NULL,'Lời thoại/đoạn văn nêu: "No way! My team is faster and stronger." — khớp với đáp án "It''s faster".','Grace: My team is faster and stronger.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('93037c90-759e-4c69-9021-fe1dd35e08ee','bf9e8e27-16cc-44e2-a8b6-33611f17e1e0',2,'multiple_choice','Was Grace''s last match easy or difficult?','["Easier than Marco''s", "More difficult than Marco''s", "The same", "Cancelled"]','Easier than Marco''s',NULL,NULL,NULL,'Lời thoại nêu: "That''s true, but our last match was easier than yours." — khớp với đáp án "Easier than Marco''s".','Grace: our last match was easier than yours.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('7074725f-8fdd-45fd-ab88-7c64390c7b26','bf9e8e27-16cc-44e2-a8b6-33611f17e1e0',3,'multiple_choice','What is Marco''s next match like?','["More difficult", "Very easy", "Cancelled", "At home"]','More difficult',NULL,NULL,NULL,'Lời thoại nêu: "Our next match is more difficult. We''re playing the best team in town." — khớp với đáp án "More difficult".','Marco: Our next match is more difficult.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('79eb0a3b-e164-4f29-9320-a8ea6026fddf','bf9e8e27-16cc-44e2-a8b6-33611f17e1e0',4,'multiple_choice','What does Grace hope for Marco''s team?','["That they don''t lose", "That they lose", "That they stop playing", "That they win nothing"]','That they don''t lose',NULL,NULL,NULL,'Lời thoại/đoạn văn nêu: "I hope you don''t lose!" — khớp với đáp án "That they don''t lose".','Grace: I hope you don''t lose!',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('ddb25f1d-0f72-4a45-aee9-d5c0ec76b0b3','bf9e8e27-16cc-44e2-a8b6-33611f17e1e0',5,'multiple_choice','How popular is Marco''s team?','["Very popular", "Not popular", "A little popular", "Unknown"]','Very popular',NULL,NULL,NULL,'Lời thoại nêu: "Me too! Our team is very popular now." — khớp với đáp án "Very popular".','Marco: Our team is very popular now.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('a2a0212c-4068-4448-883f-b20f99ebf401','bf9e8e27-16cc-44e2-a8b6-33611f17e1e0',6,'multiple_choice','What do people do for Grace''s team?','["Come to watch", "Stay at home", "Play music", "Sell tickets"]','Come to watch',NULL,NULL,NULL,'Lời thoại nêu: "My team is popular too. Everyone comes to watch us play." — khớp với đáp án "Come to watch".','Grace: Everyone comes to watch us play.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('58b770e7-c360-4eb3-9d84-39ddc733cd43','bf9e8e27-16cc-44e2-a8b6-33611f17e1e0',7,'multiple_choice','What do Marco and Grace plan to do this weekend?','["Watch each other''s matches", "Play together", "Stay home", "Go shopping"]','Watch each other''s matches',NULL,NULL,NULL,'Lời thoại nêu: "Let''s watch each other''s matches this weekend." — khớp với đáp án "Watch each other''s matches".','Marco: Let''s watch each other''s matches this weekend.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('c31fd57d-5d7b-408c-bb6e-5f49cf04ea38','bf9e8e27-16cc-44e2-a8b6-33611f17e1e0',8,'fill_blank','Marco says his team is ___ than Grace''s.',NULL,NULL,'["better"]','["better", "worse", "the same"]',NULL,'Câu trong bài: "Our team is better than yours this year, Grace!" — từ cần điền là "better".','Marco: Our team is better than yours.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('b7455c2d-c635-4bc9-af64-74e14d2c47c8','bf9e8e27-16cc-44e2-a8b6-33611f17e1e0',9,'fill_blank','Grace''s team is ___ and stronger.',NULL,NULL,'["faster"]','["faster", "slower", "weaker"]',NULL,'Câu trong bài: "No way! My team is faster and stronger." — từ cần điền là "faster".','Grace: My team is faster and stronger.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('1a40be7e-3196-4856-ba5a-b0f9ca1671f1','bf9e8e27-16cc-44e2-a8b6-33611f17e1e0',10,'fill_blank','Marco''s team ___ more matches.',NULL,NULL,'["wins"]','["wins", "loses", "plays"]',NULL,'Câu trong bài: "Maybe, but my team wins more matches." — từ cần điền là "wins".','Marco: my team wins more matches.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('6d9ac39f-82a2-437b-a801-bb6cbe085c6a','bf9e8e27-16cc-44e2-a8b6-33611f17e1e0',11,'fill_blank','Marco''s next match is ___ difficult.',NULL,NULL,'["more"]','["more", "less", "not"]',NULL,'Câu trong bài: "Maybe, but my team wins more matches." — từ cần điền là "more".','Marco: Our next match is more difficult.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('91be8151-d375-4b02-a32d-5816ef6e2952','bf9e8e27-16cc-44e2-a8b6-33611f17e1e0',12,'fill_blank','Marco''s team is very ___ now.',NULL,NULL,'["popular"]','["popular", "unknown", "boring"]',NULL,'Câu trong bài: "Me too! Our team is very popular now." — từ cần điền là "popular".','Marco: Our team is very popular now.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('6e135fe8-2d43-40be-88c0-02d099572bdb','bf9e8e27-16cc-44e2-a8b6-33611f17e1e0',13,'matching','Match each team to what is said about it.',NULL,NULL,NULL,NULL,NULL,'Ghép theo nội dung bài: "Marco''s team" ↔ "wins more matches" (dựa trên: "Maybe, but my team wins more matches."); "Grace''s team" ↔ "is faster" (dựa trên: "No way! My team is faster and stronger.").','Marco: my team wins more matches. Grace: My team is faster.','[{"left": "Marco''s team", "right": "wins more matches"}, {"left": "Grace''s team", "right": "is faster"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('ad3bda7d-ba80-4b82-a508-67fc9465cc10','bf9e8e27-16cc-44e2-a8b6-33611f17e1e0',14,'matching','Match each match to its description.',NULL,NULL,NULL,NULL,NULL,'Ghép theo nội dung bài: "easier" ↔ "last match" (dựa trên: "That''s true, but our last match was easier than yours."); "more difficult" ↔ "next match" (dựa trên: "Our next match is more difficult. We''re playing the best team in town.").','our last match was easier than yours. Our next match is more difficult.','[{"left": "easier", "right": "last match"}, {"left": "more difficult", "right": "next match"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('1f7ded60-2b4c-4b17-b317-a5f1ae8db816','a1-s8-15-reading-comprehension','New Gadgets for School',1,'reading','A1 Movers',NULL,'Schools today use a lot of new technology. Many students have a tablet or a laptop for their lessons. Teachers use a computer and a projector to show pictures and videos. Some schools also have robots that help students practice English. In the library, students can search for books on a computer instead of looking through shelves. At home, students often do their homework using an app on their phone. Some students like playing video games after school, but they must finish their homework first. A new gadget in many classrooms is a smart board. Students can write on it like a whiteboard, but it also connects to the internet. Technology makes learning more fun, but students should not spend too much time on screens. It is important to also read books, play outside, and talk with friends.','[{"text":"Schools today use a lot of new technology.","ipa":"/skulz təˈdeɪ juz ə lɑt əv nu tɛkˈnɑlədʒi./","vi":"Trường học ngày nay sử dụng rất nhiều công nghệ mới."},{"text":"Many students have a tablet or a laptop for their lessons.","ipa":"/ˈmɛni ˈstudənts hæv ə ˈtæblət ɔr ə ˈlæptɑp fɔr ðɛr ˈlɛsənz./","vi":"Nhiều học sinh có máy tính bảng hoặc máy tính xách tay để học bài."},{"text":"Teachers use a computer and a projector to show pictures and videos.","ipa":"/ˈtitʃərz juz ə kəmˈpjutər ænd ə prəˈdʒɛktər tu ʃoʊ ˈpɪktʃərz ænd ˈvɪdioʊz./","vi":"Giáo viên sử dụng máy tính và máy chiếu để trình chiếu hình ảnh và video."},{"text":"Some schools also have robots that help students practice English.","ipa":"/sʌm skulz ˈɔlsoʊ hæv ˈroʊbɑts ðæt hɛlp ˈstudənts ˈpræktəs ˈɪŋɡlɪʃ./","vi":"Một số trường học còn có robot giúp học sinh luyện tập tiếng Anh."},{"text":"In the library, students can search for books on a computer instead of looking through shelves.","ipa":"/ɪn ðə ˈlaɪˌbrɛri, ˈstudənts kæn sɜrtʃ fɔr bʊks ɑn ə kəmˈpjutər ɪnˈstɛd əv ˈlʊkɪŋ θru ʃɛlvz./","vi":"Trong thư viện, học sinh có thể tìm sách trên máy tính thay vì phải tìm trên kệ."},{"text":"At home, students often do their homework using an app on their phone.","ipa":"/æt hoʊm, ˈstudənts ˈɔfən du ðɛr ˈhoʊmwɜrk ˈjuzɪŋ ən æp ɑn ðɛr foʊn./","vi":"Ở nhà, học sinh thường làm bài tập về nhà bằng ứng dụng trên điện thoại."},{"text":"Some students like playing video games after school, but they must finish their homework first.","ipa":"/sʌm ˈstudənts laɪk ˈpleɪɪŋ ˈvɪdioʊ ɡeɪmz ˈæftər skul, bʌt ðeɪ mʌst ˈfɪnɪʃ ðɛr ˈhoʊmwɜrk fɜrst./","vi":"Một số học sinh thích chơi trò chơi điện tử sau giờ học, nhưng các em phải hoàn thành bài tập về nhà trước."},{"text":"A new gadget in many classrooms is a smart board.","ipa":"/ə nu ˈɡædʒət ɪn ˈmɛni ˈklæsˌrumz ɪz ə smɑrt bɔrd./","vi":"Một thiết bị mới trong nhiều lớp học là bảng thông minh."},{"text":"Students can write on it like a whiteboard, but it also connects to the internet.","ipa":"/ˈstudənts kæn raɪt ɑn ɪt laɪk ə ˈwaɪtˌbɔrd, bʌt ɪt ˈɔlsoʊ kəˈnɛkts tu ðə ˈɪntərˌnɛt./","vi":"Học sinh có thể viết lên đó như bảng trắng, nhưng nó còn có thể kết nối internet."},{"text":"Technology makes learning more fun, but students should not spend too much time on screens.","ipa":"/tɛkˈnɑlədʒi meɪks ˈlɜrnɪŋ mɔr fʌn, bʌt ˈstudənts ʃʊd nɑt spɛnd tu mʌtʃ taɪm ɑn skrinz./","vi":"Công nghệ giúp việc học thú vị hơn, nhưng học sinh không nên dành quá nhiều thời gian trước màn hình."},{"text":"It is important to also read books, play outside, and talk with friends.","ipa":"/ɪt ɪz ɪmˈpɔrtənt tu ˈɔlsoʊ rid bʊks, pleɪ ˈaʊtˌsaɪd, ænd tɔk wɪð frɛndz./","vi":"Điều quan trọng là cũng cần đọc sách, vui chơi ngoài trời và trò chuyện cùng bạn bè."}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'reading_comprehension',NULL,1550,'a1-s8','0ecee655f703454cb1aa6f209779f976',NULL,NULL,'2026-07-25T12:48:06.937Z',NULL);
