INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('bce05d1a-dff2-44bb-873a-a3345f8bbd57','1f7ded60-2b4c-4b17-b317-a5f1ae8db816',7,'multiple_choice','What should students also do besides using technology?','["Read books, play outside, and talk with friends", "Watch more TV", "Play more video games", "Sleep all day"]','Read books, play outside, and talk with friends',NULL,NULL,NULL,'Đoạn văn khuyên nên đọc sách, chơi ngoài trời, trò chuyện cùng bạn bè.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('b751dc06-03e3-46ab-ab0a-423a1979b078','1f7ded60-2b4c-4b17-b317-a5f1ae8db816',8,'fill_blank','Teachers use a computer and a ___ to show pictures.',NULL,NULL,'["projector"]','["projector", "camera", "phone"]',NULL,'Đoạn văn nói máy chiếu dùng để chiếu hình.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
