INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('31b96002-17a2-4e16-852a-dca7c674bdfd','1f7ded60-2b4c-4b17-b317-a5f1ae8db816',12,'matching','Match each gadget to its use.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng thiết bị với công dụng theo đoạn văn.',NULL,'[{"left": "tablet or laptop", "right": "for lessons"}, {"left": "smart board", "right": "like a whiteboard"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('9e35b16c-f0ae-498f-8b7c-0417c543ca63','1f7ded60-2b4c-4b17-b317-a5f1ae8db816',13,'matching','Match each tool to what it helps with.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng công cụ với công dụng theo đoạn văn.',NULL,'[{"left": "robots", "right": "help practice English"}, {"left": "app", "right": "for homework"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('01bafe58-2476-4fc2-8caf-d2c45ecac57d','1f7ded60-2b4c-4b17-b317-a5f1ae8db816',14,'categorize','Sort each activity into the correct group.',NULL,NULL,NULL,NULL,NULL,'Đọc sách, chơi ngoài trời, trò chuyện là thói quen tốt; chơi game cả ngày là dùng màn hình quá nhiều.',NULL,NULL,NULL,'["Good habit", "Too much screen time"]','[{"text": "read books", "category": "Good habit"}, {"text": "play outside", "category": "Good habit"}, {"text": "play video games all day", "category": "Too much screen time"}, {"text": "talk with friends", "category": "Good habit"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('b2763928-bbb1-4c30-acbb-cb1966bafb4e','a1-s8-16-mixed-checkpoint','Nghiệm thu A1',1,'mixed','A1 Movers',NULL,'Every year, my town has a big International Festival. This year, my friend Liam calls me on the phone. ''Hello, can I speak to you about the festival?'' he asks. ''Speaking!'' I say. Liam asks, ''Would you like to come with me?'' I say, ''I''d love to!'' We decide to invite our friend Zoe too. ''Let''s text her now,'' Liam says. He sends her a message, and she replies quickly. Zoe says she is busy but she will call back later. On the day of the festival, there are many fun activities. There is a running race, and my team is faster than the other team. There is also a music competition, and my team''s song is better than last year''s song. The festival is more popular every year, with more and more guests. It is a tradition to decorate the town square with flags from many countries. At the end, everyone says, ''This festival is easier to enjoy than any other day. Let''s celebrate together!''','[{"text":"Every year, my town has a big International Festival.","ipa":"/ˈɛvri jɪr, maɪ taʊn hæz ə bɪɡ ˌɪntərˈnæʃənəl ˈfɛstəvəl./","vi":"Mỗi năm, thị trấn của tôi đều tổ chức một Lễ hội Quốc tế lớn."},{"text":"This year, my friend Liam calls me on the phone.","ipa":"/ðɪs jɪr, maɪ frɛnd ˈliəm kɔlz mi ɑn ðə foʊn./","vi":"Năm nay, bạn tôi là Liam gọi điện cho tôi."},{"text":"''Hello, can I speak to you about the festival?'' he asks.","ipa":"/həˈloʊ, kæn aɪ spik tu ju əˈbaʊt ðə ˈfɛstəvəl? hi æsks./","vi":"\"Chào bạn, mình có thể nói chuyện với bạn về lễ hội được không?\" cậu ấy hỏi."},{"text":"''Speaking!'' I say.","ipa":"/ˈspikɪŋ! aɪ seɪ./","vi":"\"Mình đây!\" tôi trả lời."},{"text":"Liam asks, ''Would you like to come with me?''","ipa":"/ˈliəm æsks, wʊd ju laɪk tu kʌm wɪð mi?/","vi":"Liam hỏi: \"Bạn có muốn đi cùng mình không?\""},{"text":"I say, ''I''d love to!''","ipa":"/aɪ seɪ, aɪd lʌv tu!/","vi":"Tôi đáp: \"Mình rất sẵn lòng!\""},{"text":"We decide to invite our friend Zoe too.","ipa":"/wi dɪˈsaɪd tu ɪnˈvaɪt ˈaʊər frɛnd ˈzoʊi tu./","vi":"Chúng tôi quyết định rủ thêm bạn Zoe nữa."},{"text":"''Let''s text her now,'' Liam says.","ipa":"/lɛts tɛkst hər naʊ, ˈliəm sɛz./","vi":"\"Hãy nhắn tin cho cô ấy ngay bây giờ đi,\" Liam nói."},{"text":"He sends her a message, and she replies quickly.","ipa":"/hi sɛndz hər ə ˈmɛsɪdʒ, ænd ʃi rɪˈplaɪz ˈkwɪkli./","vi":"Cậu ấy gửi tin nhắn cho cô ấy, và cô ấy trả lời rất nhanh."},{"text":"Zoe says she is busy but she will call back later.","ipa":"/ˈzoʊi sɛz ʃi ɪz ˈbɪzi bʌt ʃi wɪl kɔl bæk ˈleɪtər./","vi":"Zoe nói rằng cô ấy đang bận nhưng sẽ gọi lại sau."},{"text":"On the day of the festival, there are many fun activities.","ipa":"/ɑn ðə deɪ ʌv ðə ˈfɛstəvəl, ðɛr ɑr ˈmɛni fʌn ækˈtɪvɪtiz./","vi":"Vào ngày diễn ra lễ hội, có rất nhiều hoạt động vui chơi."},{"text":"There is a running race, and my team is faster than the other team.","ipa":"/ðɛr ɪz ə ˈrʌnɪŋ reɪs, ænd maɪ tim ɪz ˈfæstər ðæn ði ˈʌðər tim./","vi":"Có một cuộc đua chạy bộ, và đội của tôi chạy nhanh hơn đội kia."},{"text":"There is also a music competition, and my team''s song is better than last year''s song.","ipa":"/ðɛr ɪz ˈɔlsoʊ ə ˈmjuzɪk ˌkɑmpəˈtɪʃən, ænd maɪ timz sɔŋ ɪz ˈbɛtər ðæn læst jɪrz sɔŋ./","vi":"Ngoài ra còn có cuộc thi âm nhạc, và bài hát của đội tôi hay hơn bài hát năm ngoái."},{"text":"The festival is more popular every year, with more and more guests.","ipa":"/ðə ˈfɛstəvəl ɪz mɔr ˈpɑpjələr ˈɛvri jɪr, wɪð mɔr ænd mɔr ɡɛsts./","vi":"Lễ hội ngày càng phổ biến hơn mỗi năm, với ngày càng nhiều khách tham quan."},{"text":"It is a tradition to decorate the town square with flags from many countries.","ipa":"/ɪt ɪz ə trəˈdɪʃən tu ˈdɛkəˌreɪt ðə taʊn skwɛr wɪð flæɡz frʌm ˈmɛni ˈkʌntriz./","vi":"Việc trang trí quảng trường thị trấn bằng cờ của nhiều quốc gia đã trở thành truyền thống."},{"text":"At the end, everyone says, ''This festival is easier to enjoy than any other day.","ipa":"/æt ði ɛnd, ˈɛvriˌwʌn sɛz, ðɪs ˈfɛstəvəl ɪz ˈiziər tu ɛnˈdʒɔɪ ðæn ˈɛni ˈʌðər deɪ./","vi":"Cuối cùng, mọi người đều nói: \"Lễ hội này dễ tận hưởng hơn bất kỳ ngày nào khác."},{"text":"Let''s celebrate together!''","ipa":"/lɛts ˈsɛləˌbreɪt təˈɡɛðər!/","vi":"Hãy cùng nhau ăn mừng nào!\""}]',NULL,'Every year, my town has a big International Festival. This year, my friend Liam calls me on the phone. ''Hello, can I speak to you about the festival?'' he asks. ''Speaking!'' I say. Liam asks, ''Would you like to come with me?'' I say, ''I''d love to!'' We decide to invite our friend Zoe too. ''Let''s text her now,'' Liam says. He sends her a message, and she replies quickly. Zoe says she is busy but she will call back later. On the day of the festival, there are many fun activities. There is a running race, and my team is faster than the other team. There is also a music competition, and my team''s song is better than last year''s song. The festival is more popular every year, with more and more guests. It is a tradition to decorate the town square with flags from many countries. At the end, everyone says, ''This festival is easier to enjoy than any other day. Let''s celebrate together!''',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mixed_all',NULL,1560,'a1-s8','173d3e218c4b4105acb75346b8ee9cef',NULL,NULL,'2026-07-25T12:48:06.937Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('c2f94560-3559-4334-8b19-60b2bccf118b','b2763928-bbb1-4c30-acbb-cb1966bafb4e',0,'multiple_choice','What does Liam ask on the phone first?','["Can I speak to you about the festival?", "Are you busy?", "What is your name?", "Do you like music?"]','Can I speak to you about the festival?',NULL,NULL,NULL,'Đoạn ghi Liam mở đầu bằng câu này.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('67dbf777-1f3c-4b89-a72c-bf4962099de9','b2763928-bbb1-4c30-acbb-cb1966bafb4e',1,'multiple_choice','What does the narrator say when Liam invites them?','["I''d love to!", "I''m afraid I can''t.", "No thanks.", "Maybe later."]','I''d love to!',NULL,NULL,NULL,'Đoạn ghi ''I say, "I''d love to!"''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('9909e24c-fe1a-4898-9068-40508772c270','b2763928-bbb1-4c30-acbb-cb1966bafb4e',2,'multiple_choice','Who do they decide to invite?','["Zoe", "Anna", "Mia", "Ben"]','Zoe',NULL,NULL,NULL,'Đoạn ghi ''We decide to invite our friend Zoe too.''',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('835dec8a-038b-470d-bc89-523c85032074','b2763928-bbb1-4c30-acbb-cb1966bafb4e',3,'multiple_choice','How does Liam contact Zoe?','["By text", "By post", "By letter", "In person"]','By text',NULL,NULL,NULL,'Đoạn ghi ''Let''s text her now''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('aa70ec8d-24aa-4bac-ad63-d5a37f934fe5','b2763928-bbb1-4c30-acbb-cb1966bafb4e',4,'multiple_choice','Why can''t Zoe come right away?','["She is busy", "She is sick", "She doesn''t like festivals", "She has no phone"]','She is busy',NULL,NULL,NULL,'Đoạn ghi ''Zoe says she is busy''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
