INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('4e80bc01-1d2c-4eeb-9902-4e5085052242','b2763928-bbb1-4c30-acbb-cb1966bafb4e',13,'matching','Match each event to what happens.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng hoạt động với kết quả theo đoạn văn.',NULL,'[{"left": "running race", "right": "the narrator''s team is faster"}, {"left": "music competition", "right": "the narrator''s team''s song is better"}]',NULL,NULL,NULL,NULL,NULL);
