INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('aaf75960-1287-4b55-bf2b-64960b40d9e9','b2763928-bbb1-4c30-acbb-cb1966bafb4e',15,'ordering','Put the words in the correct order.',NULL,'My team is faster',NULL,NULL,NULL,'Trật tự: chủ ngữ + be + tính từ so sánh hơn.',NULL,NULL,'["team", "is", "My", "faster"]',NULL,NULL,NULL,'comparative-adjectives');
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('ec8cd313-89be-46a2-8363-597c3d6bb730','b2763928-bbb1-4c30-acbb-cb1966bafb4e',16,'categorize','Sort each phrase into the correct group.',NULL,NULL,NULL,NULL,NULL,'Phân biệt câu dùng khi mời và câu dùng khi gọi điện.',NULL,NULL,NULL,'["Invitation", "Phone"]','[{"text": "Would you like to come?", "category": "Invitation"}, {"text": "Can I speak to you?", "category": "Phone"}, {"text": "I''d love to!", "category": "Invitation"}, {"text": "Speaking!", "category": "Phone"}]',NULL,NULL);
