INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('c1c380fa-d5fa-446a-92e2-5ec13e9b688e','a96e18b9-79a2-476a-9d19-f4540311aaa7',1,'multiple_choice','Does she have a new phone? — ___','["Yes, she does.", "Yes, she is.", "Yes, does she.", "Yes, she has."]','Yes, she does.',NULL,NULL,NULL,'Trả lời ngắn dùng ''does''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
