INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('513662c3-3498-4494-913d-f5ce03ecdc9e','a96e18b9-79a2-476a-9d19-f4540311aaa7',3,'multiple_choice','I''m afraid I ___.','["can''t", "don''t", "am not", "won''t"]','can''t',NULL,NULL,NULL,'''I''m afraid I can''t'' là cách từ chối lịch sự.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('45a15001-af39-4bbf-b5b8-bced88237232','a96e18b9-79a2-476a-9d19-f4540311aaa7',4,'multiple_choice','My team is ___ than yours.','["better", "good", "best", "well"]','better',NULL,NULL,NULL,'So sánh hơn bất quy tắc của ''good'' là ''better''.',NULL,NULL,NULL,NULL,NULL,NULL,'comparative-adjectives');
