INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('1cbb1847-7c7e-4a4e-b64e-c92bd64122cc','b23ddb72-a763-45ce-b0c6-48e105849b5c',16,'categorize','Sort each subject by its correct ''to be'' contraction.',NULL,NULL,NULL,NULL,NULL,'I→''m · he/she/it→''s · we/you/they→''re.',NULL,NULL,NULL,'["''m","''s","''re"]','[{"text":"I","category":"''m"},{"text":"He","category":"''s"},{"text":"We","category":"''re"},{"text":"She","category":"''s"},{"text":"They","category":"''re"},{"text":"It","category":"''s"}]',NULL,'verb-to-be');
