INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('08e5aa98-b81c-4560-acac-da925a3976a3','b23ddb72-a763-45ce-b0c6-48e105849b5c',18,'categorize','Sort each subject by its correct negative contraction.',NULL,NULL,NULL,NULL,NULL,'he/she/it→isn''t · we/you/they→aren''t.',NULL,NULL,NULL,'["isn''t","aren''t"]','[{"text":"He","category":"isn''t"},{"text":"They","category":"aren''t"},{"text":"It","category":"isn''t"},{"text":"We","category":"aren''t"},{"text":"She","category":"isn''t"},{"text":"You","category":"aren''t"}]',NULL,'verb-to-be');
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('924ab36d-af76-4370-a7ea-0d761dfbdaea','b23ddb72-a763-45ce-b0c6-48e105849b5c',19,'categorize','Sort each contracted sentence: singular or plural subject?',NULL,NULL,NULL,NULL,NULL,'I/he/she/it là số ít; we/you/they là số nhiều.',NULL,NULL,NULL,'["Singular","Plural"]','[{"text":"I''m a nurse.","category":"Singular"},{"text":"We''re friends.","category":"Plural"},{"text":"She''s from Peru.","category":"Singular"},{"text":"They''re at home.","category":"Plural"},{"text":"It''s a big dog.","category":"Singular"},{"text":"You''re welcome.","category":"Plural"}]',NULL,'verb-to-be');
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('caccfcd8-e5fa-4cf9-896a-d9c7713dcd15','prea1-s1-04-read-aloud-ii-i','Introducing Myself (/iː/ vs /ɪ/)',1,'reading','Pre A1 Starters',NULL,'Hello, everyone! Nice to meet you. My name is Kim. I am from a small city, but now I live in a big city with my family. I am sixteen years old, and I am a student. In my free time, I like to read books and eat sweet fruit with my sister. I feel happy when I sit and read a story in the evening. My sister is a teacher. She likes to teach English to little kids near our street. Every evening, we sit together and drink hot tea. We speak English and practice new words. I think it is nice to meet new people and make new friends. I hope we will meet again very soon. See you next week!','[{"text":"Hello, everyone!","ipa":"/həˈloʊ, ˈɛvriˌwʌn/","vi":"Chào mọi người!"},{"text":"Nice to meet you.","ipa":"/naɪs tu mit ju/","vi":"Rất vui được gặp các bạn."},{"text":"My name is Kim.","ipa":"/maɪ neɪm ɪz kɪm/","vi":"Tên mình là Kim."},{"text":"I am from a small city, but now I live in a big city with my family.","ipa":"/aɪ æm frʌm ə smɔl ˈsɪti, bʌt naʊ aɪ lɪv ɪn ə bɪg ˈsɪti wɪð maɪ ˈfæməli/","vi":"Mình đến từ một thành phố nhỏ, nhưng bây giờ mình đang sống ở một thành phố lớn cùng gia đình."},{"text":"I am sixteen years old, and I am a student.","ipa":"/aɪ æm ˌsɪkˈstin jɪrz oʊld, ænd aɪ æm ə ˈstudənt/","vi":"Mình mười sáu tuổi và mình là học sinh."},{"text":"In my free time, I like to read books and eat sweet fruit with my sister.","ipa":"/ɪn maɪ fri taɪm, aɪ laɪk tu rid bʊks ænd it swit frut wɪð maɪ ˈsɪstər/","vi":"Vào thời gian rảnh, mình thích đọc sách và ăn trái cây ngọt cùng chị gái."},{"text":"I feel happy when I sit and read a story in the evening.","ipa":"/aɪ fil ˈhæpi wɛn aɪ sɪt ænd rid ə ˈstɔri ɪn ði ˈivnɪŋ/","vi":"Mình cảm thấy rất vui khi ngồi đọc truyện vào buổi tối."},{"text":"My sister is a teacher.","ipa":"/maɪ ˈsɪstər ɪz ə ˈtitʃər/","vi":"Chị gái mình là giáo viên."},{"text":"She likes to teach English to little kids near our street.","ipa":"/ʃi laɪks tu titʃ ˈɪŋglɪʃ tu ˈlɪtəl kɪdz nɪr ˈaʊər strit/","vi":"Chị ấy thích dạy tiếng Anh cho các em nhỏ gần khu phố mình ở."},{"text":"Every evening, we sit together and drink hot tea.","ipa":"/ˈɛvri ˈivnɪŋ, wi sɪt təˈgɛðər ænd drɪŋk hɑt ti/","vi":"Mỗi tối, chúng mình ngồi cùng nhau và uống trà nóng."},{"text":"We speak English and practice new words.","ipa":"/wi spik ˈɪŋglɪʃ ænd ˈpræktɪs nu wɜrdz/","vi":"Chúng mình nói tiếng Anh và luyện tập từ mới."},{"text":"I think it is nice to meet new people and make new friends.","ipa":"/aɪ θɪŋk ɪt ɪz naɪs tu mit nu ˈpipəl ænd meɪk nu frɛndz/","vi":"Mình nghĩ thật tuyệt khi được gặp gỡ những người mới và kết thêm bạn mới."},{"text":"I hope we will meet again very soon.","ipa":"/aɪ hoʊp wi wɪl mit əˈgɛn ˈvɛri sun/","vi":"Mình hy vọng chúng ta sẽ sớm gặp lại nhau."},{"text":"See you next week!","ipa":"/si ju nɛkst wik/","vi":"Hẹn gặp lại bạn vào tuần tới nhé!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,40,'16b2ee0e-4f77-484c-8640-92a15dc9a471','264127e4120e4d2bb62236b78f0189b9',NULL,NULL,'2026-07-24T18:14:14.568Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('86215662-75c5-4b2a-a946-be14902a745f','prea1-s1-05-listen-choose','Meeting Someone New',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'A (M) [happy]: Hi! I''m Ben. What''s your name?
B (F) [happy]: Hello, Ben! I''m Lin. Nice to meet you.
A (M): Nice to meet you too, Lin. Where are you from?
B (F): I''m from Korea. And you?
A (M): I''m from Canada. What do you do, Lin?
B (F): I''m a nurse. I work at a big hospital in Seoul. What about you?
A (M): I''m a student. I study English and math.
B (F) [happy]: That''s great! How old are you?
A (M): I''m nineteen. And you?
B (F): I''m twenty-five.
A (M) [happy]: Nice! Is this your first time here?
B (F): Yes, it is. I''m here with my friend, Tom.
A (M): Oh, where is Tom from?
B (F): He''s from Australia. He''s a teacher.
A (M) [happy]: Wow, nice to meet both of you! See you around.
B (F) [happy]: See you, Ben! Bye!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,50,'16b2ee0e-4f77-484c-8640-92a15dc9a471','264127e4120e4d2bb62236b78f0189b9',NULL,NULL,'2026-07-24T18:14:14.568Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('376dce04-a51c-4c7e-a688-4a1b34e75a97','86215662-75c5-4b2a-a946-be14902a745f',0,'multiple_choice','What is the man''s name?','["Ben","Tom","Lin","Kim"]','Ben',NULL,NULL,NULL,'A nói ''I''m Ben'' ngay từ đầu.','A: Hi! I''m Ben. What''s your name?',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('a4728a62-00e0-482f-a16c-be71b5f30dc0','86215662-75c5-4b2a-a946-be14902a745f',1,'multiple_choice','Where is Lin from?','["Canada","Korea","Australia","Japan"]','Korea',NULL,NULL,NULL,'Lin nói ''I''m from Korea''.','A: Where are you from?
B: I''m from Korea.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('1ecf54d1-3170-4e0a-a158-baa92ee31202','86215662-75c5-4b2a-a946-be14902a745f',2,'multiple_choice','Where is Ben from?','["Korea","Canada","Australia","England"]','Canada',NULL,NULL,NULL,'Ben nói ''I''m from Canada''.','A: I''m from Canada. What do you do, Lin?',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('751f3c2b-6d11-430f-b570-dcde8bb45df5','86215662-75c5-4b2a-a946-be14902a745f',3,'multiple_choice','What is Lin''s job?','["Teacher","Student","Nurse","Doctor"]','Nurse',NULL,NULL,NULL,'Lin nói ''I''m a nurse''.','B: I''m a nurse. I work at a big hospital in Seoul.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('93cab311-4baf-482e-ab5c-2c4f0ecdeaaa','86215662-75c5-4b2a-a946-be14902a745f',4,'multiple_choice','Where does Lin work?','["At a school","At a big hospital","At a shop","At home"]','At a big hospital',NULL,NULL,NULL,'Lin nói làm ''at a big hospital in Seoul''.','B: I''m a nurse. I work at a big hospital in Seoul.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('1ca9062d-5d5c-4e13-a436-d0bf12cb7196','86215662-75c5-4b2a-a946-be14902a745f',5,'multiple_choice','What is Ben''s job?','["Nurse","Teacher","Student","Doctor"]','Student',NULL,NULL,NULL,'Ben nói ''I''m a student''.','A: I''m a student. I study English and math.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('2cbd83db-598d-42cb-8ada-248303990231','86215662-75c5-4b2a-a946-be14902a745f',6,'multiple_choice','How old is Ben?','["Nineteen","Twenty-five","Twenty","Sixteen"]','Nineteen',NULL,NULL,NULL,'Ben nói ''I''m nineteen''.','B: How old are you?
A: I''m nineteen.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('2a0a7250-b826-448c-8a58-046c27326176','86215662-75c5-4b2a-a946-be14902a745f',7,'multiple_choice','Who is Tom?','["Lin''s friend","Ben''s teacher","Lin''s brother","Ben''s boss"]','Lin''s friend',NULL,NULL,NULL,'Lin nói ''I''m here with my friend, Tom''.','B: I''m here with my friend, Tom.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('2972bbab-4581-4a21-a244-26604ffe3458','86215662-75c5-4b2a-a946-be14902a745f',8,'fill_blank','Ben''s friend, Lin, is from ___.',NULL,NULL,'["Korea"]','["Korea", "Canada", "Australia"]',NULL,'Lin nói ''I''m from Korea''.','B: I''m from Korea.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('c261e9b9-7c6d-453d-9d43-eab01a09d55a','86215662-75c5-4b2a-a946-be14902a745f',9,'fill_blank','Lin is twenty-five ___ old.',NULL,NULL,'["years"]','["years", "months", "days"]',NULL,'B nói ''I''m twenty-five''; đơn vị tuổi là ''years old''.','B: I''m twenty-five.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('03b2dba1-c71a-44c3-8aa4-006d56584633','86215662-75c5-4b2a-a946-be14902a745f',10,'fill_blank','Tom is from ___.',NULL,NULL,'["Australia"]','["Australia", "Korea", "Canada"]',NULL,'B nói ''He''s from Australia''.','A: Where is Tom from?
B: He''s from Australia.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('58d47b2e-6aaf-45b4-85f3-790a6896abc7','86215662-75c5-4b2a-a946-be14902a745f',11,'fill_blank','Tom''s job is ___.',NULL,NULL,'["teacher"]','["teacher", "nurse", "student"]',NULL,'B nói ''He''s a teacher''.','B: He''s from Australia. He''s a teacher.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('0f8aadf3-cb3c-4a42-96fc-868462a30184','86215662-75c5-4b2a-a946-be14902a745f',12,'fill_blank','Ben studies English and ___.',NULL,NULL,'["math"]','["math", "science", "art"]',NULL,'Ben nói ''I study English and math''.','A: I''m a student. I study English and math.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('bbae8bb2-92a6-4da3-bc53-2a841bea6146','86215662-75c5-4b2a-a946-be14902a745f',13,'matching','Match each name to their country.',NULL,NULL,NULL,NULL,NULL,'Ghép theo nội dung bài: "Ben" ↔ "Canada" (dựa trên: "I''m from Canada. What do you do, Lin?"); "Lin" ↔ "Korea" (dựa trên: "I''m from Korea. And you?"); "Tom" ↔ "Australia" (dựa trên: "He''s from Australia. He''s a teacher.").','A: I''m from Canada.
B: I''m from Korea.
B: He''s from Australia. (Tom)','[{"left":"Ben","right":"Canada"},{"left":"Lin","right":"Korea"},{"left":"Tom","right":"Australia"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('4dc14098-cfe7-4622-af42-a976a1289363','86215662-75c5-4b2a-a946-be14902a745f',14,'matching','Match each name to their job.',NULL,NULL,NULL,NULL,NULL,'Ghép theo nội dung bài: "Lin" ↔ "nurse" (dựa trên: "I''m a nurse. I work at a big hospital in Seoul. What about you?"); "Ben" ↔ "student" (dựa trên: "I''m a student. I study English and math."); "Tom" ↔ "teacher" (dựa trên: "He''s from Australia. He''s a teacher.").','A: I''m a student.
B: I''m a nurse.
B: He''s a teacher. (Tom)','[{"left":"Lin","right":"nurse"},{"left":"Ben","right":"student"},{"left":"Tom","right":"teacher"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('ab1e24e2-e0da-452a-89ef-574d53984c79','prea1-s1-06-grammar-subject-pronouns','Subject Pronouns',1,'grammar','Pre A1 Starters',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'grammar_drill',NULL,60,'16b2ee0e-4f77-484c-8640-92a15dc9a471','264127e4120e4d2bb62236b78f0189b9',NULL,NULL,'2026-07-24T18:14:14.568Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('14c3a034-c794-4091-9163-e39a31ce7ec4','ab1e24e2-e0da-452a-89ef-574d53984c79',0,'multiple_choice','Tom is a doctor. ___ works at a hospital.','["He","She","It","They"]','He',NULL,NULL,NULL,'Tom là bạn nam, thay bằng he.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('ac2a3d59-3413-4c36-aa81-fd7d488590a1','ab1e24e2-e0da-452a-89ef-574d53984c79',1,'multiple_choice','Anna is my sister. ___ is a teacher.','["He","She","It","We"]','She',NULL,NULL,NULL,'Anna là bạn nữ, thay bằng she.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('959fd9b0-a591-47ef-aa86-a3256a12b08c','ab1e24e2-e0da-452a-89ef-574d53984c79',2,'multiple_choice','This is my dog. ___ is very friendly.','["He","She","It","They"]','It',NULL,NULL,NULL,'Con vật/đồ vật thay bằng it.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('f7aff1a3-5549-40b6-a2e1-9c50ae2c026b','ab1e24e2-e0da-452a-89ef-574d53984c79',3,'multiple_choice','Ben and I are classmates. ___ study English together.','["I","You","We","They"]','We',NULL,NULL,NULL,'Ben và người nói (tôi) = we.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('b22ea5a8-51d2-4722-b23b-0ea24587049c','ab1e24e2-e0da-452a-89ef-574d53984c79',4,'multiple_choice','My parents are from Peru. ___ live in Lima.','["He","She","It","They"]','They',NULL,NULL,NULL,'Nhiều người (parents) thay bằng they.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('97d9410b-dcf2-4d2c-b8b2-8c8a6f50908b','ab1e24e2-e0da-452a-89ef-574d53984c79',5,'multiple_choice','Talking to a friend: ''___ are very kind.''','["I","You","He","It"]','You',NULL,NULL,NULL,'Nói trực tiếp với người nghe dùng you.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('9883b5e3-4af3-441f-908d-a99233f1bb3d','ab1e24e2-e0da-452a-89ef-574d53984c79',6,'multiple_choice','Which pronoun replaces ''my teacher'' (a man)?','["She","He","It","They"]','He',NULL,NULL,NULL,'Giáo viên nam thay bằng he.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('84dbab8c-3092-4e51-bc34-7f7d41547d2b','ab1e24e2-e0da-452a-89ef-574d53984c79',7,'multiple_choice','Which pronoun replaces ''the students'' (many people)?','["He","She","It","They"]','They',NULL,NULL,NULL,'Số nhiều thay bằng they.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('4000b88c-372c-4098-8e7c-4716c2a36f1a','ab1e24e2-e0da-452a-89ef-574d53984c79',8,'multiple_choice','Which sentence is correct?','["He are my friend.","He is my friend.","He am my friend.","He be my friend."]','He is my friend.',NULL,NULL,NULL,'He đi với is, không phải are/am.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('f7b2a9cf-65ab-43ae-9ed2-77aa2596c7c9','ab1e24e2-e0da-452a-89ef-574d53984c79',9,'fill_blank','Kim is a student. ___ is from Korea.',NULL,NULL,'["She"]','["She", "He", "It"]',NULL,'Kim ở đây là bạn nữ, thay bằng She.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('cfe46c52-56e7-4864-bb01-43246011af13','ab1e24e2-e0da-452a-89ef-574d53984c79',10,'fill_blank','This is my book. ___ is on the table.',NULL,NULL,'["It"]','["It", "She", "They"]',NULL,'Đồ vật (book) thay bằng It.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('b2bb217c-ea97-46a2-bb1f-64fca0738bdd','ab1e24e2-e0da-452a-89ef-574d53984c79',11,'fill_blank','You and Tom are friends. ___ often play football.',NULL,NULL,'["You"]','["You", "We", "They"]',NULL,'Nói với người nghe và người khác vẫn dùng You (số nhiều).',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('b3bd56c8-6456-4055-97ad-7bb2ada09ba8','ab1e24e2-e0da-452a-89ef-574d53984c79',12,'fill_blank','My brother is a driver. ___ works every day.',NULL,NULL,'["He"]','["He", "She", "It"]',NULL,'Brother là nam, thay bằng He.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('5c71f9d8-8a1a-4ce1-b5ea-d1cc1c54f799','ab1e24e2-e0da-452a-89ef-574d53984c79',13,'fill_blank','Lan and I are sisters. ___ live together.',NULL,NULL,'["We"]','["We", "You", "They"]',NULL,'Lan và người nói (tôi) = We.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('aa0b0acf-2672-412c-958e-190232792da8','ab1e24e2-e0da-452a-89ef-574d53984c79',14,'fill_blank','The cats are hungry. ___ want some food.',NULL,NULL,'["They"]','["They", "We", "It"]',NULL,'Con vật số nhiều thay bằng They.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('191d696d-035f-4163-9be8-d776d1fd7afc','ab1e24e2-e0da-452a-89ef-574d53984c79',15,'ordering','Put the words in the correct order.',NULL,'He is my brother',NULL,NULL,NULL,'Trật tự: S(He) + is + a/my + N.',NULL,NULL,'["is","my","He","brother"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('8bb23568-473f-43db-852c-fbd7af59c2cd','ab1e24e2-e0da-452a-89ef-574d53984c79',16,'ordering','Put the words in the correct order.',NULL,'They are students',NULL,NULL,NULL,'Trật tự: S(They) + are + N.',NULL,NULL,'["are","They","students"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('d739e097-f6a2-481b-a7bd-24ebb11a5a5e','ab1e24e2-e0da-452a-89ef-574d53984c79',17,'ordering','Put the words in the correct order.',NULL,'We are from Vietnam',NULL,NULL,NULL,'Trật tự: S(We) + are + from + N.',NULL,NULL,'["from","We","Vietnam","are"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('867b3b4f-27ea-4408-9898-68135f8e9ac9','ab1e24e2-e0da-452a-89ef-574d53984c79',18,'categorize','Sort each pronoun: singular or plural.',NULL,NULL,NULL,NULL,NULL,'I/he/she/it là số ít; we/they là số nhiều (you cả hai).',NULL,NULL,NULL,'["Singular","Plural"]','[{"text":"I","category":"Singular"},{"text":"he","category":"Singular"},{"text":"we","category":"Plural"},{"text":"they","category":"Plural"},{"text":"she","category":"Singular"},{"text":"it","category":"Singular"}]',NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('8e8700a2-9606-455d-ad70-9731e071dd6b','ab1e24e2-e0da-452a-89ef-574d53984c79',19,'categorize','Sort each noun by the pronoun that replaces it.',NULL,NULL,NULL,NULL,NULL,'Nam→he · nữ→she · vật/con vật số ít→it · số nhiều→they.',NULL,NULL,NULL,'["he","she","it","they"]','[{"text":"my father","category":"he"},{"text":"my mother","category":"she"},{"text":"the book","category":"it"},{"text":"my classmates","category":"they"},{"text":"the dog","category":"it"},{"text":"the girls","category":"they"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('163951c8-92c7-49d3-820b-b9e6b1272946','prea1-s1-07-listen-choose-variant','Welcome to Class',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'A (F) [happy]: Good morning! Welcome to our class. What''s your full name?
B (F): Good morning! My name is Sara Lopez. S-A-R-A, L-O-P-E-Z.
A (F): Nice to meet you, Sara. Are you Mrs. Lopez or Miss Lopez?
B (F): I''m single, so please call me Miss Lopez.
A (F): OK, Miss Lopez. Where do you live?
B (F): I live on Green Street, near the park.
A (F): Great. Can I have your email, please?
B (F): Yes, it''s sara dot lopez at mail dot com.
A (F): Thank you. And what''s your job?
B (F): I''m an engineer. I work at a technology company downtown.
A (F) [happy]: That''s wonderful. This is my colleague, Mr. Kim.
C (M) [happy]: Hello, Sara! Nice to meet you. I''m married, and I have two kids.
B (F) [happy]: Nice to meet you too, Mr. Kim.
A (F) [happy]: Welcome to everyone! Let''s start the lesson.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,70,'16b2ee0e-4f77-484c-8640-92a15dc9a471','264127e4120e4d2bb62236b78f0189b9',NULL,NULL,'2026-07-24T18:14:14.568Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('e2e89acb-43b7-4908-9dfa-d7416ec1bc3b','163951c8-92c7-49d3-820b-b9e6b1272946',0,'multiple_choice','What is the new student''s full name?','["Sara Lopez","Sara Kim","Lopez Green","Mia Lopez"]','Sara Lopez',NULL,NULL,NULL,'B nói ''My name is Sara Lopez''.','B: My name is Sara Lopez. S-A-R-A, L-O-P-E-Z.',NULL,NULL,NULL,NULL,NULL,NULL);
