INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('e47b5188-2253-4c58-adae-abb641e43bec','163951c8-92c7-49d3-820b-b9e6b1272946',9,'fill_blank','A introduces Sara to his ___, Mr. Kim.',NULL,NULL,'["colleague"]','["colleague", "friend", "brother"]',NULL,'A nói ''This is my colleague, Mr. Kim''.','A: This is my colleague, Mr. Kim.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('b2e3c83a-113e-499c-81ee-2d357513963a','163951c8-92c7-49d3-820b-b9e6b1272946',10,'fill_blank','Mr. Kim has two ___.',NULL,NULL,'["kids"]','["kids", "sisters", "brothers"]',NULL,'Mr. Kim nói ''I have two kids''.','C: I''m married, and I have two kids. (Mr. Kim)',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('fb683706-7b17-4b02-ae67-d7843deef8ac','163951c8-92c7-49d3-820b-b9e6b1272946',11,'fill_blank','Sara''s surname is ___.',NULL,NULL,'["Lopez"]','["Lopez", "Kim", "Green"]',NULL,'B nói tên đầy đủ ''Sara Lopez''.','B: My name is Sara Lopez. S-A-R-A, L-O-P-E-Z.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('f6ad0d2e-b96b-4e9e-acdc-2f5b6a67a184','163951c8-92c7-49d3-820b-b9e6b1272946',12,'matching','Match each person to the correct information.',NULL,NULL,NULL,NULL,NULL,'Ghép theo nội dung bài: "Sara" ↔ "single, engineer" (dựa trên: "I''m single, so please call me Miss Lopez."); "Mr. Kim" ↔ "married, two kids" (dựa trên: "Hello, Sara! Nice to meet you. I''m married, and I have two kids."); "A" ↔ "welcomes new students".','B: I''m an engineer.
C: I''m married, and I have two kids.
A: Welcome to our class.','[{"left":"Sara","right":"single, engineer"},{"left":"Mr. Kim","right":"married, two kids"},{"left":"A","right":"welcomes new students"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('dd7fc4d6-57ab-448a-a135-301821407cab','163951c8-92c7-49d3-820b-b9e6b1272946',13,'matching','Match each phrase to its meaning.',NULL,NULL,NULL,NULL,NULL,'Ghép theo nội dung bài: "full name" ↔ "họ tên đầy đủ" (dựa trên: "Good morning! Welcome to our class. What''s your full name?"); "colleague" ↔ "đồng nghiệp" (dựa trên: "That''s wonderful. This is my colleague, Mr. Kim."); "married" ↔ "đã kết hôn" (dựa trên: "Hello, Sara! Nice to meet you. I''m married, and I have two kids.").','A: What''s your full name?
A: This is my colleague, Mr. Kim.
C: I''m married, and I have two kids.','[{"left":"full name","right":"họ tên đầy đủ"},{"left":"colleague","right":"đồng nghiệp"},{"left":"married","right":"đã kết hôn"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('255312fb-fb47-49dd-a558-6bca2495a37f','163951c8-92c7-49d3-820b-b9e6b1272946',14,'matching','Match each question to the correct answer.',NULL,NULL,NULL,NULL,NULL,'Ghép theo nội dung bài: "What''s your full name?" ↔ "My name is Sara Lopez." (dựa trên: "Good morning! My name is Sara Lopez. S-A-R-A, L-O-P-E-Z."); "Where do you live?" ↔ "I live on Green Street." (dựa trên: "I live on Green Street, near the park."); "What''s your job?" ↔ "I''m an engineer." (dựa trên: "I''m an engineer. I work at a technology company downtown.").','A: What''s your full name?
B: My name is Sara Lopez.
A: Where do you live?
B: I live on Green Street.
A: What''s your job?
B: I''m an engineer.','[{"left":"What''s your full name?","right":"My name is Sara Lopez."},{"left":"Where do you live?","right":"I live on Green Street."},{"left":"What''s your job?","right":"I''m an engineer."}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('c6cde67b-c467-4b33-9edf-a87d8758180b','prea1-s1-09-read-aloud-final-sounds','Introducing Myself (final sounds)',1,'reading','Pre A1 Starters',NULL,'Hi! My name is Sam. I have a good job at a small company. I work from home in a quiet room. I am a student too, and I study with my friend, Kim, from my hometown. We come to class and talk with our teacher every morning. Thanks to my teacher, I can read many books and learn new words from him. I like to talk and thank people every day, and I like to help them. My mom and dad live near my home, from Monday to Sunday, and I visit them from time to time. Thanks for your time today, and thanks for coming to my class. See you again soon, my friend! Thanks, and goodbye!','[{"text":"Hi!","ipa":"/haɪ/","vi":"Chào bạn!"},{"text":"My name is Sam.","ipa":"/maɪ neɪm ɪz sæm/","vi":"Tên tôi là Sam."},{"text":"I have a good job at a small company.","ipa":"/aɪ hæv ə ɡʊd dʒɑb æt ə smɔl ˈkʌmpəni/","vi":"Tôi có một công việc tốt tại một công ty nhỏ."},{"text":"I work from home in a quiet room.","ipa":"/aɪ wɜrk frʌm hoʊm ɪn ə ˈkwaɪət rum/","vi":"Tôi làm việc tại nhà trong một căn phòng yên tĩnh."},{"text":"I am a student too, and I study with my friend, Kim, from my hometown.","ipa":"/aɪ æm ə ˈstudənt tu, ænd aɪ ˈstʌdi wɪð maɪ frɛnd, kɪm, frʌm maɪ ˈhoʊmˌtaʊn/","vi":"Tôi cũng là một học sinh, và tôi học cùng với bạn tôi, Kim, người đến từ quê hương tôi."},{"text":"We come to class and talk with our teacher every morning.","ipa":"/wi kʌm tu klæs ænd tɔk wɪð ˈaʊər ˈtitʃər ˈɛvəri ˈmɔrnɪŋ/","vi":"Chúng tôi đến lớp và trò chuyện với thầy giáo mỗi sáng."},{"text":"Thanks to my teacher, I can read many books and learn new words from him.","ipa":"/θæŋks tu maɪ ˈtitʃər, aɪ kæn rid ˈmɛni bʊks ænd lɜrn nu wɜrdz frʌm hɪm/","vi":"Nhờ thầy giáo, tôi có thể đọc nhiều sách và học thêm từ mới từ thầy."},{"text":"I like to talk and thank people every day, and I like to help them.","ipa":"/aɪ laɪk tu tɔk ænd θæŋk ˈpipəl ˈɛvəri deɪ, ænd aɪ laɪk tu hɛlp ðɛm/","vi":"Tôi thích trò chuyện và cảm ơn mọi người mỗi ngày, và tôi thích giúp đỡ họ."},{"text":"My mom and dad live near my home, from Monday to Sunday, and I visit them from time to time.","ipa":"/maɪ mɑm ænd dæd lɪv nɪr maɪ hoʊm, frʌm ˈmʌndeɪ tu ˈsʌndeɪ, ænd aɪ ˈvɪzɪt ðɛm frʌm taɪm tu taɪm/","vi":"Bố mẹ tôi sống gần nhà tôi, từ thứ Hai đến Chủ Nhật, và tôi thỉnh thoảng ghé thăm họ."},{"text":"Thanks for your time today, and thanks for coming to my class.","ipa":"/θæŋks fɔr jʊər taɪm təˈdeɪ, ænd θæŋks fɔr ˈkʌmɪŋ tu maɪ klæs/","vi":"Cảm ơn bạn đã dành thời gian hôm nay, và cảm ơn bạn đã đến lớp của tôi."},{"text":"See you again soon, my friend!","ipa":"/si ju əˈɡɛn sun, maɪ frɛnd/","vi":"Hẹn sớm gặp lại bạn nhé!"},{"text":"Thanks, and goodbye!","ipa":"/θæŋks, ænd ˌɡʊdˈbaɪ/","vi":"Cảm ơn, và tạm biệt!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,90,'16b2ee0e-4f77-484c-8640-92a15dc9a471','264127e4120e4d2bb62236b78f0189b9',NULL,NULL,'2026-07-24T18:14:14.568Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('1897a749-8057-49a4-9e63-2c3a027d99e5','prea1-s1-10-reading-comprehension','Anna and Her Friends',1,'reading','Pre A1 Starters',NULL,'This is Anna. She is twenty-two years old, and she is from Spain. Anna is a nurse. She works at a big hospital in Madrid. She lives with her brother, Carlos. Carlos is twenty-five. He is an engineer, and he works for a technology company. Anna has a good friend named Mia. Mia is from Italy. She is twenty years old, and she is a student. Mia studies English and French at university. Every Saturday, Anna, Carlos, and Mia meet at a small cafe near the park. They drink tea and talk about their week. Anna''s teacher is Mr. Brown. He is from England, and he is fifty years old. He teaches English on Monday and Wednesday. Anna likes her class very much. She wants to be a good nurse and help many people. On Sundays, Anna calls her parents in Spain. She tells them about her new friends and her happy life in the city.','[{"text":"This is Anna.","ipa":"/ðɪs ɪz ˈænə./","vi":"Đây là Anna."},{"text":"She is twenty-two years old, and she is from Spain.","ipa":"/ʃi ɪz ˈtwɛntiˈtu jɪrz oʊld, ænd ʃi ɪz frʌm speɪn./","vi":"Cô ấy 22 tuổi và đến từ Tây Ban Nha."},{"text":"Anna is a nurse.","ipa":"/ˈænə ɪz ə nɜrs./","vi":"Anna là một y tá."},{"text":"She works at a big hospital in Madrid.","ipa":"/ʃi wɜrks æt ə bɪg ˈhɑspɪtəl ɪn məˈdrɪd./","vi":"Cô ấy làm việc tại một bệnh viện lớn ở Madrid."},{"text":"She lives with her brother, Carlos.","ipa":"/ʃi lɪvz wɪð hɜr ˈbrʌðər, ˈkɑrloʊs./","vi":"Cô ấy sống cùng anh trai mình, Carlos."},{"text":"Carlos is twenty-five.","ipa":"/ˈkɑrloʊs ɪz ˈtwɛntiˈfaɪv./","vi":"Carlos 25 tuổi."},{"text":"He is an engineer, and he works for a technology company.","ipa":"/hi ɪz ən ˌɛndʒɪˈnɪr, ænd hi wɜrks fɔr ə tɛkˈnɑlədʒi ˈkʌmpəni./","vi":"Anh ấy là kỹ sư và làm việc cho một công ty công nghệ."},{"text":"Anna has a good friend named Mia.","ipa":"/ˈænə hæz ə gʊd frɛnd neɪmd ˈmiə./","vi":"Anna có một người bạn tốt tên là Mia."},{"text":"Mia is from Italy.","ipa":"/ˈmiə ɪz frʌm ˈɪtəli./","vi":"Mia đến từ Ý."},{"text":"She is twenty years old, and she is a student.","ipa":"/ʃi ɪz ˈtwɛnti jɪrz oʊld, ænd ʃi ɪz ə ˈstudənt./","vi":"Cô ấy 20 tuổi và là sinh viên."},{"text":"Mia studies English and French at university.","ipa":"/ˈmiə ˈstʌdiz ˈɪŋglɪʃ ænd frɛntʃ æt ˌjunɪˈvɜrsɪti./","vi":"Mia học tiếng Anh và tiếng Pháp tại trường đại học."},{"text":"Every Saturday, Anna, Carlos, and Mia meet at a small cafe near the park.","ipa":"/ˈɛvri ˈsætərdeɪ, ˈænə, ˈkɑrloʊs, ænd ˈmiə mit æt ə smɔl kæˈfeɪ nɪr ðə pɑrk./","vi":"Mỗi thứ Bảy, Anna, Carlos và Mia gặp nhau tại một quán cà phê nhỏ gần công viên."},{"text":"They drink tea and talk about their week.","ipa":"/ðeɪ drɪŋk ti ænd tɔk əˈbaʊt ðɛr wik./","vi":"Họ uống trà và trò chuyện về tuần vừa qua của mình."},{"text":"Anna''s teacher is Mr. Brown.","ipa":"/ˈænəz ˈtitʃər ɪz ˈmɪstər braʊn./","vi":"Giáo viên của Anna là ông Brown."},{"text":"He is from England, and he is fifty years old.","ipa":"/hi ɪz frʌm ˈɪŋglənd, ænd hi ɪz ˈfɪfti jɪrz oʊld./","vi":"Ông ấy đến từ Anh và 50 tuổi."},{"text":"He teaches English on Monday and Wednesday.","ipa":"/hi ˈtitʃəz ˈɪŋglɪʃ ɑn ˈmʌndeɪ ænd ˈwɛnzdeɪ./","vi":"Ông ấy dạy tiếng Anh vào thứ Hai và thứ Tư."},{"text":"Anna likes her class very much.","ipa":"/ˈænə laɪks hɜr klæs ˈvɛri mʌtʃ./","vi":"Anna rất thích lớp học của mình."},{"text":"She wants to be a good nurse and help many people.","ipa":"/ʃi wɑnts tu bi ə gʊd nɜrs ænd hɛlp ˈmɛni ˈpipəl./","vi":"Cô ấy muốn trở thành một y tá giỏi và giúp đỡ nhiều người."},{"text":"On Sundays, Anna calls her parents in Spain.","ipa":"/ɑn ˈsʌndeɪz, ˈænə kɔlz hɜr ˈpɛrənts ɪn speɪn./","vi":"Vào các ngày Chủ nhật, Anna gọi điện cho bố mẹ ở Tây Ban Nha."},{"text":"She tells them about her new friends and her happy life in the city.","ipa":"/ʃi tɛlz ðɛm əˈbaʊt hɜr nu frɛndz ænd hɜr ˈhæpi laɪf ɪn ðə ˈsɪti./","vi":"Cô ấy kể cho họ nghe về những người bạn mới và cuộc sống hạnh phúc của mình ở thành phố."}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'reading_comprehension',NULL,100,'16b2ee0e-4f77-484c-8640-92a15dc9a471','264127e4120e4d2bb62236b78f0189b9',NULL,NULL,'2026-07-24T18:14:14.568Z',NULL);
