INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('897a5f65-3feb-46cf-b85c-c6f348c4aa9e','1897a749-8057-49a4-9e63-2c3a027d99e5',3,'multiple_choice','Who is Carlos?','["Anna''s brother","Anna''s teacher","Mia''s brother","Anna''s father"]','Anna''s brother',NULL,NULL,NULL,'Đoạn ghi ''She lives with her brother, Carlos''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
