INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('92615c46-badb-45da-9b03-2b305256802b','1897a749-8057-49a4-9e63-2c3a027d99e5',6,'multiple_choice','What does Mia study?','["Math and science","English and French","History and art","Music and math"]','English and French',NULL,NULL,NULL,'Đoạn ghi ''Mia studies English and French''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('dfe25553-2f59-4218-b38a-a44131b02df5','1897a749-8057-49a4-9e63-2c3a027d99e5',7,'multiple_choice','When do Anna, Carlos, and Mia meet at the cafe?','["Every Saturday","Every Sunday","Every Monday","Every Wednesday"]','Every Saturday',NULL,NULL,NULL,'Đoạn ghi ''Every Saturday, Anna, Carlos, and Mia meet''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('8bb5d402-bf27-45da-91a4-222039fe1578','1897a749-8057-49a4-9e63-2c3a027d99e5',8,'fill_blank','Anna works at a big ___ in Madrid.',NULL,NULL,'["hospital"]','["hospital", "school", "company"]',NULL,'Đoạn ghi ''She works at a big hospital in Madrid''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('055c1e2e-5c14-422b-a6fe-f2138a3f0b3c','1897a749-8057-49a4-9e63-2c3a027d99e5',9,'fill_blank','Anna''s teacher, Mr. Brown, is from ___.',NULL,NULL,'["England"]','["England", "Spain", "Italy"]',NULL,'Đoạn ghi ''He is from England''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('9417934d-4030-4466-b84f-0249adf0b3b8','1897a749-8057-49a4-9e63-2c3a027d99e5',10,'fill_blank','Mr. Brown teaches English on Monday and ___.',NULL,NULL,'["Wednesday"]','["Wednesday", "Friday", "Tuesday"]',NULL,'Đoạn ghi ''He teaches English on Monday and Wednesday''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('1ade029a-97da-468e-9e89-620a6f8f544e','1897a749-8057-49a4-9e63-2c3a027d99e5',11,'fill_blank','On Sundays, Anna calls her ___ in Spain.',NULL,NULL,'["parents"]','["parents", "friends", "brother"]',NULL,'Đoạn ghi ''Anna calls her parents in Spain''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('03c798f5-e2ef-447b-adb5-403532877672','1897a749-8057-49a4-9e63-2c3a027d99e5',12,'matching','Match each person to their country.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng theo nghĩa/chức năng: "Anna" ↔ "Spain"; "Mia" ↔ "Italy"; "Mr. Brown" ↔ "England".',NULL,'[{"left":"Anna","right":"Spain"},{"left":"Mia","right":"Italy"},{"left":"Mr. Brown","right":"England"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('1ec604f9-309a-4e3c-b674-55f98c9b64cd','1897a749-8057-49a4-9e63-2c3a027d99e5',13,'matching','Match each person to their job.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng theo nghĩa/chức năng: "Anna" ↔ "nurse"; "Carlos" ↔ "engineer"; "Mia" ↔ "student".',NULL,'[{"left":"Anna","right":"nurse"},{"left":"Carlos","right":"engineer"},{"left":"Mia","right":"student"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('e1a766b1-dbe9-4150-8323-9a32c219fe0d','1897a749-8057-49a4-9e63-2c3a027d99e5',14,'categorize','Sort each person by age: under 25 or 25 and over.',NULL,NULL,NULL,NULL,NULL,'So tuổi với mốc 25: Anna 22 và Mia 20 dưới 25; Carlos 25 và Mr. Brown 50 từ 25 trở lên.',NULL,NULL,NULL,'["Under 25","25 and over"]','[{"text":"Anna","category":"Under 25"},{"text":"Carlos","category":"25 and over"},{"text":"Mia","category":"Under 25"},{"text":"Mr. Brown","category":"25 and over"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('278f7ad0-c3c8-43a7-82ef-227cc0e21d05','prea1-s1-11-reading-comprehension-variant','New Students in Class 5B',1,'reading','Pre A1 Starters',NULL,'Welcome to English Class 5B! There are four new students today. Ben is nineteen years old, and he is from Canada. He wants to be a doctor. Lin is eighteen, and she is from Korea. She is friendly, and she loves music. Omar is twenty years old. He is from Egypt, and he works part-time in a shop. He is single. Mia is twenty-two, and she is from Italy. She is married, and she has one daughter. The teacher, Mrs. Green, is from the United States. She is forty-five years old, and she has taught English for twenty years. Every student says hello and tells the class about their country and their job. After that, they play a game to remember names. Everyone is happy to make new friends in this class. Mrs. Green says, ''Please introduce yourself to your neighbor now.'' The students smile and start talking to each other.','[{"text":"Welcome to English Class 5B!","ipa":"/ˈwɛlkəm tu ˈɪŋɡlɪʃ klæs faɪv bi/","vi":"Chào mừng các em đến với lớp Tiếng Anh 5B!"},{"text":"There are four new students today.","ipa":"/ðɛr ɑr fɔr nu ˈstudənts təˈdeɪ/","vi":"Hôm nay lớp chúng ta có bốn học sinh mới."},{"text":"Ben is nineteen years old, and he is from Canada.","ipa":"/bɛn ɪz ˌnaɪnˈtin jɪrz oʊld, ænd hi ɪz frʌm ˈkænədə/","vi":"Ben mười chín tuổi và cậu ấy đến từ Canada."},{"text":"He wants to be a doctor.","ipa":"/hi wɑnts tu bi ə ˈdɑktər/","vi":"Cậu ấy muốn trở thành bác sĩ."},{"text":"Lin is eighteen, and she is from Korea.","ipa":"/lɪn ɪz ˌeɪˈtin, ænd ʃi ɪz frʌm kəˈriə/","vi":"Lin mười tám tuổi và cô ấy đến từ Hàn Quốc."},{"text":"She is friendly, and she loves music.","ipa":"/ʃi ɪz ˈfrɛndli, ænd ʃi lʌvz ˈmjuzɪk/","vi":"Cô ấy rất thân thiện và yêu âm nhạc."},{"text":"Omar is twenty years old.","ipa":"/ˈoʊmɑr ɪz ˈtwɛnti jɪrz oʊld/","vi":"Omar hai mươi tuổi."},{"text":"He is from Egypt, and he works part-time in a shop.","ipa":"/hi ɪz frʌm ˈiʤɪpt, ænd hi wɜrks ˈpɑrtˌtaɪm ɪn ə ʃɑp/","vi":"Cậu ấy đến từ Ai Cập và làm việc bán thời gian tại một cửa hàng."},{"text":"He is single.","ipa":"/hi ɪz ˈsɪŋɡəl/","vi":"Cậu ấy vẫn còn độc thân."},{"text":"Mia is twenty-two, and she is from Italy.","ipa":"/miə ɪz ˌtwɛntiˈtu, ænd ʃi ɪz frʌm ˈɪtəli/","vi":"Mia hai mươi hai tuổi và cô ấy đến từ Ý."},{"text":"She is married, and she has one daughter.","ipa":"/ʃi ɪz ˈmɛrid, ænd ʃi hæz wʌn ˈdɔtər/","vi":"Cô ấy đã kết hôn và có một cô con gái."},{"text":"The teacher, Mrs. Green, is from the United States.","ipa":"/ðə ˈtitʃər, ˈmɪsɪz ɡrin, ɪz frʌm ðə juˈnaɪtəd steɪts/","vi":"Giáo viên, cô Green, đến từ Hoa Kỳ."},{"text":"She is forty-five years old, and she has taught English for twenty years.","ipa":"/ʃi ɪz ˌfɔrtiˈfaɪv jɪrz oʊld, ænd ʃi hæz tɔt ˈɪŋɡlɪʃ fɔr ˈtwɛnti jɪrz/","vi":"Cô ấy bốn mươi lăm tuổi và đã dạy Tiếng Anh được hai mươi năm."},{"text":"Every student says hello and tells the class about their country and their job.","ipa":"/ˈɛvəri ˈstudənt sɛz həˈloʊ ænd tɛlz ðə klæs əˈbaʊt ðɛr ˈkʌntri ænd ðɛr ʤɑb/","vi":"Mỗi học sinh đều chào hỏi và giới thiệu với cả lớp về đất nước và công việc của mình."},{"text":"After that, they play a game to remember names.","ipa":"/ˈæftər ðæt, ðeɪ pleɪ ə ɡeɪm tu rɪˈmɛmbər neɪmz/","vi":"Sau đó, họ chơi một trò chơi để ghi nhớ tên của nhau."},{"text":"Everyone is happy to make new friends in this class.","ipa":"/ˈɛvriwʌn ɪz ˈhæpi tu meɪk nu frɛndz ɪn ðɪs klæs/","vi":"Ai cũng vui vẻ khi có thêm những người bạn mới trong lớp học này."},{"text":"Mrs. Green says, ''Please introduce yourself to your neighbor now.''","ipa":"/ˈmɪsɪz ɡrin sɛz, pliz ˌɪntrəˈdus jʊərˈsɛlf tu jʊər ˈneɪbər naʊ/","vi":"Cô Green nói: ''Bây giờ các em hãy giới thiệu bản thân với người ngồi cạnh mình nhé.''"},{"text":"The students smile and start talking to each other.","ipa":"/ðə ˈstudənts smaɪl ænd stɑrt ˈtɔkɪŋ tu itʃ ˈʌðər/","vi":"Các học sinh mỉm cười và bắt đầu trò chuyện với nhau."}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'reading_comprehension',NULL,110,'16b2ee0e-4f77-484c-8640-92a15dc9a471','264127e4120e4d2bb62236b78f0189b9',NULL,NULL,'2026-07-24T18:14:14.568Z',NULL);
