INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('be6b1ae4-1614-4971-ba0d-f27a4b111dc0','prea1-s1-16-listen-small-talk','How Are You Today?',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'A (M) [happy]: Hi, Mia! Long time no see. How are you?
B (F): Hi, Ben! I''m fine, thank you. And you?
A (M): I''m great, thanks. Are you a student here now?
B (F): Yes, I am. This is my first day. I''m a little nervous.
A (M) [happy]: Don''t worry. This is my friend, Lin. Lin, this is Mia.
C (F) [happy]: Nice to meet you, Mia.
B (F) [happy]: Nice to meet you too, Lin.
C (F): Where are you from, Mia?
B (F): I''m from Canada, but my family lives in Spain now.
C (F): That''s interesting. How old are you?
B (F): I''m twelve years old. My birthday is in May.
A (M): Our English class starts at nine. See you there!
B (F) [happy]: Thank you very much. Have a nice day!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,115,'16b2ee0e-4f77-484c-8640-92a15dc9a471','264127e4120e4d2bb62236b78f0189b9',NULL,NULL,'2026-07-29T10:23:33.129Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('dbda6ca5-c261-44e7-9efb-b26db2e7be7f','be6b1ae4-1614-4971-ba0d-f27a4b111dc0',0,'multiple_choice','How does Mia feel on her first day?','["Happy", "A little nervous", "Angry", "Tired"]','A little nervous',NULL,NULL,NULL,'Mia nói ''I''m a little nervous''.','B: This is my first day. I''m a little nervous.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('99642efd-8493-464c-83e2-4e883fc39f37','be6b1ae4-1614-4971-ba0d-f27a4b111dc0',1,'multiple_choice','Who is Ben''s friend?','["Mia", "Lin", "Anna", "Sara"]','Lin',NULL,NULL,NULL,'Ben giới thiệu ''This is my friend, Lin''.','A: This is my friend, Lin.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('6e60c4fe-6598-401e-b496-8b3fec07065b','be6b1ae4-1614-4971-ba0d-f27a4b111dc0',2,'multiple_choice','Where is Mia from?','["Spain", "Canada", "England", "Australia"]','Canada',NULL,NULL,NULL,'Mia nói ''I''m from Canada''.','B: I''m from Canada, but my family lives in Spain now.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('7d8e4554-c052-4154-b34f-14a0ce673eea','be6b1ae4-1614-4971-ba0d-f27a4b111dc0',3,'multiple_choice','Where does Mia''s family live now?','["Canada", "Spain", "England", "Australia"]','Spain',NULL,NULL,NULL,'Gia đình Mia sống ở Spain.','B: ...but my family lives in Spain now.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('60400a20-5dc8-4649-be98-3e369e3320cf','be6b1ae4-1614-4971-ba0d-f27a4b111dc0',4,'multiple_choice','How old is Mia?','["Nine", "Ten", "Twelve", "Fifteen"]','Twelve',NULL,NULL,NULL,'Mia nói ''twelve years old''.','B: I''m twelve years old.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('b23b7c09-1edc-4376-ab8a-23a890bab25a','be6b1ae4-1614-4971-ba0d-f27a4b111dc0',5,'multiple_choice','When is Mia''s birthday?','["In March", "In May", "In June", "In July"]','In May',NULL,NULL,NULL,'Mia nói ''in May''.','B: My birthday is in May.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('c5c4ad1e-261b-40a4-b203-63bb97bc41aa','be6b1ae4-1614-4971-ba0d-f27a4b111dc0',6,'multiple_choice','What time does the English class start?','["At eight", "At nine", "At ten", "At eleven"]','At nine',NULL,NULL,NULL,'Ben nói lớp bắt đầu ''at nine''.','A: Our English class starts at nine.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('cbc303be-db2a-4e1f-9726-1b2b12c5925d','be6b1ae4-1614-4971-ba0d-f27a4b111dc0',7,'multiple_choice','What does Ben say when he sees Mia?','["Good night", "Long time no see", "Take care", "See you later"]','Long time no see',NULL,NULL,NULL,'Ben mở đầu bằng ''Long time no see''.','A: Hi, Mia! Long time no see.',NULL,NULL,NULL,NULL,NULL,NULL);
