INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('0fe54106-fe9e-4885-a157-bf1d51fe89ec','be6b1ae4-1614-4971-ba0d-f27a4b111dc0',9,'fill_blank','I''m fine, thank you. And ___?',NULL,NULL,'["you"]',NULL,NULL,'Hỏi lại bằng ''And you?''.','B: I''m fine, thank you. And you?',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('7e0ca6f4-0ffc-4cf2-a97f-dd581b5bd2e2','be6b1ae4-1614-4971-ba0d-f27a4b111dc0',10,'fill_blank','Nice to meet you ___.',NULL,NULL,'["too"]',NULL,NULL,'Đáp lại lời làm quen bằng ''too''.','B: Nice to meet you too, Lin.',NULL,NULL,NULL,NULL,NULL,NULL);
