INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('bae1ffcc-d47c-4932-84c5-4740f6447386','be6b1ae4-1614-4971-ba0d-f27a4b111dc0',13,'matching','Match each person to a fact about them.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng nhân vật với chi tiết trong hội thoại.','Mia: I''m twelve years old. / A: This is my friend, Lin. / A: Long time no see.','[{"left": "Mia", "right": "is twelve years old"}, {"left": "Lin", "right": "is Ben''s friend"}, {"left": "Ben", "right": "says ''Long time no see''"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('760f6dde-7a78-4e9a-b07b-e19cd28df6a2','be6b1ae4-1614-4971-ba0d-f27a4b111dc0',14,'matching','Match each question to its reply.',NULL,NULL,NULL,NULL,NULL,'Ghép câu hỏi chào hỏi với câu trả lời tương ứng.','How are you? - I''m fine, thank you. / Nice to meet you - Nice to meet you too. / Where are you from? - I''m from Canada.','[{"left": "How are you?", "right": "I''m fine, thank you."}, {"left": "Nice to meet you.", "right": "Nice to meet you too."}, {"left": "Where are you from?", "right": "I''m from Canada."}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('89472130-38d5-40d3-8eb0-320ef6adec21','prea1-s1-14-mixed-checkpoint','Meet the New Students',1,'mixed','Pre A1 Starters',NULL,'Hi! My name is Sophie Turner. I''m nineteen years old, and I''m from London, England. I''m a student at a language school.
This is my friend Marco Rossi. He''s twenty-two, and he''s from Rome, Italy. He''s a chef at a small restaurant.
Next to him is Emma Clark. She''s twenty years old, and she''s from Toronto, Canada. She''s a nurse at a big hospital.
And this is Daniel Kim. He''s twenty-one, and he''s from Seattle, in the United States. He''s an engineer.
We are all new students here. We''re happy to meet each other. Sophie and Emma are friends now, and Marco and Daniel are friends too. Nice to meet you all!','[{"text":"Hi!","ipa":"/haɪ/","vi":"Chào bạn!"},{"text":"My name is Sophie Turner.","ipa":"/maɪ neɪm ɪz ˈsoʊfi ˈtɜrnər/","vi":"Tên mình là Sophie Turner."},{"text":"I''m nineteen years old, and I''m from London, England.","ipa":"/aɪm ˌnaɪnˈtin jɪrz oʊld, ænd aɪm frʌm ˈlʌndən, ˈɪŋɡlənd/","vi":"Mình mười chín tuổi và mình đến từ Luân Đôn, nước Anh."},{"text":"I''m a student at a language school.","ipa":"/aɪm ə ˈstudənt æt ə ˈlæŋɡwɪdʒ skul/","vi":"Mình là học sinh tại một trường ngôn ngữ."},{"text":"This is my friend Marco Rossi.","ipa":"/ðɪs ɪz maɪ frɛnd ˈmɑrkoʊ ˈrɑsi/","vi":"Đây là bạn của mình, Marco Rossi."},{"text":"He''s twenty-two, and he''s from Rome, Italy.","ipa":"/hiz ˈtwɛnti-tu, ænd hiz frʌm roʊm, ˈɪtəli/","vi":"Anh ấy hai mươi hai tuổi và đến từ Rome, nước Ý."},{"text":"He''s a chef at a small restaurant.","ipa":"/hiz ə ʃɛf æt ə smɔl ˈrɛstəˌrɑnt/","vi":"Anh ấy là đầu bếp tại một nhà hàng nhỏ."},{"text":"Next to him is Emma Clark.","ipa":"/nɛkst tu hɪm ɪz ˈɛmə klɑrk/","vi":"Bên cạnh anh ấy là Emma Clark."},{"text":"She''s twenty years old, and she''s from Toronto, Canada.","ipa":"/ʃiz ˈtwɛnti jɪrz oʊld, ænd ʃiz frʌm təˈrɑntoʊ, ˈkænədə/","vi":"Cô ấy hai mươi tuổi và đến từ Toronto, Canada."},{"text":"She''s a nurse at a big hospital.","ipa":"/ʃiz ə nɜrs æt ə bɪɡ ˈhɑˌspɪtəl/","vi":"Cô ấy là y tá tại một bệnh viện lớn."},{"text":"And this is Daniel Kim.","ipa":"/ænd ðɪs ɪz ˈdænjəl kɪm/","vi":"Và đây là Daniel Kim."},{"text":"He''s twenty-one, and he''s from Seattle, in the United States.","ipa":"/hiz ˈtwɛnti-wʌn, ænd hiz frʌm siˈætəl, ɪn ðə juˈnaɪtəd steɪts/","vi":"Anh ấy hai mươi mốt tuổi và đến từ Seattle, Hoa Kỳ."},{"text":"He''s an engineer.","ipa":"/hiz ən ˌɛndʒəˈnɪr/","vi":"Anh ấy là kỹ sư."},{"text":"We are all new students here.","ipa":"/wi ɑr ɔl nu ˈstudənts hɪr/","vi":"Tất cả chúng mình đều là học sinh mới ở đây."},{"text":"We''re happy to meet each other.","ipa":"/wɪr ˈhæpi tu mit iʧ ˈʌðər/","vi":"Chúng mình rất vui khi được gặp nhau."},{"text":"Sophie and Emma are friends now, and Marco and Daniel are friends too.","ipa":"/ˈsoʊfi ænd ˈɛmə ɑr frɛndz naʊ, ænd ˈmɑrkoʊ ænd ˈdænjəl ɑr frɛndz tu/","vi":"Sophie và Emma giờ đã là bạn, Marco và Daniel cũng là bạn của nhau."},{"text":"Nice to meet you all!","ipa":"/naɪs tu mit ju ɔl/","vi":"Rất vui được gặp tất cả các bạn!"}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mixed_all',NULL,140,'16b2ee0e-4f77-484c-8640-92a15dc9a471','264127e4120e4d2bb62236b78f0189b9',NULL,NULL,'2026-07-25T10:06:11.317Z',NULL);
