INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('9c5c9755-dc48-4f2d-8921-eee48b34e276','39729327-099f-49bb-9504-56bf8a9e26c8',20,'categorize','Sort each word by the article it needs (a / an).',NULL,NULL,NULL,NULL,NULL,'Chia theo âm đầu của từ: phụ âm → ''a'', nguyên âm → ''an''.',NULL,NULL,NULL,'["a", "an"]','[{"text": "pen", "category": "a"}, {"text": "eraser", "category": "an"}, {"text": "ruler", "category": "a"}, {"text": "apple", "category": "an"}, {"text": "book", "category": "a"}, {"text": "orange", "category": "an"}]',NULL,'articles-a-an');
