INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('f695e590-f19a-48ea-a7d5-004d3b0c81f1','prea1-s2-03-read-aloud-p-b','My School Bag (/p/ vs /b/)',1,'reading','Pre A1 Starters',NULL,'Look at my school bag! It''s big and blue. I have a pen, a pencil, and a book inside. I also have a purple pencil case and some blue paper. My backpack has a big pocket for my notebook and a small pocket for my pen. I put my books in my bag every morning. My best friend, Ben, has a pink backpack. He has a pen and a pencil too, but his pencil is purple. We open our bags before class and put our books on the desk. I like my blue bag very much. It is perfect for school!','[{"text":"Look at my school bag!","ipa":"/lʊk æt maɪ skul bæɡ/","vi":"Hãy nhìn chiếc cặp sách của tớ này!"},{"text":"It''s big and blue.","ipa":"/ɪts bɪɡ ænd blu/","vi":"Nó to và có màu xanh dương."},{"text":"I have a pen, a pencil, and a book inside.","ipa":"/aɪ hæv ə pɛn, ə ˈpɛnsəl, ænd ə bʊk ɪnˈsaɪd/","vi":"Tớ có một chiếc bút mực, một chiếc bút chì và một cuốn sách ở bên trong."},{"text":"I also have a purple pencil case and some blue paper.","ipa":"/aɪ ˈɔlsoʊ hæv ə ˈpɜrpəl ˈpɛnsəl keɪs ænd sʌm blu ˈpeɪpər/","vi":"Tớ cũng có một chiếc hộp bút màu tím và vài tờ giấy màu xanh dương."},{"text":"My backpack has a big pocket for my notebook and a small pocket for my pen.","ipa":"/maɪ ˈbækˌpæk hæz ə bɪɡ ˈpɑkɪt fɔr maɪ ˈnoʊtˌbʊk ænd ə smɔl ˈpɑkɪt fɔr maɪ pɛn/","vi":"Cặp của tớ có một ngăn lớn để đựng vở và một ngăn nhỏ để đựng bút."},{"text":"I put my books in my bag every morning.","ipa":"/aɪ pʊt maɪ bʊks ɪn maɪ bæɡ ˈɛvəri ˈmɔrnɪŋ/","vi":"Sáng nào tớ cũng bỏ sách vào cặp."},{"text":"My best friend, Ben, has a pink backpack.","ipa":"/maɪ bɛst frɛnd, bɛn, hæz ə pɪŋk ˈbækˌpæk/","vi":"Bạn thân của tớ, Ben, có một chiếc cặp màu hồng."},{"text":"He has a pen and a pencil too, but his pencil is purple.","ipa":"/hi hæz ə pɛn ænd ə ˈpɛnsəl tu, bʌt hɪz ˈpɛnsəl ɪz ˈpɜrpəl/","vi":"Cậu ấy cũng có bút mực và bút chì, nhưng bút chì của cậu ấy màu tím."},{"text":"We open our bags before class and put our books on the desk.","ipa":"/wi ˈoʊpən ˈaʊər bæɡz bɪˈfɔr klæs ænd pʊt ˈaʊər bʊks ɑn ðə dɛsk/","vi":"Chúng tớ mở cặp trước giờ học và đặt sách lên bàn."},{"text":"I like my blue bag very much.","ipa":"/aɪ laɪk maɪ blu bæɡ ˈvɛri mʌtʃ/","vi":"Tớ rất thích chiếc cặp màu xanh dương của mình."},{"text":"It is perfect for school!","ipa":"/ɪt ɪz ˈpɜrfɪkt fɔr skul/","vi":"Nó thật hoàn hảo để đi học!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,170,'87288d9b-2d01-4f57-a512-d09b29dff35e','9bf279dd312c91f2b490b3a1c666ca03',NULL,NULL,'2026-07-25T11:05:15.527Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('202176f4-ca09-4468-bc04-32c6a00fb1f6','prea1-s2-04-listen-choose','What''s in Your Bag?',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'Leo: Hi Mia! What''s in your bag today?
Mia: Hi Leo! I have two books, a pencil case, and a red notebook.
Leo [happy]: Nice! I have a blue backpack. I have three pens and one pencil.
Mia: Do you have an eraser?
Leo: Yes, I have a small eraser and a big ruler.
Mia: I don''t have a ruler, but I have some paper and a folder.
Leo: What''s in your pencil case?
Mia: I have two pencils, a pen, and a purple eraser.
Leo [happy]: Cool! I also have a calculator for math class.
Mia [happy]: I have a calculator too! Let''s go to class now.
Leo: I also have a small stapler in my bag.
Mia [surprised]: Wow, that''s useful! I don''t have a stapler.
Leo: Okay, let''s go!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,180,'87288d9b-2d01-4f57-a512-d09b29dff35e','9bf279dd312c91f2b490b3a1c666ca03',NULL,NULL,'2026-07-25T11:05:15.527Z',NULL);
