INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('9b70233b-c24f-48f8-b5c9-29e31f835a3a','0fa71665-47ec-41a3-90a2-4d474d9b2f09',20,'categorize','Sort each sentence by the correct form of ''to be''.',NULL,NULL,NULL,NULL,NULL,'Số ít dùng ''is'', số nhiều dùng ''are''.',NULL,NULL,NULL,'["is", "are"]','[{"text": "My bag ___ blue.", "category": "is"}, {"text": "My shoes ___ black.", "category": "are"}, {"text": "It ___ red.", "category": "is"}, {"text": "The walls ___ green.", "category": "are"}]',NULL,'verb-to-be');
