INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('2e81629a-3f71-45ce-a685-111810909bb9','prea1-s2-08-read-aloud-r-l','My Favorite Colors (/r/ vs /l/)',1,'reading','Pre A1 Starters',NULL,'Look at all these colors! My favorite color is red, but I also really like green and purple. My little sister loves yellow and light blue. She says a rainbow has lots of colors: red, orange, yellow, green, blue, and purple. Our classroom is very colorful. The walls are light green, and the door is dark red. I have a purple ruler and a green pencil. My friend has an orange bag and a yellow book. Our library has a red carpet and light brown shelves. Every Friday, we color pictures with bright crayons. I really love looking at all the colors around our school!','[{"text":"Look at all these colors!","ipa":"/lʊk æt ɔl ðiz ˈkʌlərz/","vi":"Hãy nhìn tất cả những màu sắc này xem!"},{"text":"My favorite color is red, but I also really like green and purple.","ipa":"/maɪ ˈfeɪvərɪt ˈkʌlər ɪz rɛd, bʌt aɪ ˈɔlsoʊ ˈrɪli laɪk grin ænd ˈpɜrpəl/","vi":"Màu yêu thích của mình là màu đỏ, nhưng mình cũng rất thích màu xanh lá cây và màu tím."},{"text":"My little sister loves yellow and light blue.","ipa":"/maɪ ˈlɪtəl ˈsɪstər lʌvz ˈjɛloʊ ænd laɪt blu/","vi":"Em gái mình thích màu vàng và màu xanh dương nhạt."},{"text":"She says a rainbow has lots of colors: red, orange, yellow, green, blue, and purple.","ipa":"/ʃi sɛz ə ˈreɪnˌboʊ hæz lɑts ʌv ˈkʌlərz: rɛd, ˈɔrɪndʒ, ˈjɛloʊ, grin, blu, ænd ˈpɜrpəl/","vi":"Em ấy nói cầu vồng có rất nhiều màu: đỏ, cam, vàng, xanh lá, xanh dương và tím."},{"text":"Our classroom is very colorful.","ipa":"/ˈaʊər ˈklæsˌrum ɪz ˈvɛri ˈkʌlərˌfʊl/","vi":"Lớp học của chúng mình rất nhiều màu sắc."},{"text":"The walls are light green, and the door is dark red.","ipa":"/ðə wɔlz ɑr laɪt grin, ænd ðə dɔr ɪz dɑrk rɛd/","vi":"Những bức tường có màu xanh lá nhạt, còn cánh cửa thì màu đỏ đậm."},{"text":"I have a purple ruler and a green pencil.","ipa":"/aɪ hæv ə ˈpɜrpəl ˈrulər ænd ə grin ˈpɛnsəl/","vi":"Mình có một chiếc thước kẻ màu tím và một cây bút chì màu xanh lá."},{"text":"My friend has an orange bag and a yellow book.","ipa":"/maɪ frɛnd hæz ən ˈɔrɪndʒ bæg ænd ə ˈjɛloʊ bʊk/","vi":"Bạn mình có một chiếc cặp màu cam và một cuốn sách màu vàng."},{"text":"Our library has a red carpet and light brown shelves.","ipa":"/ˈaʊər ˈlaɪˌbrɛri hæz ə rɛd ˈkɑrpɪt ænd laɪt braʊn ʃɛlvz/","vi":"Thư viện của chúng mình có một tấm thảm màu đỏ và những chiếc kệ màu nâu nhạt."},{"text":"Every Friday, we color pictures with bright crayons.","ipa":"/ˈɛvəri ˈfraɪˌdeɪ, wi ˈkʌlər ˈpɪktʃərz wɪð braɪt ˈkreɪˌɑnz/","vi":"Mỗi thứ Sáu, chúng mình lại tô màu các bức tranh bằng những cây bút sáp màu rực rỡ."},{"text":"I really love looking at all the colors around our school!","ipa":"/aɪ ˈrɪli lʌv ˈlʊkɪŋ æt ɔl ðə ˈkʌlərz əˈraʊnd ˈaʊər skul/","vi":"Mình thực sự rất thích ngắm nhìn tất cả những màu sắc xung quanh trường học của chúng mình!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,220,'87288d9b-2d01-4f57-a512-d09b29dff35e','65b8a1a59c2ba8c1ae52090894f1a62b',NULL,NULL,'2026-07-25T11:05:15.527Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('c6620331-3fcb-46c7-8399-18068c33e450','prea1-s2-09-listen-choose','What Color Is Your Shirt?',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'Amy [happy]: Hi Jack! I love your shirt. What color is it?
Jack: Thanks! It''s blue. What color is your dress?
Amy [happy]: My dress is yellow. And look at my shoes, they''re pink!
Jack [happy]: Nice! My shoes are black, and my socks are white.
Amy: What color is your bag?
Jack: My bag is green. What about your hat?
Amy [happy]: My hat is orange. I really like bright colors.
Jack: Me too! My favorite color is red, but I don''t have a red shirt.
Amy [happy]: You should get a red shirt! It''s a great color.
Jack: Do you like my new backpack too? It''s dark green.
Amy [happy]: Yes, I love dark green! Let''s go to school now.
Jack: Okay, let''s go!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,230,'87288d9b-2d01-4f57-a512-d09b29dff35e','65b8a1a59c2ba8c1ae52090894f1a62b',NULL,NULL,'2026-07-25T11:05:15.527Z',NULL);
