INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('b69d2a96-b13a-4191-b1b4-45291f2a55ef','fe2dfa01-2494-4923-a276-bb1ac0bca5c1',17,'ordering','Put the words in the correct order.',NULL,'Open your book',NULL,NULL,NULL,'Trật tự: động từ nguyên thể (Open) + tính từ sở hữu (your) + danh từ (book).',NULL,NULL,'["book", "your", "Open"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('3890014f-e896-4edd-becb-32f38a7e2ca7','fe2dfa01-2494-4923-a276-bb1ac0bca5c1',18,'ordering','Put the words in the correct order.',NULL,'Please be quiet',NULL,NULL,NULL,'Trật tự: Please + động từ nguyên thể (be) + tính từ (quiet).',NULL,NULL,'["quiet", "be", "Please"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('09ecfb5b-6f7c-4790-b4fb-2e2e39e03623','fe2dfa01-2494-4923-a276-bb1ac0bca5c1',19,'ordering','Put the words in the correct order.',NULL,'Don''t talk now',NULL,NULL,NULL,'Trật tự mệnh lệnh phủ định: Don''t + động từ nguyên thể (talk) + trạng từ (now).',NULL,NULL,'["talk", "now", "Don''t"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('6a347667-176e-45c2-95bf-7883c467d51c','fe2dfa01-2494-4923-a276-bb1ac0bca5c1',20,'categorize','Sort each instruction by whether it is positive or negative.',NULL,NULL,NULL,NULL,NULL,'Mệnh lệnh khẳng định vs phủ định (Don''t + V).',NULL,NULL,NULL,'["Positive", "Negative"]','[{"text": "Stand up.", "category": "Positive"}, {"text": "Don''t talk.", "category": "Negative"}, {"text": "Open your book.", "category": "Positive"}, {"text": "Don''t run.", "category": "Negative"}]',NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('a15ca145-9d0b-498e-a085-48f65f922c0e','fe2dfa01-2494-4923-a276-bb1ac0bca5c1',21,'categorize','Sort each word into ''things we do with our hands'' or ''things we do with our voice''.',NULL,NULL,NULL,NULL,NULL,'Phân loại hành động lớp học theo bộ phận cơ thể sử dụng.',NULL,NULL,NULL,'["Hands", "Voice"]','[{"text": "write", "category": "Hands"}, {"text": "raise your hand", "category": "Hands"}, {"text": "answer", "category": "Voice"}, {"text": "listen", "category": "Voice"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('fc4832fd-6e12-4be8-8b80-b4fc563c411b','prea1-s2-13-read-aloud-s-sh','In the Classroom (/s/ vs /ʃ/)',1,'reading','Pre A1 Starters',NULL,'Good morning, class! Please sit down and listen. Our teacher, Ms. Smith, stands at the front. She says, ''Open your books, please.'' We open our books and start the lesson. Ms. Smith shows us new words on the board. Sometimes she asks a question, and a student answers. Each student shares one sentence about the new words. We must stay quiet and listen carefully. She shows a short story, and we read it together slowly. Please put your books back on the shelf when you finish. Stand up slowly and push your chair in. Ms. Smith says, ''Well done, everyone! See you tomorrow.''','[{"text":"Good morning, class!","ipa":"/ɡʊd ˈmɔrnɪŋ, klæs!/","vi":"Chào buổi sáng, cả lớp!"},{"text":"Please sit down and listen.","ipa":"/pliz sɪt daʊn ænd ˈlɪsən./","vi":"Các em hãy ngồi xuống và lắng nghe."},{"text":"Our teacher, Ms. Smith, stands at the front.","ipa":"/ˈaʊər ˈtitʃər, ˈmɪz smɪθ, stændz æt ðə frʌnt./","vi":"Cô giáo của chúng tôi, cô Smith, đang đứng ở phía trên."},{"text":"She says, ''Open your books, please.''","ipa":"/ʃi sɛz, ˈoʊpən jʊər bʊks, pliz./","vi":"Cô nói: ''Các em vui lòng mở sách ra.''"},{"text":"We open our books and start the lesson.","ipa":"/wi ˈoʊpən ˈaʊər bʊks ænd stɑrt ðə ˈlɛsən./","vi":"Chúng tôi mở sách ra và bắt đầu bài học."},{"text":"Ms. Smith shows us new words on the board.","ipa":"/ˈmɪz smɪθ ʃoʊz ʌs nu wɜrdz ɑn ðə bɔrd./","vi":"Cô Smith chỉ cho chúng tôi những từ mới trên bảng."},{"text":"Sometimes she asks a question, and a student answers.","ipa":"/ˈsʌmˌtaɪmz ʃi æsks ə ˈkwɛstʃən, ænd ə ˈstudənt ˈænsərz./","vi":"Đôi khi cô đặt câu hỏi và một học sinh sẽ trả lời."},{"text":"Each student shares one sentence about the new words.","ipa":"/it ˈstudənt ʃɛrz wʌn ˈsɛntəns əˈbaʊt ðə nu wɜrdz./","vi":"Mỗi học sinh chia sẻ một câu về các từ mới."},{"text":"We must stay quiet and listen carefully.","ipa":"/wi mʌst steɪ ˈkwaɪət ænd ˈlɪsən ˈkɛrfəli./","vi":"Chúng tôi phải giữ trật tự và lắng nghe cẩn thận."},{"text":"She shows a short story, and we read it together slowly.","ipa":"/ʃi ʃoʊz ə ʃɔrt ˈstɔri, ænd wi rid ɪt təˈɡɛðər ˈsloʊli./","vi":"Cô cho xem một câu chuyện ngắn và chúng tôi cùng đọc nó một cách chậm rãi."},{"text":"Please put your books back on the shelf when you finish.","ipa":"/pliz pʊt jʊər bʊks bæk ɑn ðə ʃɛlf wɛn ju ˈfɪnɪʃ./","vi":"Các em hãy cất sách lên kệ khi làm xong nhé."},{"text":"Stand up slowly and push your chair in.","ipa":"/stænd ʌp ˈsloʊli ænd pʊʃ jʊər tʃɛr ɪn./","vi":"Hãy đứng dậy từ từ và đẩy ghế vào."},{"text":"Ms. Smith says, ''Well done, everyone! See you tomorrow.''","ipa":"/ˈmɪz smɪθ sɛz, wɛl dʌn, ˈɛvriˌwʌn! si ju təˈmɑroʊ./","vi":"Cô Smith nói: ''Làm tốt lắm, cả lớp! Hẹn gặp lại các em vào ngày mai.''"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,270,'87288d9b-2d01-4f57-a512-d09b29dff35e','9bf279dd312c91f2b490b3a1c666ca03',NULL,NULL,'2026-07-25T11:05:15.527Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('07ece869-cc17-44f5-9fae-f630efdac68f','prea1-s2-14-listen-choose-commands','Follow the Teacher''s Instructions',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'Ms. Lee: Good morning, class! Please stand up.
Tom: Okay, Ms. Lee, we are standing.
Ms. Lee: Now sit down and open your books to page ten.
Tom: I am opening my book now.
Ms. Lee: Listen carefully and look at the board.
Tom: I am listening and looking, Ms. Lee.
Ms. Lee: Please close your books now.
Tom: Okay, I am closing my book.
Ms. Lee: Now take out your pencils and write your name.
Tom: Okay, I am writing my name now.
Ms. Lee: Stand up and line up at the door.
Tom: We are standing up and lining up now.
Ms. Lee [happy]: Very good! Now let''s go to the library.
Tom [happy]: Great, let''s go!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,280,'87288d9b-2d01-4f57-a512-d09b29dff35e','9bf279dd312c91f2b490b3a1c666ca03',NULL,NULL,'2026-07-25T11:05:15.527Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('738c5640-d201-43b3-b6c6-d941fb722a39','07ece869-cc17-44f5-9fae-f630efdac68f',0,'multiple_choice','What does Ms. Lee ask the class to do first?','["Stand up", "Sit down", "Open books", "Line up"]','Stand up',NULL,NULL,NULL,'Ms. Lee nói ''Please stand up'' đầu tiên.','Ms. Lee: Good morning, class! Please stand up.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('949a12f1-de19-4b61-a66e-28273513171a','07ece869-cc17-44f5-9fae-f630efdac68f',1,'multiple_choice','What page do students open their books to?','["Five", "Eight", "Ten", "Twenty"]','Ten',NULL,NULL,NULL,'Ms. Lee nói ''page ten''.','Ms. Lee: Now sit down and open your books to page ten.',NULL,NULL,NULL,NULL,NULL,NULL);
