INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('6cd9c3b0-a698-4d6b-b797-fb10239859c4','07ece869-cc17-44f5-9fae-f630efdac68f',5,'multiple_choice','Where do students line up?','["At the board", "At the desk", "At the door", "At the shelf"]','At the door',NULL,NULL,NULL,'Ms. Lee nói ''line up at the door''.','Ms. Lee: Stand up and line up at the door.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('9fe82063-2f24-4b69-bf7e-734e82cc04a6','07ece869-cc17-44f5-9fae-f630efdac68f',6,'multiple_choice','Where does the class go at the end?','["The library", "The classroom", "The office", "Home"]','The library',NULL,NULL,NULL,'Ms. Lee nói ''let''s go to the library''.','Ms. Lee: Very good! Now let''s go to the library.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('25a88f42-28c7-44b3-be90-14eef53d679f','07ece869-cc17-44f5-9fae-f630efdac68f',7,'multiple_choice','Who is the teacher?','["Ms. Lee", "Ms. Smith", "Mr. Adams", "Tom"]','Ms. Lee',NULL,NULL,NULL,'Người ra lệnh trong hội thoại là Ms. Lee.','Ms. Lee: Good morning, class!',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('837dfe6f-6045-47fb-a715-815761bb5cb5','07ece869-cc17-44f5-9fae-f630efdac68f',8,'fill_blank','Please ___ down and open your books.',NULL,NULL,'["sit"]','["sit", "stand", "close"]',NULL,'Ms. Lee nói ''sit down''.','Ms. Lee: Now sit down and open your books to page ten.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('3c1d6d61-e8e0-4d95-9f7c-dbd91c8c9f07','07ece869-cc17-44f5-9fae-f630efdac68f',9,'fill_blank','Listen carefully and ___ at the board.',NULL,NULL,'["look"]','["look", "listen", "open"]',NULL,'Ms. Lee nói ''look at the board''.','Ms. Lee: Listen carefully and look at the board.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('71542342-7441-4a23-803c-4017fea3bfe2','07ece869-cc17-44f5-9fae-f630efdac68f',10,'fill_blank','Please ___ your books now.',NULL,NULL,'["close"]','["close", "open", "look"]',NULL,'Ms. Lee nói ''close your books''.','Ms. Lee: Please close your books now.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('5dd3a1a6-2f80-4841-8c3d-102476ca35a0','07ece869-cc17-44f5-9fae-f630efdac68f',11,'fill_blank','Stand up and ___ up at the door.',NULL,NULL,'["line"]','["line", "stand", "sit"]',NULL,'Ms. Lee nói ''line up at the door''.','Ms. Lee: Stand up and line up at the door.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('3d09bd28-1c08-49a3-bdac-20d1d36c60a7','07ece869-cc17-44f5-9fae-f630efdac68f',12,'fill_blank','Now let''s go to the ___.',NULL,NULL,'["library"]','["library", "classroom", "door"]',NULL,'Ms. Lee nói ''let''s go to the library''.','Ms. Lee: Now let''s go to the library.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('24b1c4df-de5f-49af-bc0c-f1f0df52ad50','07ece869-cc17-44f5-9fae-f630efdac68f',13,'matching','Match each instruction to what Tom does.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng phản hồi của Tom cho từng lệnh.','Tom: we are standing... opening my book... listening and looking... closing my book.','[{"left": "Stand up", "right": "We are standing"}, {"left": "Open your books", "right": "I am opening my book"}, {"left": "Listen and look", "right": "I am listening and looking"}, {"left": "Close your books", "right": "I am closing my book"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('fc1f8413-b0a2-4afb-87e7-5bb389eca6ce','07ece869-cc17-44f5-9fae-f630efdac68f',14,'matching','Match each place to what happens there.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng địa điểm với hoạt động tương ứng.','look at the board... line up at the door.','[{"left": "the board", "right": "students look here"}, {"left": "the door", "right": "students line up here"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('46f83c78-4d9c-4cf0-b296-2238dcec6263','prea1-s2-15-reading-classroom','A Day in Class 5B',1,'reading','Pre A1 Starters',NULL,'Class 5B is a small classroom with twenty students. Every morning, the students stand up and say hello to their teacher, Mr. Adams. He is friendly and kind. First, the students sit down and open their books. Mr. Adams writes new words on the board, and the students listen carefully. When he asks a question, some students raise their hands to answer. Lucy always answers first because she is very quick. Tom likes to draw pictures in his notebook, but he still listens to the lesson. After the lesson, the teacher gives homework: five sentences about school. The students close their books and put them in their bags. Then everyone stands up and lines up at the door. Class 5B walks to the library together. In the library, they read new books and are very quiet. It is a wonderful day at school!','[{"text":"Class 5B is a small classroom with twenty students.","ipa":"/klæs ˈfaɪv biː ɪz ə smɔːl ˈklæsˌruːm wɪð ˈtwɛnti ˈstudənts./","vi":"Lớp 5B là một lớp học nhỏ với hai mươi học sinh."},{"text":"Every morning, the students stand up and say hello to their teacher, Mr. Adams.","ipa":"/ˈɛvəri ˈmɔrnɪŋ, ðə ˈstudənts stænd ʌp ænd seɪ həˈloʊ tuː ðɛr ˈtiːtʃər, ˈmɪstər ˈædəmz./","vi":"Mỗi buổi sáng, các học sinh đứng dậy và chào thầy giáo của họ, thầy Adams."},{"text":"He is friendly and kind.","ipa":"/hiː ɪz ˈfrɛndli ænd kaɪnd./","vi":"Thầy ấy rất thân thiện và tốt bụng."},{"text":"First, the students sit down and open their books.","ipa":"/fɜrst, ðə ˈstudənts sɪt daʊn ænd ˈoʊpən ðɛr bʊks./","vi":"Đầu tiên, các học sinh ngồi xuống và mở sách ra."},{"text":"Mr. Adams writes new words on the board, and the students listen carefully.","ipa":"/ˈmɪstər ˈædəmz raɪts nuː wɜrdz ɑn ðə bɔrd, ænd ðə ˈstudənts ˈlɪsən ˈkɛrfəli./","vi":"Thầy Adams viết các từ mới lên bảng, và các học sinh lắng nghe cẩn thận."},{"text":"When he asks a question, some students raise their hands to answer.","ipa":"/wɛn hiː æsks ə ˈkwɛstʃən, sʌm ˈstudənts reɪz ðɛr hændz tuː ˈænsər./","vi":"Khi thầy đặt câu hỏi, một vài học sinh giơ tay để trả lời."},{"text":"Lucy always answers first because she is very quick.","ipa":"/ˈlusi ˈɔlˌweɪz ˈænsərz fɜrst bɪˈkəz ʃiː ɪz ˈvɛri kwɪk./","vi":"Lucy luôn trả lời đầu tiên vì bạn ấy rất nhanh nhẹn."},{"text":"Tom likes to draw pictures in his notebook, but he still listens to the lesson.","ipa":"/tɑm laɪks tuː drɔ ˈpɪktʃərz ɪn hɪz ˈnoʊtˌbʊk, bʌt hiː stɪl ˈlɪsənz tuː ðə ˈlɛsən./","vi":"Tom thích vẽ tranh vào vở, nhưng bạn ấy vẫn lắng nghe bài giảng."},{"text":"After the lesson, the teacher gives homework: five sentences about school.","ipa":"/ˈæftər ðə ˈlɛsən, ðə ˈtiːtʃər ɡɪvz ˈhoʊmˌwɜrk: faɪv ˈsɛntənsəz əˈbaʊt skul./","vi":"Sau bài học, thầy giáo giao bài tập về nhà: năm câu về trường học."},{"text":"The students close their books and put them in their bags.","ipa":"/ðə ˈstudənts kloʊz ðɛr bʊks ænd pʊt ðɛm ɪn ðɛr bæɡz./","vi":"Các học sinh đóng sách lại và cất vào cặp."},{"text":"Then everyone stands up and lines up at the door.","ipa":"/ðɛn ˈɛvriˌwʌn laɪnz ʌp æt ðə dɔr./","vi":"Sau đó mọi người xếp hàng ở cửa."},{"text":"Class 5B walks to the library together.","ipa":"/klæs ˈfaɪv biː wɔks tuː ðə ˈlaɪˌbrɛri təˈɡɛðər./","vi":"Lớp 5B cùng nhau đi đến thư viện."},{"text":"In the library, they read new books and are very quiet.","ipa":"/ɪn ðə ˈlaɪˌbrɛri, ðeɪ riːd nuː bʊks ænd ɑr ˈvɛri ˈkwaɪət./","vi":"Trong thư viện, các bạn đọc sách mới và rất trật tự."},{"text":"It is a wonderful day at school!","ipa":"/ɪt ɪz ə ˈwʌndərfəl deɪ æt skul!/","vi":"Đó là một ngày tuyệt vời ở trường!"}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'reading_comprehension',NULL,290,'87288d9b-2d01-4f57-a512-d09b29dff35e','9bf279dd312c91f2b490b3a1c666ca03',NULL,NULL,'2026-07-25T11:05:15.527Z',NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('92a965a9-ecc5-4554-8fd9-c7c1dbae1b7b','46f83c78-4d9c-4cf0-b296-2238dcec6263',0,'multiple_choice','How many students are in Class 5B?','["Ten", "Fifteen", "Twenty", "Twenty-five"]','Twenty',NULL,NULL,NULL,'Đoạn ghi ''a small classroom with twenty students''.',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
