INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('8744bd37-92d6-4561-ae9d-353e3c831a24','46f83c78-4d9c-4cf0-b296-2238dcec6263',14,'categorize','Sort each activity by where it happens.',NULL,NULL,NULL,NULL,NULL,'Đoạn văn tả rõ hoạt động ở lớp học và ở thư viện.',NULL,NULL,NULL,'["Classroom", "Library"]','[{"text": "listen to the lesson", "category": "Classroom"}, {"text": "read new books", "category": "Library"}, {"text": "raise hands to answer", "category": "Classroom"}, {"text": "stay very quiet", "category": "Library"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('83583821-664a-4513-94ab-95b6827abc8e','prea1-s2-16-mixed-checkpoint','A Colorful Day at School',1,'mixed','Pre A1 Starters',NULL,'Good morning! Today is a fun day at school. I have a new backpack. It''s green and yellow. Inside, I have a book, a pencil, and an eraser. My teacher says, ''Stand up, everyone!'' We stand up and say hello. Then she says, ''Sit down and open your books.'' We sit down and look at page five. My friend Mia has a purple pencil case. She also has an orange notebook. ''What color is your ruler?'' she asks me. ''It''s blue,'' I answer. Our classroom is colorful: the walls are light green, and the door is red. At the end of class, the teacher says, ''Close your books, please.'' We close our books and line up quietly. It''s a wonderful, colorful day!','[{"text":"Good morning!","ipa":"/ɡʊd ˈmɔrnɪŋ/","vi":"Chào buổi sáng!"},{"text":"Today is a fun day at school.","ipa":"/təˈdeɪ ɪz ə fʌn deɪ æt skul/","vi":"Hôm nay là một ngày vui ở trường."},{"text":"I have a new backpack.","ipa":"/aɪ hæv ə nu ˈbækˌpæk/","vi":"Mình có một chiếc ba lô mới."},{"text":"It''s green and yellow.","ipa":"/ɪts ɡrin ænd ˈjɛˌloʊ/","vi":"Nó có màu xanh lá cây và màu vàng."},{"text":"Inside, I have a book, a pencil, and an eraser.","ipa":"/ɪnˈsaɪd, aɪ hæv ə bʊk, ə ˈpɛnsəl, ænd ən ɪˈreɪsər/","vi":"Bên trong, mình có một cuốn sách, một cây bút chì và một cục tẩy."},{"text":"My teacher says, ''Stand up, everyone!''","ipa":"/maɪ ˈtitʃər sɛz, /stænd ʌp, ˈɛvriˌwʌn/!/","vi":"Cô giáo của mình nói: ''Các em đứng lên nào!''"},{"text":"We stand up and say hello.","ipa":"/wi stænd ʌp ænd seɪ həˈloʊ/","vi":"Chúng mình đứng lên và chào cô."},{"text":"Then she says, ''Sit down and open your books.''","ipa":"/ðɛn ʃi sɛz, /sɪt daʊn ænd ˈoʊpən jʊr bʊks/./","vi":"Sau đó cô nói: ''Các em ngồi xuống và mở sách ra.''"},{"text":"We sit down and look at page five.","ipa":"/wi sɪt daʊn ænd lʊk æt peɪdʒ faɪv/","vi":"Chúng mình ngồi xuống và nhìn vào trang năm."},{"text":"My friend Mia has a purple pencil case.","ipa":"/maɪ frɛnd ˈmiə hæz ə ˈpɜrpəl ˈpɛnsəl keɪs/","vi":"Bạn Mia của mình có một chiếc hộp bút màu tím."},{"text":"She also has an orange notebook.","ipa":"/ʃi ˈɔlsoʊ hæz ən ˈɔrɪndʒ ˈnoʊtˌbʊk/","vi":"Bạn ấy cũng có một cuốn vở màu cam."},{"text":"''What color is your ruler?'' she asks me.","ipa":"/wʌt ˈkʌlər ɪz jʊr ˈrulər? ʃi æsks mi./","vi":"''Thước kẻ của bạn màu gì?'' bạn ấy hỏi mình."},{"text":"''It''s blue,'' I answer.","ipa":"/ɪts blu, aɪ ˈænsər./","vi":"''Nó màu xanh dương,'' mình trả lời."},{"text":"Our classroom is colorful: the walls are light green, and the door is red.","ipa":"/ˈaʊər ˈklæsˌrum ɪz ˈkʌlərˌfʊl: ðə wɔlz ɑr laɪt ɡrin, ænd ðə dɔr ɪz rɛd./","vi":"Lớp học của chúng mình rất nhiều màu sắc: tường màu xanh lá nhạt, còn cửa thì màu đỏ."},{"text":"At the end of class, the teacher says, ''Close your books, please.''","ipa":"/æt ði ɛnd ʌv klæs, ðə ˈtitʃər sɛz, /kloʊz jʊr bʊks, pliz/./","vi":"Cuối giờ học, cô giáo nói: ''Các em gấp sách lại nhé.''"},{"text":"We close our books and line up quietly.","ipa":"/wi kloʊz ˈaʊər bʊks ænd laɪn ʌp ˈkwaɪətli./","vi":"Chúng mình gấp sách lại và xếp hàng thật trật tự."},{"text":"It''s a wonderful, colorful day!","ipa":"/ɪts ə ˈwʌndərˌfʊl, ˈkʌlərˌfʊl deɪ!/","vi":"Đó là một ngày thật tuyệt vời và đầy màu sắc!"}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mixed_all',NULL,300,'87288d9b-2d01-4f57-a512-d09b29dff35e','9bf279dd312c91f2b490b3a1c666ca03',NULL,NULL,'2026-07-25T11:05:15.527Z',NULL);
