INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('e34f5f50-7ef5-4558-930c-56d29623372b','prea1-s3-03-read-aloud-ee-ai','My Favorite Food (/iː/ vs /aɪ/)',1,'reading','Pre A1 Starters',NULL,'Hi! My name is Mai. I like a lot of food. I like rice very much. I eat rice every day with my family. I also like apples. I like sweet apples the best. My favorite fruit is bananas. I like bananas because they are nice and easy to eat. But I don''t like eggs. I don''t like eggs at all! My friend, Kai, likes eggs and fish. He eats fish and rice for dinner every night. Kai doesn''t like bread, but I like bread with cheese. We like different food, but we are still good friends. I like to eat with my family. It''s nice to eat together and talk about our day.','[{"text":"Hi!","ipa":"/haɪ/","vi":"Chào bạn!"},{"text":"My name is Mai.","ipa":"/maɪ neɪm ɪz maɪ/","vi":"Tên mình là Mai."},{"text":"I like a lot of food.","ipa":"/aɪ laɪk ə lɑt əv fud/","vi":"Mình thích rất nhiều món ăn."},{"text":"I like rice very much.","ipa":"/aɪ laɪk raɪs ˈvɛri mʌtʃ/","vi":"Mình rất thích cơm."},{"text":"I eat rice every day with my family.","ipa":"/aɪ it raɪs ˈɛvri deɪ wɪð maɪ ˈfæməli/","vi":"Mình ăn cơm cùng gia đình mỗi ngày."},{"text":"I also like apples.","ipa":"/aɪ ˈɔlsoʊ laɪk ˈæpəlz/","vi":"Mình cũng thích táo."},{"text":"I like sweet apples the best.","ipa":"/aɪ laɪk swit ˈæpəlz ðə bɛst/","vi":"Mình thích nhất là táo ngọt."},{"text":"My favorite fruit is bananas.","ipa":"/maɪ ˈfeɪvərɪt frut ɪz bəˈnænəz/","vi":"Loại trái cây yêu thích của mình là chuối."},{"text":"I like bananas because they are nice and easy to eat.","ipa":"/aɪ laɪk bəˈnænəz bɪˈkəz ðeɪ ɑr naɪs ænd ˈizi tu it/","vi":"Mình thích chuối vì chúng rất ngon và dễ ăn."},{"text":"But I don''t like eggs.","ipa":"/bʌt aɪ doʊnt laɪk ɛgz/","vi":"Nhưng mình không thích trứng."},{"text":"I don''t like eggs at all!","ipa":"/aɪ doʊnt laɪk ɛgz æt ɔl/","vi":"Mình hoàn toàn không thích trứng!"},{"text":"My friend, Kai, likes eggs and fish.","ipa":"/maɪ frɛnd, kaɪ, laɪks ɛgz ænd fɪʃ/","vi":"Bạn của mình, Kai, lại thích trứng và cá."},{"text":"He eats fish and rice for dinner every night.","ipa":"/hi its fɪʃ ænd raɪs fɔr ˈdɪnər ˈɛvri naɪt/","vi":"Cậu ấy ăn cá và cơm vào bữa tối mỗi đêm."},{"text":"Kai doesn''t like bread, but I like bread with cheese.","ipa":"/kaɪ ˈdʌzənt laɪk brɛd, bʌt aɪ laɪk brɛd wɪð tʃiz/","vi":"Kai không thích bánh mì, nhưng mình lại thích bánh mì với phô mai."},{"text":"We like different food, but we are still good friends.","ipa":"/wi laɪk ˈdɪfrənt fud, bʌt wi ɑr stɪl gʊd frɛndz/","vi":"Chúng mình thích những món ăn khác nhau, nhưng vẫn là bạn tốt của nhau."},{"text":"I like to eat with my family.","ipa":"/aɪ laɪk tu it wɪð maɪ ˈfæməli/","vi":"Mình thích ăn cùng gia đình."},{"text":"It''s nice to eat together and talk about our day.","ipa":"/ɪts naɪs tu it təˈgɛðər ænd tɔk əˈbaʊt ˈaʊər deɪ/","vi":"Thật tuyệt khi được ăn cùng nhau và trò chuyện về một ngày của mình."}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,340,'7b684ec6-1123-4f12-ad58-cdc597a77cd4','7f3bce8fedfd3b05a63a079c87327931',NULL,NULL,'2026-07-25T11:23:14.813Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('cac52bc0-eed3-4b46-8107-c8264734ba3c','prea1-s3-04-listen-choose','Do You Like Rice?',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'Sam (M): Hi Emma! What food do you like?
Emma (F): Hi Sam! I like apples and bananas. Do you like apples?
Sam (M) [happy]: Yes, I do! I like apples too. I have two apples in my bag.
Emma (F): I have three bananas. Do you like rice?
Sam (M): Yes, I like rice very much. But I don''t like bread.
Emma (F) [surprised]: Really? I like bread! I don''t like eggs, though.
Sam (M): I like eggs! I have one egg for breakfast every day.
Emma (F): What about fish? Do you like fish?
Sam (M): Yes, I like fish a lot. I like fish for dinner.
Emma (F): I don''t like fish. I like rice and bananas more.
Sam (M): That''s OK! Everyone likes different food.
Emma (F) [happy]: True! Let''s eat lunch now. I''m hungry.
Sam (M) [happy]: Me too! I''m very hungry. Let''s go.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,350,'7b684ec6-1123-4f12-ad58-cdc597a77cd4','7f3bce8fedfd3b05a63a079c87327931',NULL,NULL,'2026-07-25T11:23:14.813Z',NULL);
