INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('75407d11-9cd0-4e12-b278-b35b8fd8e146','67875e17-605a-4d2c-8b65-22669e87c095',20,'categorize','Sort each short answer as Yes or No.',NULL,NULL,NULL,NULL,NULL,'Trả lời có ''do'' là đồng ý (Yes), có ''don''t'' là phủ định (No).',NULL,NULL,NULL,'["Yes", "No"]','[{"text": "I do", "category": "Yes"}, {"text": "I don''t", "category": "No"}, {"text": "Yes, I do.", "category": "Yes"}, {"text": "No, I don''t.", "category": "No"}]',NULL,NULL);
