INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('51f6a221-3449-47c1-9210-3e5ab1ad4520','prea1-s3-08-read-aloud-t-d','At Snack Time (/t/ vs /d/)',1,'reading','Pre A1 Starters',NULL,'It''s snack time at my house today. I want to drink tea, but my sister wants cold water instead. My dad drinks coffee every morning at ten o''clock. I don''t like coffee at all. Do you like tea? I like tea with a little sugar and two biscuits. My mom makes a sweet snack: a biscuit and a bit of juice for dessert. I eat a biscuit and drink some juice too. My brother doesn''t like juice, so he drinks cold milk instead. He also likes a sweet snack after dinner. It''s a good time to sit down and talk together as a family. We drink and eat, and then we do our homework at the table.','[{"text":"It''s snack time at my house today.","ipa":"/ɪts snæk taɪm æt maɪ haʊs təˈdeɪ./","vi":"Hôm nay là giờ ăn nhẹ tại nhà tôi."},{"text":"I want to drink tea, but my sister wants cold water instead.","ipa":"/aɪ wɑnt tu drɪŋk ti, bʌt maɪ ˈsɪstər wɑnts koʊld ˈwɔtər ɪnˈstɛd./","vi":"Tôi muốn uống trà, nhưng em gái tôi lại muốn uống nước lạnh."},{"text":"My dad drinks coffee every morning at ten o''clock.","ipa":"/maɪ dæd drɪŋks ˈkɔfi ˈɛvri ˈmɔrnɪŋ æt tɛn əˈklɑk./","vi":"Bố tôi uống cà phê vào mỗi buổi sáng lúc mười giờ."},{"text":"I don''t like coffee at all.","ipa":"/aɪ doʊnt laɪk ˈkɔfi æt ɔl./","vi":"Tôi không thích cà phê chút nào."},{"text":"Do you like tea?","ipa":"/du ju laɪk ti?/","vi":"Bạn có thích trà không?"},{"text":"I like tea with a little sugar and two biscuits.","ipa":"/aɪ laɪk ti wɪð ə ˈlɪtəl ˈʃʊgər ænd tu ˈbɪskəts./","vi":"Tôi thích trà với một chút đường và hai chiếc bánh quy."},{"text":"My mom makes a sweet snack: a biscuit and a bit of juice for dessert.","ipa":"/maɪ mɑm meɪks ə swit snæk: ə ˈbɪskət ænd ə bɪt ʌv dʒus fɔr dɪˈzɜrt./","vi":"Mẹ tôi làm một món ăn nhẹ ngọt ngào: một chiếc bánh quy và một chút nước ép để tráng miệng."},{"text":"I eat a biscuit and drink some juice too.","ipa":"/aɪ it ə ˈbɪskət ænd drɪŋk sʌm dʒus tu./","vi":"Tôi cũng ăn một chiếc bánh quy và uống một chút nước ép."},{"text":"My brother doesn''t like juice, so he drinks cold milk instead.","ipa":"/maɪ ˈbrʌðər ˈdʌzənt laɪk dʒus, so hi drɪŋks koʊld mɪlk ɪnˈstɛd./","vi":"Anh trai tôi không thích nước ép, nên anh ấy uống sữa lạnh thay thế."},{"text":"He also likes a sweet snack after dinner.","ipa":"/hi ˈɔlsoʊ laɪks ə swit snæk ˈæftər ˈdɪnər./","vi":"Anh ấy cũng thích ăn nhẹ đồ ngọt sau bữa tối."},{"text":"It''s a good time to sit down and talk together as a family.","ipa":"/ɪts ə gʊd taɪm tu sɪt daʊn ænd tɔk təˈgɛðər æz ə ˈfæməli./","vi":"Đây là khoảng thời gian tuyệt vời để cả gia đình cùng ngồi xuống và trò chuyện."},{"text":"We drink and eat, and then we do our homework at the table.","ipa":"/wi drɪŋk ænd it, ænd ðɛn wi du ˈaʊər ˈhoʊmwɜrk æt ðə ˈteɪbəl./","vi":"Chúng tôi vừa ăn uống, vừa làm bài tập về nhà tại bàn."}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,390,'7b684ec6-1123-4f12-ad58-cdc597a77cd4','7f3bce8fedfd3b05a63a079c87327931',NULL,NULL,'2026-07-25T11:23:14.813Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('f9fc4221-3ca7-4f65-88f3-344a45cbac2d','prea1-s3-09-listen-choose','What Do You Want to Drink?',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'Ana (F): Hi Leo! Do you like tea?
Leo (M): No, I don''t like tea. I like coffee.
Ana (F) [surprised]: Really? I don''t like coffee. Do you like juice?
Leo (M) [happy]: Yes, I do! I like orange juice very much.
Ana (F): I like juice too. Do you like water?
Leo (M): Yes, I like water. I drink water every day.
Ana (F): Do you like milk?
Leo (M): No, I don''t like milk. But I like snacks with my drink.
Ana (F): What snack do you like?
Leo (M): I like biscuits. Do you like biscuits too?
Ana (F) [happy]: Yes, I do! I like sweet biscuits. Are you thirsty now?
Leo (M): Yes, I''m very thirsty. Let''s get a drink.
Ana (F) [happy]: Good idea! I want some juice.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,400,'7b684ec6-1123-4f12-ad58-cdc597a77cd4','7f3bce8fedfd3b05a63a079c87327931',NULL,NULL,'2026-07-25T11:23:14.813Z',NULL);
