INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('c5f4fe42-022d-4c91-ae81-df217eec1dbd','prea1-s3-13-listen-choose-cafe','Ordering at the Café',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'Waiter (M): Good morning! Welcome to Sunny Café. Would you like a menu?
Grace (F): Yes, please. Thank you!
Waiter (M): What would you like to order?
Grace (F): I''d like a sandwich and some juice, please.
Waiter (M): Would you like some cake too?
Grace (F): Yes, I''d like a small cake, please. How much is the sandwich?
Waiter (M): The sandwich is three dollars.
Grace (F): And how much is the cake?
Waiter (M): The cake is two dollars.
Grace (F): How much is it all together?
Waiter (M): It''s six dollars, please.
Grace (F) [happy]: Here you are. Thank you!
Waiter (M) [happy]: Thank you! Enjoy your sandwich and cake.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,440,'7b684ec6-1123-4f12-ad58-cdc597a77cd4','7f3bce8fedfd3b05a63a079c87327931',NULL,NULL,'2026-07-25T11:23:14.813Z',NULL);
