INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('499b7329-d926-4d20-b72c-1b47c3c87380','prea1-s3-14-reading-cafe','A Trip to the Café',1,'reading','Pre A1 Starters',NULL,'Every Saturday, Lily and her mom go to a small café near their house. The café is called Sunny Café. When they arrive, a friendly waiter gives them a menu. Lily looks at the menu carefully. She would like a sandwich and some orange juice. Her mom would like a cup of tea and a small cake. The waiter writes down the order. After a few minutes, the food and drinks arrive at the table. Lily''s sandwich has cheese and chicken inside. It looks delicious! Her mom''s cake is sweet and fresh. When they finish eating, the waiter brings the bill. The sandwich is three dollars, the juice is two dollars, the tea is two dollars, and the cake is three dollars. ''How much is it all together?'' asks Lily''s mom. ''It''s ten dollars, please,'' says the waiter. Lily''s mom pays with a ten-dollar bill. They say ''Thank you!'' and leave the café happy.','[{"text":"Every Saturday, Lily and her mom go to a small café near their house.","ipa":"/ˈɛvri ˈsætərdeɪ, ˈlɪli ænd hər mɑm goʊ tu ə smɔl kæˈfeɪ nɪr ðɛr haʊs./","vi":"Mỗi thứ Bảy, Lily và mẹ đi đến một quán cà phê nhỏ gần nhà."},{"text":"The café is called Sunny Café.","ipa":"/ðə kæˈfeɪ ɪz kɔld ˈsʌni kæˈfeɪ./","vi":"Quán cà phê đó tên là Sunny Café."},{"text":"When they arrive, a friendly waiter gives them a menu.","ipa":"/wɛn ðeɪ əˈraɪv, ə ˈfrɛndli ˈweɪtər ɡɪvz ðɛm ə ˈmɛnju./","vi":"Khi họ đến nơi, một người phục vụ thân thiện đưa cho họ thực đơn."},{"text":"Lily looks at the menu carefully.","ipa":"/ˈlɪli lʊks æt ðə ˈmɛnju ˈkɛrfəli./","vi":"Lily xem thực đơn một cách cẩn thận."},{"text":"She would like a sandwich and some orange juice.","ipa":"/ʃi wʊd laɪk ə ˈsænwɪtʃ ænd sʌm ˈɔrɪndʒ dʒus./","vi":"Cô bé muốn một chiếc bánh mì kẹp và một ít nước cam."},{"text":"Her mom would like a cup of tea and a small cake.","ipa":"/hər mɑm wʊd laɪk ə kʌp əv ti ænd ə smɔl keɪk./","vi":"Mẹ cô bé muốn một tách trà và một chiếc bánh ngọt nhỏ."},{"text":"The waiter writes down the order.","ipa":"/ðə ˈweɪtər raɪts daʊn ði ˈɔrdər./","vi":"Người phục vụ ghi lại món họ gọi."},{"text":"After a few minutes, the food and drinks arrive at the table.","ipa":"/ˈæftər ə fju ˈmɪnɪts, ðə fud ænd drɪŋks əˈraɪv æt ðə ˈteɪbəl./","vi":"Sau vài phút, đồ ăn và thức uống được mang ra bàn."},{"text":"Lily''s sandwich has cheese and chicken inside.","ipa":"/ˈlɪliz ˈsænwɪtʃ hæz tʃiz ænd ˈtʃɪkən ɪnˈsaɪd./","vi":"Bánh mì của Lily có phô mai và thịt gà bên trong."},{"text":"It looks delicious!","ipa":"/ɪt lʊks dɪˈlɪʃəs!/","vi":"Trông thật ngon miệng!"},{"text":"Her mom''s cake is sweet and fresh.","ipa":"/hər mɑmz keɪk ɪz swit ænd frɛʃ./","vi":"Bánh của mẹ cô bé thì ngọt và tươi mới."},{"text":"When they finish eating, the waiter brings the bill.","ipa":"/wɛn ðeɪ ˈfɪnɪʃ ˈitɪŋ, ðə ˈweɪtər brɪŋz ðə bɪl./","vi":"Khi họ ăn xong, người phục vụ mang hóa đơn đến."},{"text":"The sandwich is three dollars, the juice is two dollars, the tea is two dollars, and the cake is three dollars.","ipa":"/ðə ˈsænwɪtʃ ɪz θri ˈdɑlərz, ðə dʒus ɪz tu ˈdɑlərz, ðə ti ɪz tu ˈdɑlərz, ænd ðə keɪk ɪz θri ˈdɑlərz./","vi":"Bánh mì giá ba đô la, nước cam giá hai đô la, trà giá hai đô la và bánh ngọt giá ba đô la."},{"text":"''How much is it all together?'' asks Lily''s mom.","ipa":"/haʊ mʌtʃ ɪz ɪt ɔl təˈɡɛðər? æsks ˈlɪliz mɑm./","vi":"\"Tổng cộng là bao nhiêu tiền vậy?\" mẹ Lily hỏi."},{"text":"''It''s ten dollars, please,'' says the waiter.","ipa":"/ɪts tɛn ˈdɑlərz, pliz, seɪz ðə ˈweɪtər./","vi":"\"Dạ là mười đô la ạ,\" người phục vụ nói."},{"text":"Lily''s mom pays with a ten-dollar bill.","ipa":"/ˈlɪliz mɑm peɪz wɪð ə tɛn-ˈdɑlər bɪl./","vi":"Mẹ Lily trả bằng tờ mười đô la."},{"text":"They say ''Thank you!'' and leave the café happy.","ipa":"/ðeɪ seɪ θæŋk ju! ænd liv ðə kæˈfeɪ ˈhæpi./","vi":"Họ nói \"Cảm ơn!\" và rời quán cà phê trong vui vẻ."}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'reading_comprehension',NULL,450,'7b684ec6-1123-4f12-ad58-cdc597a77cd4','7f3bce8fedfd3b05a63a079c87327931',NULL,NULL,'2026-07-25T11:23:14.813Z',NULL);
