INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('6ae2cf11-2398-48ed-b43d-58d874b48584','499b7329-d926-4d20-b72c-1b47c3c87380',14,'categorize','Sort each item by who ordered it.',NULL,NULL,NULL,NULL,NULL,'Lily gọi sandwich và juice; mẹ Lily gọi tea và cake.',NULL,NULL,NULL,'["Lily", "Lily''s mom"]','[{"text": "sandwich", "category": "Lily"}, {"text": "orange juice", "category": "Lily"}, {"text": "tea", "category": "Lily''s mom"}, {"text": "cake", "category": "Lily''s mom"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('a68107ff-7eaf-413e-838d-f365f12cecfd','prea1-s3-16-mixed-checkpoint','A Day of Food and Drinks',1,'mixed','Pre A1 Starters',NULL,'Today, Lily talks about food and drinks. In the morning, she has bread and an egg for breakfast. She likes bread very much, but she doesn''t like eggs. Her brother Tom likes eggs and rice. At school, Lily drinks water, but Tom likes juice. ''Do you like tea?'' Tom asks Lily. ''No, I don''t,'' says Lily. ''I like water more.'' After school, they go to a café with their mom. Lily would like a sandwich, please. Tom would like a cake. ''How much is the sandwich?'' asks their mom. ''It''s three dollars,'' says the waiter. The cake is two dollars, too. Their mom pays five dollars. Lily and Tom say ''Thank you!'' It''s a nice, tasty day.','[{"text":"Today, Lily talks about food and drinks.","ipa":"/təˈdeɪ, ˈlɪli tɔks əˈbaʊt fud ænd drɪŋks./","vi":"Hôm nay, Lily nói về đồ ăn và thức uống."},{"text":"In the morning, she has bread and an egg for breakfast.","ipa":"/ɪn ðə ˈmɔrnɪŋ, ʃi hæz brɛd ænd ən ɛɡ fɔr ˈbrɛkfəst./","vi":"Vào buổi sáng, cô bé ăn bánh mì và trứng cho bữa sáng."},{"text":"She likes bread very much, but she doesn''t like eggs.","ipa":"/ʃi laɪks brɛd ˈvɛri mʌtʃ, bʌt ʃi ˈdʌzənt laɪk ɛɡz./","vi":"Cô bé rất thích bánh mì, nhưng lại không thích trứng."},{"text":"Her brother Tom likes eggs and rice.","ipa":"/hər ˈbrʌðər tɑm laɪks ɛɡz ænd raɪs./","vi":"Anh trai Tom của cô bé thì thích trứng và cơm."},{"text":"At school, Lily drinks water, but Tom likes juice.","ipa":"/æt skul, ˈlɪli drɪŋks ˈwɔtər, bʌt tɑm laɪks dʒus./","vi":"Ở trường, Lily uống nước lọc, nhưng Tom lại thích nước trái cây."},{"text":"''Do you like tea?'' Tom asks Lily.","ipa":"/du ju laɪk ti? tɑm æsks ˈlɪli./","vi":"\"Em có thích trà không?\" Tom hỏi Lily."},{"text":"''No, I don''t,'' says Lily.","ipa":"/noʊ, aɪ doʊnt, sɛz ˈlɪli./","vi":"\"Không, em không thích,\" Lily trả lời."},{"text":"''I like water more.''","ipa":"/aɪ laɪk ˈwɔtər mɔr./","vi":"\"Em thích uống nước lọc hơn.\""},{"text":"After school, they go to a café with their mom.","ipa":"/ˈæftər skul, ðeɪ ɡoʊ tu ə kæˈfeɪ wɪð ðɛr mɑm./","vi":"Sau giờ học, hai anh em cùng mẹ đi đến một quán cà phê."},{"text":"Lily would like a sandwich, please.","ipa":"/ˈlɪli wʊd laɪk ə ˈsænwɪtʃ, pliz./","vi":"Lily muốn gọi một chiếc bánh mì kẹp."},{"text":"Tom would like a cake.","ipa":"/tɑm wʊd laɪk ə keɪk./","vi":"Tom thì muốn một chiếc bánh ngọt."},{"text":"''How much is the sandwich?'' asks their mom.","ipa":"/haʊ mʌtʃ ɪz ðə ˈsænwɪtʃ? æsks ðɛr mɑm./","vi":"\"Chiếc bánh mì kẹp giá bao nhiêu vậy?\" mẹ hỏi."},{"text":"''It''s three dollars,'' says the waiter.","ipa":"/ɪts θri ˈdɑlərz, sɛz ðə ˈweɪtər./","vi":"\"Ba đô la ạ,\" người phục vụ trả lời."},{"text":"The cake is two dollars, too.","ipa":"/ðə keɪk ɪz tu ˈdɑlərz, tu./","vi":"Chiếc bánh ngọt cũng có giá hai đô la."},{"text":"Their mom pays five dollars.","ipa":"/ðɛr mɑm peɪz faɪv ˈdɑlərz./","vi":"Mẹ trả tổng cộng năm đô la."},{"text":"Lily and Tom say ''Thank you!''","ipa":"/ˈlɪli ænd tɑm seɪ θæŋk ju!/","vi":"Lily và Tom nói \"Cảm ơn ạ!\""},{"text":"It''s a nice, tasty day.","ipa":"/ɪts ə naɪs, ˈteɪsti deɪ./","vi":"Đó là một ngày thật tuyệt và ngon miệng."}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mixed_all',NULL,470,'7b684ec6-1123-4f12-ad58-cdc597a77cd4','7f3bce8fedfd3b05a63a079c87327931',NULL,NULL,'2026-07-25T11:23:14.813Z',NULL);
