INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('f27285ef-edc0-4a5a-b09e-641bf71b8cd7','prea1-s4-03-read-aloud-th','My House (/θ/ vs /ð/)',1,'reading','Pre A1 Starters',NULL,'This is my house. It''s big and white. There is a kitchen, three bedrooms, and a bathroom. My mother and father sleep in the biggest bedroom. My brother sleeps in the room next to mine. There is a small bathroom with a mirror. In the kitchen, there is a table and three chairs. My mother cooks there every morning, and my father reads the newspaper. There is a garden behind the house with a big tree and three flowers. I think this house is the best house on this street. This is where my family lives together, and we love this house very much. Thank you for visiting my house today!','[{"text":"This is my house.","ipa":"/ðɪs ɪz maɪ haʊs./","vi":"Đây là nhà của mình."},{"text":"It''s big and white.","ipa":"/ɪts bɪg ænd waɪt./","vi":"Nó to và có màu trắng."},{"text":"There is a kitchen, three bedrooms, and a bathroom.","ipa":"/ðɛr ɪz ə ˈkɪtʃən, θri ˈbɛdˌrumz, ænd ə ˈbæθˌrum./","vi":"Nhà có một phòng bếp, ba phòng ngủ và một phòng tắm."},{"text":"My mother and father sleep in the biggest bedroom.","ipa":"/maɪ ˈmʌðər ænd ˈfɑðər slip ɪn ðə ˈbɪgəst ˈbɛdˌrum./","vi":"Bố mẹ mình ngủ ở phòng ngủ lớn nhất."},{"text":"My brother sleeps in the room next to mine.","ipa":"/maɪ ˈbrʌðər slips ɪn ðə rum nɛkst tu maɪn./","vi":"Anh trai mình ngủ ở căn phòng ngay cạnh phòng mình."},{"text":"There is a small bathroom with a mirror.","ipa":"/ðɛr ɪz ə smɔl ˈbæθˌrum wɪð ə ˈmɪrər./","vi":"Có một phòng tắm nhỏ với một chiếc gương."},{"text":"In the kitchen, there is a table and three chairs.","ipa":"/ɪn ðə ˈkɪtʃən, ðɛr ɪz ə ˈteɪbəl ænd θri tʃɛrz./","vi":"Trong bếp có một cái bàn và ba cái ghế."},{"text":"My mother cooks there every morning, and my father reads the newspaper.","ipa":"/maɪ ˈmʌðər kʊks ðɛr ˈɛvəri ˈmɔrnɪŋ, ænd maɪ ˈfɑðər ridz ðə ˈnuzˌpeɪpər./","vi":"Mẹ mình nấu ăn ở đó mỗi sáng, còn bố mình thì đọc báo."},{"text":"There is a garden behind the house with a big tree and three flowers.","ipa":"/ðɛr ɪz ə ˈgɑrdən bɪˈhaɪnd ðə haʊs wɪð ə bɪg tri ænd θri ˈflaʊərz./","vi":"Phía sau nhà có một khu vườn với một cái cây lớn và ba bông hoa."},{"text":"I think this house is the best house on this street.","ipa":"/aɪ θɪŋk ðɪs haʊs ɪz ðə bɛst haʊs ɑn ðɪs strit./","vi":"Mình nghĩ đây là ngôi nhà tuyệt nhất trên con phố này."},{"text":"This is where my family lives together, and we love this house very much.","ipa":"/ðɪs ɪz wɛr maɪ ˈfæməli lɪvz təˈgɛðər, ænd wi lʌv ðɪs haʊs ˈvɛri mʌtʃ./","vi":"Đây là nơi gia đình mình sống cùng nhau, và chúng mình rất yêu ngôi nhà này."},{"text":"Thank you for visiting my house today!","ipa":"/θæŋk yu fɔr ˈvɪzɪtɪŋ maɪ haʊs təˈdeɪ!/","vi":"Cảm ơn bạn đã ghé thăm nhà mình hôm nay nhé!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,620,'3b88bd86-f6d6-4a24-a034-70de84255b23','fa708633f9b354a508ff9e8e0fdead3b',NULL,NULL,'2026-07-25T11:25:14.660Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('4bc79482-621a-40b8-b9e2-ef043e47cde0','prea1-s4-04-listen-choose','A Tour of My House',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'Ben (M): Welcome to my house! This is the living room.
Mia (F) [surprised]: Wow, it''s so big! Is there a kitchen too?
Ben (M): Yes. The kitchen is next to the living room.
Mia (F): How many bedrooms are there?
Ben (M): There are three bedrooms. My bedroom is upstairs.
Mia (F): Is there a bathroom upstairs?
Ben (M): Yes, a small bathroom next to my bedroom.
Mia (F) [happy]: I love your garden! Is it big?
Ben (M): Yes, it''s very big. There is a big tree in it.
Mia (F): Is there a TV in the living room?
Ben (M): Yes, a big TV and a comfortable sofa.
Mia (F): What color is your bedroom?
Ben (M): My bedroom is blue, with a small window.
Mia (F): Is there a mirror in the bathroom?
Ben (M): Yes, a big mirror next to the sink.
Mia (F) [happy]: This house is wonderful, Ben!
Ben (M) [happy]: Thank you! Let''s have some tea in the kitchen.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,630,'3b88bd86-f6d6-4a24-a034-70de84255b23','fa708633f9b354a508ff9e8e0fdead3b',NULL,NULL,'2026-07-25T11:25:14.660Z',NULL);
