INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('cbe83a48-744e-47de-b6ae-8a75e83a07ca','prea1-s4-08-read-aloud-u','In My Room (/ʊ/ vs /uː/)',1,'reading','Pre A1 Starters',NULL,'Look at my room! It''s a good room with a big window. There is a wooden bed and a blue blanket. I put my books on the shelf, and I put my shoes under the bed. My cushion is on the chair, and my wardrobe is full of clothes. I look at the clock on the wall; it''s noon soon. My room is cool and quiet, and I like to look at a book on my bed. My mother tells me to clean my room, so I put the cushion on the sofa and close the door. This room is a good place to sleep, and I love my room very much.','[{"text":"Look at my room!","ipa":"/lʊk æt maɪ rum/","vi":"Hãy nhìn căn phòng của mình này!"},{"text":"It''s a good room with a big window.","ipa":"/ɪts ə ɡʊd rum wɪð ə bɪɡ ˈwɪndoʊ/","vi":"Đó là một căn phòng đẹp với một cái cửa sổ lớn."},{"text":"There is a wooden bed and a blue blanket.","ipa":"/ðɛr ɪz ə ˈwʊdən bɛd ænd ə blu ˈblæŋkɪt/","vi":"Trong phòng có một chiếc giường gỗ và một cái chăn màu xanh dương."},{"text":"I put my books on the shelf, and I put my shoes under the bed.","ipa":"/aɪ pʊt maɪ bʊks ɑn ðə ʃɛlf, ænd aɪ pʊt maɪ ʃuz ˈʌndər ðə bɛd/","vi":"Mình đặt sách lên kệ và để giày dưới gầm giường."},{"text":"My cushion is on the chair, and my wardrobe is full of clothes.","ipa":"/maɪ ˈkʊʃən ɪz ɑn ðə tʃɛr, ænd maɪ ˈwɔrˌdroʊb ɪz fʊl əv kloʊðz/","vi":"Gối của mình ở trên ghế, còn tủ quần áo thì đầy ắp đồ."},{"text":"I look at the clock on the wall; it''s noon soon.","ipa":"/aɪ lʊk æt ðə klɑk ɑn ðə wɔl; ɪts nun sun/","vi":"Mình nhìn đồng hồ trên tường; sắp đến trưa rồi."},{"text":"My room is cool and quiet, and I like to look at a book on my bed.","ipa":"/maɪ rum ɪz kul ænd ˈkwaɪət, ænd aɪ laɪk tu lʊk æt ə bʊk ɑn maɪ bɛd/","vi":"Phòng mình rất mát mẻ và yên tĩnh, mình thích nằm trên giường đọc sách."},{"text":"My mother tells me to clean my room, so I put the cushion on the sofa and close the door.","ipa":"/maɪ ˈmʌðər tɛlz mi tu klin maɪ rum, soʊ aɪ pʊt ðə ˈkʊʃən ɑn ðə ˈsoʊfə ænd kloʊz ðə dɔr/","vi":"Mẹ bảo mình dọn phòng, nên mình mang gối ra ghế sofa rồi đóng cửa lại."},{"text":"This room is a good place to sleep, and I love my room very much.","ipa":"/ðɪs rum ɪz ə ɡʊd pleɪs tu slip, ænd aɪ lʌv maɪ rum ˈvɛri mʌtʃ/","vi":"Căn phòng này là một nơi tuyệt vời để ngủ, và mình rất yêu căn phòng của mình."}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,670,'3b88bd86-f6d6-4a24-a034-70de84255b23','fa708633f9b354a508ff9e8e0fdead3b',NULL,NULL,'2026-07-25T11:25:14.660Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('1dd96a8a-419f-43c5-85ed-22b8fd099dd8','prea1-s4-09-listen-choose-find-it','Where Is It?',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'Alex (M) [worried]: Where is my toy car? I can''t find it!
Lily (F): Is it under the bed?
Alex (M): No, it''s not under the bed.
Lily (F): Look on the shelf, next to your books.
Alex (M): No, it''s not on the shelf.
Lily (F): Is it in the drawer?
Alex (M) [happy]: Yes! It''s in the drawer, under my socks!
Lily (F) [happy]: Great! Now where is your ball?
Alex (M): I think it''s under the table.
Lily (F): Yes, it''s under the table, behind the chair.
Alex (M): Thank you! Now I need my blanket.
Lily (F): It''s on your bed, next to the pillow.
Alex (M) [relieved]: Oh yes, I see it now!
Lily (F): And your lamp is on the desk, in front of the clock.
Alex (M) [happy]: Perfect! My room is clean and tidy now.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,680,'3b88bd86-f6d6-4a24-a034-70de84255b23','fa708633f9b354a508ff9e8e0fdead3b',NULL,NULL,'2026-07-25T11:25:14.660Z',NULL);
