INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('b99e9a15-45e7-487f-9c14-b71cb3b9c9b1','879ad693-6f01-42a1-a037-0c3bb0ce34bf',21,'categorize','Sort each word by ''have'' or ''has''.',NULL,NULL,NULL,NULL,NULL,'Ngôi thứ 3 số ít (she/he/it) dùng ''has''.',NULL,NULL,NULL,'["have", "has"]','[{"text": "I", "category": "have"}, {"text": "she", "category": "has"}, {"text": "we", "category": "have"}, {"text": "he", "category": "has"}, {"text": "they", "category": "have"}, {"text": "it", "category": "has"}]',NULL,'present-simple');
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('7b0684c7-aebe-4b3b-bed5-a603bfee5c67','prea1-s4-13-read-aloud-k-g','My Pet (/k/ vs /g/)',1,'reading','Pre A1 Starters',NULL,'I have a cat and a dog. My cat is small and grey, and my dog is big and gold. My cat likes to climb, and my dog likes to run in the garden. My grandma has a goat and a cow on her farm. The goat is grey, and the cow is big and calm. I also have a green frog in a glass box. My friend Greg has a big rabbit and a small duck. We give our pets good food every day. Taking care of a pet is a great job, and I am glad to have my cat and dog. I think pets make our family happy!','[{"text":"I have a cat and a dog.","ipa":"/aɪ hæv ə kæt ænd ə dɔɡ./","vi":"Tôi có một con mèo và một con chó."},{"text":"My cat is small and grey, and my dog is big and gold.","ipa":"/maɪ kæt ɪz smɔl ænd ɡreɪ, ænd maɪ dɔɡ ɪz bɪɡ ænd ɡoʊld./","vi":"Con mèo của tôi nhỏ và có màu xám, còn con chó của tôi thì to và có màu vàng."},{"text":"My cat likes to climb, and my dog likes to run in the garden.","ipa":"/maɪ kæt laɪks tu klaɪm, ænd maɪ dɔɡ laɪks tu rʌn ɪn ðə ˈɡɑrdən./","vi":"Con mèo thích leo trèo, còn con chó thích chạy nhảy trong vườn."},{"text":"My grandma has a goat and a cow on her farm.","ipa":"/maɪ ˈɡrændˌmɑ hæz ə ɡoʊt ænd ə kaʊ ɑn hər fɑrm./","vi":"Bà của tôi có một con dê và một con bò ở trong trang trại."},{"text":"The goat is grey, and the cow is big and calm.","ipa":"/ðə ɡoʊt ɪz ɡreɪ, ænd ðə kaʊ ɪz bɪɡ ænd kɑm./","vi":"Con dê có màu xám, còn con bò thì to lớn và hiền lành."},{"text":"I also have a green frog in a glass box.","ipa":"/aɪ ˈɔlsoʊ hæv ə ɡrin frɑɡ ɪn ə ɡlæs bɑks./","vi":"Tôi còn có một con ếch màu xanh lá cây trong một cái hộp thủy tinh."},{"text":"My friend Greg has a big rabbit and a small duck.","ipa":"/maɪ frɛnd ɡrɛɡ hæz ə bɪɡ ˈræbɪt ænd ə smɔl dʌk./","vi":"Bạn Greg của tôi có một con thỏ to và một con vịt nhỏ."},{"text":"We give our pets good food every day.","ipa":"/wi ɡɪv ˈaʊər pɛts ɡʊd fud ˈɛvri deɪ./","vi":"Chúng tôi cho thú cưng ăn thức ăn ngon mỗi ngày."},{"text":"Taking care of a pet is a great job, and I am glad to have my cat and dog.","ipa":"/ˈteɪkɪŋ kɛr əv ə pɛt ɪz ə ɡreɪt dʒɑb, ænd aɪ æm ɡlæd tu hæv maɪ kæt ænd dɔɡ./","vi":"Chăm sóc thú cưng là một việc rất tuyệt, và tôi rất vui khi có con mèo và con chó của mình."},{"text":"I think pets make our family happy!","ipa":"/aɪ θɪŋk pɛts meɪk ˈaʊər ˈfæməli ˈhæpi!/","vi":"Tôi nghĩ thú cưng làm cho gia đình chúng tôi hạnh phúc!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,720,'3b88bd86-f6d6-4a24-a034-70de84255b23','03b6c4da770844e9db339f05b419ad55',NULL,NULL,'2026-07-25T11:25:14.660Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('d90218a2-e8c4-4920-bdbb-422ed9d45c58','prea1-s4-14-listen-choose','Do You Have a Pet?',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'Sara (F): Do you have a pet, Tom?
Tom (M): Yes, I have a dog. His name is Rex.
Sara (F): Is Rex big or small?
Tom (M): He''s big, and he''s brown.
Sara (F): I have a cat. Her name is Luna.
Tom (M): Is Luna big or small?
Sara (F): She''s small, and she''s white.
Tom (M): Do you have any other pets?
Sara (F): Yes, I have a rabbit too. It''s grey.
Tom (M) [surprised]: Wow! My grandpa has a farm with a cow and two sheep.
Sara (F) [happy]: That''s great! Does he have a horse?
Tom (M): No, but he has a goat and some ducks.
Sara (F) [happy]: I love animals! Can I visit the farm?
Tom (M) [happy]: Sure! You can see the pig too. It''s very pink!
Sara (F) [excited]: I can''t wait to see all the animals!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,730,'3b88bd86-f6d6-4a24-a034-70de84255b23','03b6c4da770844e9db339f05b419ad55',NULL,NULL,'2026-07-25T11:25:14.660Z',NULL);
