INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('6f4eea08-8993-4bd4-979a-4e75cda9643d','d90218a2-e8c4-4920-bdbb-422ed9d45c58',14,'multiple_choice','What does Sara want to do?','["Visit the farm", "Buy a new pet", "Go to school", "Clean her room"]','Visit the farm',NULL,NULL,NULL,'Sara hỏi ''Can I visit the farm?''.','Sara (F): I love animals! Can I visit the farm?',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('53fb6ea0-549e-4669-858c-3086759ddf42','prea1-s4-16-mixed-checkpoint','Home, Sweet Home',1,'mixed','Pre A1 Starters',NULL,'Good afternoon! Today I want to tell you about my home and my pet. There is a big kitchen, three bedrooms, and a small bathroom in my house. My bedroom is blue, and there is a soft bed next to the window. My books are on the shelf, and my shoes are under the bed. I have a small dog. His name is Max. Max is brown and very friendly. He sleeps under my bed at night. ''Where is Max?'' my mother asks every morning. ''He''s under my bed!'' I answer. There is a big garden behind the house, and Max loves to run there. My grandma has a farm with a cow and two goats. I love my home and my pet very much.','[{"text":"Good afternoon!","ipa":"/ɡʊd ˌæftərˈnun/","vi":"Chào buổi chiều!"},{"text":"Today I want to tell you about my home and my pet.","ipa":"/təˈdeɪ aɪ wɑnt tu tɛl ju əˈbaʊt maɪ hoʊm ænd maɪ pɛt/","vi":"Hôm nay mình muốn kể cho bạn nghe về ngôi nhà và thú cưng của mình."},{"text":"There is a big kitchen, three bedrooms, and a small bathroom in my house.","ipa":"/ðɛr ɪz ə bɪɡ ˈkɪtʃən, θri ˈbɛdˌrumz, ænd ə smɔl ˈbæθˌrum ɪn maɪ haʊs/","vi":"Nhà mình có một căn bếp lớn, ba phòng ngủ và một phòng tắm nhỏ."},{"text":"My bedroom is blue, and there is a soft bed next to the window.","ipa":"/maɪ ˈbɛdˌrum ɪz blu, ænd ðɛr ɪz ə sɔft bɛd nɛkst tu ðə ˈwɪndoʊ/","vi":"Phòng ngủ của mình màu xanh dương, và có một chiếc giường êm ái cạnh cửa sổ."},{"text":"My books are on the shelf, and my shoes are under the bed.","ipa":"/maɪ bʊks ɑr ɑn ðə ʃɛlf, ænd maɪ ʃuz ɑr ˈʌndər ðə bɛd/","vi":"Sách của mình ở trên kệ, còn giày thì để dưới gầm giường."},{"text":"I have a small dog.","ipa":"/aɪ hæv ə smɔl dɔɡ/","vi":"Mình có một chú chó nhỏ."},{"text":"His name is Max.","ipa":"/hɪz neɪm ɪz mæks/","vi":"Tên của chú ấy là Max."},{"text":"Max is brown and very friendly.","ipa":"/mæks ɪz braʊn ænd ˈvɛri ˈfrɛndli/","vi":"Max có màu nâu và rất thân thiện."},{"text":"He sleeps under my bed at night.","ipa":"/hi slips ˈʌndər maɪ bɛd æt naɪt/","vi":"Chú ấy ngủ dưới gầm giường của mình vào ban đêm."},{"text":"''Where is Max?'' my mother asks every morning.","ipa":"/wɛr ɪz mæks? maɪ ˈmʌðər æsks ˈɛvəri ˈmɔrnɪŋ/","vi":"\"Max đâu rồi?\" mẹ mình hỏi mỗi sáng."},{"text":"''He''s under my bed!'' I answer.","ipa":"/hiz ˈʌndər maɪ bɛd! aɪ ˈænsər/","vi":"\"Chú ấy ở dưới gầm giường con!\" mình trả lời."},{"text":"There is a big garden behind the house, and Max loves to run there.","ipa":"/ðɛr ɪz ə bɪɡ ˈɡɑrdən bɪˈhaɪnd ðə haʊs, ænd mæks lʌvz tu rʌn ðɛr/","vi":"Có một khu vườn lớn phía sau nhà, và Max rất thích chạy nhảy ở đó."},{"text":"My grandma has a farm with a cow and two goats.","ipa":"/maɪ ˈɡrændˌmɑ hæz ə fɑrm wɪð ə kaʊ ænd tu ɡoʊts/","vi":"Bà mình có một trang trại với một con bò và hai con dê."},{"text":"I love my home and my pet very much.","ipa":"/aɪ lʌv maɪ hoʊm ænd maɪ pɛt ˈvɛri mʌtʃ/","vi":"Mình rất yêu ngôi nhà và thú cưng của mình."}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mixed_all',NULL,750,'3b88bd86-f6d6-4a24-a034-70de84255b23','fa708633f9b354a508ff9e8e0fdead3b',NULL,NULL,'2026-07-25T11:25:14.660Z',NULL);
