INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('9df5ce39-b383-406f-938c-9f737aebf6a4','1daea8af-2f02-4f77-8621-33af327b587c',19,'ordering','Put the words in the correct order.',NULL,'Her tooth hurts',NULL,NULL,NULL,'Trật tự: tính từ sở hữu (Her) + danh từ (tooth) + động từ (hurts).',NULL,NULL,'["hurts","tooth","Her"]',NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('acb91ab5-fbd1-483d-9e50-968d79dee2c3','1daea8af-2f02-4f77-8621-33af327b587c',20,'categorize','Sort each body part by whose it is (male or female).',NULL,NULL,NULL,NULL,NULL,'''His'' dùng cho nam, ''Her'' dùng cho nữ.',NULL,NULL,NULL,'["Male (his)","Female (her)"]','[{"text":"his knee","category":"Male (his)"},{"text":"her arm","category":"Female (her)"},{"text":"his back","category":"Male (his)"},{"text":"her tooth","category":"Female (her)"}]',NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('f0aa035f-730a-4fb0-8c40-3770ff59b7d6','1daea8af-2f02-4f77-8621-33af327b587c',21,'categorize','Sort each sentence: ''hurts'' (one part) or ''hurt'' (many parts)?',NULL,NULL,NULL,NULL,NULL,'Một bộ phận số ít dùng ''hurts''; nhiều bộ phận (số nhiều) dùng ''hurt''.',NULL,NULL,NULL,'["hurts (one)","hurt (many)"]','[{"text":"My head","category":"hurts (one)"},{"text":"My legs","category":"hurt (many)"},{"text":"Her arm","category":"hurts (one)"},{"text":"His feet","category":"hurt (many)"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('ca6455dc-431f-4b5a-a89d-2dbeaf29e1eb','prea1-s5-03-read-aloud-h-f','My Body Hurts (/h/ vs /f/)',1,'reading','Pre A1 Starters',NULL,'Look at my face! I have two eyes, a nose, and a mouth. My hair is short and black. Yesterday, I fell down and hurt my hand. My hand still hurts a little. My friend Faye has a headache today. Her head hurts a lot. She feels sick and has a fever. We went to the hospital to see the doctor. The doctor looked at Faye''s face and felt her forehead. ''You have a fever,'' he said. ''Drink water and rest.'' Faye said, ''Thank you, doctor.'' Now Faye feels fine. I hope her headache goes away fast. Health is very important for everyone!','[{"text":"Look at my face!","ipa":"/lʊk æt maɪ feɪs/","vi":"Hãy nhìn vào khuôn mặt của mình này!"},{"text":"I have two eyes, a nose, and a mouth.","ipa":"/aɪ hæv tu aɪz, ə noʊz, ænd ə maʊθ/","vi":"Mình có hai mắt, một cái mũi và một cái miệng."},{"text":"My hair is short and black.","ipa":"/maɪ hɛr ɪz ʃɔrt ænd blæk/","vi":"Tóc mình ngắn và có màu đen."},{"text":"Yesterday, I fell down and hurt my hand.","ipa":"/ˈjɛstərˌdeɪ, aɪ fɛl daʊn ænd hɜrt maɪ hænd/","vi":"Hôm qua, mình bị ngã và làm đau tay."},{"text":"My hand still hurts a little.","ipa":"/maɪ hænd stɪl hɜrts ə ˈlɪtəl/","vi":"Tay mình vẫn còn hơi đau một chút."},{"text":"My friend Faye has a headache today.","ipa":"/maɪ frɛnd feɪ hæz ə ˈhɛdˌeɪk təˈdeɪ/","vi":"Bạn Faye của mình hôm nay bị đau đầu."},{"text":"Her head hurts a lot.","ipa":"/hɜr hɛd hɜrts ə lɑt/","vi":"Đầu bạn ấy đau lắm."},{"text":"She feels sick and has a fever.","ipa":"/ʃi filz sɪk ænd hæz ə ˈfivər/","vi":"Bạn ấy cảm thấy mệt và bị sốt."},{"text":"We went to the hospital to see the doctor.","ipa":"/wi wɛnt tu ðə ˈhɑˌspɪtəl tu si ðə ˈdɑktər/","vi":"Chúng mình đã đến bệnh viện để gặp bác sĩ."},{"text":"The doctor looked at Faye''s face and felt her forehead.","ipa":"/ðə ˈdɑktər lʊkt æt feɪz feɪs ænd fɛlt hɜr ˈfɔrˌhɛd/","vi":"Bác sĩ nhìn vào mặt Faye và sờ trán bạn ấy."},{"text":"''You have a fever,'' he said.","ipa":"/ju hæv ə ˈfivər, hi sɛd/","vi":"\"Cháu bị sốt rồi,\" bác sĩ nói."},{"text":"''Drink water and rest.''","ipa":"/drɪŋk ˈwɔtər ænd rɛst/","vi":"\"Hãy uống nước và nghỉ ngơi nhé.\""},{"text":"Faye said, ''Thank you, doctor.''","ipa":"/feɪ sɛd, θæŋk ju, ˈdɑktər/","vi":"Faye nói: \"Cháu cảm ơn bác sĩ ạ.\""},{"text":"Now Faye feels fine.","ipa":"/naʊ feɪ filz faɪn/","vi":"Bây giờ Faye cảm thấy khỏe hơn rồi."},{"text":"I hope her headache goes away fast.","ipa":"/aɪ hoʊp hɜr ˈhɛdˌeɪk goʊz əˈweɪ fæst/","vi":"Mình hy vọng cơn đau đầu của bạn ấy sẽ nhanh chóng biến mất."},{"text":"Health is very important for everyone!","ipa":"/hɛlθ ɪz ˈvɛri ɪmˈpɔrtənt fɔr ˈɛvriˌwʌn/","vi":"Sức khỏe rất quan trọng đối với tất cả mọi người!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,900,'e2186f79-6fc7-4843-acb7-b89fe884dd34','71ab9bd5210054d2e76e8ca9ad5e6833',NULL,NULL,'2026-07-25T11:31:14.014Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('88daebab-fb5c-4d7a-ad0d-f981426aa92b','prea1-s5-04-listen-choose-doctor','At the Doctor',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'Dr. Kim (F) [gentle]: Hello! What''s wrong today?
Leo (M) [worried]: Hi, Dr. Kim. My head hurts a lot.
Dr. Kim (F) [gentle]: I see. Does your stomach hurt too?
Leo (M): No, it doesn''t. But my hand hurts a little.
Dr. Kim (F) [gentle]: Let me look. Can you move your fingers?
Leo (M): Yes, I can. It''s not too bad.
Dr. Kim (F) [gentle]: Good. Now, do your legs hurt?
Leo (M): No, my legs are fine. Only my head and my hand.
Dr. Kim (F) [calm]: Okay. You need to rest today.
Leo (M) [worried]: What about my eyes? They feel tired.
Dr. Kim (F) [gentle]: Close your eyes and rest for one hour.
Leo (M): Thank you, Dr. Kim.
Dr. Kim (F) [gentle]: You''re welcome. Drink some water too.
Leo (M) [relieved]: I will. My nose feels okay, so that''s good.
Dr. Kim (F) [calm]: Great. Come back if your head still hurts tomorrow.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,910,'e2186f79-6fc7-4843-acb7-b89fe884dd34','71ab9bd5210054d2e76e8ca9ad5e6833',NULL,NULL,'2026-07-25T11:31:14.014Z',NULL);
