INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('b3b896ed-27eb-4892-83bc-1f431500bb64','prea1-s5-08-read-aloud-ei-e','How I Feel Today (/eɪ/ vs /e/)',1,'reading','Pre A1 Starters',NULL,'Today is a great day! I feel happy and excited to play with my friends. But sometimes I feel afraid, like when it''s dark. Is that okay? Yes, it''s okay to feel afraid sometimes. My friend Faye says, ''Just tell me, and I will help you.'' When I feel sad, I rest and feel well again. My best friend, Jay, always makes me laugh. Today, I am happy, and I feel great. I say, ''Thank you, Jay, my best friend!''','[{"text":"Today is a great day!","ipa":"/təˈdeɪ ɪz ə greɪt deɪ/","vi":"Hôm nay là một ngày tuyệt vời!"},{"text":"I feel happy and excited to play with my friends.","ipa":"/aɪ fiːl ˈhæpi ænd ɪkˈsaɪtɪd tu pleɪ wɪð maɪ frɛndz/","vi":"Tớ cảm thấy rất vui và hào hứng khi được chơi cùng các bạn."},{"text":"But sometimes I feel afraid, like when it''s dark.","ipa":"/bʌt ˈsʌmˌtaɪmz aɪ fiːl əˈfreɪd, laɪk wɛn ɪts dɑrk/","vi":"Nhưng đôi khi tớ cũng thấy sợ, ví dụ như khi trời tối."},{"text":"Is that okay?","ipa":"/ɪz ðæt oʊˈkeɪ/","vi":"Như vậy có sao không nhỉ?"},{"text":"Yes, it''s okay to feel afraid sometimes.","ipa":"/jɛs, ɪts oʊˈkeɪ tu fiːl əˈfreɪd ˈsʌmˌtaɪmz/","vi":"Có chứ, thỉnh thoảng cảm thấy sợ là chuyện bình thường mà."},{"text":"My friend Faye says, ''Just tell me, and I will help you.''","ipa":"/maɪ frɛnd feɪ sɛz, dʒʌst tɛl mi, ænd aɪ wɪl hɛlp ju/","vi":"Bạn Faye của tớ bảo rằng: ''Cứ nói với tớ, tớ sẽ giúp cậu.''"},{"text":"When I feel sad, I rest and feel well again.","ipa":"/wɛn aɪ fiːl sæd, aɪ rɛst ænd fiːl wɛl əˈgɛn/","vi":"Khi buồn, tớ sẽ nghỉ ngơi và cảm thấy khỏe khoắn trở lại."},{"text":"My best friend, Jay, always makes me laugh.","ipa":"/maɪ bɛst frɛnd, dʒeɪ, ˈɔlˌweɪz meɪks mi læf/","vi":"Bạn thân nhất của tớ, Jay, luôn làm tớ cười."},{"text":"Today, I am happy, and I feel great.","ipa":"/təˈdeɪ, aɪ æm ˈhæpi, ænd aɪ fiːl greɪt/","vi":"Hôm nay, tớ rất vui và cảm thấy thật tuyệt."},{"text":"I say, ''Thank you, Jay, my best friend!''","ipa":"/aɪ seɪ, θæŋk ju, dʒeɪ, maɪ bɛst frɛnd/","vi":"Tớ nói: ''Cảm ơn cậu nhé, Jay, bạn thân nhất của tớ!''"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,950,'e2186f79-6fc7-4843-acb7-b89fe884dd34','fc95a7e65cc48f4cd00079b539d20d12',NULL,NULL,'2026-07-25T11:31:14.014Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('f3132433-e169-4ca0-844f-e4889d8c5046','prea1-s5-09-listen-choose-feelings','How Are You Feeling?',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'Mia (F): Hi Sam! How are you feeling today?
Sam (M): Hi Mia. I''m a little tired. I didn''t sleep well.
Mia (F) [worried]: Oh no! Are you sad about it?
Sam (M): No, I''m not sad. I''m just sleepy.
Mia (F) [happy]: I''m happy today! I got a new book.
Sam (M) [happy]: That''s great! Are you excited to read it?
Mia (F) [excited]: Yes, I''m very excited!
Sam (M) [worried]: My little sister is scared of the dark.
Mia (F): Really? What do you do?
Sam (M): I stay with her, and she feels better.
Mia (F) [happy]: That''s so kind of you!
Sam (M): Thanks. Are you hungry? Let''s eat lunch.
Mia (F) [happy]: Yes, I''m hungry too. Let''s go!
Sam (M) [worried]: Wait, are you worried about the test tomorrow?
Mia (F) [calm]: A little, but I feel okay now.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,960,'e2186f79-6fc7-4843-acb7-b89fe884dd34','fc95a7e65cc48f4cd00079b539d20d12',NULL,NULL,'2026-07-25T11:31:14.014Z',NULL);
