INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('62d9d65f-35e2-4f38-8d92-4fc1dfed8c99','84bad12a-a84f-41c9-b9fc-1f720cd4f8d8',20,'categorize','Sort each sentence by the weather it describes.',NULL,NULL,NULL,NULL,NULL,'Phân loại theo tính từ thời tiết trong câu.',NULL,NULL,NULL,'["Sunny/Hot","Rainy/Cold"]','[{"text":"It''s sunny today.","category":"Sunny/Hot"},{"text":"It''s raining outside.","category":"Rainy/Cold"},{"text":"It''s very hot.","category":"Sunny/Hot"},{"text":"It''s cold and windy.","category":"Rainy/Cold"}]',NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('35892d43-bf36-4f37-a1b3-75aa0d0b25f8','84bad12a-a84f-41c9-b9fc-1f720cd4f8d8',21,'categorize','Sort each clothing item by the weather it''s for.',NULL,NULL,NULL,NULL,NULL,'Quần áo dày mặc khi lạnh, quần áo mỏng mặc khi nóng.',NULL,NULL,NULL,'["Hot weather clothes","Cold weather clothes"]','[{"text":"t-shirt","category":"Hot weather clothes"},{"text":"cap","category":"Hot weather clothes"},{"text":"coat","category":"Cold weather clothes"},{"text":"scarf","category":"Cold weather clothes"},{"text":"sweater","category":"Cold weather clothes"},{"text":"jacket","category":"Cold weather clothes"}]',NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('0baa5070-0268-4d2b-b35c-58afb56b15dd','prea1-s5-13-read-aloud-ow-ou','Today''s Weather (/aʊ/ vs /oʊ/)',1,'reading','Pre A1 Starters',NULL,'Look outside now! How is the weather today? It''s cold and snowy. Snow is falling slowly, and the wind is starting to blow. I put on my warm coat and my scarf. My mom says, ''Wow, it''s very cold outside!'' We talk about the cloudy sky. Soon, the snow will cover the ground. I like cold weather, so I go outside to play. My friend also wears a big coat. We throw snowballs and laugh out loud. Now, let''s go home and drink something warm!','[{"text":"Look outside now!","ipa":"/lʊk ˌaʊtˈsaɪd naʊ/","vi":"Hãy nhìn ra ngoài xem!"},{"text":"How is the weather today?","ipa":"/haʊ ɪz ðə ˈwɛðər təˈdeɪ/","vi":"Thời tiết hôm nay thế nào?"},{"text":"It''s cold and snowy.","ipa":"/ɪts koʊld ænd ˈsnoʊi/","vi":"Trời lạnh và có tuyết."},{"text":"Snow is falling slowly, and the wind is starting to blow.","ipa":"/snoʊ ɪz ˈfɔlɪŋ ˈsloʊli, ænd ðə wɪnd ɪz ˈstɑrtɪŋ tu bloʊ/","vi":"Tuyết đang rơi chậm rãi, và gió bắt đầu thổi."},{"text":"I put on my warm coat and my scarf.","ipa":"/aɪ pʊt ɑn maɪ wɔrm koʊt ænd maɪ skɑrf/","vi":"Tôi mặc áo khoác ấm và quàng khăn vào."},{"text":"My mom says, ''Wow, it''s very cold outside!''","ipa":"/maɪ mɑm sɛz, waʊ, ɪts ˈvɛri koʊld ˌaʊtˈsaɪd/","vi":"Mẹ tôi nói: ''Ồ, ngoài trời lạnh quá!''"},{"text":"We talk about the cloudy sky.","ipa":"/wi tɔk əˈbaʊt ðə ˈklaʊdi skaɪ/","vi":"Chúng tôi nói về bầu trời đầy mây."},{"text":"Soon, the snow will cover the ground.","ipa":"/sun, ðə snoʊ wɪl ˈkʌvər ðə ɡraʊnd/","vi":"Chẳng bao lâu nữa, tuyết sẽ phủ kín mặt đất."},{"text":"I like cold weather, so I go outside to play.","ipa":"/aɪ laɪk koʊld ˈwɛðər, soʊ aɪ ɡoʊ ˌaʊtˈsaɪd tu pleɪ/","vi":"Tôi thích thời tiết lạnh nên tôi ra ngoài chơi."},{"text":"My friend also wears a big coat.","ipa":"/maɪ frɛnd ˈɔlsoʊ wɛrz ə bɪɡ koʊt/","vi":"Bạn tôi cũng mặc một chiếc áo khoác to."},{"text":"We throw snowballs and laugh out loud.","ipa":"/wi θroʊ ˈsnoʊˌbɔlz ænd læf aʊt laʊd/","vi":"Chúng tôi ném bóng tuyết và cười lớn."},{"text":"Now, let''s go home and drink something warm!","ipa":"/naʊ, lɛts ɡoʊ hoʊm ænd drɪŋk ˈsʌmθɪŋ wɔrm/","vi":"Bây giờ, hãy về nhà và uống thứ gì đó ấm áp thôi!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,1000,'e2186f79-6fc7-4843-acb7-b89fe884dd34','584dc6f875f04fd72642bce3e6e99b97',NULL,NULL,'2026-07-25T11:31:14.014Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('12b0236e-edde-4cc2-951e-f8251333e934','prea1-s5-14-listen-choose-weather','What''s the Weather Like?',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'Tom (M): Hi Ana! What''s the weather like today?
Ana (F): Hi Tom! It''s sunny and warm outside.
Tom (M) [happy]: Great! Let''s go to the park.
Ana (F): Wait, is it windy too?
Tom (M): A little windy, but it''s not cold.
Ana (F): Okay. Tomorrow, it will be rainy.
Tom (M) [surprised]: Really? I need my umbrella then.
Ana (F): Yes, and wear a jacket. It will be cool.
Tom (M): What about the weekend?
Ana (F): It will be cloudy on Saturday.
Tom (M): And on Sunday?
Ana (F): Sunday will be cold and snowy!
Tom (M) [happy]: I love snow! I will wear my warm coat.
Ana (F) [happy]: Me too. Let''s build a snowman on Sunday.
Tom (M) [excited]: Yes! That sounds like a lot of fun.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,1010,'e2186f79-6fc7-4843-acb7-b89fe884dd34','584dc6f875f04fd72642bce3e6e99b97',NULL,NULL,'2026-07-25T11:31:14.014Z',NULL);
