INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('d63124f1-6507-4ec4-ba7a-c97455f023ce','12b0236e-edde-4cc2-951e-f8251333e934',12,'fill_blank','Sunday will be cold and ___.',NULL,NULL,'["snowy"]','["snowy","rainy","windy"]',NULL,'Ana nói ''Sunday will be cold and snowy!''.','Ana: Sunday will be cold and snowy!',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('337a9ff2-0394-46c0-b3cb-6447f6e6f9a9','12b0236e-edde-4cc2-951e-f8251333e934',13,'matching','Match each day to its weather.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng ngày với thời tiết theo hội thoại.','Ana: It''s sunny... Tomorrow rainy... Saturday cloudy... Sunday cold and snowy.','[{"left":"Today","right":"sunny and warm"},{"left":"Tomorrow","right":"rainy"},{"left":"Saturday","right":"cloudy"},{"left":"Sunday","right":"cold and snowy"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('915de286-7ab0-4d01-be22-8a2125c750f4','12b0236e-edde-4cc2-951e-f8251333e934',14,'matching','Match each person to what they need.',NULL,NULL,NULL,NULL,NULL,'Ghép đúng người với điều họ cần theo hội thoại.','Tom: I need my umbrella then. / Ana: wear a jacket.','[{"left":"Tom","right":"needs an umbrella"},{"left":"Ana","right":"wants a jacket too"}]',NULL,NULL,NULL,NULL,NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('28d26f64-6fb8-43a8-8e6c-90efffa6d081','prea1-s5-16-mixed-checkpoint','A Rainy Day at Home',1,'mixed','Pre A1 Starters',NULL,'Today it''s cold and rainy outside. I feel a little tired, and my head hurts. I stay home from school because I am sick. My mom says, ''Rest today, but drink some warm tea.'' I lie in bed and look out the window. The sky is grey, and the wind is blowing. My little sister, Amy, comes to see me. ''Are you okay?'' she asks. ''I''m okay, but my stomach hurts a bit,'' I answer. Amy brings me a warm blanket and a book. I feel happy because she is so kind. Later, the rain stops, but it is still cloudy. I feel better now, and I am not sad anymore. Tomorrow, I hope it will be sunny and warm again!','[{"text":"Today it''s cold and rainy outside.","ipa":"/təˈdeɪ ɪts koʊld ænd ˈreɪni ˌaʊtˈsaɪd./","vi":"Hôm nay bên ngoài trời lạnh và mưa."},{"text":"I feel a little tired, and my head hurts.","ipa":"/aɪ fiːl ə ˈlɪtəl ˈtaɪərd, ænd maɪ hɛd hɜrts./","vi":"Tôi cảm thấy hơi mệt và bị đau đầu."},{"text":"I stay home from school because I am sick.","ipa":"/aɪ steɪ hoʊm frʌm skul bɪˈkəz aɪ æm sɪk./","vi":"Tôi nghỉ học vì bị ốm."},{"text":"My mom says, ''Rest today, but drink some warm tea.''","ipa":"/maɪ mɑm sɛz, rɛst təˈdeɪ, bʌt drɪŋk sʌm wɔrm ti./","vi":"Mẹ tôi bảo: ''Hôm nay con hãy nghỉ ngơi, nhưng nhớ uống chút trà ấm nhé.''"},{"text":"I lie in bed and look out the window.","ipa":"/aɪ laɪ ɪn bɛd ænd lʊk ˈaʊt ðə ˈwɪndoʊ./","vi":"Tôi nằm trên giường và nhìn ra ngoài cửa sổ."},{"text":"The sky is grey, and the wind is blowing.","ipa":"/ðə skaɪ ɪz greɪ, ænd ðə wɪnd ɪz ˈbloʊɪŋ./","vi":"Bầu trời xám xịt và gió đang thổi."},{"text":"My little sister, Amy, comes to see me.","ipa":"/maɪ ˈlɪtəl ˈsɪstər, ˈeɪmi, kʌmz tu si mi./","vi":"Em gái tôi, Amy, đến thăm tôi."},{"text":"''Are you okay?'' she asks.","ipa":"/ɑr ju oʊˈkeɪ? ʃi æsks./","vi":"''Anh/chị có sao không?'' con bé hỏi."},{"text":"''I''m okay, but my stomach hurts a bit,'' I answer.","ipa":"/aɪm oʊˈkeɪ, bʌt maɪ ˈstʌmək hɜrts ə bɪt, aɪ ˈænsər./","vi":"''Anh/chị ổn, nhưng hơi đau bụng một chút,'' tôi trả lời."},{"text":"Amy brings me a warm blanket and a book.","ipa":"/ˈeɪmi brɪŋz mi ə wɔrm ˈblæŋkɪt ænd ə bʊk./","vi":"Amy mang cho tôi một chiếc chăn ấm và một cuốn sách."},{"text":"I feel happy because she is so kind.","ipa":"/aɪ fiːl ˈhæpi bɪˈkəz ʃi ɪz soʊ kaɪnd./","vi":"Tôi cảm thấy vui vì con bé rất tốt bụng."},{"text":"Later, the rain stops, but it is still cloudy.","ipa":"/ˈleɪtər, ðə reɪn stɑps, bʌt ɪt ɪz stɪl ˈklaʊdi./","vi":"Sau đó, trời tạnh mưa nhưng vẫn còn nhiều mây."},{"text":"I feel better now, and I am not sad anymore.","ipa":"/aɪ fiːl ˈbɛtər naʊ, ænd aɪ æm nɑt sæd ˈɛniˌmɔr./","vi":"Bây giờ tôi thấy đỡ hơn rồi và không còn buồn nữa."},{"text":"Tomorrow, I hope it will be sunny and warm again!","ipa":"/təˈmɑroʊ, aɪ hoʊp ɪt wɪl bi ˈsʌni ænd wɔrm əˈgɛn!/","vi":"Ngày mai, tôi hy vọng trời sẽ nắng và ấm áp trở lại!"}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mixed_all',NULL,1030,'e2186f79-6fc7-4843-acb7-b89fe884dd34','71ab9bd5210054d2e76e8ca9ad5e6833',NULL,NULL,'2026-07-25T11:31:14.014Z',NULL);
