INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('3aec0ff1-d0ed-4089-9d03-b769e848947a','prea1-s6-03-read-aloud-schwa-er','My Morning Routine',1,'reading','Pre A1 Starters',NULL,'Every morning, I get up at seven o''clock. First, I wash my face and brush my teeth. Then I have breakfast with my mother and my sister. My mother makes eggs and toast, and I drink a glass of milk. After breakfast, I put on my shirt and my shoes. I take my bag and walk to school with my sister. My teacher is very kind, and she always smiles at us. We learn new words every day. At school, I sit near my best friend, and we talk about our morning. In the afternoon, I go home and do my homework. I like my morning routine very much!','[{"text":"Every morning, I get up at seven o''clock.","ipa":"/ˈɛvri ˈmɔrnɪŋ, aɪ ɡɛt ʌp æt ˈsɛvən əˈklɑk./","vi":"Mỗi sáng, tôi thức dậy lúc bảy giờ."},{"text":"First, I wash my face and brush my teeth.","ipa":"/fɜrst, aɪ wɑʃ maɪ feɪs ænd brʌʃ maɪ tiθ./","vi":"Đầu tiên, tôi rửa mặt và đánh răng."},{"text":"Then I have breakfast with my mother and my sister.","ipa":"/ðɛn aɪ hæv ˈbrɛkfəst wɪð maɪ ˈmʌðər ænd maɪ ˈsɪstər./","vi":"Sau đó, tôi ăn sáng cùng mẹ và chị gái."},{"text":"My mother makes eggs and toast, and I drink a glass of milk.","ipa":"/maɪ ˈmʌðər meɪks ɛɡz ænd toʊst, ænd aɪ drɪŋk ə ɡlæs ʌv mɪlk./","vi":"Mẹ tôi làm trứng và bánh mì nướng, còn tôi uống một ly sữa."},{"text":"After breakfast, I put on my shirt and my shoes.","ipa":"/ˈæftər ˈbrɛkfəst, aɪ pʊt ɑn maɪ ʃɜrt ænd maɪ ʃuz./","vi":"Sau khi ăn sáng, tôi mặc áo và đi giày."},{"text":"I take my bag and walk to school with my sister.","ipa":"/aɪ teɪk maɪ bæɡ ænd wɔk tu skul wɪð maɪ ˈsɪstər./","vi":"Tôi cầm cặp sách và đi bộ đến trường cùng chị gái."},{"text":"My teacher is very kind, and she always smiles at us.","ipa":"/maɪ ˈtitʃər ɪz ˈvɛri kaɪnd, ænd ʃi ˈɔlweɪz smaɪlz æt ʌs./","vi":"Cô giáo của tôi rất tốt bụng và cô luôn mỉm cười với chúng tôi."},{"text":"We learn new words every day.","ipa":"/wi lɜrn nu wɜrdz ˈɛvri deɪ./","vi":"Chúng tôi học từ mới mỗi ngày."},{"text":"At school, I sit near my best friend, and we talk about our morning.","ipa":"/æt skul, aɪ sɪt nɪr maɪ bɛst frɛnd, ænd wi tɔk əˈbaʊt ˈaʊər ˈmɔrnɪŋ./","vi":"Ở trường, tôi ngồi gần bạn thân nhất của mình và chúng tôi trò chuyện về buổi sáng."},{"text":"In the afternoon, I go home and do my homework.","ipa":"/ɪn ði ˌæftərˈnun, aɪ ɡoʊ hoʊm ænd du maɪ ˈhoʊmwɜrk./","vi":"Vào buổi chiều, tôi về nhà và làm bài tập về nhà."},{"text":"I like my morning routine very much!","ipa":"/aɪ laɪk maɪ ˈmɔrnɪŋ ruˈtin ˈvɛri mʌtʃ!/","vi":"Tôi rất thích thói quen buổi sáng của mình!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,1180,'8a51c647-bc53-447a-b239-31bafdda13ef','63fcb6083c8ab61c175811c3f3ff2625',NULL,NULL,'2026-07-25T11:26:04.508Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('b9e3185a-706b-488c-a018-376104790cbc','prea1-s6-04-listen-choose-daily-routine','What Time Do You Get Up?',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'Emma (F): Hi Jack! What time do you get up in the morning?
Jack (M): I get up at six thirty. What about you, Emma?
Emma (F): I get up at seven o''clock. Then I have breakfast at seven thirty.
Jack (M): I have breakfast at seven, too. What do you eat?
Emma (F): I eat toast and eggs. I drink some milk.
Jack (M): I eat cereal. My school starts at eight o''clock.
Emma (F): My school starts at eight, too! I walk to school with my sister.
Jack (M): I go to school by bus. In the afternoon, I do my homework at four o''clock.
Emma (F): I do my homework at four thirty. Then I play with my friends.
Jack (M): That''s fun! I have dinner at six thirty in the evening.
Emma (F): I have dinner at seven o''clock. After dinner, I read a book.
Jack (M): I watch TV after dinner. I go to bed at nine o''clock.
Emma (F) [gentle]: I go to bed at nine thirty. Good night, Jack!
Jack (M) [gentle]: Good night, Emma! See you at school tomorrow.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,1190,'8a51c647-bc53-447a-b239-31bafdda13ef','63fcb6083c8ab61c175811c3f3ff2625',NULL,NULL,'2026-07-25T11:26:04.508Z',NULL);
