INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('eebc6913-5361-43ba-9cb2-3e30f3c05f4c','9c52db36-862f-408f-8fd4-005a5311cce5',20,'categorize','Sort each sentence as Correct or Incorrect.',NULL,NULL,NULL,NULL,NULL,'''can'' không thêm -s và không đi kèm ''to''.',NULL,NULL,NULL,'["Correct", "Incorrect"]','[{"text": "She can swim.", "category": "Correct"}, {"text": "She cans swim.", "category": "Incorrect"}, {"text": "They can dance well.", "category": "Correct"}, {"text": "They can to dance well.", "category": "Incorrect"}]',NULL,'can-ability');
INSERT OR IGNORE INTO questions (id,exercise_id,position,type,question,options,answer,accept,word_bank,image,explanation,hint,pairs,tokens,categories,items,article_lenient,grammar_id) VALUES ('b5e35e10-7957-45e0-8653-78ccdfb56009','9c52db36-862f-408f-8fd4-005a5311cce5',21,'categorize','Sort each sentence as Correct or Incorrect.',NULL,NULL,NULL,NULL,NULL,'Sau ''can/can''t'' là động từ nguyên thể, không chia -s, không ''to''.',NULL,NULL,NULL,'["Correct", "Incorrect"]','[{"text": "He can play the guitar.", "category": "Correct"}, {"text": "He can plays the guitar.", "category": "Incorrect"}, {"text": "I can''t swim.", "category": "Correct"}, {"text": "I can not to swim.", "category": "Incorrect"}]',NULL,'can-ability');
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('79431288-0bc6-42c1-ba11-6f91ac5ab280','prea1-s6-08-read-aloud-e-ae','What I Can Do',1,'reading','Pre A1 Starters',NULL,'Hi! My name is Sam. I have many hobbies. I can swim very well, and I can run fast too. Every Saturday, I play basketball with my friends in the park. I can''t play tennis yet, but I can dance a little bit. My best friend, Anna, can sing and play the guitar. She can''t swim, but she can ride a bike very well. We often play games together after school. I have a black and orange ball, and I have a small guitar too. Sometimes, we sing and dance at the same time. It''s fantastic fun! I really love my hobbies.','[{"text":"Hi!","ipa":"/haɪ/","vi":"Chào bạn!"},{"text":"My name is Sam.","ipa":"/maɪ neɪm ɪz sæm/","vi":"Tên mình là Sam."},{"text":"I have many hobbies.","ipa":"/aɪ hæv ˈmɛni ˈhɑbiz/","vi":"Mình có nhiều sở thích."},{"text":"I can swim very well, and I can run fast too.","ipa":"/aɪ kæn swɪm ˈvɛri wɛl, ænd aɪ kæn rʌn fæst tu/","vi":"Mình bơi rất giỏi và cũng chạy rất nhanh."},{"text":"Every Saturday, I play basketball with my friends in the park.","ipa":"/ˈɛvri ˈsætərdeɪ, aɪ pleɪ ˈbæskətˌbɔl wɪð maɪ frɛndz ɪn ðə pɑrk/","vi":"Mỗi thứ Bảy, mình chơi bóng rổ với bạn bè ở công viên."},{"text":"I can''t play tennis yet, but I can dance a little bit.","ipa":"/aɪ kænt pleɪ ˈtɛnəs jɛt, bʌt aɪ kæn dæns ə ˈlɪtəl bɪt/","vi":"Mình chưa biết chơi quần vợt, nhưng mình có thể nhảy một chút."},{"text":"My best friend, Anna, can sing and play the guitar.","ipa":"/maɪ bɛst frɛnd, ˈænə, kæn sɪŋ ænd pleɪ ðə ɡɪˈtɑr/","vi":"Bạn thân của mình, Anna, có thể hát và chơi đàn ghi-ta."},{"text":"She can''t swim, but she can ride a bike very well.","ipa":"/ʃi kænt swɪm, bʌt ʃi kæn raɪd ə baɪk ˈvɛri wɛl/","vi":"Bạn ấy không biết bơi, nhưng lại đạp xe rất giỏi."},{"text":"We often play games together after school.","ipa":"/wi ˈɔfən pleɪ ɡeɪmz təˈɡɛðər ˈæftər skul/","vi":"Chúng mình thường chơi trò chơi cùng nhau sau giờ học."},{"text":"I have a black and orange ball, and I have a small guitar too.","ipa":"/aɪ hæv ə blæk ænd ˈɔrɪndʒ bɔl, ænd aɪ hæv ə smɔl ɡɪˈtɑr tu/","vi":"Mình có một quả bóng màu đen cam và một cây đàn ghi-ta nhỏ nữa."},{"text":"Sometimes, we sing and dance at the same time.","ipa":"/ˈsʌmˌtaɪmz, wi sɪŋ ænd dæns æt ðə seɪm taɪm/","vi":"Đôi khi, chúng mình vừa hát vừa nhảy cùng lúc."},{"text":"It''s fantastic fun!","ipa":"/ɪts fænˈtæstɪk fʌn/","vi":"Thật là vui tuyệt vời!"},{"text":"I really love my hobbies.","ipa":"/aɪ ˈrɪli lʌv maɪ ˈhɑbiz/","vi":"Mình thực sự rất yêu thích các sở thích của mình."}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,1230,'8a51c647-bc53-447a-b239-31bafdda13ef','789b7b1d83fec658b86f5a6fb0b4929b',NULL,NULL,'2026-07-25T11:26:04.508Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('41943fe6-0839-4bb1-8ae9-3aa61a19dcfc','prea1-s6-09-listen-choose-hobbies','Can You Swim?',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'Mia (F): Hi Leo! Do you have any hobbies?
Leo (M) [happy]: Yes! I can play football very well. Can you play football too?
Mia (F): No, I can''t play football, but I can swim very well.
Leo (M): That''s great! I can''t swim, but I can ride a bike.
Mia (F): I can ride a bike too! Can you play a musical instrument?
Leo (M): Yes, I can play the guitar. What about you?
Mia (F): I can play the piano. I practice every evening.
Leo (M) [happy]: Cool! Can you sing?
Mia (F): Yes, I can sing, but I can''t dance well.
Leo (M): I can dance, but I can''t sing at all!
Mia (F): Let''s play a game together. Can you draw?
Leo (M): Yes, I can draw pictures of animals. Can you draw too?
Mia (F) [happy]: I can draw a little bit. Let''s draw together after school!
Leo (M) [happy]: Great idea! See you later, Mia.',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,1240,'8a51c647-bc53-447a-b239-31bafdda13ef','789b7b1d83fec658b86f5a6fb0b4929b',NULL,NULL,'2026-07-25T11:26:04.508Z',NULL);
