INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('0ff6dcd3-72f8-48c5-839b-6cb6c462230b','prea1-s6-13-read-aloud-th-z','Going to the Park',1,'reading','Pre A1 Starters',NULL,'This is my street. There is a small park near my house. My brother goes to the park every afternoon. He plays football there with his friends. The park is next to the library, and there are buses that stop near the gate. This bus goes to the city, and that bus goes to the station. My sister rides her bike to the park, but she goes there by bike, not by bus. There is a big tree in the park, and there are many flowers too. We often walk there together on Sundays. This place is my favorite place in town!','[{"text":"This is my street.","ipa":"/ðɪs ɪz maɪ striːt./","vi":"Đây là con phố của mình."},{"text":"There is a small park near my house.","ipa":"/ðɛr ɪz ə smɔl pɑrk nɪr maɪ haʊs./","vi":"Có một công viên nhỏ gần nhà mình."},{"text":"My brother goes to the park every afternoon.","ipa":"/maɪ ˈbrʌðər ɡoʊz tu ðə pɑrk ˈɛvri ˈæftərˌnuːn./","vi":"Anh trai mình đến công viên vào mỗi buổi chiều."},{"text":"He plays football there with his friends.","ipa":"/hi pleɪz ˈfʊtˌbɔl ðɛr wɪð hɪz frɛndz./","vi":"Anh ấy chơi bóng đá ở đó với bạn bè."},{"text":"The park is next to the library, and there are buses that stop near the gate.","ipa":"/ðə pɑrk ɪz nɛkst tu ðə ˈlaɪˌbrɛri, ænd ðɛr ɑr ˈbʌsəz ðæt stɑp nɪr ðə ɡeɪt./","vi":"Công viên nằm cạnh thư viện, và có những chuyến xe buýt dừng gần cổng."},{"text":"This bus goes to the city, and that bus goes to the station.","ipa":"/ðɪs bʌs ɡoʊz tu ðə ˈsɪti, ænd ðæt bʌs ɡoʊz tu ðə ˈsteɪʃən./","vi":"Chuyến xe buýt này đi vào thành phố, còn chuyến kia đi đến nhà ga."},{"text":"My sister rides her bike to the park, but she goes there by bike, not by bus.","ipa":"/maɪ ˈsɪstər raɪdz hər baɪk tu ðə pɑrk, bʌt ʃi ɡoʊz ðɛr baɪ baɪk, nɑt baɪ bʌs./","vi":"Chị gái mình đạp xe đến công viên, chị ấy đi bằng xe đạp chứ không đi xe buýt."},{"text":"There is a big tree in the park, and there are many flowers too.","ipa":"/ðɛr ɪz ə bɪɡ tri ɪn ðə pɑrk, ænd ðɛr ɑr ˈmɛni ˈflaʊərz tu./","vi":"Trong công viên có một cái cây lớn và cũng có rất nhiều hoa."},{"text":"We often walk there together on Sundays.","ipa":"/wi ˈɔfən wɔk ðɛr təˈɡɛðər ɑn ˈsʌnˌdeɪz./","vi":"Chúng mình thường cùng nhau đi dạo ở đó vào các ngày Chủ nhật."},{"text":"This place is my favorite place in town!","ipa":"/ðɪs pleɪs ɪz maɪ ˈfeɪvərɪt pleɪs ɪn taʊn!/","vi":"Đây là nơi mình yêu thích nhất trong thị trấn!"}]',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'read_aloud',NULL,1280,'8a51c647-bc53-447a-b239-31bafdda13ef','f02b61a23fac0687670b292feffca750',NULL,NULL,'2026-07-25T11:26:04.508Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('1d7f1be4-54f9-4ff2-bfd2-878b9036bba4','prea1-s6-14-listen-choose-directions','How Do You Get to School?',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,'Nora (F): Hi Max! How do you get to school every day?
Max (M): I go to school by bus. What about you, Nora?
Nora (F): I walk on foot. My house is near the school.
Max (M): That''s nice! Is the bus stop far from your house?
Nora (F): No, it''s near the park, just around the corner.
Max (M): I see. How do you get to the library?
Nora (F): I ride my bike to the library. It''s on Main Street.
Max (M): I go there on foot too. It''s not far.
Nora (F): Do you know how to get to the train station?
Max (M): Yes! Go straight, then turn left at the bank.
Nora (F): And then?
Max (M): Then turn right at the corner. The station is next to the market.
Nora (F): Thanks! I want to visit my grandmother. She lives near the station.
Max (M): You can go there by bus or by train.
Nora (F) [happy]: I think I will go by train. See you tomorrow, Max!',NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'listen_choose',NULL,1290,'8a51c647-bc53-447a-b239-31bafdda13ef','f02b61a23fac0687670b292feffca750',NULL,NULL,'2026-07-25T11:26:04.508Z',NULL);
