INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('54d1aae4-f4be-47de-b630-06e59bec0f55','prea1-s6-16-mixed-nghiem-thu','Lucy''s Saturday',1,'mixed','Pre A1 Starters',NULL,'Today is Saturday, and Lucy is happy. She gets up at eight o''clock, later than school days. First, she has breakfast with her family in the morning. Then, at nine o''clock, she goes to the park by bike with her brother, Tom. Lucy can ride a bike very well, but Tom can''t ride fast yet. At the park, they play football with their friends. Lucy can play football well, but she can''t swim. In the afternoon, they walk to the library on Main Street. It is near the school, so it doesn''t take long. Lucy borrows a book about animals. At six o''clock in the evening, they go home by bus. Lucy has dinner with her family and goes to bed at nine thirty. What a wonderful Saturday!','[{"text":"Today is Saturday, and Lucy is happy.","ipa":"/təˈdeɪ ɪz ˈsætərdeɪ, ænd ˈlusi ɪz ˈhæpi./","vi":"Hôm nay là thứ Bảy, và Lucy rất vui."},{"text":"She gets up at eight o''clock, later than school days.","ipa":"/ʃi ɡɛts ʌp æt eɪt əˈklɑk, ˈleɪtər ðæn skul deɪz./","vi":"Cô bé thức dậy lúc tám giờ, muộn hơn so với những ngày đi học."},{"text":"First, she has breakfast with her family in the morning.","ipa":"/fɜrst, ʃi hæz ˈbrɛkfəst wɪð hər ˈfæməli ɪn ðə ˈmɔrnɪŋ./","vi":"Đầu tiên, cô bé ăn sáng cùng gia đình vào buổi sáng."},{"text":"Then, at nine o''clock, she goes to the park by bike with her brother, Tom.","ipa":"/ðɛn, æt naɪn əˈklɑk, ʃi ɡoʊz tu ðə pɑrk baɪ baɪk wɪð hər ˈbrʌðər, tɑm./","vi":"Sau đó, lúc chín giờ, cô bé đạp xe đến công viên cùng em trai là Tom."},{"text":"Lucy can ride a bike very well, but Tom can''t ride fast yet.","ipa":"/ˈlusi kæn raɪd ə baɪk ˈvɛri wɛl, bʌt tɑm kænt raɪd fæst jɛt./","vi":"Lucy đạp xe rất giỏi, nhưng Tom vẫn chưa đạp nhanh được."},{"text":"At the park, they play football with their friends.","ipa":"/æt ðə pɑrk, ðeɪ pleɪ ˈfʊtbɔl wɪð ðɛr frɛndz./","vi":"Tại công viên, họ chơi bóng đá cùng bạn bè."},{"text":"Lucy can play football well, but she can''t swim.","ipa":"/ˈlusi kæn pleɪ ˈfʊtbɔl wɛl, bʌt ʃi kænt swɪm./","vi":"Lucy chơi bóng đá giỏi, nhưng cô bé không biết bơi."},{"text":"In the afternoon, they walk to the library on Main Street.","ipa":"/ɪn ði ˌæftərˈnun, ðeɪ wɔk tu ðə ˈlaɪˌbrɛri ɑn meɪn strit./","vi":"Vào buổi chiều, họ đi bộ đến thư viện trên phố Main."},{"text":"It is near the school, so it doesn''t take long.","ipa":"/ɪt ɪz nɪr ðə skul, soʊ ɪt ˈdʌzənt teɪk lɔŋ./","vi":"Nó gần trường học nên đi không mất nhiều thời gian."},{"text":"Lucy borrows a book about animals.","ipa":"/ˈlusi ˈbɑroʊz ə bʊk əˈbaʊt ˈænəməlz./","vi":"Lucy mượn một cuốn sách về động vật."},{"text":"At six o''clock in the evening, they go home by bus.","ipa":"/æt sɪks əˈklɑk ɪn ði ˈivnɪŋ, ðeɪ ɡoʊ hoʊm baɪ bʌs./","vi":"Lúc sáu giờ tối, họ đi xe buýt về nhà."},{"text":"Lucy has dinner with her family and goes to bed at nine thirty.","ipa":"/ˈlusi hæz ˈdɪnər wɪð hər ˈfæməli ænd ɡoʊz tu bɛd æt naɪn ˈθɜrti./","vi":"Lucy ăn tối cùng gia đình và đi ngủ lúc chín giờ ba mươi."},{"text":"What a wonderful Saturday!","ipa":"/wʌt ə ˈwʌndərfəl ˈsætərdeɪ!/","vi":"Thật là một ngày thứ Bảy tuyệt vời!"}]',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'mixed_all',NULL,1310,'8a51c647-bc53-447a-b239-31bafdda13ef','789b7b1d83fec658b86f5a6fb0b4929b',NULL,NULL,'2026-07-25T11:26:04.508Z',NULL);
